/** The four faces of the door (design-calm stage 6). Decided here and
 *  nowhere else: `name` is a stranger, `signedIn` an account that is
 *  connected, `reconnect` an account used here before that is not, and
 *  `extension` a NIP-07 signer with nobody signed in. */
type DoorMode = 'name' | 'signedIn' | 'reconnect' | 'extension'
const DOOR_OFFLINE = 'You are offline. The room opens when you are back.'

/** The person declined the account and chose to go in with a name. Keyed to
 *  the room and identity it was chosen in, so changing either forgets it. */
let visitorChosenKey: string | undefined
const doorKey = (): string => `${roomGeneration}:${identityGeneration}`
const visitorChosen = (): boolean => visitorChosenKey === doorKey()

/** A saved Nostr sign-in is still being restored: not connected yet, but not
 *  lost either, so the door waits for it instead of asking to reconnect. */
const accountRestoring = (): boolean => !nostrSession && identityRestoring && !!expectedAccount

function doorMode(): DoorMode {
  if (visitorChosen()) return 'name'
  // A pass this device holds for the room speaks for the account without its
  // signer: Continue joins on it, as the account, and asks for nothing.
  if (nostrSession || accountRestoring() || accountPassForRoom()) return 'signedIn'
  if (needsAccountReconnect()) return 'reconnect'
  if (extensionSignerPresent() && !loadCredential()) return 'extension'
  return 'name'
}

/** A 24 px picture for the Continue button. The initial is drawn by CSS
 *  from `data-initial`, so the button's text stays its accessible name. */
function doorAvatar(pubkey: string): HTMLElement {
  const shown = shownAs(pubkey)
  const el = document.createElement('span')
  el.className = 'joinAvatar'
  el.setAttribute('aria-hidden', 'true')
  el.dataset.initial = [...(shown.name?.trim() ?? '')][0]?.toLocaleUpperCase() ?? ''
  if (shown.picture) {
    const image = document.createElement('img')
    image.alt = ''
    image.referrerPolicy = 'no-referrer'
    image.src = shown.picture
    image.addEventListener('error', () => image.remove(), { once: true })
    el.append(image)
  }
  return el
}

let doorFocusedFor: number | undefined

/** Put the cursor where the next move is: the name, or the Continue button.
 *  Never on a touch screen (the keyboard would cover the room's name) and
 *  never after the person has focused something of their own. */
function focusDoor(mode: DoorMode): void {
  if (doorFocusedFor === roomGeneration) return
  const join = $('join') as HTMLButtonElement
  if ($('identity').hidden || $('joinRoomForm').hidden || join.hidden || join.disabled || joining) return
  doorFocusedFor = roomGeneration
  if (!matchMedia('(pointer: fine)').matches) return
  const active = document.activeElement
  if (active && active !== document.body && active !== document.documentElement && !(active as HTMLElement).hidden) return
  const field = $('displayName') as HTMLInputElement
  ;(mode === 'name' || (mode === 'signedIn' && !$('doorName').hidden) ? field : join).focus({ preventScroll: true })
}

function renderDoorMode(): void {
  applyHideIpDefault()
  // The knock door keeps its own controls (Request to join).
  if (guestAdmissionPreview) return
  const mode = doorMode()
  const join = $('join') as HTMLButtonElement
  const known = joiningName()
  const account = nostrSession?.pubkey ?? accountPassForRoom()?.pubkey ?? (mode === 'reconnect' || accountRestoring() ? expectedAccount : undefined)
  const showField = mode === 'name' || (mode === 'signedIn' && known === undefined)
  $('doorName').hidden = !showField
  $('displayNameHint').hidden = !(showField && visitorChosen())
  if (showField && visitorChosen()) $('displayName').setAttribute('aria-describedby', 'displayNameHint')
  else $('displayName').removeAttribute('aria-describedby')
  $('joinNostr').hidden = mode !== 'name' || visitorChosen() || !!loadCredential()
  $('joinVisitor').hidden = mode !== 'reconnect' && mode !== 'extension'
  if (!joining) {
    // The account's own name; the name typed on this device is a visitor's
    // unless the account is connected and has none of its own.
    const named = account ? ((mode === 'signedIn' && nostrSession ? known : undefined) ?? shownAs(account).name ?? lastKnownProfileNames.get(account)) : undefined
    const text = mode === 'name' ? 'Join'
      : mode === 'extension' ? 'Continue with your Nostr extension'
      : named ? `Continue as ${named}` : 'Continue with your Nostr account'
    const picture = account && (mode === 'signedIn' || mode === 'reconnect') ? shownAs(account).picture ?? '' : undefined
    const key = `${text}|${picture ?? ''}|${account ?? ''}`
    if (join.dataset.doorKey !== key || join.textContent !== text) {
      join.dataset.doorKey = key
      join.replaceChildren(...(account && picture !== undefined ? [doorAvatar(account), document.createTextNode(text)] : [document.createTextNode(text)]))
    }
  }
  join.classList.add('primary')
  join.classList.remove('quiet')
  if (account) profiles.want([account])
  if (!navigator.onLine && !joining && !session && !$('status').textContent) setStatus(DOOR_OFFLINE, 'progress')
  focusDoor(mode)
}

window.addEventListener('offline', () => { if (!$('identity').hidden) renderDoorMode() })
window.addEventListener('online', () => { if ($('status').textContent === DOOR_OFFLINE) setStatus('') })

/** What the primary button does, by the door's face. */
async function joinFromDoor(): Promise<void> {
  const mode = doorMode()
  if (mode === 'reconnect') await reconnectNostr()
  else if (mode === 'extension') await signInWithNostr()
  if ((mode === 'reconnect' || mode === 'extension') && !nostrSession) return
  if (session || joining) return
  await startSession(visitorChosen())
}

/** The wrapping disclosure for the three "More for your Nostr account"
 *  parts, shown only when at least one of them has something to offer -
 *  an empty disclosure is a dead end with a label on it. */
function renderAccountMore(): void {
  $('accountMore').hidden = $('rendezvousProvision').hidden && $('historyRecovery').hidden && $('importedHistorySearch').hidden
}

/** Signed in, still looking: a status line under the home lede, mirroring
 *  the existing #roomSyncStatus text (spec section 6). A separate element
 *  rather than writing into #homeStatus, which holds #status and must
 *  never be overwritten. */
function renderHomeSyncStatus(): void {
  const line = $('homeSyncStatus')
  const message = $('roomSyncStatus').textContent ?? ''
  const show = roomsListShown && !!nostrSession && knownRooms(roomStore()).length === 0 && message !== ''
  line.textContent = show ? message : ''
  line.hidden = !show
}

function renderHistoryRecovery(): void {
  const details = $('historyRecovery') as HTMLDetailsElement
  const select = $('historyRecoveryBox') as HTMLSelectElement
  const action = $('recoverRecentHistory') as HTMLButtonElement
  const status = $('historyRecoveryStatus')
  const report = $('historyRecoveryReport')
  report.replaceChildren(...historyRecoveryView.rows.map(row => {
    const item = document.createElement('li'); item.textContent = row; return item
  }))
  const account = nostrSession
  details.hidden = !account
  renderAccountMore()
  select.replaceChildren()
  if (!account) return
  const crypt = account.signer.nip44
  if (!crypt) {
    status.textContent = 'This signer cannot make the private NIP-44 handoff required for recovery.'
    action.disabled = true
    return
  }
  const boxes = boxDiscovery?.migrationBoxes(account.pubkey) ?? []
  if (!boxes.length) {
    status.textContent = 'Add your own current contact card, then choose Check box. Recovery is offered only after its signed claim and current status verify this account as master or stash.'
    action.disabled = true
    return
  }
  const held = select.value
  for (const box of boxes) select.add(new Option(`${box.authority === 'master' ? 'Master' : 'Stash'} box ${shortKey(box.node)} (checked until ${new Date(box.validUntil * 1000).toLocaleTimeString()})`, box.node))
  if (boxes.some(box => box.node === held)) select.value = held
  const windows = recoveryProgressWindows(loadHistoryRecoveryProgress(deviceStore, account.pubkey, select.value || boxes[0]!.node), relayConnections.configuration('default').filter(relay => relay.read).map(relay => relay.url), nowSeconds())
  status.textContent = historyRecoveryView.status || `Choose a freshly checked box. The next action has ${windows.length} independent relay/class window${windows.length === 1 ? '' : 's'}; a completed one moves older, while a partial one stays put. Recovery is never a background sync.`
  action.disabled = historyRecoveryBusy
  action.textContent = historyRecoveryBusy ? 'Bringing the selected windows home…' : 'Bring the next windows home'
}

function renderImportedHistorySearch(): void {
  const details = $('importedHistorySearch') as HTMLDetailsElement
  const input = $('importedHistoryQuery') as HTMLInputElement
  const action = $('searchImportedHistory') as HTMLButtonElement
  const status = $('importedHistoryStatus')
  const results = $('importedHistoryResults')
  const account = nostrSession
  details.hidden = !account
  renderAccountMore()
  results.replaceChildren()
  if (!account) return
  input.value = importedHistorySearchView.query
  status.textContent = importedHistorySearchView.status || 'Search is explicit and local. It has no relay, box or signer request.'
  action.disabled = importedHistorySearchBusy
  action.textContent = importedHistorySearchBusy ? 'Searching this device…' : 'Search this device'
  for (const result of importedHistorySearchView.results) {
    const row = document.createElement('li')
    const when = new Date(result.document.sentAt * 1000).toLocaleString()
    const text = result.document.text.length > 280 ? `${result.document.text.slice(0, 280)}…` : result.document.text
    row.append(`${when} · ${shortKey(result.document.participant ?? 'unknown')} · ${text}`)
    const remove = document.createElement('button')
    remove.type = 'button'; remove.className = 'danger'; remove.textContent = 'Delete from this device and box'
    remove.disabled = importedHistorySearchBusy
    remove.addEventListener('click', () => { void deleteImportedHistoryResult(result.document.id) })
    row.append(' ', remove)
    results.append(row)
  }
}

function clearImportedHistorySearch(): void {
  importedHistorySearchBusy = false
  importedHistorySearchView = { query: '', status: '', results: [] }
  // Clear rendered plaintext synchronously too: an asynchronous sign-in or
  // sign-out must not leave a former account's search result on screen.
  document.getElementById('importedHistoryResults')?.replaceChildren()
  const input = document.getElementById('importedHistoryQuery') as HTMLInputElement | null
  if (input) input.value = ''
  const status = document.getElementById('importedHistoryStatus')
  if (status) status.textContent = ''
}

async function searchImportedHistory(): Promise<void> {
  if (importedHistorySearchBusy) return
  const account = nostrSession, generation = identityGeneration
  if (!account) return
  const query = ($('importedHistoryQuery') as HTMLInputElement).value
  importedHistorySearchBusy = true
  importedHistorySearchView = { query, status: 'Opening this device’s encrypted imported-history index…', results: [] }
  renderImportedHistorySearch()
  try {
    const index = new LocalHistoryIndex(new BrowserHistoryIndexStorage())
    const count = await index.count()
    const results = await index.search(query)
    if (nostrSession !== account || identityGeneration !== generation) return
    importedHistorySearchView = {
      query,
      results,
      status: `${importedHistoryCoverage(count)} ${results.length} matching item${results.length === 1 ? '' : 's'} shown.`,
    }
  } catch (error) {
    if (nostrSession !== account || identityGeneration !== generation) return
    importedHistorySearchView = { query, status: describeError(error), results: [] }
  } finally {
    if (nostrSession !== account || identityGeneration !== generation) return
    importedHistorySearchBusy = false
    renderImportedHistorySearch()
  }
}

async function deleteImportedHistoryResult(eventId: string): Promise<void> {
  if (importedHistorySearchBusy) return
  const account = nostrSession, generation = identityGeneration
  const crypt = account?.signer.nip44
  const node = ($('historyRecoveryBox') as HTMLSelectElement).value
  const box = account && boxDiscovery?.migrationBoxes(account.pubkey).find(candidate => candidate.node === node)
  const document = importedHistorySearchView.results.find(result => result.document.id === eventId)?.document
  const publicKind = document?.accountAuthoredKind
  if (!account || !crypt || !box) {
    importedHistorySearchView = { ...importedHistorySearchView, status: 'Choose a freshly checked master or stash box in “Bring recent Nostr history home” before deleting an imported item.' }
    renderImportedHistorySearch()
    return
  }
  if (!await confirmAction({
    title: 'Delete this imported message?',
    message: publicKind === undefined
      ? 'KithMoot will first ask the selected box to record a private deletion barrier for this exact stored outer event. Only after its authenticated receipt will this browser remove its encrypted search material. A received NIP-17 outer wrapper is ephemeral-signed, not authored by this account, so no invalid public kind-5 deletion request will be sent. Public copies held by other people or relays may remain.'
      : 'KithMoot will first ask the selected box to record a private deletion barrier for this exact account-authored event. Only after its authenticated receipt will this browser remove its encrypted search material, then it will make a signed kind-5 deletion request to each configured public relay and show each acknowledgement. An acknowledgement is not proof that a relay erased bytes or that another client discarded a copy.',
    confirmLabel: 'Delete locally and from box',
    isCurrent: () => nostrSession === account && identityGeneration === generation && !!boxDiscovery?.migrationBoxes(account.pubkey).some(candidate => candidate.node === node),
  })) return
  importedHistorySearchBusy = true
  importedHistorySearchView = { ...importedHistorySearchView, status: 'Waiting for the selected box’s private deletion receipt…' }
  renderImportedHistorySearch()
  try {
    const index = new LocalHistoryIndex(new BrowserHistoryIndexStorage())
    const transport = relayConnections.pool('default')
    let outcome
    try {
      outcome = await deleteImportedHistory({
        eventId,
        index,
        recordPrivateTombstone: async id => {
          const recorded = await recordPrivateHistoryTombstone({
            eventId: id,
            identity: { pubkey: account.pubkey, signEvent: event => account.signer.signEvent(event), encrypt: (peer, text) => crypt.encrypt(peer, text), decrypt: (peer, text) => crypt.decrypt(peer, text) },
            node,
            nonce: migrationNonce(),
            transport,
          })
          if (nostrSession !== account || identityGeneration !== generation) throw new Error('Account changed while the box deletion was running.')
          return recorded
        },
      })
    } finally { transport.close() }
    const remaining = await index.count()
    let publicStatus: string
    if (publicKind === undefined) {
      publicStatus = 'Public relays: no request sent, because this received NIP-17 outer wrapper is not signed by this account.'
    } else {
      try {
        if (nostrSession !== account || identityGeneration !== generation) throw new Error('Account changed before the public deletion request could be signed.')
        const relays = relayConnections.configuration('default').filter(relay => relay.write && !relay.circle).map(relay => relay.url)
        if (!relays.length) publicStatus = 'Public relays: no configured writable public relay; no deletion request was sent.'
        else {
          const request = await signedPublicDeletionRequest(account, eventId, publicKind)
          const outcomes = await new NostrPublicDeletionRelayWriter().publish(relays, request)
          publicStatus = `Public relays: ${outcomes.map(outcome => `${outcome.relay} ${outcome.status}${outcome.detail ? ` (${outcome.detail})` : ''}`).join('; ')}.`
        }
      } catch (error) {
        publicStatus = `Public relays: deletion request was not sent (${describeError(error)}).`
      }
    }
    importedHistorySearchView = {
      ...importedHistorySearchView,
      results: importedHistorySearchView.results.filter(result => result.document.id !== eventId),
      status: `${importedHistoryCoverage(remaining)} Box deletion barrier: ${outcome.box}; this device: ${outcome.device}. ${publicStatus}`,
    }
  } catch (error) {
    importedHistorySearchView = { ...importedHistorySearchView, status: describeError(error) }
  } finally {
    importedHistorySearchBusy = false
    renderImportedHistorySearch()
  }
}

async function signedPublicDeletionRequest(account: SignetSession, eventId: string, targetKind: number): Promise<NostrEvent> {
  const created_at = nowSeconds(), tags = [['e', eventId], ['k', String(targetKind)]]
  const signed = await account.signer.signEvent({ kind: 5, created_at, tags, content: '' })
  if (signed.pubkey !== account.pubkey || signed.kind !== 5 || signed.created_at !== created_at || signed.content !== '' || JSON.stringify(signed.tags) !== JSON.stringify(tags) || !verifyEventUncached(signed)) {
    throw new Error('The signer changed or refused the public deletion request.')
  }
  return signed
}

function migrationNonce(): string {
  const bytes = new Uint8Array(8); crypto.getRandomValues(bytes)
  return Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('')
}

async function recoverRecentHistoryToBox(): Promise<void> {
  if (historyRecoveryBusy) return
  const account = nostrSession, generation = identityGeneration
  const crypt = account?.signer.nip44
  const node = ($('historyRecoveryBox') as HTMLSelectElement).value
  const box = account && boxDiscovery?.migrationBoxes(account.pubkey).find(candidate => candidate.node === node)
  if (!account || !crypt || !box) { renderHistoryRecovery(); return }
  const relays = relayConnections.configuration('default').filter(relay => relay.read).map(relay => relay.url)
  if (!relays.length) throw new Error('Choose at least one readable default relay before recovering history.')
  const progress = loadHistoryRecoveryProgress(deviceStore, account.pubkey, node)
  const windows = recoveryProgressWindows(progress, relays, nowSeconds())
  if (!await confirmAction({
    title: 'Bring this recent history home?',
    message: `KithMoot will make ${windows.length} bounded relay/class requests across ${relays.length} configured read relay${relays.length === 1 ? '' : 's'}. Completed requests move to their next older 30-day window; limited, closed and timed-out requests do not advance. Verified original events go in encrypted NIP-59 requests to ${shortKey(box.node)}. Relays will see the bounded requests; the box receives no plaintext search query.`,
    confirmLabel: 'Bring it home',
    isCurrent: () => nostrSession === account && identityGeneration === generation && !!boxDiscovery?.migrationBoxes(account.pubkey).some(candidate => candidate.node === node),
  })) return
  historyRecoveryBusy = true
    historyRecoveryView = { status: 'Reading the selected relay windows…', rows: [] }
  renderHistoryRecovery()
  try {
    const imported = await recoverHistoryWindows({ person: account.pubkey, windows, read: new NostrHistoryRelayReader().read })
    if (nostrSession !== account || identityGeneration !== generation) throw new Error('Account changed while recovery was running.')
    const transport = relayConnections.pool('default')
    let retained
    try {
      retained = await retainRecoveredHistory({
        events: imported.events,
        identity: { pubkey: account.pubkey, signEvent: event => account.signer.signEvent(event), encrypt: (peer, text) => crypt.encrypt(peer, text), decrypt: (peer, text) => crypt.decrypt(peer, text) },
        node,
        transport,
        nonce: migrationNonce,
      })
    } finally { transport.close() }
    const retainedIds = new Set<string>()
    for (const batch of retained.batches) {
      const outcomes = batch.reply.ok ? batch.reply.result?.outcomes : undefined
      outcomes?.forEach((outcome, index) => { if (outcome === 'stored' || outcome === 'duplicate') retainedIds.add(batch.ids[index]!) })
    }
    const index = new LocalHistoryIndex(new BrowserHistoryIndexStorage())
    const retainedEvents = imported.events.filter(event => retainedIds.has(event.id))
    const local = await indexAccessibleNip17GiftWraps({ events: retainedEvents, identity: { pubkey: account.pubkey, signEvent: event => account.signer.signEvent(event), encrypt: (peer, text) => crypt.encrypt(peer, text), decrypt: (peer, text) => crypt.decrypt(peer, text) }, index })
    const authored = await indexAccountAuthoredTextNotes({ events: retainedEvents, account: account.pubkey, index })
    const custody = retained.batches.flatMap(batch => batch.reply.ok ? batch.reply.result?.outcomes ?? [] : [`box error: ${batch.reply.error?.code ?? 'unknown'}`])
    const nextWindows = advanceRecoveryWindows(windows, imported.receipts)
    saveHistoryRecoveryProgress(deviceStore, { version: 1, person: account.pubkey, node, windows: nextWindows })
    const advanced = imported.receipts.filter(receipt => receipt.terminal === 'complete').length
    historyRecoveryView = {
      status: `Verified ${imported.events.length} distinct relay event${imported.events.length === 1 ? '' : 's'}; box outcomes: ${custody.length ? custody.join(', ') : 'no events to retain'}. This device indexed ${local.stored} decryptable NIP-17 message${local.stored === 1 ? '' : 's'} (${local.duplicate} already present; ${local.inaccessible} remained raw only) and ${authored.stored} account-authored public note${authored.stored === 1 ? '' : 's'} (${authored.duplicate} already present). ${advanced} completed relay/class request${advanced === 1 ? '' : 's'} will move to an older window next time; partial requests remain on this window.`,
      rows: imported.receipts.map(receipt => `${receipt.relay} · ${receipt.request.class} · ${receipt.terminal}: accepted ${receipt.accepted}, duplicate ${receipt.duplicate}, invalid ${receipt.invalid}, rejected ${receipt.rejected}.`),
    }
  } catch (error) {
    historyRecoveryView = { ...historyRecoveryView, status: describeError(error) }
  } finally {
    historyRecoveryBusy = false
    renderHistoryRecovery()
  }
}

// The published tracks. Neither the microphone nor the camera track is the
// device: both are the far end of an effect pipeline, so turning blur or
// masking on and off never replaces a track the mesh has already published
// and never renegotiates. See app/src/video-pipeline.ts for why that
// matters more than it sounds like it does.
let micTrack: MediaStreamTrack | undefined
let cameraTrack: MediaStreamTrack | undefined
let screenTrack: MediaStreamTrack | undefined
/** The shared tab or window's own sound, captured alongside `screenTrack`
 *  when the browser offers it. Absent on Firefox, Safari, a window share, or
 *  when the person unticked the box - a share still works with no audio, it
 *  is simply silent, which is what the note near the toggle says. */
let screenAudioTrack: MediaStreamTrack | undefined
/** Whether this device's own share may be capturing KithMoot itself right
 *  now - a full-screen area, a whole screen, or a window that may be ours -
 *  and so this device's own live preview of its own share is withheld; see
 *  `applySelfMirrorGuard` and `self-mirror-guard.ts`. */
let shareMayShowItself = false

let camera: CameraPipeline | undefined
let mic: MicPipeline | undefined
const pendingMedia = new Set<CameraPipeline | MicPipeline>()
let backgroundId = BACKGROUNDS[0]?.id ?? ''

/** Whether the shoal swims over the chosen sea. Off to start with - motion
 *  behind a talking head is a thing you opt into - and remembered on this
 *  device, because nobody wants to tick it again every call. */
const FISH_STORAGE_KEY = 'kithmoot.fish.enabled'
let fishEnabled = (() => {
  try { return localStorage.getItem(FISH_STORAGE_KEY) === 'true' } catch { return false }
})()
/** Keeping you in the middle of your own picture - see `auto-frame.ts`. On
 *  unless turned off, remembered on this device. */
const FRAMING_STORAGE_KEY = 'kithmoot.camera.framing'
let framingEnabled = (() => {
  try { return localStorage.getItem(FRAMING_STORAGE_KEY) !== 'false' } catch { return true }
})()
let videoInputs: MediaDeviceInfo[] = []

const localPreviewEls = new Map<'camera' | 'screen', HTMLVideoElement>()
/** The marks overlay on each preview of a screen share, own or received -
 *  see `ShareViewer.overlay`. Swept when the preview leaves the page. */
const shareMarkOverlays = new Map<HTMLVideoElement, () => void>()
/** Drop the overlay of any preview that has left the page. Deferred, because
 *  a render builds tiles before it attaches them, and a preview mid-move
 *  reads as disconnected for a moment it will not stay disconnected. */
function sweepShareMarkOverlays(): void {
  setTimeout(() => {
    for (const [video, dispose] of shareMarkOverlays) if (!video.isConnected) { dispose(); shareMarkOverlays.delete(video) }
  }, 0)
}
// Where this device's own pictures live: one persistent holder, so the
// element showing your camera is the same element wherever it is shown. It
// sits in the preview strip under the toggles until you join, and in your
// own tile in the room from then on - you are in the room with everybody
// else, so that is where you are shown. Moved, never rebuilt: a fresh
// <video> would restart the picture, and one taken out of the document is
// paused by Chromium and stays paused (see parkPicture), so render() only
// ever reparents this holder within a single synchronous pass.
const localMediaEl = document.createElement('div')
localMediaEl.className = 'media mine'

/**
 * One tile per participant, kept between renders.
 *
 * `render()` used to empty the grid and build every tile again, on every
 * roster change - which, with heartbeats every twenty seconds from every
 * device, is several times a minute in a small call. Each rebuild took
 * every <video> out of the document and put it back in the same pass,
 * which Chromium survives without pausing the picture but not without
 * dropping its compositing layer: a black flash on every face, on a
 * regular beat, for the whole call. Now the box stays, and only the words
 * around the picture are rebuilt.
 */
const tileBoxes = new Map<string, HTMLDivElement>()
$('local').append(localMediaEl)
// One persistent <div class="media"> per remote device, holding at most one
// <video> and one <audio>. Kept outside the room grid's own lifecycle and
// re-appended into whichever tile render() builds next, so a live video
// element is never torn down and restarted just because the roster changed.
const deviceMediaEls = new Map<string, HTMLDivElement>()

function joinLinkBase(): string {
  return location.origin + location.pathname
}

function activeTracks(): MediaStreamTrack[] {
  return [micTrack, cameraTrack, screenTrack, screenAudioTrack].filter((t): t is MediaStreamTrack => t !== undefined)
}

function activeTrackRole(track: MediaStreamTrack): TrackAdvert['role'] | undefined {
  if (track === micTrack) return 'mic'
  if (track === cameraTrack) return 'camera'
  if (track === screenTrack) return 'screen'
  if (track === screenAudioTrack) return 'screen-audio'
  return undefined
}

function fragmentPayload(url: string): Partial<RoomUrlPayload> {
  const hash = new URL(url).hash.slice(1)
  if (!hash) throw new Error('join URL has no fragment')
  try {
    return JSON.parse(
      new TextDecoder().decode(base64urlnopad.decode(hash)),
    ) as Partial<RoomUrlPayload>
  } catch {
    throw new Error('join URL fragment is not valid')
  }
}

function invitationFromLocation(url: string): RoomInvitation | undefined {
  return parseRoomLink(url).invitation
}

/**
 * Resolve the room behind the current fragment.
 *
 * V2 first checks local creator state, then this tab's admission cache, then
 * performs the live one-tap rendezvous. Legacy v1 links still decode through
 * src/room.ts so old links do not break during rollout.
 */
async function roomFromLocation(): Promise<boolean> {
  if (location.hash.length <= 1) return false
  // One parser for every link the app opens, so the bounds it enforces -
  // fragment size, how many relays and ICE servers a link may name, and
  // that a public relay is wss - hold here as they do in the library.
  const parsedLink = parseRoomLink(location.href)
  // A returning account restores its live signer asynchronously. Do not
  // issue an unproved guest request while that matching signer is arriving.
  if (parsedLink.invitation && !parsedLink.invitation.persistent && identityRestoring && expectedAccount) await identityReady
  if (browserMlsPanel || import.meta.env.DEV && (browserMlsGrantPanel || browserMlsRoomPanel)) await pauseBrowserMls()

  // The room's name, when the link says. Text a stranger wrote, so it gets
  // the display-name treatment before it lands anywhere.
  roomName = parsedLink.name

  const invitation = parsedLink.invitation
  const knownSecret = secretForKnownRoom(parsedLink)
  roomRelayScope = `room:${knownSecret ? deriveRoom(knownSecret).roomId : deriveInvitationId(invitation!)}`
  if (invitation) {
    roomInvitationCapability = invitation
    invitationLinkRelays = parsedLink.relays
    const owner = loadInvitationOwner(invitation)
    // The room's own relays, when its secret is already known here: the
    // device that made it signs what it holds (or the link's, for a room
    // made before invitations carried relays); anybody else keeps what it
    // holds, or takes the link's on first sight.
    if (knownSecret) {
      const roomId = deriveRoom(knownSecret).roomId
      if (owner) relayConnections.setRoomRelays(roomId, { fixed: relayConnections.roomRelays(roomId)?.c ?? makerRoomRelays(roomId, parsedLink.relays), signed: true })
      else relayConnections.setRoomRelays(roomId, { fixed: invitationRelaysFrom(parsedLink.relays) })
    }
    // The maker's own relays are the snapshot it took when it made the room,
    // not its link's: a link names only the room's relays, and the maker may
    // also use a read-only or write-only relay of its own.
    useRoomRelays(owner && relayConnections.inherits(roomRelayScope) ? [] : parsedLink.relays)
    roomPolicy = parsedLink.policy

    if (owner) {
      roomSecret = owner.roomSecret
      roomEndsAt = owner.endsAt
      roomDestruct = owner.destruct === true
      invitationAuthoritySk = owner.inviterSk
      invitationDelegation = []
      // A room this browser made is at epoch 0: only its authority could
      // have moved it, and that is this browser, which has not.
      expectedEpoch = 0
      serveCurrentInvitation()
    } else {
      // This tab's session first, then what the person chose to keep on
      // this device, then the live rendezvous.
      const tabCached = loadCachedAdmission(invitation)
      const saved = tabCached ?? loadKeptAdmission(deviceStore, deriveInvitationId(invitation), nowSeconds())
      // An updated group link must load its signed durable invitation once,
      // so an earlier temporary grant cannot keep the twelve-hour storage rule.
      const cached = invitation.persistent && saved && 'delegate' in saved ? undefined : saved
      if (cached) {
        roomSecret = cached.secret
        roomEndsAt = 'endsAt' in cached ? cached.endsAt : undefined
        roomDestruct = 'destruct' in cached && cached.destruct === true
        admittedRoom = cached
        invitationAuthoritySk = 'delegate' in cached ? cached.delegate.delegateSk : undefined
        invitationDelegation = 'delegate' in cached ? cached.delegate.chain : []
        // A kept admission's epoch is whatever the room was at when it was
        // kept, usually 0, and says nothing about where the room is now.
        // Passed on, it would let the session skip waiting for the relays
        // to replay the rekeys and announce under a key the room has left.
        // Undefined makes it wait and see. This tab's own cache is from
        // this visit, so its hint stands, unless it is a group's (see
        // `admissionEpochHint`).
        expectedEpoch = cached === tabCached ? admissionEpochHint(cached) : undefined
        cacheAdmission(invitation, cached)
        serveCurrentInvitation()
      } else {
        $('arrivalTitle').textContent = invitation.persistent ? 'Opening this room' : roomName ? `Ask to join ${roomName}` : 'Ask to join this room'
        $('arrivalLead').textContent = invitation.persistent
          ? 'Checking the room invitation…'
          : 'Someone in the room needs to let you in. Check your details before sending a request.'
        $('arrivalLead').hidden = false
        setStatus(invitation.persistent ? 'Getting you in…' : '', 'progress')
        if (!invitation.persistent) showDoorWhileSwitching()
        admissionController?.abort()
        guestAdmissionPreview?.close()
        guestAdmissionPreview = undefined
        const pending = new AbortController()
        admissionController = pending
        let transport: ManagedRelayPool | undefined
        let preview: AdmissionPreview | undefined
        try {
          if (!invitation.persistent) {
            disarmStopOpening()
            pendingJoin = false
            $('joinRoomForm').hidden = false; $('joinRoomForm').inert = false; $('join').hidden = true
            $('identityMore').hidden = true
            $('arrivalActions').hidden = true
            renderIdentity()
            preview = new AdmissionPreview({ root: $('admissionPreview'), name: $('displayName') as HTMLInputElement,
              status: $('admissionPreviewStatus'), request: $('requestAdmission') as HTMLButtonElement,
              cancel: $('cancelAdmission') as HTMLButtonElement, camera: $('previewAdmissionCamera') as HTMLButtonElement,
              mic: $('previewAdmissionMic') as HTMLButtonElement, video: $('admissionPreviewVideo') as HTMLVideoElement,
              meter: $('admissionPreviewMeter') as HTMLMeterElement, signal: pending.signal, cancelRequest: () => pending.abort() })
            guestAdmissionPreview = preview
            await preview.ready
            if (pending.signal.aborted) throw new AdmissionPreviewCancelled(preview.requested)
            $('arrivalTitle').textContent = 'Waiting to be admitted'
            $('arrivalLead').textContent = 'Your details are ready. Someone in the room needs to accept your request.'
            armStopOpening()
          }
          const identityAtRequest = identityGeneration, generationAtRequest = roomGeneration, hashAtRequest = location.hash
          const deadline = Date.now() + KNOCK_WAIT_MS
          transport = configuredPool(relays)
          // A temporary room's link is answered by a person, who may have
          // been asked first: the request says who is asking, and the wait
          // is long enough for somebody to read a card and press a button.
          const askedAs = joiningName()
          const askedFrom = currentParticipant()
          // A cached room pass or paired device cannot sign a new account
          // proof. Use only the matching live signer or local identity.
          const proofIdentity = askedFrom === nostrSession?.pubkey ? nostrSession?.signer
            : askedFrom && !expectedAccount && !isPairedSecondary(deviceStore) ? localIdentity(participantKey()) : undefined
          preview?.phase(proofIdentity && nostrSession ? 'signing' : 'preparing')
          const requestTransport = admissionRequestTransport(transport, {
            current: () => !pending.signal.aborted && identityAtRequest === identityGeneration &&
              generationAtRequest === roomGeneration && hashAtRequest === location.hash &&
              roomInvitationCapability === invitation && Date.now() < deadline,
            phase: phase => preview?.phase(phase),
          })
          let foundFurther: string[] = []
          const admission = invitation.persistent
            ? await admitFromGroupInvitation(invitation, parsedLink.relays, transport, wider => { foundFurther = wider })
            : await requestRoomAdmissionCapability({
              transport: requestTransport, invitation, timeoutMs: KNOCK_WAIT_MS,
              signal: pending.signal,
              ...(askedAs !== undefined ? { name: askedAs } : {}),
              ...(askedFrom !== undefined ? { participant: askedFrom } : {}),
              ...(proofIdentity !== undefined ? { identity: proofIdentity } : {}),
            })
          if (pending.signal.aborted || identityAtRequest !== identityGeneration) throw new Error('Room admission cancelled.')
          roomSecret = admission.secret
          roomEndsAt = 'endsAt' in admission ? admission.endsAt : undefined
          roomDestruct = 'destruct' in admission && admission.destruct === true
          // A relay that ignores NIP-40 can still hand out the invitation of
          // a conference room that has ended. Nobody joins it.
          if (conferenceEnded(roomEndsAt, nowSeconds())) throw new Error(conferenceEndedMessage(roomEndsAt!))
          roomRelayScope = `room:${deriveRoom(roomSecret).roomId}`
          // The room's own relays: what its signed invitation names wins;
          // else the link's, on first sight.
          const signed = 'relays' in admission ? admission.relays : undefined
          relayConnections.setRoomRelays(deriveRoom(roomSecret).roomId, signed ? { fixed: signed, signed: true } : { fixed: invitationRelaysFrom(parsedLink.relays) })
          // Found beyond the link's relays: the room evidently lives there
          // too, so it is read and written there as well.
          useRoomRelays([...parsedLink.relays, ...foundFurther])
          admittedRoom = admission
          invitationAuthoritySk = 'delegate' in admission ? admission.delegate.delegateSk : undefined
          invitationDelegation = 'delegate' in admission ? admission.delegate.chain : []
          expectedEpoch = admissionEpochHint(admission)
          cacheAdmission(invitation, admission)
          // The ending to "Getting you in…". It says the waiting is over
          // and that the next move is the reader's, which is the thing they
          // could not tell while a line saying "in progress" sat under a
          // button that was ready to be pressed.
          setStatus('')
        } catch (error) {
          if (pending.signal.aborted) throw new AdmissionPreviewCancelled(preview?.requested ?? false)
          throw error
        } finally {
          pending.abort()
          preview?.close()
          if (guestAdmissionPreview === preview) guestAdmissionPreview = undefined
          if (admissionController === pending) admissionController = undefined
          transport?.close()
        }
        serveCurrentInvitation()
      }
    }
  } else {
    const { secret, relays: hinted, policy } = parsedLink
    if (!secret) throw new Error('join URL carries neither an invitation nor a secret')
    roomSecret = secret
    relayConnections.setRoomRelays(deriveRoom(secret).roomId, { fixed: invitationRelaysFrom(hinted) })
    useRoomRelays(hinted)
    roomPolicy = policy
    roomInvitationCapability = undefined
    invitationAuthoritySk = undefined
    invitationDelegation = []
  }

  profiles.setEnabled(false); profiles.setEnabled(profilesEnabled)
  iceUrls = parsedLink.iceUrls.length ? parsedLink.iceUrls : DEFAULT_ICE_URLS

  if (parsedLink.pairingCode) {
    // Drop the code out of the address bar first: it is single-use and there
    // is no reason for it to sit somewhere it could be forwarded by accident.
    const code = parsedLink.pairingCode
    history.replaceState(null, '', encodeRoomUrl(joinLinkBase(), relays, iceUrls))
    pairWithPrimary(code).catch((err) => setStatus(describeError(err)))
  }

  // An older saved invitation may predate names in room links. The rooms
  // list still knows the human name, so keep it when opening that bookmark
  // instead of replacing it with `Room deadbeef` on desktop.
  // A name the room's members chose since the link was written outranks
  // the one on the link: the newest rename this device read, kept with its
  // order key (see `adoptSharedRoomName`).
  roomName = loadRoomNameRecord(currentRoomId() ?? '')?.name ?? roomName
  if (!roomName) roomName = knownRooms(roomStore()).find((room) => room.roomId === currentRoomId())?.name
  // A room shared through a project carries its name in the project's
  // encrypted directory rather than in its link. Adopt it as this device's
  // label, so the room is not "Untitled room" here; it goes no further than
  // where a named room's own name already goes.
  if (!roomName) roomName = projectRoomName(currentRoomId())
  // A membership kept before conference rooms existed, or adopted from a
  // bookmark, may not carry the end; the rooms list does.
  if (invitation?.persistent) roomEndsAt ??= knownRoom(roomStore(), currentRoomId() ?? '')?.endsAt
  // The same for self-destruct, which also sticks once any copy said so.
  if (invitation?.persistent && roomIsDestruct(currentRoomId())) roomDestruct = true

  // A conference room whose end has come opens for nobody, the person who
  // made it included: its end is the point of it. Said with the date, and
  // written down so the list shows it ended.
  if (conferenceEnded(roomEndsAt, nowSeconds())) {
    const roomId = currentRoomId()
    if (roomId) for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) markEnded(store, roomId, roomEndsAt!)
    stopInvitationHost()
    // A self-destructing room that ended while this device was away goes now.
    if (roomDestruct) { void runDueDestructs(); throw new Error(SELF_DESTRUCTED_MESSAGE) }
    throw new Error(conferenceEndedMessage(roomEndsAt!))
  }

  // Admitted, one way or another: this is now a room this device has been
  // in, and the list on the front page will offer it again - and, if the
  // person chose to keep it here, readable from there.
  rememberCurrentRoom()
  refreshKeptAdmission()
  if (invitation && !loadInvitationOwner(invitation)) readRoomRelaysOnce(invitation, deriveRoom(roomSecret).roomId)
  return true
}

/**
 * Ask the primary device for a credential and remember it.
 *
 * The participant key is not transferred and never has been: what arrives is
 * a credential for this room that expires, signed by the other device.
 */
async function pairWithPrimary(code: Uint8Array): Promise<void> {
  const generation = roomGeneration
  ++roomOperation
  // Joining before the credential lands would mint a fresh participant key
  // and put this device in the room as a stranger - the exact thing pairing
  // exists to avoid. So the button is held until the exchange settles.
  const joinBtn = $('join') as HTMLButtonElement
  joinBtn.disabled = true
  setStatus('Asking your other device to add this one\u2026')

  const { roomId, roomKey } = deriveRoom(roomSecret)
  const transport = configuredPool(relays)
  try {
    const credential = await requestPairing({
      transport,
      roomId,
      roomKey,
      code,
      deviceSk: deviceKey(),
      expiresAt: roomEndsAt,
    })
    if (generation !== roomGeneration) return
    storeCredential(credential)
    setStatus('This device is now part of that person. Join when ready.')
  } finally {
    transport.close()
    --roomOperation
    if (generation === roomGeneration) joinBtn.disabled = false
  }
}

// isDefaultIceUrls (imported from ice-defaults.ts) is the gate for whether
// it is this app's own default TURN server (and so this app's own
// credential endpoint) that is in play, versus a room naming its own ICE
// servers - see the design principle at the top of deploy/README.md: the
// room names its own STUN/TURN, and an operator's minted credential must
// never be attached to a server the room never asked for. It also
// recognises the old literal Google default an existing link may still
// carry as the default, so those rooms are upgraded to this origin's own
// STUN/TURN rather than kept on Google's server - see ice-defaults.ts.

/** Fetches one TURN credential from the configured minting endpoint. A
 *  malformed or slow response is treated the same as no endpoint at all -
 *  callers decide the fallback, this only ever resolves to a usable
 *  RTCIceServer or undefined, never throws past its own timeout. */
async function fetchTurnCredential(endpoint: string): Promise<RTCIceServer | undefined> {
  const controller = new AbortController()
  // A credential endpoint that's down should fail fast, not hold up
  // joining until the browser's own connect timeout - see the "never
  // block joining" note on resolveIceServers below.
  const timeout = setTimeout(() => controller.abort(), 4000)
  try {
    const res = await fetch(endpoint, { signal: controller.signal })
    if (!res.ok) return undefined
    const body = (await res.json()) as Partial<{
      urls: string[]
      username: string
      credential: string
    }>
    if (!Array.isArray(body.urls) || body.urls.length === 0 || !body.username || !body.credential) {
      return undefined
    }
    return { urls: body.urls, username: body.username, credential: body.credential }
  } catch {
    return undefined
  } finally {
    clearTimeout(timeout)
  }
}

/**
 * Turns the room's ICE URL list into the RTCIceServer list a real
 * RTCPeerConnection gets, fetching a minted TURN credential to attach to
 * the operator's own default TURN server when one is configured and this
 * room is actually using that default (see isDefaultIceUrls).
 *
 * A room naming its own ICE servers gets exactly those, unchanged. A room
 * on the defaults gets nothing named by this bundle: this origin's own
 * STUN, derived from wherever the minted TURN credential actually points
 * (stunFromTurnUrl) when the credential endpoint answers, or a same-host
 * guess on the standard port when it doesn't (originStunGuess) - see
 * ice-defaults.ts for why, and docs/decisions.md, 2026-09-13.
 *
 * A failed or unreachable credential endpoint must never block joining: a
 * room that only has STUN still works for roughly 80% of real connections
 * (see deploy/README.md), and a call that refuses to start because an
 * optional convenience server had a bad day is a strictly worse outcome
 * than one that just falls back to what already worked before this
 * endpoint existed.
 */
async function resolveIceServers(urls: string[]): Promise<RTCIceServer[]> {
  if (!isDefaultIceUrls(urls)) {
    return urls.map((iceUrl) => ({ urls: iceUrl }))
  }

  if (!TURN_CREDENTIAL_ENDPOINT) {
    return originStunGuess(location).map((iceUrl) => ({ urls: iceUrl }))
  }

  const fetchedTurnServer = await fetchTurnCredential(TURN_CREDENTIAL_ENDPOINT)
  if (!fetchedTurnServer) {
    return originStunGuess(location).map((iceUrl) => ({ urls: iceUrl }))
  }
  const compatibleTurnUrls = browserDefaultTurnUrls(toUrlList(fetchedTurnServer.urls))
  if (compatibleTurnUrls.length === 0) {
    return originStunGuess(location).map((iceUrl) => ({ urls: iceUrl }))
  }
  const turnServer: RTCIceServer = { ...fetchedTurnServer, urls: compatibleTurnUrls }

  // The same host and port the minted credential just proved answers plain
  // TURN on, not a second guess at this origin's hostname. A TURN/TLS URL
  // remains available for relaying but is not duplicated as STUN/TLS: that
  // optional ICE protocol makes Safari reject the whole configuration. The
  // redundant plain TURN/TCP query form has also been removed above because
  // WebKit rejects that URL; TURN/TLS still supplies the TCP route.
  const stunUrls = [...new Set(toUrlList(turnServer.urls).map(stunFromTurnUrl).filter((u): u is string => u !== undefined))]
  return [...stunUrls.map((iceUrl) => ({ urls: iceUrl })), turnServer]
}

/** An RTCIceServer's `urls` is a string or a list of them. */
function toUrlList(urls: string | string[]): string[] {
  return typeof urls === 'string' ? [urls] : urls
}

function parseIceInput(): string[] {
  const raw = ($('iceServers') as HTMLInputElement).value
  const parsed = raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
  const safe = safeIceUrls(parsed)
  return safe.length ? safe : DEFAULT_ICE_URLS
}

// ---------------------------------------------------------------------------
// Peer assist: the room's spare uplink comes from the people in it.
//
// Opt in, never on by default, and never quietly. Relaying spends this
// person's bandwidth and battery on somebody else's call, so the only thing
// that turns it on is them deciding to, and the only defaults here are about
// whether to put the question in front of them at all.
// ---------------------------------------------------------------------------

/** The person's own choice. Opt in, always - see `assistDecision`. */
let assistEnabled = false

/** What this device is carrying for other people, if anything. */
const peerRelay = new PeerRelay()

/** Reachability, measured from the candidates this device actually gathers,
 *  never guessed from a user agent. Fed by every connection the mesh opens. */
const reachability = new ReachabilityProbe()

/** What this device has spare, measured from its own connections - see
 *  `UplinkProbe`. Nothing else in this file invents a bandwidth figure, and
 *  before this has two samples of something the honest answer is "we have not
 *  measured", which `assistDecision` reads as a refusal. */
const uplink = new UplinkProbe()

/** Every connection currently open, so the probe above has something to
 *  sample. Keyed by rung and remote device, because the mesh opens a fresh
 *  connection per rung and the old one lingers until it is closed. */
const openConnections = new Map<string, RTCPeerConnection>()

/** Makes each connection's key its own, so a connection closing can only ever
 *  forget its own measurement. */
let connectionSeq = 0

/** Whether this browser can forward encoded frames without decoding them.
 *  Measured against the objects, not the user agent - see
 *  `detectRelayCapability`. Chromium can; Safari and Firefox expose only
 *  `RTCRtpScriptTransform` and have not been measured carrying a frame
 *  through it, so they are read as unable until somebody has. */
const relayCapability = detectRelayCapability()

/** True when the platform says this is a phone. `navigator.userAgentData` is
 *  a proper API rather than a user-agent string parse, and where it is absent
 *  the honest answer is "we could not tell" - which `assistDecision` reads as
 *  "do not volunteer this by default". */
function formFactor(): AssistEnvironment['formFactor'] {
  const data = (navigator as Navigator & { userAgentData?: { mobile?: boolean } }).userAgentData
  if (typeof data?.mobile !== 'boolean') return undefined
  return data.mobile ? 'mobile' : 'desktop'
}

/** True when the connection is metered or the person has asked for data
 *  saving. Undefined where the platform will not say. */
function metered(): boolean | undefined {
  const connection = (navigator as Navigator & {
    connection?: { saveData?: boolean; type?: string }
  }).connection
  if (!connection) return undefined
  if (connection.saveData === true) return true
  if (connection.type === 'cellular') return true
  return undefined
}

/** Set from the Battery Status API where it exists. Left undefined where it
 *  does not, which several browsers have removed on privacy grounds. */
let onBattery: boolean | undefined
void (async () => {
  const getBattery = (navigator as Navigator & {
    getBattery?: () => Promise<{ charging: boolean; addEventListener(type: string, cb: () => void): void }>
  }).getBattery
  if (!getBattery) return
  try {
    const battery = await getBattery.call(navigator)
    const read = (): void => {
      onBattery = !battery.charging
      renderAssist()
    }
    read()
    battery.addEventListener('chargingchange', read)
  } catch {
    // No answer is a perfectly good answer here - see `assistDecision`.
  }
})()

function assistEnvironment(): AssistEnvironment {
  return {
    reachability: reachability.reachability,
    canRelay: relayCapability.canForwardFrames,
    capacity: uplink.capacity(),
    formFactor: formFactor(),
    onBattery,
    metered: metered(),
  }
}

function currentAssistOffer(): AssistOffer | null {
  return buildAssistOffer(assistEnvironment(), peerRelay.relaying, assistEnabled)
}

/**
 * Whether to put the question in front of this person at all.
 *
 * A phone on mobile data is the one case where the control is not shown, only
 * explained. `assistDecision` would still permit it - it is their allowance to
 * spend, and the library does not get to refuse on their behalf - but offering
 * somebody a button that bills them by the byte for a stranger's video is not
 * a question worth asking, and a phone that answers it by accident pays for it.
 *
 * Everywhere else the control appears, always off, with whatever is standing
 * against it written underneath. Where a platform will not say whether it is
 * metered or on battery, that is a thing to tell somebody rather than a thing
 * to assume either way.
 */
function assistOfferable(): boolean {
  return !(formFactor() === 'mobile' && metered() === true)
}

// ---------------------------------------------------------------------------
// Saying what it costs, in numbers that were measured
// ---------------------------------------------------------------------------

function bitrate(bps: number): string {
  if (!Number.isFinite(bps) || bps <= 0) return 'nothing'
  if (bps >= 1_000_000) return `${(bps / 1_000_000).toFixed(1)} Mbps`
  return `${Math.round(bps / 1000)} kbps`
}

function quantity(bytes: number): string {
  if (bytes >= 1_000_000_000) return `${(bytes / 1_000_000_000).toFixed(1)} GB`
  if (bytes >= 1_000_000) return `${Math.round(bytes / 1_000_000)} MB`
  return `${Math.round(bytes / 1000)} kB`
}

/** What one pair costs this device: the pair's media in, and the same back
 *  out again to the far end. */
function costPerPairBps(): number {
  return uplink.capacity().perPeerBps * ASSIST_STREAMS_PER_PAIR
}

/** Whoever is in the room, by device, so a carried pair can be named rather
 *  than shown as two truncated keys. */
function nameOfDevice(device: string): string {
  const target = device.toLowerCase()
  for (const view of session?.participants() ?? []) {
    if (!view.devices.some((d) => d.toLowerCase() === target)) continue
    return shownAs(view.participant, view.name).name ?? shortKey(device)
  }
  return shortKey(device)
}

/** The one sentence that has to be true: what this costs, per person, right
 *  now, from measurements rather than from a table of typical bitrates. */
function costSentence(): string {
  const perPair = costPerPairBps()
  if (perPair <= 0) {
    return 'Nothing has been measured yet. Once there is video or sound moving, this will say what helping one pair really costs, instead of guessing.'
  }
  return (
    `About ${bitrate(perPair)} of what you send, for each pair you help, and the same again coming in. ` +
    `Three pairs at full stretch is about ${bitrate(perPair * MAX_ASSISTED_PAIRS)} going out.`
  )
}

/** Why this device is not being recommended, or cannot help at all, in the
 *  order somebody would want to hear it. */
function blockSentence(block: AssistBlock): string {
  switch (block) {
    case 'no-relay-support':
      return 'This browser cannot pass video on without unpacking it first, so it cannot help anybody. Chrome and Edge can. Safari and Firefox look like they can but have never actually managed it.'
    case 'not-publicly-reachable':
      return 'Other people cannot reach this device directly through your router, going by the addresses it found. Offering to help would point them at a way in that is not there.'
    case 'no-spare-uplink':
      return uplink.measured()
        ? 'Your connection has nothing left over once your own call is paid for.'
        : 'Your connection has not been measured yet. Join a room, give it a few seconds, and this fills in.'
    case 'mobile':
      return formFactor() === undefined
        ? 'This browser will not say whether it is a phone. If it is, leave this off.'
        : 'This is a phone. Helping somebody uses its battery and its signal for as long as they need it.'
    case 'on-battery':
      return 'Running on battery. Helping somebody means sending steadily and working hard, and you will notice.'
    case 'metered':
      return 'This connection is one you pay for by the amount used, or you have asked to save data. Somebody is paying for every byte.'
  }
}

/**
 * The control and the indicator.
 *
 * Called on every render and on every poll tick, so "you are carrying two
 * people" is on screen within a second or two of becoming true rather than
 * whenever something else happened to redraw.
 */
function renderAssist(): void {
  const section = $('assist')
  const button = $('toggleAssist') as HTMLButtonElement
  const indicator = $('assistIndicator')
  const costNote = $('assistCostNote')

  section.hidden = session === undefined
  costNote.textContent = costSentence()

  if (!assistOfferable()) {
    // Not a disabled button: a control that cannot be used is still a control
    // somebody has to work out, and this one is never going to be usable here.
    button.hidden = true
    $('assistCost').hidden = true
    indicator.textContent =
      'Not offered on a phone using mobile data. Helping somebody would spend your data and your battery on their call.'
    indicator.classList.remove('mine')
    return
  }

  button.hidden = false
  $('assistCost').hidden = false

  const decision = assistDecision(assistEnvironment(), assistEnabled)
  const hard = decision.blocks.filter((block) => HARD_ASSIST_BLOCKS.includes(block))
  const soft = decision.blocks.filter((block) => !HARD_ASSIST_BLOCKS.includes(block))

  button.disabled = hard.length > 0 && !assistEnabled
  setToggle('toggleAssist', assistEnabled)
  button.setAttribute('aria-pressed', String(assistEnabled))

  if (hard.length > 0) {
    indicator.textContent = hard.map(blockSentence).join(' ')
    indicator.classList.remove('mine')
    return
  }

  if (!assistEnabled) {
    indicator.textContent = soft.length
      ? soft.map(blockSentence).join(' ')
      : `Your connection has room to spare, so it could help other people get through. ${costSentence()}`
    indicator.classList.remove('mine')
    return
  }

  const pairs = peerRelay.pairs
  if (pairs.length === 0) {
    indicator.textContent = soft.length
      ? `Offering to help. Nobody has needed it yet. ${soft.map(blockSentence).join(' ')}`
      : 'Offering to help. Nobody has needed it yet.'
    indicator.classList.remove('mine')
    return
  }

  // Named rather than counted: "carrying Priya and Sam" is a thing somebody
  // can check against the room in front of them, and a number is not.
  const carried = pairs.map((pair) => `${nameOfDevice(pair.a)} and ${nameOfDevice(pair.b)}`).join(', ')
  const stats = peerRelay.stats
  indicator.textContent =
    `Helping ${pairs.length} of ${peerRelay.max}: ${carried}. ` +
    `About ${bitrate(costPerPairBps() * pairs.length)} going out, ${quantity(stats.bytesOut)} passed on so far.`
  indicator.classList.add('mine')
}

/** Which blocks no amount of willingness can get past. Mirrors the split
 *  `assistDecision` makes, which is not exported as a list. */
const HARD_ASSIST_BLOCKS: readonly AssistBlock[] = ['no-relay-support', 'not-publicly-reachable', 'no-spare-uplink']

/**
 * Sample every open connection, then say what changed.
 *
 * One `getStats()` per connection per tick and nothing else: no probe
 * traffic, no extra sockets. Two seconds is fast enough that the indicator
 * tracks a call somebody is watching, and slow enough to be free.
 */
async function pollAssist(): Promise<void> {
  const generation = roomGeneration
  const now = Date.now()
  for (const [key, pc] of [...openConnections]) {
    if (pc.connectionState === 'closed') {
      openConnections.delete(key)
      uplink.forget(key)
      continue
    }
    try {
      const stats: StatLike[] = []
      ;(await pc.getStats()).forEach((stat) => stats.push(stat as StatLike))
      if (generation !== roomGeneration) return
      uplink.update(key, stats, now)
    } catch {
      // A connection that will not answer for its own statistics tells us
      // nothing, which is exactly what it contributes until it does.
    }
  }

  // An offer that has gone stale in either direction is the failure this
  // whole module argues against: advertising a capability that is no longer
  // there, or sitting on one that is. Either way the roster is republished
  // and the relay's own gate is brought back into step with it.
  const offering = currentAssistOffer() !== null
  const carrier = mediaSession()
  if (carrier && offering !== lastOffering) {
    lastOffering = offering
    void carrier.setAssist(currentAssistOffer).catch(() => {})
  }
  renderAssist()
}

let lastOffering = false
let assistTimer: ReturnType<typeof setInterval> | undefined

function startAssistPolling(): void {
  if (assistTimer !== undefined) return
  assistTimer = setInterval(() => void pollAssist(), 2000)
}

/**
 * Turn carrying on or off.
 *
 * Off is the case that has to work properly. It stops carrying everybody
 * before it stops advertising, so there is no window where the room believes
 * an offer already withdrawn, and the pairs that were being carried fall to
 * the next rung of their own ladder. Nothing about this device's own call
 * changes either way.
 */
async function toggleAssist(): Promise<void> {
  if (!assistOfferable()) return
  assistEnabled = !assistEnabled
  renderAssist()
  try {
    await session?.setAssist(assistEnabled ? currentAssistOffer : null)
    lastOffering = currentAssistOffer() !== null
  } catch (err) {
    setStatus(describeError(err))
  }
  renderAssist()
}

/** Whether this browser is the one that opened this room, as opposed to
 *  one that followed a link into it. A joiner is handed a delegated key of
 *  its own, so the presence of a key says nothing about which of the two
 *  you are; only having been here when the room was made does. */
let startedHere = false

async function startNewRoom(): Promise<void> {
  return withLegacyMessagesClosed(async () => {
    // "People ask, and somebody lets them in" is a temporary-style room: the
    // link makes a person ask, and a device in the room answers - after
    // asking its owner, see `askToLetIn`. It cannot be self-service from the
    // relay, which is exactly the point, and it is why such a room needs
    // somebody online to let people in.
    const ask = ($('roomAsk') as HTMLInputElement).checked
    const persistent = !ask
    // Only a group can be a conference room: a meeting that asks before
    // anybody joins already ends when its people leave.
    const endsChoice = ($('roomEnds') as HTMLSelectElement).value
    if (persistent && endsChoice === 'duration' && roomDurationSeconds() === 0) throw new Error('Choose at least one minute for the room lifetime.')
    const endsAt = !persistent ? undefined
      : endsChoice === 'duration' ? nowSeconds() + roomDurationSeconds()
      : endsChoice === 'test' && TEST_ROOM_END_SECONDS ? nowSeconds() + TEST_ROOM_END_SECONDS
        : conferenceEndsAt(Number(endsChoice), nowSeconds())
    // Self-destruct is a property of a group: by its date, or when ended.
    const destruct = persistent && endsAt !== undefined && ($('roomWhenEnds') as HTMLSelectElement).value === 'destruct'
    const secret = generateRoomSecret()
    const created = createRoomInvitation(persistent)
    setKnock(deriveRoom(secret).roomId, ask)
    const relayScope = `room:${deriveRoom(secret).roomId}`
    // Snapshot access modes too: an invitation carries URLs, so reconstructing
    // this room from its link must not turn a read-only default into a writer.
    relayConnections.inheritDefaults(relayScope)
    // The room's own relays: the ones this device reads and writes, fixed
    // now and named in its signed invitation, so every member uses them.
    const roomRelays = invitationRelaysFrom(relayConnections.configuration(relayScope.replace(/^room:/, 'inherited:')).filter(relay => relay.read && relay.write).map(relay => relay.url))
    relayConnections.setRoomRelays(deriveRoom(secret).roomId, { fixed: roomRelays, signed: true })
    // Persist the owner's recovery before publishing. Failure leaves the form
    // usable and never offers a link whose asynchronous admission was not saved.
    storeInvitationOwner(created.invitation, secret, created.inviterSk, endsAt, destruct)
    if (persistent) await publishGroupInvitation(created.invitation, secret, created.inviterSk, RELAYS, { endsAt, destruct, roomRelays })
    startedHere = true
    admittedRoom = undefined
    roomEndsAt = endsAt
    roomDestruct = destruct
    roomStartsAt = nowSeconds()
    expectedEpoch = 0
    roomPolicy = undefined
    roomSecret = secret
    roomInvitationCapability = created.invitation
    invitationAuthoritySk = created.inviterSk
    invitationDelegation = []
    roomRelayScope = relayScope
    useRoomRelays()
    iceUrls = parseIceInput()
    roomName = sanitiseDisplayName(($('roomName') as HTMLInputElement).value)
    profiles.setEnabled(false); profiles.setEnabled(profilesEnabled)
    serveCurrentInvitation()
    history.replaceState(null, '', encodeRoomUrl(joinLinkBase(), relays, iceUrls))
    rememberCurrentRoom()
  })
}

/** The "Open in the KithMoot app" button: browsers on Android and on a
 *  computer the desktop app runs on, never inside the desktop app itself,
 *  and only for the room an invitation link opened. See open-in-app.ts. */
function renderOpenInApp(): void {
  const invited = OPENED_FROM_LINK && !linkArrivalOver
  const platform = !invited || import.meta.env.VITE_DESKTOP === 'true' ? undefined : appPlatform(navigator.userAgent, navigator.maxTouchPoints)
  const appLink = platform ? appLinkFor(location.href) : undefined
  $('openInApp').hidden = appLink === undefined
  if (appLink !== undefined) ($('openInAppLink') as HTMLAnchorElement).href = appLink
  const get = $('getAndroidApp') as HTMLAnchorElement
  get.href = platform === 'desktop' ? DESKTOP_DOWNLOAD_URL : ANDROID_DOWNLOAD_URL
  get.textContent = platform === 'desktop' ? 'Get KithMoot for your computer' : 'Get KithMoot for Android'
  $('getAndroidLine').hidden = appLink === undefined
}

function renderDoorBothyRecovery(): void {
  const room = currentRoomId(), button = $('doorBothyRecovery')
  button.hidden = true
  if (!room) return
  void browserRoomRoutes.store.all().then(consents => {
    if (currentRoomId() !== room) return
    button.hidden = !consents.some(c => c.room === room && c.phase !== 'retired')
  }).catch(() => {
    // Corrupt or unavailable consent still needs the recovery surface;
    // joining must never become the prerequisite for inspecting its error.
    if (currentRoomId() === room) button.hidden = false
  })
}

/**
 * The door, and only the door.
 *
 * A person handed a link came to read what was said and to say something
 * back. Everything used to set a room UP - the camera, the share link, the
 * pairing pass, the notification switch - waits behind `showRoomTools()`
 * until they are actually inside, because until then none of it has
 * anything to be about. What is left is a name and a way in.
 */
function showRoomUi(): void {
  renderDoorBothyRecovery()
  $('home').hidden = true
  $('identity').hidden = false
  $('joinRoomForm').hidden = false
  $('arrivalActions').hidden = true
  $('arrivalActions').before($('status'))
  $('notify').hidden = true
  hideRoomsList()
  // A room, or its door, is the main pane: below 900 px it sits over the list.
  showRoomPane()
  // At the door of a room the way back to the list is here, because the
  // room's own bar does not exist until you are inside. The way back INTO a
  // room has been taken.
  $('roomNav').hidden = false
  $('doorToRooms').hidden = false
  $('backToRoom').hidden = true
  forgetWayBack()
  renderRoomTitle()
  // The tagline has just gone and the way back has just appeared, so where
  // the room starts is not where it started a moment ago.
  renderKeepChoice()
  renderArrival()
  renderOpenInApp()
  $('join').hidden = false
  tryPendingJoin()
  ;($('shareUrl') as HTMLInputElement).value = encodeRoomUrl(joinLinkBase(), relays, iceUrls)
  ;($('shareRoom') as HTMLButtonElement).hidden = navigator.share === undefined
  ;($('rotateShare') as HTMLButtonElement).hidden =
    roomInvitationCapability === undefined || invitationAuthoritySk === undefined || invitationDelegation.length !== 0
  // The sentence about a new link goes with the button that makes one.
  // Only the browser that opened the room has that button, so everybody
  // else was reading about a control that was not on their page.
  $('rotateNote').hidden = ($('rotateShare') as HTMLButtonElement).hidden
  renderEndRoom()
  $('makePersistent').hidden = Boolean(roomInvitationCapability?.persistent) || $('rotateNote').hidden
  $('invitationAvailability').textContent = roomInvitationCapability?.persistent
    ? 'This group stays available when everyone closes the app. Anyone with this invitation can join and read its shared history.'
    : 'Keep a member’s tab open to admit newcomers. Temporary invitation permissions last up to twelve hours.'
}

/** Everything that is not the conversation, revealed once there is a
 *  conversation for it to be about - which now means putting it in the
 *  room's details rather than on the screen. */
function showRoomTools(): void {
  // In the room now, and the room's own bar carries the way out of it.
  $('roomNav').hidden = true
  $('doorToRooms').hidden = true
  renderWorkspace()
  // Notifications are a front-page control as well as a room one, so the
  // markup lives in `main` for the rooms list. In a room it belongs in the
  // details with everything else, and it is moved rather than duplicated:
  // one element, one set of listeners, one truth about its state. Leaving
  // a room reloads the page, so it never needs moving back.
  // The one line the page uses to say something went wrong belongs where
  // the person is looking. It is written in `main` for the join screen and
  // the rooms list; in a room it moves under the box to write in, because
  // the room takes the whole screen and anything after it is below the
  // fold. Moved rather than duplicated, and leaving a room reloads.
  $('roomArea').append($('status'))
}

/**
 * The call.
 *
 * Camera, microphone and screen share were three buttons on the message
 * screen at all times, in a room where most of the time nobody is on a
 * call. A phone shows call controls during a call and a call button the
 * rest of the time; so does this. Anything of yours that is live keeps the
 * controls open, because a control that hides while it is doing something
 * is how a camera ends up on with nobody watching.
 */
function setCallOpen(open: boolean): void {
  const bay = $('callBay')
  if (open && bay.hidden) showMobileRoomView('call')
  if (!open) showMobileRoomView('chat')
  bay.hidden = !open
  // The controls themselves start hidden in the markup, because until the
  // room is on screen there is nothing for them to be about.
  $('deviceControls').hidden = !open
  $('callToggle').setAttribute('aria-expanded', String(open))
  $('callToggle').dataset.on = String(open)
  renderDock()
}

function callIsLive(): boolean {
  return Boolean(micTrack ?? cameraTrack ?? screenTrack)
}

// ---------------------------------------------------------------------------
// The call, as a thing.
//
// Until September 2026 "a call" meant "this device has a track": nobody could
// start one for other people to join, and a person with everything switched
// off looked exactly like one who had never joined. Now a call is a
// membership carried on presence - see `RosterEntry.call` - so Start, Join,
// Leave and "Rowan started a call, 2 on it" are all things the room can say.
// ---------------------------------------------------------------------------

/** On the call, whatever is or is not switched on. */
function onCall(): boolean {
  return mediaSession()?.call !== undefined
}

/**
 * Holds this device's screen on for as long as it is on the call: requested
 * in `joinCall`, released in `leaveCall`, on leaving the room, and on the
 * page itself going away. See app/src/wake-lock.ts for why it also has to
 * re-request itself on `visibilitychange` - the browser drops the lock the
 * moment the tab is hidden, with no event of its own to say so until it is
 * looked at again.
 */
const callWakeLock = new CallWakeLock({ onStateChange: () => renderWakeLockNote() })
const incomingCallTracker = new IncomingCallTracker()

function resetIncomingCall(): void {
  if (incomingCallTracker.reset()?.type === 'stop') stopCallRing()
  hideRingBanner()
}

// ---------------------------------------------------------------------------
// The ring banner (design-calm-shell 6.5): a call has started in the room on
// screen and this device is not on it. Pinned to the top of the window, in
// the top layer, with focus on Answer. Answer is the join path with the
// microphone on and the camera off, whatever kind of call it is. Decline and
// Escape stop the ringing and put the banner away: nothing is sent and
// nobody is told. Out of scope here: rings for rooms that are not open,
// ringing a contact with no private chat, notification actions, and an
// outgoing "Ringing Priya…".
// ---------------------------------------------------------------------------

let ringTimer: ReturnType<typeof setTimeout> | undefined

/** The ring (banner and sound) gives up after `seconds`, as a phone does. */
function giveUpRingingAfter(seconds: number): void {
  clearTimeout(ringTimer)
  ringTimer = setTimeout(() => { stopCallRing(); hideRingBanner() }, seconds * 1000)
}

function showRingBanner(caller: string): void {
  const banner = $('ringBanner')
  $('ringBannerTitle').textContent = `${caller} is calling`
  // The call does not say whether it is voice or video, so it is a "Call".
  $('ringBannerKind').textContent = 'Call'
  const wasOpen = banner.matches(':popover-open')
  if (!wasOpen) banner.showPopover()
  $('ringAnswer').focus({ preventScroll: true })
}

function hideRingBanner(): void {
  clearTimeout(ringTimer)
  ringTimer = undefined
  const banner = $('ringBanner')
  if (banner.matches(':popover-open')) banner.hidePopover()
}

$('ringDecline').addEventListener('click', () => { stopCallRing(); hideRingBanner() })
$('ringBanner').addEventListener('keydown', event => {
  if (event.key !== 'Escape') return
  event.preventDefault()
  stopCallRing()
  hideRingBanner()
})
$('ringAnswer').addEventListener('click', () => {
  stopCallRing()
  hideRingBanner()
  void (async () => {
    await joinCall()
    // Straight in with the microphone live and the camera off, like Signal.
    if (!micTrack && onCall()) await toggleMic()
  })().catch(err => noteMediaBlocked('Microphone', err))
})

/** The quiet line under the call controls saying the screen might sleep
 *  here. Worth saying only when it might actually happen - no Wake Lock API,
 *  or a request refused - and only while on the call; off it, or with the
 *  lock actually held, it would be a line answering a question nobody
 *  asked. */
function renderWakeLockNote(): void {
  const note = $('wakeLockNote')
  note.hidden = !onCall() || (callWakeLock.state !== 'unsupported' && callWakeLock.state !== 'error')
}

/**
 * Pressed Leave, and not Join since.
 *
 * Not the same as "not on the call". Somebody who has just walked into a
 * room where a call is on sees and hears it before pressing anything - the
 * media acceptance test pins that, and it is right: a person is not a
 * spectator for having brought nothing. Somebody who has pressed Leave has
 * said the opposite, and for them the pictures park and the sound stops
 * until they press Join.
 */
let leftCall = false

/**
 * The person has asked for this device to be on a call - pressed Join, or
 * switched a microphone, camera or share on - and has not pressed Leave
 * since. The only thing that lets `publishActiveTracks` start a call rather
 * than join the one that is on: see `callToDeclare`.
 */
let callWanted = false

/**
 * Leave was pressed and has not finished.
 *
 * Set before anything is torn down and cleared only once the panes have
 * been repainted, so every call control reads "on the way out" for the
 * whole of it. Without this, the moment between "this device stopped saying
 * it is on the call" and "the roster agrees" painted the join door - see
 * app/src/call-stance.ts for why that is our own shadow and not a race.
 */
let leavingCall = false

/**
 * What every call control is looking at: this device's own membership, how
 * many OTHER devices are on the room's current call, and whether a leave is
 * in flight. Other devices, never the roster's count of people, because
 * this device's own entry outlives its leave by a beat.
 */
function callStanceNow(views: ParticipantView[]): CallStanceInput {
  const current = (mediaSession()?.calls() ?? [])[0]
  let otherDevicesOn = 0
  if (current) {
    for (const view of views) {
      if (view.call?.id !== current.id) continue
      // Own other devices count. A call taken on the laptop is one this
      // window may join, and the notice about it says so.
      otherDevicesOn += view.call.devices.filter(device => device !== myDeviceId).length
    }
  }
  return { mineOn: onCall(), otherDevicesOn, leaving: leavingCall }
}

function newCallId(): string {
  return bytesToHex(crypto.getRandomValues(new Uint8Array(16)))
}

// ---------------------------------------------------------------------------
// One call per device, across this browser's tabs
//
// Two tabs signed in as the same account share one device key - see
// room-tabs.ts, which coordinates the same fact for leaving a room outright.
// This is the narrower, more damaging case: both tabs open on the same
// room, and the one not on the call keeps heartbeating "no tracks" under
// the identical device key - see Session.pausePresence for why that orphans
// the other tab's live media. call-tab-lock.ts is the wire protocol; this is
// how the app answers it: whichever tab is not the call holder for this
// room's device key goes quiet and says so.
// ---------------------------------------------------------------------------

/** The call-tab-lock key for this device's call on the current room, or
 *  undefined outside a room. */
function callLockKey(): string | undefined {
  const roomId = dockedCall ? dockedCall.room.roomId : currentRoomId()
  return roomId && myDeviceId ? `${roomId}|${myDeviceId}` : undefined
}

/** The call-tab-lock key another tab currently holds for this device, if
 *  this tab knows of one - cleared the moment it is freed or this tab takes
 *  it back. */
let heldElsewhereKey: string | undefined

function renderCallTabNotice(): void {
  const held = heldElsewhereKey !== undefined && heldElsewhereKey === callLockKey()
  const notice = $('callTabNotice')
  notice.hidden = !held
  if (held) $('callTabNoticeText').textContent = "This room's call is open in another tab."
}

// A rolling, redacted record of what happened during this call, and a
// per-pair health sampler that turns single-snapshot stats into "is it
// actually moving". Both feed `collectDiagnostics` below; see
// app/src/call-timeline.ts for what they will and will not record.
const callTimeline = new CallTimeline()

/** Which call this device said it was on, and why a call rang or did not.
 *  To the timeline for a pasted report, and to the console as well: the
 *  timeline keeps ten minutes, and a ring nobody can explain is usually
 *  asked about later than that. Short ids only, as the timeline takes. */
function logCall(kind: 'call-declared' | 'call-ring', who: string | undefined, detail: string): void {
  callTimeline.record(kind, who, detail)
  console.info(`[kithmoot] ${kind}${who ? ` ${who.slice(0, 8)}` : ''}: ${detail}`)
}
const pairHealthSampler = new PairHealthSampler()

/**
 * Which call signalling profile this device advertises, decided once per page
 * load and off unless somebody turned it on.
 *
 * Read here rather than at each room join so a person cannot end up with one
 * room on each profile in the same tab, and so the answer is in the bug
 * report whatever they do next. Turning it on lasts this page session;
 * turning it off is remembered for good. See app/src/call-profile.ts.
 */
const callProfile = readCallProfile(location.search, localStorage, sessionStorage)
const advertTracker = new AdvertTracker()

const callTabLock = new CallTabLock({
  onPreempted: (key) => {
    if (key !== callLockKey()) return
    heldElsewhereKey = key
    callTimeline.record('call-tab-lock', undefined, 'preempted')
    leaveCall('preempted').then(() => {
      session?.pausePresence()
      renderCallTabNotice()
    }).catch(() => {})
  },
  onHeldElsewhere: (key) => {
    if (key !== callLockKey() || onCall()) return
    heldElsewhereKey = key
    callTimeline.record('call-tab-lock', undefined, 'held-elsewhere')
    session?.pausePresence()
    renderCallTabNotice()
  },
  onFreed: (key) => {
    if (key !== heldElsewhereKey) return
    heldElsewhereKey = undefined
    callTimeline.record('call-tab-lock', undefined, 'freed')
    session?.resumePresence()
    renderCallTabNotice()
  },
  // A fresh tab has just probed and been told this tab holds the call. Its
  // own join() is about to publish (or has just published) one trackless
  // entry under the identical device key, simply to enter the room - see
  // call-tab-lock.ts. Republishing now, rather than waiting for the next
  // heartbeat, keeps that contradiction down to one round trip instead of
  // up to a full heartbeat interval.
  onProbeAnswered: (key) => {
    if (key !== callLockKey()) return
    callTimeline.record('call-tab-lock', undefined, 'probe-answered')
    publishActiveTracks()
  },
})

$('callTabNoticeTake').addEventListener('click', () => {
  joinCall().catch((err) => setStatus(describeError(err)))
})

/** Start a call, or join the one that is on. The same act: say which call
 *  this device is on. Nothing is switched on by joining; the controls are. */
async function joinCall(): Promise<void> {
  if (roomUsesBothy) throw new Error('Calls and media are unavailable on this text-only Bothy route.')
  // One call at a time: the room on screen beside a docked call is for
  // reading and writing only.
  if (docked()) return
  const s = session
  if (!s || s.call) return
  // The user gesture the gain path needs to open an AudioContext that is
  // not born suspended - see remote-volume.ts. Harmless to call whether or
  // not this call ever needs it.
  remoteVolume.resume()
  if (!await consentToRecordedCall() || session !== s || s.call) return
  const existing = s.calls()[0]
  leftCall = false
  callWanted = true
  const id = existing?.id ?? newCallId()
  callProjectContexts.set(s, { call: id, project: roomProjectContext })
  logCall('call-declared', undefined, `${existing ? 'joined' : 'started'} ${id.slice(0, 8)} on Join`)
  await s.setCall({ id, since: nowSeconds() })
  publishActiveTracks()
  setCallOpen(true)
  void callWakeLock.acquire()
  // Claiming the call for this device's key sends every other tab of this
  // device in this room quiet on it - see the CallTabLock handlers above.
  const key = callLockKey()
  if (key) {
    heldElsewhereKey = undefined
    s.resumePresence()
    callTabLock.claim(key)
  }
  renderCallTabNotice()
  updateUi()
}

/** Everything of this device's that was live, off, and the previews with it.
 *  Shared by leaving a call and closing the room. */
function stopLocalMedia(): void {
  desktopShareArea.stop()
  shareMarksOverlay.close()
  desktopRedaction.closeAll()
  desktopRedaction.setHidden(false)
  micTrack?.removeEventListener('ended', onMicEnded)
  for (const track of activeTracks()) track.stop()
  mic?.stop()
  camera?.stop()
  for (const pipeline of pendingMedia) pipeline.stop()
  pendingMedia.clear()
  mic = camera = undefined
  $('mediaRecoveryNote').hidden = true
  $('voiceFailureNotice').hidden = true
  micTrack = cameraTrack = screenTrack = screenAudioTrack = undefined
  shareMayShowItself = false
  clearShareError()
  micClaimedAt = monitorClaimedAt = undefined
  besideAnotherDevice = false
  for (const video of localPreviewEls.values()) { video.srcObject = null; video.remove() }
  localPreviewEls.clear()
}

/** Off the call. The room, and everybody else's call, carry on.
 *
 *  `reason: 'preempted'` is another tab of this device taking the call.
 *  Everything here still applies - stop media, say we are off - and one
 *  thing more: this device sends a farewell for its call footprint rather
 *  than an ordinary "no tracks" update, so every peer's mesh drops its
 *  connection to this device cleanly instead of trying to renegotiate it -
 *  see `Session.farewellCall` for why an ordinary update cannot hand a live
 *  connection to a different physical tab. Never done for `'user'`: a
 *  normal Leave keeps the connection warm on purpose, for an instant Join
 *  back. */
async function leaveCall(reason: 'user' | 'preempted' = 'user'): Promise<void> {
  // A recording of a call this device has left would be a recording of
  // nothing, still announced. Stopped first, so the file is kept.
  if (activeRecording) await stopRecording()
  // Leaving a docked call leaves its room too: nothing of it is on screen.
  if (dockedCall) return endDockedCall(reason)
  const s = session
  // Before a single thing is torn down. Everything between here and the
  // repaint at the end reads this and paints the resting state, so the
  // person sees the call go and never sees a door asking them back in.
  leavingCall = true
  try {
    shareViewer.endCall()
    floatingSharePreview.close()
    stopLocalMedia()
    speakingMonitor.retain([...remoteAudios.keys()])
    remoteVolume.retain([...remoteAudios.keys()])
    leftCall = true
    callWanted = false
    // A microphone or camera still opening lands after this, and a track
    // live with no call is exactly what `publishActiveTracks` puts back on
    // one. Moving the generation on makes it stop itself when it lands.
    ++callGeneration
    if (reason === 'preempted') {
      if (s) await s.farewellCall()
    } else {
      publishActiveTracks()
      if (s) await s.setCall(null)
    }
    setCallOpen(false)
    void callWakeLock.release()
    autoplayBanner.hide()
    renderAutoplayBanner()
    if (reason === 'user') {
      const key = callLockKey()
      if (key) callTabLock.release(key)
    }
  } finally {
    // Cleared before the last repaint, not after: this is where the resting
    // state becomes the honest answer rather than a held one, and the
    // repaint below is the one that draws it.
    leavingCall = false
  }
  updateUi()
  repaint()
}

/**
 * Which pane the window is drawing, and the clock that lets it shrink.
 *
 * The settler is the only thing that decides: `render` tells it what the
 * room justifies, and it answers with what may actually be drawn - see
 * app/src/call-stance.ts for why growing is immediate and shrinking waits.
 */
const paneSettler = new PaneSettler()
let paneTimer: ReturnType<typeof setTimeout> | undefined

/**
 * Whether the room has a picture in it.
 *
 * Adverts and this device's own tracks, never decoded frames. A tile whose
 * video has stalled for a moment, or is re-binding after the mesh rebuilt a
 * connection, still belongs to a room that has a picture; judging this on
 * what is currently painting would collapse the whole layout under a
 * hiccup and hand it back a second later.
 */
function roomHasPictures(views: ParticipantView[]): boolean {
  if (cameraTrack || screenTrack) return true
  if (localMediaEl.querySelector('video')) return true
  // After Leave the pictures are parked on purpose - see `leftCall` - so
  // there is nothing for the pane to hold, whatever the roster still says.
  if (leftCall) return false
  return views.some(view => view.tracks.some(track => track.role === 'camera' || track.role === 'screen'))
}

function applyCallPane(views: ParticipantView[], state: CallStanceInput): void {
  // The docked gallery still belongs to the live call while another chat is
  // open. Its explicit Hide gallery control manages collapse independently.
  const target = docked() ? 'live' : callPane({ ...state, pictures: roomHasPictures(views) })
  const shown = paneSettler.settle(target, Date.now())
  if (document.documentElement.dataset.callPane !== shown) document.documentElement.dataset.callPane = shown
  if (paneTimer !== undefined) { clearTimeout(paneTimer); paneTimer = undefined }
  const due = paneSettler.due
  // Nobody else will ask. The last picture going is the last thing that
  // happens in a quiet room, so without this the pane would stay expanded
  // until something unrelated caused a render.
  if (due !== undefined) {
    paneTimer = setTimeout(() => {
      paneTimer = undefined
      const s = mediaSession()
      if (s) applyCallPane(s.participants(), callStanceNow(s.participants()))
    }, Math.max(0, due - Date.now()) + 20)
  }
}

/**
 * The call as a voice call: who is on it, by name.
 *
 * An empty video grid says nothing that this does not say in one row, so
 * the controls-only pane shows these instead - see `CallPane`. The badges
 * and the speaking class are the tiles' own, so the two cannot disagree
 * about who is talking or who is muted, and `paintSpeaking` lights these
 * from the same `data-devices` attribute twenty times a second without a
 * render.
 *
 * Nothing here goes near the media. The remote `<audio>` elements stay in
 * their tiles inside `#whoIsHere`, which the controls pane hides with CSS
 * and never unmounts: a media element taken out of the document is paused
 * by Chromium and does not reliably recover, and a chip row that cost the
 * room its sound would be a worse bug than the one it fixes.
 */
function renderCallChips(views: ParticipantView[], callId: string | undefined): void {
  const row = $('callChips')
  row.replaceChildren()
  if (!callId) return
  for (const view of views) {
    if (view.call?.id !== callId) continue
    const mine = view.participant === mediaMe()
    const chip = document.createElement('span')
    chip.className = 'callChip'
    const devices = mine ? [LOCAL_SPEAKING_KEY] : view.devices
    chip.dataset.devices = devices.join(' ')
    if (devices.some((device) => speakingMonitor.isSpeaking(device))) chip.classList.add('speaking')
    chip.append(identityRun(shownAs(view.participant, view.name), mine, false, false, true))
    if (mine) {
      if (!micTrack) chip.append(noMicBadge())
      else if (!micTrack.enabled) chip.append(selfMuteBadge())
    } else {
      if (volumeLevel(view.participant) === 0) chip.append(volumeMuteBadge())
      if (selfMutedMic(view)) chip.append(selfMuteBadge())
      else if (!view.tracks.some((track) => track.role === 'mic')) chip.append(noMicBadge())
    }
    row.append(chip)
  }
}

/**
 * The call button, the banner, and who is on it. Called from `render`, so
 * it follows presence: a call somebody else started shows up the moment
 * their heartbeat says so, and ends when the last of them stops saying so.
 */
function renderCallState(views: ParticipantView[]): void {
  const calls = mediaSession()?.calls() ?? []
  const state = callStanceNow(views)
  const stance = callStance(state)
  const mineOn = stance === 'leave'
  window.kithmootDesktop?.setCallActive(mineOn)
  callFocus.setOnCall(mineOn && !docked())
  const button = $('callToggle')
  const current = calls[0]
  const starter = current && views
    .filter(view => view.call?.id === current.id)
    .sort((a, b) => (a.call?.since ?? 0) - (b.call?.since ?? 0) || a.participant.localeCompare(b.participant))[0]
  const incoming = current && starter ? { id: current.id, caller: starter.participant } : undefined
  const callChange = incomingCallTracker.update(incoming, mediaMe() || currentParticipant(), mineOn)
  if (callChange && callChange.type !== 'stop') {
    logCall('call-ring', callChange.call.caller, `${callChange.type === 'ring' ? 'rang for' : 'kept quiet, just on a call:'} ${callChange.call.id.slice(0, 8)}`)
  }
  if (callChange?.type === 'stop') { stopCallRing(); hideRingBanner() }
  else if (callChange?.type === 'ring') {
    const settings = notifySettings(deviceStore)
    const roomId = currentRoomId()
    // The banner is for the room on screen, whether or not system
    // notifications are on: it is the app saying so, not the system. Only
    // for a call that has just started: opening a room where a call has been
    // going for an hour is not somebody calling, and the room's own banner
    // already says "Call on" with Join.
    const ringFor = current ? ringBannerSeconds(current.since, nowSeconds()) : 0
    // Banner, sound and alert alike, and all of them stop together a minute
    // after the call began.
    if (ringFor > 0) giveUpRingingAfter(ringFor)
    if (roomId && ringFor > 0 && !$('roomArea').hidden && !docked() && !onCall()) {
      showRingBanner(shownAs(callChange.call.caller, starter?.name).name ?? 'Somebody')
    }
    // A room that is muted, for a while or set to Nothing, keeps its ring
    // quiet here (sound and system alert); the banner above is not gated.
    if (ringFor > 0 && settings.enabled && roomId && roomNotificationsEnabled(deviceStore, nostrSession?.pubkey, roomId, notificationProjectsForRoom(roomId))) {
      void startCallRing()
      const caller = shownAs(callChange.call.caller, starter?.name)
      void deliverIncomingCallAlert({
        title: currentRoomLabel(),
        body: `${caller.name ?? 'Somebody'} is calling`,
        tag: `kithmoot:${roomId}:call:${callChange.call.id}`,
      }, roomId)
    }
  }
  // One control, three things it can do, and it says which. "Call" told a
  // person nothing, and "On call" was a state where they expected an act.
  //
  // Written only when it changes, here and below. This runs on every
  // heartbeat of every device in the room, and the pane's state lives on
  // the root element: restating it would throw the whole document's style
  // away several times a second, during a call, which is the one moment
  // the machine has something better to do.
  const label = CALL_STANCE_LABELS[stance]
  const word = button.querySelector('.barWord')!
  if (word.textContent !== label) {
    // The word stays in the button for assistive technology and the specs;
    // what is drawn is the phone, or the hang-up while you are on the call.
    word.textContent = label
    button.setAttribute('aria-label', label)
    button.dataset.tip = CALL_STANCE_TITLES[stance]
    button.dataset.stance = stance
    button.querySelector('use')!.setAttribute('href', stance === 'leave' ? '#i-hangup' : '#i-phone')
  }
  if (button.dataset.live !== String(mineOn)) button.dataset.live = String(mineOn)
  publishDesktopMenu()

  // A call pane with nothing in it costs the conversation its room. See
  // `applyCallPane`, and the two strips in app/src/desktop.css.
  applyCallPane(views, state)
  renderCallChips(views, current?.id)
  const strip = stance === 'join' ? 'A call is on in this room.' : 'Nobody is on a call.'
  if ($('callStripText').textContent !== strip) $('callStripText').textContent = strip

  const banner = $('callBanner')
  const doorShut = !joinDoorOpen(state)
  if (banner.hidden !== doorShut) banner.hidden = doorShut
  if (current && !banner.hidden) {
    const on = views.filter(view => view.call?.id === current.id).sort((a, b) => (a.call?.since ?? 0) - (b.call?.since ?? 0))
    const starter = on[0]
    const who = starter ? (shownAs(starter.participant, starter.name).name ?? 'Somebody') : 'Somebody'
    const names = on.map(view => shownAs(view.participant, view.name).name ?? 'Somebody')
    // "Call on · Rowan and Priya": who is on it, three at most by name, then
    // "Rowan, Priya and 2 more".
    const said = names.length <= 1 ? (names[0] ?? who)
      : names.length === 2 ? `${names[0]} and ${names[1]}`
      : names.length === 3 ? `${names[0]}, ${names[1]} and ${names[2]}`
      : `${names[0]}, ${names[1]} and ${names.length - 2} more`
    $('callBannerText').textContent = `Call on · ${said}`
  }

  if (mineOn && current) {
    const names = views.filter(view => view.call?.id === current.id && view.participant !== mediaMe())
      .map(view => shownAs(view.participant, view.name).name ?? 'somebody')
    $('callWho').textContent = names.length === 0 ? 'On the call. Just you.' : `On the call with ${names.slice(0, 3).join(', ')}${names.length > 3 ? ` and ${names.length - 3} more` : ''}.`
  }
}

// ---------------------------------------------------------------------------
// Room info (design-calm-shell 5.4)
//
// One short panel with a row for each place the room's details live; a row
// opens a subpage inside the same panel. A window 900 px wide or more gets it
// as a side panel on the end edge, non-modal, so the conversation stays in
// use beside it (and narrows to make room from 1280 px). Anything narrower
// gets a full screen modal with a back arrow. It is the same `<dialog>` either
// way, so `open` still says whether it is showing.
// ---------------------------------------------------------------------------

const INFO_SIDE_PANEL = window.matchMedia('(min-width: 900px)')
const INFO_PUSHES = window.matchMedia('(min-width: 1280px)')
/** Which subpage the panel is on: `main` or a `data-info-page` name. */
let infoPage = 'main'
/** What had the focus when the panel opened, to hand it back on close. */
let infoOpener: HTMLElement | undefined
/** The row that opened the subpage on screen, for the back arrow to return to. */
let infoRow: HTMLElement | undefined
/** Where the admission requests sit when the panel is not carrying them. */
let infoApprovalsHome: { parent: Node; next: Node | null } | undefined
/** Set while the panel is closed and opened again to change its mode. */
let infoReopening = false

function infoSheet(): HTMLDialogElement {
  return $('roomSheet') as HTMLDialogElement
}

/** The text a row shows under its title. */
function setInfoSub(id: string, text: string): void {
  const el = $(id)
  el.textContent = text
  el.hidden = !text
}

/** Fill the rows with the state they report. Cheap; it runs when the panel
 *  opens, when it returns to its first page and when who is here changes. */
function renderRoomInfo(): void {
  const roomId = currentRoomId()
  if (!roomId) return
  const me = meParticipant || currentParticipant()
  const peer = me ? dmPeer(roomPolicy, me) : undefined
  renderLogo($('infoAvatar'), displayedRoomLogo(roomId, roomProjectContext), currentRoomLabel())
  $('infoName').textContent = currentRoomLabel()
  const views = session?.participants() ?? []
  const agents = views.filter(view => view.agent).length
  const people = views.length - agents
  const who = views.length === 0 ? '' : `${people} ${people === 1 ? 'person' : 'people'}${agents ? `, ${agents} agent${agents === 1 ? '' : 's'}` : ''}`
  const admits = peer ? 'Only members can join' : roomPolicy?.members?.length ? 'Only members can join' : 'Anyone with the link can join'
  $('infoWho').textContent = peer ? (isQuietPolicy(roomPolicy) ? 'Quiet chat · Only members can join' : 'Private chat · Only members can join') : [who, admits].filter(Boolean).join(' · ')
  // "Ends in 3 days · Self-destructs", from the header's own words.
  const ends = $('infoEnds')
  const endsText = roomEndsAt === undefined ? '' : conferenceEndsLine(roomEndsAt)
  ends.textContent = [endsText, roomDestruct ? 'Self-destructs' : ''].filter(Boolean).join(' · ')
  if (!endsText && roomDestruct) ends.textContent = 'Self-destructs if it is ended for everyone'
  ends.hidden = !ends.textContent

  const model = roomMenuModel()
  $('infoInvite').hidden = !model.invite
  const callButton = $('callToggle')
  $('infoCall').hidden = callButton.hidden || (callButton.getAttribute('aria-label') ?? '') === ''
  const callLabel = callButton.getAttribute('aria-label') ?? 'Call'
  $('infoCall').querySelector('span')!.textContent = /^(start|join) call$/i.test(callLabel) ? 'Call' : callLabel
  $('infoRowInvite').hidden = !model.invite || roomUsesBothy
  const knock = $('toggleKnock').dataset.on === 'true'
  setInfoSub('infoSubInvite', $('knockRow').hidden ? '' : `Ask before letting people in: ${knock ? 'on' : 'off'}`)
  // The conversations every room has are not worth listing; the ones somebody opened are.
  const opened = Array.from($('channelBar').querySelectorAll<HTMLElement>('button[data-channel]'), tab => tab.dataset.channel!).filter(name => name && !['agents', 'transcript', 'minutes'].includes(name))
  setInfoSub('infoSubConversations', opened.join(', '))
  const board = boardTab()
  $('infoRowBoard').hidden = !board
  setInfoSub('infoSubBoard', board ? (board.needsYou ? `${board.needsYou} need${board.needsYou === 1 ? 's' : ''} you` : '') : '')
  // Per-room alerts are the ⋯ menu's Notifications; this page is only for what
  // a keeper can offer, so the row is there only then.
  $('infoRowNotifications').hidden = $('nudgeRow').hidden
  setInfoSub('infoSubNotifications', 'Nudge me when I am away')
  const route = roomUsesBothy ? 'Bothy route' : 'public relays'
  setInfoSub('infoSubPrivacy', `Encrypted · ${route}`)
  setInfoSub('infoSubName', $('roomRename').hidden && $('roomLogoControls').hidden ? '' : 'Anyone here can change them')
  $('infoRowName').hidden = $('roomRename').hidden && $('roomLogoControls').hidden
  setInfoSub('infoSubPhone', '')
  $('infoRowPhone').hidden = isPairedSecondary(deviceStore)
  setInfoSub('infoSubCards', contacts(deviceStore).length ? `${contacts(deviceStore).length} saved` : '')
  $('leave').textContent = peer ? 'Leave private chat…' : 'Leave room…'
  $('roomRelaySettings').hidden = roomUsesBothy
  $('roomBothySettings').hidden = !roomUsesBothy
}

/** Show one page of the panel. The heading is the panel's title and takes the
 *  focus, so a screen reader hears where it is; the back arrow shows below the
 *  first page. */
function showInfoPage(name: string, row?: HTMLElement): void {
  const sheet = infoSheet()
  const previous = infoPage
  infoPage = name
  if (name !== 'main' && row) infoRow = row
  for (const page of sheet.querySelectorAll<HTMLElement>('[data-info-page]')) page.hidden = page.dataset.infoPage !== name
  const title = name === 'main' ? 'Room info' : sheet.querySelector<HTMLElement>(`[data-info-page="${name}"]`)?.dataset.infoTitle ?? 'Room info'
  $('roomSheetTitle').textContent = title
  $('roomInfoBack').hidden = name === 'main'
  sheet.dataset.page = name
  if (name === 'main') renderRoomInfo()
  if (name === 'invite') {
    $('inviteStatus').textContent = ''
    $('meetingCodeStatus').textContent = ''
    meetingCodePasswordTouched = false
    renderInviteEnds()
    renderMeetingCode()
  }
  sheet.scrollTop = 0
  if (name === 'main' && previous !== 'main' && infoRow?.isConnected && !infoRow.hidden) infoRow.focus({ preventScroll: true })
  else $('roomSheetTitle').focus({ preventScroll: true })
}

function openRoomSheet(page = 'main', from?: HTMLElement): void {
  const sheet = infoSheet()
  if (sheet.open) {
    if (page !== 'main' && page !== infoPage) showInfoPage(page, infoRow)
    else if (page === 'main' && infoPage !== 'main') showInfoPage('main')
    else $('roomSheetTitle').focus({ preventScroll: true })
    return
  }
  const active = document.activeElement
  infoOpener = from ?? (active instanceof HTMLElement && active !== document.body && !active.closest('#roomMoreMenu') && !active.closest('dialog') ? active : $('roomIdentity'))
  // A hover card left open in the log would sit over a panel that is not modal.
  for (const card of document.querySelectorAll<HTMLElement>('.reactionDetails:popover-open')) card.hidePopover()
  if (session) renderSheetRoster(session.participants(), meParticipant)
  renderSheetRoom()
  renderChannels()
  renderContacts()
  // Admission requests lead the member list while the panel is open.
  const approvals = $('approvals')
  if (!infoApprovalsHome) infoApprovalsHome = { parent: approvals.parentNode!, next: approvals.nextSibling }
  $('infoApprovalsHome').append(approvals)
  const side = INFO_SIDE_PANEL.matches
  sheet.dataset.mode = side ? 'panel' : 'sheet'
  if (side) {
    document.documentElement.dataset.roomInfo = INFO_PUSHES.matches ? 'push' : 'over'
    sheet.show()
  } else sheet.showModal()
  infoRow = undefined
  infoPage = ''
  showInfoPage(page)
}

/** Open the panel on one of its subpages, as a menu item or a quick action does. */
function openRoomInfoPage(page: string): void {
  openRoomSheet()
  const row = infoSheet().querySelector<HTMLElement>(`[data-info-open="${page}"]`) ?? undefined
  showInfoPage(page, row)
}

function closeRoomSheet(): void {
  const sheet = infoSheet()
  if (sheet.open) sheet.close()
}

infoSheet().addEventListener('close', () => {
  const sheet = infoSheet()
  delete document.documentElement.dataset.roomInfo
  if (infoApprovalsHome) {
    const approvals = $('approvals')
    infoApprovalsHome.parent.insertBefore(approvals, infoApprovalsHome.next)
    infoApprovalsHome = undefined
  }
  if (infoReopening) return
  infoPage = 'main'
  delete sheet.dataset.page
  // A non-modal dialog does not hand the focus back by itself. Take it only
  // if it is still on the panel (or nowhere): a click on something else, or
  // a thing that has just opened over it, keeps what it asked for.
  const active = document.activeElement
  const opener = infoOpener
  infoOpener = undefined
  if (opener?.isConnected && (!active || active === document.body || sheet.contains(active)) && opener.getClientRects().length) opener.focus({ preventScroll: true })
})
infoSheet().querySelectorAll<HTMLElement>('[data-info-open]').forEach(row => {
  row.addEventListener('click', () => showInfoPage(row.dataset.infoOpen!, row))
})
$('roomInfoBack').addEventListener('click', () => showInfoPage('main'))
document.addEventListener('keydown', event => {
  const sheet = infoSheet()
  if (event.key !== 'Escape' || event.defaultPrevented || !sheet.open || sheet.matches(':modal')) return
  const active = document.activeElement
  if (!(active && sheet.contains(active)) || document.querySelector('dialog:modal, [popover]:popover-open')) return
  event.preventDefault()
  closeRoomSheet()
})
// A window resized across 900 px, or turned, changes which kind of panel it
// should be. Close it and open it again on the same page rather than leave a
// modal where a side panel belongs.
function infoModeChanged(): void {
  const sheet = infoSheet()
  if (!sheet.open) return
  const side = INFO_SIDE_PANEL.matches
  if (side !== (sheet.dataset.mode === 'panel')) {
    const page = infoPage, row = infoRow, opener = infoOpener
    infoReopening = true
    sheet.close()
    infoReopening = false
    infoOpener = opener
    // A modal of its own is open over the panel (a confirmation): do not stack
    // a second one on top of it, which would hide the question.
    if (!side && document.querySelector('dialog:modal')) { delete document.documentElement.dataset.roomInfo; return }
    openRoomSheet(page === 'main' ? 'main' : page)
    infoRow = row
  } else if (side) document.documentElement.dataset.roomInfo = INFO_PUSHES.matches ? 'push' : 'over'
}
INFO_SIDE_PANEL.addEventListener('change', infoModeChanged)
INFO_PUSHES.addEventListener('change', infoModeChanged)

// ---------------------------------------------------------------------------
// The contact book: cards this browser holds. See app/src/contact-store.ts.
// ---------------------------------------------------------------------------

/** What a contact is called on screen: the name on their card, else the key. */
function contactLabel(c: Contact): string {
  return c.name ?? shortKey(c.p)
}

function renderContacts(): void {
  const list = $('contactList')
  list.replaceChildren()
  for (const c of contacts(deviceStore)) {
    if (grantedContactView?.status === 'unavailable' || grantedContactView?.blocked.has(c.p)) continue
    const row = document.createElement('div')
    row.className = 'contactRow'
    const who = document.createElement('span')
    who.className = 'contactWho'
    who.textContent = contactLabel(c)
    who.title = npubOf(c.p)
    const key = document.createElement('span')
    key.className = 'pubkey'
    key.textContent = shortKey(c.p)
    const when = document.createElement('span')
    when.className = 'note'
    const expired = c.expires <= nowSeconds()
    when.textContent = expired ? `card expired ${new Date(c.expires * 1000).toLocaleDateString()}` : `card read ${new Date(c.readAt * 1000).toLocaleDateString()}`
    const forget = document.createElement('button')
    forget.type = 'button'
    forget.className = 'quiet'
    forget.textContent = 'Forget'
    forget.setAttribute('aria-label', `Forget ${contactLabel(c)}'s card`)
    forget.addEventListener('click', async () => {
      if (!await confirmRoomAction({ title: `Forget ${contactLabel(c)}'s card?`, message: 'Their card and saved box details will be removed from this device. Their key is not blocked; a new card adds them back.', confirmLabel: 'Forget card', danger: true })) return
      forgetContact(deviceStore, c.p)
      contactsChanged()
    })
    row.append(who, key, when, forget)
    const boxes = document.createElement('div')
    boxes.className = 'contactBoxes'
    if (!c.boxes.length) boxes.textContent = 'No box on this card.'
    for (const b of c.boxes) {
      const box = document.createElement('div')
      box.className = 'contactBox'
      const detail = document.createElement('p')
      detail.textContent = `Box ${shortKey(b.p)}. ${boxDiscovery?.message(c.p, b.p) ?? 'Box status is not being checked.'}`
      const action = document.createElement('button')
      action.type = 'button'; action.className = 'quiet'
      const enabled = boxDiscovery?.enabled(c.p, b.p) ?? false
      action.textContent = enabled ? 'Stop checking box' : 'Check box status'
      action.disabled = expired && !enabled
      action.addEventListener('click', async () => {
        if (!boxDiscovery) return
        if (!enabled && !await confirmRoomAction({ title: 'Check this box?', message: 'Your default read relays will see this box’s key and its keeper’s claim. Checking continues on this device until you stop or replace the contact card. A verified endpoint can label messages using an existing relay connection; checking does not change where your room sends messages.', confirmLabel: 'Check box' })) return
        try { boxDiscovery.setEnabled(c.p, b.p, !enabled, boxDiscoveryRevision(c, b)) }
        catch (error) { detail.textContent = describeError(error) }
      })
      box.append(detail, action); boxes.append(box)
    }
    row.append(boxes)
    list.append(row)
  }
  if (list.childElementCount === 0) {
    const none = document.createElement('p')
    none.className = 'note'
    none.textContent = 'No contact cards yet.'
    list.append(none)
  }
  // A card is a signed event, so any identity that signs events can make
  // one: a local key, an extension, a bunker. A paired device holds no key
  // and signs nothing.
  $('myCard').hidden = isPairedSecondary(deviceStore)
}

/** A card was read or forgotten: refresh its holder badge and lane attribution. */
function contactsChanged(): void {
  boxDiscovery?.reconcile()
  relayConnections.circleChanged()
  renderContacts()
  renderPeople()
  repaint()
  renderLaneNote()
}

function addContact(text: string, status: HTMLElement = $('contactCardStatus')): boolean {
  const r = addContactFromCard(deviceStore, text, nowSeconds())
  if (!r.ok) {
    status.textContent = `${r.words} (step ${r.step}: ${r.reason})`
    return false
  }
  const boxes = r.contact.boxes.length
  status.textContent = `${r.replaced ? 'Updated' : 'Added'} ${contactLabel(r.contact)}: ${boxes === 0 ? 'no box' : boxes === 1 ? 'one box' : `${boxes} boxes`}, ${r.contact.relays.length} public relay${r.contact.relays.length === 1 ? '' : 's'}.`
  contactsChanged()
  return true
}

/** This person's own card: their key, name and relays, a rendezvous key
 *  made here, no box. Seven days. Signed by whatever holds the identity,
 *  which sees a kind, a time and a content it can read. Handed over, never
 *  posted. */
async function showMyCard(out = $('myCardOut') as HTMLInputElement, qr = $('myCardQr') as HTMLCanvasElement): Promise<void> {
  const rz = bytesToHex(schnorr.getPublicKey(myRendezvousSecret(deviceStore, () => randomBytes(32))))
  const identity = currentIdentity()
  const card = await buildCardWith(identity.pubkey, (unsigned) => identity.signEvent(unsigned), {
    rz,
    ephemeralPrivateKey: randomBytes(32),
    ...(typedName ? { name: typedName } : {}),
    relays: RELAYS,
    boxes: [],
    ttlSeconds: 7 * 24 * 3600,
  })
  const link = cardLink(joinLinkBase(), card)
  out.value = link
  out.hidden = false
  qr.hidden = false
  await renderQr(qr, link)
}

/** Who invited you, and to what, in the one sentence somebody needs before
 *  they type their name in. A room you started yourself says so instead:
 *  "you have been invited" is not true of your own room. */
function renderArrival(): void {
  renderAdmissionRoomBrand()
  const lead = $('arrivalLead')
  const roomId = currentRoomId()
  if (!roomId) {
    lead.hidden = true
    $('arrivalAvatar').hidden = true
    return
  }
  // Named the way Chats names it, so the door and the list agree.
  const label = currentRoomLabel()
  $('arrivalTitle').textContent = label
  lead.textContent = startedHere ? 'Your room is ready.' : 'You have been invited to this room.'
  lead.hidden = false
  const avatar = $('arrivalAvatar')
  avatar.hidden = false
  avatar.dataset.slot = String(avatarSlot(roomId))
  avatar.textContent = avatarInitial(label)
  renderLogo(avatar, displayedRoomLogo(roomId), label)
}

/**
 * What this room is called, at the head of the conversation.
 *
 * The NAME, and nothing else. It used to be the name with a short id beside
 * it, which for a room somebody had named read as a name plus a code, and
 * for a room nobody had named read as `Room 353ff833  353ff83…` - the same
 * identifier twice, once inside a title manufactured out of it and once
 * again beside that. Every messaging app puts a human name in this slot.
 *
 * The identifier has not gone anywhere: two rooms can be called the same
 * thing and the code is what tells them apart, so it is in the room's
 * details with the other technical facts, and on the rooms list where you
 * are actually choosing between rooms.
 */
function renderRoomTitle(): void {
  const title = $('roomTitle')
  const roomId = currentRoomId()
  title.textContent = ''
  title.hidden = roomId === undefined
  renderCurrentRoomLogo()
  if (!roomId) return
  const me = meParticipant || currentParticipant()
  const peer = me ? dmPeer(roomPolicy, me) : undefined
  title.textContent = peer ? currentRoomLabel() : roomName ?? 'Untitled room'
  title.title = peer ? currentRoomLabel() : roomName ?? `Room ${shortKey(roomId)}`
  // The countdown pill, in place of the plain "Ends …" line.
  const ends = $('roomEndsLine')
  if (roomEndsAt === undefined) { ends.replaceChildren(); ends.hidden = true }
  else {
    fusePill(roomEndsAt, roomStartsAt ?? knownRoom(roomStore(), roomId)?.startsAt, roomDestruct, ends)
    ends.hidden = false
  }
  renderSheetRoom()
  renderDestructState()
  tickFuses()
}

/** A conference room's end, in the invite sheet: the link stops working
 *  then, which anybody about to share it should know. */
function renderInviteEnds(): void {
  const line = $('inviteEnds')
  line.textContent = roomEndsAt === undefined
    ? (roomDestruct ? 'This room self-destructs if it is ended for everyone.' : '')
    : roomDestruct
      ? `${conferenceEndsLine(roomEndsAt)}. This room self-destructs then: its link stops working and every member’s app deletes it.`
      : `${conferenceEndsLine(roomEndsAt)}. This is a conference room: its link stops working then, and its messages are wiped from relays that honour expiry.`
  line.hidden = !line.textContent
}

/** What self-destruct means, once, in the room's details. */
function renderDestructState(): void {
  const line = $('roomDestructState')
  const what = roomEndsAt !== undefined ? `This room self-destructs ${formatConferenceEnd(roomEndsAt)}. ` : 'This room self-destructs if it is ended for everyone. '
  line.textContent = roomDestruct ? what + DESTRUCT_PROMISE : ''
  line.hidden = !roomDestruct
}

/** The name and the code together, in the room's details. */
function renderSheetRoom(): void {
  const line = $('sheetRoomId')
  line.textContent = ''
  const roomId = currentRoomId()
  if (!roomId) return
  if (roomName) {
    const name = document.createElement('span')
    name.className = 'name'
    name.textContent = roomName
    line.append(name, ' ')
  }
  const id = document.createElement('span')
  id.className = 'pubkey'
  id.textContent = shortKey(roomId)
  id.title = roomId
  line.append(id)
  renderRoomRename()
}

async function copyInput(id: string): Promise<void> {
  const input = $(id) as HTMLInputElement
  input.hidden = false
  input.select()
  let copied = false
  try {
    if (navigator.clipboard) {
      await navigator.clipboard.writeText(input.value)
      copied = true
    }
  } catch { /* Try the browser's selection-based copy below. */ }
  if (!copied && input.getClientRects().length) {
    input.focus(); input.select()
    if (document.activeElement === input) {
      try { copied = document.execCommand('copy') } catch { /* Manual copying remains available. */ }
    }
  }
  if (id === 'shareUrl') {
    $('inviteStatus').textContent = copied ? 'Link copied. Share it with the people you want to invite.' : 'Automatic copy was unavailable. Select the link and copy it with your keyboard or touch menu.'
  }
}

async function shareRoomLink(): Promise<void> {
  const url = ($('shareUrl') as HTMLInputElement).value
  if (!navigator.share) {
    await copyInput('shareUrl')
    return
  }
  try {
    await navigator.share({
      title: 'KithMoot',
      text: 'Join this private KithMoot room. Anyone forwarded this link can enter while it is current.',
      url,
    })
    $('inviteStatus').textContent = 'Link shared.'
  } catch (err) {
    // Closing the platform share sheet is a choice, not an error.
    if (!(err instanceof DOMException && err.name === 'AbortError')) throw err
  }
}

async function rotateRoomInvitation(): Promise<void> {
  if (await browserRoomRoutes.selected(deriveRoom(roomSecret).roomId)) throw new Error('New invitations are unavailable on this Bothy text route.')
  if (!roomInvitationCapability || !invitationAuthoritySk || invitationDelegation.length !== 0) {
    throw new Error('Only the browser that opened this room can rotate its invitation.')
  }
  const retired = roomInvitationCapability
  const retiringSk = invitationAuthoritySk
  const created = createRoomInvitation(retired.persistent === true)
  // A conference room's fresh link ends when the room does.
  storeInvitationOwner(created.invitation, roomSecret, created.inviterSk, roomEndsAt, roomDestruct)
  if (created.invitation.persistent) await publishGroupInvitation(created.invitation, roomSecret, created.inviterSk, relays, { endsAt: roomEndsAt, destruct: roomDestruct, roomRelays: signedRoomRelays() })

  // Tell every cooperative delegated responder before replacing local
  // state. The event is durable, so an offline member learns the retirement
  // when it reconnects instead of resurrecting an old group link.
  const retirementTransport = configuredPool(relays)
  try {
    await retirementTransport.publish(encodeInvitationRetirement({
      invitation: retired,
      inviterSk: retiringSk,
      now: nowSeconds(),
      endsAt: roomEndsAt,
    }))
  } finally {
    closeWhenSettled(retirementTransport)
  }
  stopInvitationHost()
  forgetInvitationOwner(retired)
  // New link deletes the old code; a new one can be issued for the new link.
  retireMeetingCode({ invitationId: deriveInvitationId(retired) })
  roomInvitationCapability = created.invitation
  invitationAuthoritySk = created.inviterSk
  invitationDelegation = []
  storeInvitationOwner(created.invitation, roomSecret, created.inviterSk, roomEndsAt, roomDestruct)
  serveCurrentInvitation()

  const url = encodeRoomUrl(joinLinkBase(), relays, iceUrls)
  history.replaceState(null, '', url)
  ;($('shareUrl') as HTMLInputElement).value = url
  // The old link is retired; the one kept for the list is the one that opens the room now.
  rememberCurrentRoom()
  if (($('shareQrDetails') as HTMLDetailsElement).open) {
    renderQr($('shareQr') as HTMLCanvasElement, url).catch((err) => setStatus(describeError(err)))
  }
  renderMeetingCode()
  setStatus('A fresh link is ready. Current clients will no longer answer the old link. Existing members stay.')
}

/** `forRoom` names the room the invitation is for when that is not the room
 *  on screen, so the relays it goes to are exactly `relayUrls` and not
 *  whatever this room's saved relay settings say. */
async function publishGroupInvitation(
  invitation: RoomInvitation, secret: Uint8Array, inviterSk: Uint8Array, relayUrls: string[],
  { forRoom, scope, endsAt, destruct, roomRelays }: { forRoom?: string; scope?: string; endsAt?: number; destruct?: boolean; roomRelays?: string[] } = {},
): Promise<void> {
  if (await browserRoomRoutes.selected(deriveRoom(secret).roomId)) throw new Error('New invitations are unavailable on this Bothy text route.')
  const pool = scope ? relayConnections.pool(scope, relayUrls) : forRoom ? relayConnections.pool(`room:${forRoom}`, relayUrls) : configuredPool(relayUrls)
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    await Promise.race([
      pool.publish(encodePersistentInvitation({ invitation, roomSecret: secret, inviterSk, now: nowSeconds(), endsAt, ...(destruct ? { destruct: true } : {}), ...(roomRelays?.length ? { relays: roomRelays } : {}) })),
      new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error('the relays did not save the group invitation')), 15_000) }),
    ])
  } finally {
    if (timer !== undefined) clearTimeout(timer)
    closeWhenSettled(pool)
  }
}

/** Close a pool used for one durable event once every relay has answered,
 *  in the background. Closing at the first ack aborted the other relays'
 *  writes, which left a group invitation on a single relay: a member or
 *  agent that later used only another of the room's relays could not join. */
function closeWhenSettled(pool: ManagedRelayPool): void {
  void pool.settled().finally(() => pool.close())
}

async function makeRoomPersistent(): Promise<void> {
  if (!roomInvitationCapability || roomInvitationCapability.persistent || !invitationAuthoritySk || invitationDelegation.length) return
  // A fresh bearer prevents an old, never-used meeting link from silently
  // becoming durable access. Keep the room's authority and conversation.
  const invitation: RoomInvitation = {
    ...createRoomInvitation(true).invitation,
    inviter: roomInvitationCapability.inviter,
  }
  await publishGroupInvitation(invitation, roomSecret, invitationAuthoritySk, relays, { roomRelays: signedRoomRelays() })
  storeInvitationOwner(invitation, roomSecret, invitationAuthoritySk)
  stopInvitationHost()
  // A room that never ends and asks nobody keeps full links only.
  retireMeetingCode({ invitationId: deriveInvitationId(roomInvitationCapability) })
  roomInvitationCapability = invitation
  const url = encodeRoomUrl(joinLinkBase(), relays, iceUrls)
  history.replaceState(null, '', url)
  ;($('shareUrl') as HTMLInputElement).value = url
  $('makePersistent').hidden = true
  $('invitationAvailability').textContent = 'This room stays open when everyone closes the app. Share the updated invite link so people can join later.'
  rememberCurrentRoom()
  if (($('shareQrDetails') as HTMLDetailsElement).open) await renderQr($('shareQr') as HTMLCanvasElement, url)
  setStatus('This room now stays open. Share the updated invite link; the old temporary link still needs somebody online.')
}

// ---------------------------------------------------------------------------
// Local media - the mic, camera and screen-share toggles
//
// Mic mutes in place (track.enabled), which is instant and asks for no
// fresh permission. Camera and screen stop the underlying track outright:
// that is what actually turns off a laptop's camera light and ends an OS
// screen-share, rather than merely lying about it locally.
// ---------------------------------------------------------------------------

/** The OS can interrupt capture without ending the canvas/Web Audio output.
 * Keep the existing pipelines so mute, effects and paired-device claims survive. */
async function recoverCallMedia(): Promise<void> {
  if (document.hidden || switchingRoom || leftCall || !mediaSession()) return
  const generation = callGeneration
  const currentMic = mic
  const currentCamera = camera
  remoteVolume.resume()
  recoverRemoteTracks()
  const results = await Promise.allSettled([currentMic?.resume(), currentCamera?.resume()])
  if (generation !== callGeneration || leftCall || mic !== currentMic || camera !== currentCamera) return
  adoptMicTrack()
  const failed = results.some(result => result.status === 'rejected')
  $('mediaRecoveryNote').hidden = !failed
  if (failed) $('mediaRecoveryNote').textContent = 'Call media was interrupted. Tap Resume call media in More. If it still fails, switch the affected microphone or camera off and on.'
}

document.addEventListener('visibilitychange', () => { if (!document.hidden) void recoverCallMedia() })
window.addEventListener('pageshow', () => { void recoverCallMedia() })
window.addEventListener('focus', () => { void recoverCallMedia() })
$('resumeCallMedia').addEventListener('click', () => { void recoverCallMedia() })

function onMicEnded(): void {
  // A fallback raw track may end while the OS owns the microphone. Keep
  // the user's enabled state and pipeline available for foreground recovery.
  void recoverCallMedia()
}

/**
 * Publish whatever the pipeline now says the microphone is.
 *
 * An explicitly selected Off may use raw capture when its audio graph
 * fails. A selected mask instead mutes its output. A changed track must
 * still be sent to every peer: `publishActiveTracks` removes the old sender and adds the new,
 * and the roster restates the advert under the new id.
 */
function adoptMicTrack(): void {
  const next = mic?.track
  if (!next || !micTrack || next === micTrack) return
  micTrack.removeEventListener('ended', onMicEnded)
  next.enabled = micTrack.enabled
  micTrack = next
  micTrack.addEventListener('ended', onMicEnded)
  // The tap follows the published track, not the raw microphone: what the
  // indicator should report is what the room can actually hear, and those
  // differ whenever the masking graph is in the path.
  speakingMonitor.watch(LOCAL_SPEAKING_KEY, micTrack)
  publishActiveTracks()
  updateUi()
}

async function toggleMic(): Promise<void> {
  if (mediaUsesBothy()) throw new Error('Microphone sharing is unavailable on this text-only Bothy route.')
  const generation = callGeneration
  if (switchingRoom) return
  if (!micTrack && (meetingRefuses() || !await consentToRecordedCall())) return
  if (!micTrack) callWanted = true
  if ([...pendingMedia].some(pipeline => pipeline instanceof MicPipeline)) return
  // An ended output cannot be unmuted. A deliberate press reopens capture.
  if (mic?.state.blocked || micTrack?.readyState === 'ended') {
    micTrack?.removeEventListener('ended', onMicEnded)
    mic?.stop()
    mic = undefined
    micTrack = undefined
    publishActiveTracks()
    updateUi()
  }
  if (!micTrack) {
    const pipeline = new MicPipeline({
      preset: savedVoicePreset,
      onSourceEnded: () => { if (generation === callGeneration) void recoverCallMedia() },
      onStateChange: (state) => {
        if (generation !== callGeneration) return
        renderVoiceState(state)
        adoptMicTrack()
        if (mic === pipeline && state.blocked) { publishActiveTracks(); updateUi() }
      },
    })
    pendingMedia.add(pipeline)
    try {
      const track = await pipeline.start({ deviceId: loadMicDeviceId(deviceStore) })
      if (generation !== callGeneration) { pipeline.stop(); return }
      micTrack = track
    } catch (err) {
      pipeline.stop()
      if (generation !== callGeneration) return
      throw err
    } finally {
      pendingMedia.delete(pipeline)
    }
    mic = pipeline
    if (pipeline.deviceId) storeMicDeviceId(deviceStore, pipeline.deviceId)
    micTrack.addEventListener('ended', onMicEnded)
    // Choosing the microphone is an explicit choice to use this device for
    // the conversation, even if it was previously in camera-only mode. It
    // is NOT a claim on the speaker: a phone brought in beside a laptop is
    // a microphone, and its owner is listening on the laptop. The speaker
    // is claimed weakly, so it is this device's only when nothing else of
    // theirs is playing sound - see `WEAK_MONITOR_CLAIM`.
    besideAnotherDevice = false
    micClaimedAt = takeRole('mic')
    monitorClaimedAt ??= WEAK_MONITOR_CLAIM
    // Our own tile lights up too, so a person can see they are being picked
    // up rather than guessing. Muting sets `track.enabled = false`, which
    // feeds the analyser silence, so a muted mic goes dark on its own.
    speakingMonitor.watch(LOCAL_SPEAKING_KEY, micTrack)
    publishActiveTracks()
    renderVoiceState(pipeline.state)
  } else {
    micTrack.enabled = !micTrack.enabled
    if (micTrack.enabled) {
      // An explicit unmute is how this device takes the mic back from
      // another paired device. The speaker stays where it was.
      besideAnotherDevice = false
      micClaimedAt = takeRole('mic')
      monitorClaimedAt ??= WEAK_MONITOR_CLAIM
    }
    // Either way the roster's mute flag has to follow, so the far end's
    // tile stops guessing from audio energy - see `currentAdverts`.
    publishActiveTracks()
  }
  updateUi()
}

async function toggleCamera(): Promise<void> {
  if (mediaUsesBothy()) throw new Error('Camera sharing is unavailable on this text-only Bothy route.')
  const generation = callGeneration
  if (switchingRoom) return
  if (!camera && (meetingRefuses() || !await consentToRecordedCall())) return
  if (!camera) callWanted = true
  if ([...pendingMedia].some(pipeline => pipeline instanceof CameraPipeline)) return
  if (camera) {
    camera.stop()
    camera = undefined
    cameraTrack = undefined
    localPreviewEls.get('camera')?.remove()
    localPreviewEls.delete('camera')
    // Turning something off has to be published exactly as loudly as turning
    // it on. Stopping the track locally is invisible to everybody else: a
    // sender left in place sends nothing and says nothing, so the far end
    // holds the last frame it decoded and shows it for the rest of the call.
    // Somebody who turned their camera off was still sitting on the other
    // people's screens, frozen. See Peer#start.
    publishActiveTracks()
  } else {
    const pipeline = new CameraPipeline({
      mode: savedEffectMode,
      facePrivacy: savedFacePrivacyMode,
      onFacePrivacyChange: state => { if (generation === callGeneration) renderFacePrivacyState(state) },
      strength: savedBlurStrength,
      framing: framingEnabled,
      onStateChange: state => { if (generation === callGeneration) renderEffectState(state) },
      onSourceEnded: () => {
        if (generation !== callGeneration) return
        void recoverCallMedia()
      },
    })
    pendingMedia.add(pipeline)
    try {
      const track = await pipeline.start({ deviceId: loadCameraDeviceId(deviceStore) })
      if (generation !== callGeneration) { pipeline.stop(); return }
      cameraTrack = track
    } catch (err) {
      pipeline.stop()
      if (generation !== callGeneration) return
      throw err
    } finally {
      pendingMedia.delete(pipeline)
    }
    camera = pipeline
    if (pipeline.deviceId) storeCameraDeviceId(deviceStore, pipeline.deviceId)
    // A remembered "replace" choice needs its background loaded too - the
    // same two calls `setEffectMode` makes for an explicit switch, just
    // made here for the mode the pipeline already started on.
    if (savedEffectMode === 'replace') {
      const choice = BACKGROUNDS.find((b) => b.id === backgroundId) ?? BACKGROUNDS[0]
      if (choice) {
        await pipeline.setFish(fishEnabled)
        await pipeline.setBackground(choice)
      }
    }
    // The preview shows the CANVAS, not the camera, so what you see is what
    // the room gets - including whatever the effect is or is not managing to
    // do about the wall behind you.
    addLocalPreview('camera', cameraTrack)
    publishActiveTracks()
    renderEffectState(pipeline.status)
    listVideoInputs().catch(() => {
      // A browser that will not enumerate devices without a prior grant just
      // means no switch button. Not worth a status line.
    })
  }
  updateUi()
}

// ---------------------------------------------------------------------------
// Effect controls
//
// Both of these features are easy to mistake for a promise. The camera one
// is a guess that leaks at the edges; the voice one defeats casual
// recognition and nothing more. So the controls report what is actually
// happening rather than what was selected - above all when an effect the
// user believes is on has failed, which is the one state where somebody
// could be publishing a room they think is hidden.
// ---------------------------------------------------------------------------

/** Whether this device shows its own camera as a mirror, which is what most
 *  people expect of a self-view and some find backwards. Only the preview:
 *  the picture sent to the room is never flipped. */
function mirrorSelf(): boolean {
  return deviceStore.get('kithmoot.mirror-self') !== 'false'
}

function applyMirrorSelf(): void {
  document.documentElement.dataset.mirrorSelf = String(mirrorSelf())
  setToggle('toggleMirror', mirrorSelf())
}

function revealEffects(id: string, show: boolean): void {
  const details = $(id) as HTMLDetailsElement
  details.hidden = !show
  if (!show) details.open = false
}

function markSegmented(containerId: string, attribute: string, value: string): void {
  for (const button of $(containerId).querySelectorAll<HTMLButtonElement>('button')) {
    button.setAttribute('aria-checked', String(button.dataset[attribute] === value))
  }
}

function renderEffectState(state: VideoEffectState): void {
  $('effectMode').textContent = state.mode
  markSegmented('effectModes', 'mode', state.mode)
  // Strength is a blur radius, so it belongs to blur and to nothing else.
  $('strengthRow').hidden = state.mode !== 'blur'
  $('backgroundChoices').hidden = state.mode !== 'replace'
  // Only over a sea. Offering fish over Slate would be a question with no
  // sensible answer.
  // Framing follows the effect's picture of where you are, so there is
  // nothing to follow with the effect off.
  $('framingRow').hidden = state.mode === 'off'
  $('fishRow').hidden =
    state.mode !== 'replace' || !BACKGROUNDS.find((b) => b.id === backgroundId)?.sea

  const line = $('effectStatus')
  line.classList.remove('broken', 'working')
  if (state.mode === 'off') {
    line.textContent = 'The room behind you is going out as it is.'
    line.classList.add('working')
  } else if (state.status === 'degraded') {
    line.textContent = `Background effects have stopped working: ${state.error ?? 'the model would not load'}. Your camera is not being shown - only your backdrop or a full blur is, while it keeps retrying.`
    line.classList.add('broken')
  } else if (state.status === 'loading' || state.status === 'idle') {
    line.textContent =
      state.mode === 'replace'
        ? 'Loading the background model. Your backdrop is covering the frame until it arrives.'
        : 'Loading the background model. Everything is blurred until it arrives.'
    line.classList.add('working')
  } else {
    line.textContent = 'Running.'
    line.classList.add('working')
  }

  renderEffectFailureNotice()
}

function renderFacePrivacyState(state?: FacePrivacyState): void {
  const current = state ?? camera?.facePrivacyState
  const mode = current?.mode ?? savedFacePrivacyMode
  $('facePrivacyMode').textContent = mode
  markSegmented('facePrivacyModes', 'privacy', mode)
  const notice = $('facePrivacyNotice')
  notice.hidden = !camera || mode === 'off'
  notice.textContent = current?.message ?? ''
  notice.classList.toggle('broken', mode === 'mask' && current?.covered === true)
  renderEffectFailureNotice()
}

/**
 * The notice next to the self-view, seen without opening the folded "Hide
 * what is behind you" details.
 *
 * Driven off what the effect actually just painted (`lastAction`) and
 * whether it has failed and not yet earned its way back (`untrustworthy`),
 * not off `status`: `status` flips to `loading` for every retry attempt,
 * which is exactly the moment this must not go quiet. Runs on the same
 * 500ms tick as `publishEffectStats` so a retry's outcome shows up promptly
 * either way, and once more from `renderEffectState` so a mode change is
 * not left showing stale wording for up to that long.
 */
function renderEffectFailureNotice(): void {
  const outer = $('effectDegradedNotice')
  const action = camera?.lastAction
  const failing = camera?.facePrivacyState.mode === 'off' && !!camera.untrustworthy && (action === 'cover' || action === 'blur-all')
  if (!failing) {
    outer.hidden = true
    outer.textContent = ''
    return
  }
  outer.hidden = false
  outer.textContent =
    camera!.mode === 'replace'
      ? 'Others see only your backdrop, not you. Background cut-outs are unavailable.'
      : 'Others see a full blur, not you. Background cut-outs are unavailable.'
}

function renderVoiceState(state: MicState): void {
  $('voiceMode').textContent = state.preset
  markSegmented('voicePresets', 'preset', state.preset)
  const notice = $('voiceFailureNotice')
  notice.hidden = !state.blocked
  notice.textContent = state.blocked ? 'Microphone muted: voice masking failed. Press Microphone to retry. You can choose Off in Effects, under More, to use your own voice.' : ''
  const line = $('voiceStatus')
  line.classList.remove('broken', 'working')
  if (state.status === 'degraded') {
    line.textContent = state.blocked
      ? `Microphone muted because voice masking failed: ${state.error ?? 'the voice processor stopped'}. Press Microphone to try again, or choose Off and unmute to use your own voice.`
      : `Masking is set to Off. The browser's audio graph is unavailable; your own voice is available when unmuted.`
    line.classList.add('broken')
    return
  }
  line.classList.add('working')
  line.textContent =
    state.status === 'idle'
      ? (state.preset === 'off' ? 'Your own voice when the microphone is on.' : 'Mask selected. Turn the microphone on to hear a preview.')
      : state.preset === 'off'
      ? 'Your own voice, with nothing added to it.'
      : `Adds ${state.addedLatencyMs.toFixed(0)}ms of delay on top of the ${state.baseLatencyMs.toFixed(0)}ms this browser already costs.`
}

async function listVideoInputs(): Promise<void> {
  const devices = await navigator.mediaDevices.enumerateDevices()
  videoInputs = devices.filter((d) => d.kind === 'videoinput')
  // One camera is not a choice. A phone reports its front and back as two
  // devices, so this covers the flip case without a separate control, and a
  // laptop with one webcam simply never sees the button.
  $('switchCamera').hidden = videoInputs.length < 2
}

async function switchCamera(): Promise<void> {
  const pipeline = camera
  if (!pipeline) return
  if (videoInputs.length < 2) await listVideoInputs()
  if (camera !== pipeline) return
  const current = videoInputs.findIndex((d) => d.deviceId === camera?.deviceId)
  const next = videoInputs[(current + 1) % videoInputs.length]
  if (!next) return
  try { await pipeline.useCamera({ deviceId: next.deviceId }) }
  finally { if (camera !== pipeline) pipeline.stop() }
  if (camera === pipeline && pipeline.deviceId) storeCameraDeviceId(deviceStore, pipeline.deviceId)
}

function renderBackgroundChoices(): void {
  const box = $('backgroundChoices')
  if (box.childElementCount > 0) return
  for (const choice of BACKGROUNDS) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'seg'
    button.setAttribute('role', 'radio')
    button.dataset.background = choice.id
    button.textContent = choice.label
    button.addEventListener('click', () => {
      chooseBackground(choice).catch((err) => setStatus(describeError(err)))
    })
    box.append(button)
  }
  markSegmented('backgroundChoices', 'background', backgroundId)
}

async function chooseBackground(choice: BackgroundChoice): Promise<void> {
  backgroundId = choice.id
  storeBackgroundId(deviceStore, backgroundId)
  markSegmented('backgroundChoices', 'background', backgroundId)
  if (camera) renderEffectState(camera.status)
  await camera?.setBackground(choice)
}

async function setEffectMode(mode: EffectMode): Promise<void> {
  storeEffectMode(deviceStore, mode)
  const pipeline = camera
  if (!pipeline) return
  if (mode === 'replace') {
    // Told before the picture is loaded, so the first composited frame
    // already has whatever this device asked for last time.
    await pipeline.setFish(fishEnabled)
    const choice = BACKGROUNDS.find((b) => b.id === backgroundId) ?? BACKGROUNDS[0]
    // Loaded before the mode changes, so there is no frame where replace is
    // selected with nothing to replace with. If it fails the effect stays on
    // blur, which shows the room to nobody either way.
    if (choice) await pipeline.setBackground(choice)
  }
  if (camera !== pipeline) return
  pipeline.setMode(mode)
  renderEffectState(pipeline.status)
}

/** Frame counters and rate, published on the effects panel as data
 *  attributes. A `data-passthrough` above zero while the mode is not `off`
 *  means an unmodified camera frame was published, which is the failure this
 *  whole feature exists to prevent - so it is measured and readable rather
 *  than argued about. */
function publishEffectStats(): void {
  const panel = $('effects')
  if (!camera) {
    panel.removeAttribute('data-fps')
    renderEffectFailureNotice()
    return
  }
  const totals = camera.totals
  const stats = camera.stats
  panel.dataset.fps = String(stats.fps)
  panel.dataset.frameCostMs = stats.frameCostMs.toFixed(2)
  panel.dataset.mask = stats.mask
  panel.dataset.passthrough = String(totals.passthrough)
  panel.dataset.blurAll = String(totals['blur-all'])
  panel.dataset.cover = String(totals.cover)
  panel.dataset.composite = String(totals.composite)
  renderEffectFailureNotice()
}

setInterval(publishEffectStats, 500)

/**
 * Screen Capture API fields TypeScript's bundled DOM lib does not know yet.
 * Chromium honours them; a browser that does not simply ignores what it
 * does not recognise, so asking for them is harmless everywhere.
 */
interface ScreenCaptureOptions extends DisplayMediaStreamOptions {
  systemAudio?: 'include' | 'exclude'
  windowAudio?: 'window' | 'system' | 'exclude'
  selfBrowserSurface?: 'include' | 'exclude'
  surfaceSwitching?: 'include' | 'exclude'
}

let screenStarting = false
async function toggleScreen(area = false): Promise<void> {
  if (mediaUsesBothy()) throw new Error('Screen sharing is unavailable on this text-only Bothy route.')
  const generation = callGeneration
  if (switchingRoom) return
  if (screenStarting) return
  if (!screenTrack && (meetingRefuses() || !await consentToRecordedCall())) return
  if (!screenTrack) callWanted = true
  if (screenTrack) {
    desktopShareArea.stop()
    shareMarksOverlay.close()
    screenTrack.stop()
    screenTrack = undefined
    shareMayShowItself = false
    desktopRedaction.setHidden(false)
    screenAudioTrack?.stop()
    screenAudioTrack = undefined
    localPreviewEls.get('screen')?.remove()
    localPreviewEls.delete('screen')
    // Nothing left to show a mark on: close the floating window and drop
    // any notice about drawing on a share that no longer exists.
    floatingSharePreview.close()
    hideDrawingNotice()
    clearShareError()
    // Same as the camera, and worse if it is missed: a screen share nobody
    // was told had stopped stays frozen on everybody else's display.
    publishActiveTracks()
  } else {
    // Absent on iOS Safari and unreliable on Android Chrome - which is
    // exactly why the mobile app is native rather than a browser tab.
    if (!navigator.mediaDevices.getDisplayMedia) {
      throw new Error(
        'This browser cannot share a screen. iOS has no way to do it from any browser - ' +
          'use a desktop browser, or the Android app.',
      )
    }
    // Processing left off: shared sound is usually a video or music playing
    // in a tab, not somebody's voice, and echo cancellation tuned for speech
    // mangles it. Firefox and Safari offer no display audio at all, and a
    // window share or an unticked "share tab audio" box leaves it out too -
    // the share still goes ahead, silently; see `updateScreenAudioNote`.
    const options: ScreenCaptureOptions = {
      video: true,
      audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false, restrictOwnAudio: true } as MediaTrackConstraints & { restrictOwnAudio: boolean },
      systemAudio: 'include',
      windowAudio: 'window',
      selfBrowserSurface: 'exclude',
      surfaceSwitching: 'include',
    }
    screenStarting = true
    let stream: MediaStream
    let surface: string | undefined
    let capture: CaptureIdentity = {}
    try {
      // The desktop app sends every whole-screen share through the redaction
      // canvas, boxes or not, so the raw capture itself is never published.
      // Awaited only in the desktop app: a browser's own chooser keeps the
      // click's activation without a round trip in front of it.
      if (desktopRedaction.supported) await desktopRedaction.begin()
      stream = area ? await desktopShareArea.start() : await navigator.mediaDevices.getDisplayMedia(options)
      surface = stream.getVideoTracks()[0]?.getSettings().displaySurface
      // Read off the raw capture, before any redaction canvas stands in for it.
      capture = {
        deviceId: stream.getVideoTracks()[0]?.getSettings().deviceId,
        ownIds: await window.kithmootDesktop?.ownCaptureIds?.().catch(() => undefined),
      }
      if (!area && desktopRedaction.supported) {
        const raw = stream
        stream = await desktopRedaction.redact(raw, renderRedactionNote).catch(error => { for (const track of raw.getTracks()) track.stop(); throw error })
      }
    }
    finally { screenStarting = false }
    if (generation !== callGeneration || leftCall) { for (const track of stream.getTracks()) track.stop(); if (area) desktopShareArea.stop(); return }
    screenTrack = stream.getVideoTracks()[0]
    screenAudioTrack = stream.getAudioTracks()[0]
    // An area share already tracks this precisely, reactively, via the
    // frame's own rect (see `wholeDisplay` above, on `desktopShareArea`); a
    // plain share carries the standard hint on the captured track, read
    // before any redaction canvas stood in for it, and needs checking only
    // the once, here.
    if (!area) shareMayShowItself = mayShowItself(surface, capture)
    if (screenTrack) {
      // Fires when the user stops sharing from the browser's own UI, not
      // ours - the toggle has to notice either way.
      screenTrack.addEventListener('ended', () => {
        if (generation !== callGeneration) return
        desktopShareArea.stop()
        shareMarksOverlay.close()
        screenTrack = undefined
        shareMayShowItself = false
        desktopRedaction.setHidden(false)
        screenAudioTrack?.stop()
        screenAudioTrack = undefined
        localPreviewEls.get('screen')?.remove()
        localPreviewEls.delete('screen')
        floatingSharePreview.close()
        hideDrawingNotice()
        clearShareError()
        publishActiveTracks()
        updateUi()
      })
      // The picture can keep sharing after its sound stops on its own - a
      // tab switch, on a browser that ties system audio to a shared tab
      // having focus. Unadvertise the sound and leave the picture alone.
      screenAudioTrack?.addEventListener('ended', () => {
        if (generation !== callGeneration) return
        screenAudioTrack = undefined
        publishActiveTracks()
        updateUi()
      })
      addLocalPreview('screen', screenTrack)
      clearShareError()
      publishActiveTracks()
      // A whole screen: other people's marks go over the screen itself. The
      // main process's record of what was captured has to agree with the
      // track's own idea of it, as it does for redaction.
      if (!area && shareMarksOverlay.supported) {
        const shared = screenTrack
        void desktopRedaction.refresh().then(state => {
          if (screenTrack !== shared || effectiveSource(state.source, surface)?.kind !== 'screen') return
          shareMarksOverlay.open(() => screenSource(meParticipant, myDeviceId)?.id ?? shared.id)
        })
      }
    } else {
      // No picture came back at all: nothing to show, so stop whatever the
      // browser did hand over rather than leak a live capture nobody sees.
      for (const track of stream.getTracks()) track.stop()
      screenAudioTrack = undefined
    }
  }
  updateUi()
}

/**
 * A screen share that failed, said once and taken back.
 *
 * The status line outlives what it is about: a share that failed and was
 * then retried successfully left "Invalid capture constraints" in red under
 * a screen that was plainly being shared. So the line remembers it is
 * showing a share error, and a successful share, a stop or leaving the call
 * clears it - only if nothing else has been said on that line since.
 * `shownShareError` is declared beside `setStatus`, above anything that can
 * run at start-up.
 */
function showShareError(err: unknown): void {
  // The desktop app refuses a share the same way whether macOS withheld
  // Screen Recording or the person closed the "Choose what to share" menu,
  // and the page cannot tell which. With the permission granted it was the
  // person, and a cancel needs no message at all.
  const access = window.kithmootDesktop?.screenAccess
  if (access && isSystemRefusal(err)) {
    access().then(status => { if (status !== 'granted') reportShareError(err) }, () => reportShareError(err))
    return
  }
  reportShareError(err)
}

function reportShareError(err: unknown): void {
  const text = describeShareError(err)
  setStatus(text.plain)
  // The browser's own words, for a bug report, kept off the page itself.
  if (text.raw) $('status').title = `Details: ${text.raw}`
  if (text.raw) console.error(`Screen share failed: ${text.raw}`)
  shownShareError = text.plain
}

function clearShareError(): void {
  if (shownShareError !== undefined && $('status').textContent === shownShareError) setStatus('')
  shownShareError = undefined
}

function addLocalPreview(kind: 'camera' | 'screen', track: MediaStreamTrack): void {
  const video = document.createElement('video')
  if (kind === 'camera') video.classList.add('localCameraPreview')
  video.srcObject = new MediaStream([track])
  video.autoplay = true
  video.muted = true
  video.playsInline = true
  localMediaEl.append(video)
  localPreviewEls.set(kind, video)
  // A screen preview may be born already inside the recursion guard: the
  // area frame can report a whole-display area before the share's own track
  // exists (see `DesktopShareArea#setRect`), so nothing has applied the
  // guard to this element yet.
  if (kind === 'screen') applySelfMirrorGuard()
}

/**
 * Withholds this device's own live picture of its own share from every one
 * of KithMoot's surfaces that show it, whenever the share may be capturing
 * one of those surfaces - see `shareMayShowItself` and
 * `self-mirror-guard.ts`. Otherwise a full-screen area, a whole screen, or
 * KithMoot's own window captures the very tile or window showing the capture,
 * which shows the capture, and so on: a hall of mirrors, reported from a
 * real call.
 *
 * The marks overlay each of these carries (`shareMarkOverlays`,
 * `ShareViewer#overlay`) is untouched - it paints on a canvas of its own,
 * never a copy of the video's pixels - so drawing on a full-screen share
 * still shows up for the sharer, just without a live picture behind it. In
 * the desktop app a whole-screen share's marks also go over the screen
 * itself (`shareMarksOverlay`), which is where the sharer is looking.
 */
function applySelfMirrorGuard(): void {
  const preview = localPreviewEls.get('screen')
  if (preview) {
    if (shareMayShowItself) {
      if (preview.srcObject) { preview.pause(); preview.srcObject = null }
      preview.classList.add('selfMirrorGuard')
    } else {
      preview.classList.remove('selfMirrorGuard')
      if (!preview.srcObject && screenTrack) { preview.srcObject = new MediaStream([screenTrack]); void preview.play().catch(() => {}) }
    }
  }
  floatingSharePreview.sync()
}

/** Which of our own preview elements a track advert corresponds to, if any.
 *  Audio has no picture, so a mic is always a chip and never a preview. */
function previewKindOf(role: TrackAdvert['role']): 'camera' | 'screen' | undefined {
  if (role === 'camera') return 'camera'
  if (role === 'screen') return 'screen'
  return undefined
}

/**
 * Letting the person doing the sharing see marks drawn on their own screen.
 *
 * A preview tile is not where somebody presenting is looking - they are
 * looking at the window or screen they are sharing, not at this page's own
 * small picture of it. Two ways to close that gap: a floating window that
 * sits above whatever they are looking at (Chromium desktop only, opened by
 * `floatingSharePreview` above), and, everywhere else and whenever that
 * window is not open, a brief notice naming who is drawing and offering to
 * bring the ordinary preview into view - or, where the floating window is
 * available, to open it, which needs a gesture and so cannot happen on its
 * own the moment a mark arrives.
 */
const DRAWING_NOTICE_MS = 8000
let drawingNoticeTimer: ReturnType<typeof setTimeout> | undefined

function showDrawingNotice(drawer: string): void {
  $('sharerMarksNoticeText').textContent = `${personLabel(drawer)} is drawing on your screen`
  $('sharerMarksNoticeFloat').hidden = !floatingPreviewSupported()
  $('sharerMarksNotice').hidden = false
  clearTimeout(drawingNoticeTimer)
  drawingNoticeTimer = setTimeout(hideDrawingNotice, DRAWING_NOTICE_MS)
}

function hideDrawingNotice(): void {
  clearTimeout(drawingNoticeTimer)
  drawingNoticeTimer = undefined
  $('sharerMarksNotice').hidden = true
}

function revealMySharePreview(): void {
  localPreviewEls.get('screen')?.scrollIntoView({ behavior: 'smooth', block: 'center' })
}

/** Called for every mark this device receives: worth a notice only when it
 *  lands on this device's own current share, was drawn by somebody else,
 *  the floating window is not already open to show it directly, and this
 *  drawer has not already been announced within the rate limit. */
function notifyDrawingOnMyShare(drawer: string, annotation: ScreenAnnotation): void {
  if (annotation.op !== 'stroke') return
  if (!screenTrack || annotation.shareId !== screenTrack.id) return
  if (drawer === meParticipant) return
  if (floatingSharePreview.isOpen) return
  if (!drawingNoticeGate.shouldShow(drawer)) return
  showDrawingNotice(drawer)
}

$('sharerMarksNoticeShow').addEventListener('click', () => { hideDrawingNotice(); revealMySharePreview() })
$('sharerMarksNoticeFloat').addEventListener('click', () => {
  hideDrawingNotice()
  floatingSharePreview.open().then(updateUi).catch(() => {})
})
$('toggleFloatingMarks').addEventListener('click', () => {
  // Closing is immediate; opening is async (the request itself awaits the
  // platform), so the toggle's own state only catches up once it settles.
  if (floatingSharePreview.isOpen) { floatingSharePreview.close(); updateUi() }
  else floatingSharePreview.open().then(updateUi).catch(() => {})
})

/** Publish this device's whole current set of active tracks. Always the full
 *  set, never just what changed: `Mesh`/`Peer` keep their own per-peer record
 *  of what has already been added to which connection, so re-sending a track
 *  that is already there is a safe no-op, and a device that joins the mesh
 *  after a later toggle still gets everything published before it arrived. */
const AGENTS_HEAR_STORAGE_KEY = 'kithmoot.agents-hear'

/**
 * Whether anything in this room that says it is an agent is sent this
 * device's media.
 *
 * Off by default, and remembered. Off means the tracks are never handed to
 * the connection to an agent - see `RoomSession.publishTracks` - so a
 * conversation people want to have among themselves is one no agent in the
 * room can hear, whatever it claims to be for. On is the case a person
 * chooses when they want an agent following along, and a listening agent
 * then writes what they say into the transcript channel. Per device, per
 * person: it is my media, so it is my switch.
 */
let agentsMayHear = localStorage.getItem(AGENTS_HEAR_STORAGE_KEY) === 'true'

/** Sessions joined with "Hide my IP address": their calls go through the
 *  relay only. Kept per session, so a docked call and the room on screen
 *  never borrow each other's answer. */
const sessionRelayOnly = new WeakMap<RoomSession, boolean>()

/** Who this device's media goes to: everybody, unless they say they are an
 *  agent and the switch above is off. */
function audience(view: ParticipantView): boolean {
  return view.agent !== true || agentsMayHear
}

/** What an agent's tile or chip says while this person has let agents hear
 *  them: said where the agent is, so the setting is never only in a menu. */
function hearsYouNote(): HTMLElement {
  const note = document.createElement('span')
  note.className = 'hearsYou'
  note.textContent = 'can hear you'
  return note
}

function setAgentsMayHear(on: boolean): void {
  agentsMayHear = on
  try {
    localStorage.setItem(AGENTS_HEAR_STORAGE_KEY, String(on))
  } catch {
    // Storage may be unavailable; the switch still works for this page.
  }
  setToggle('toggleAgentsHear', on)
  $('agentsHearNote').textContent = on
    ? 'On: agents get your camera and microphone like anybody else does, and one that is listening writes what you say into the transcript.'
    : 'Off: nothing that says it is an agent is sent your camera or microphone. It never leaves this device for them.'
  document.documentElement.toggleAttribute('data-agents-hear', on)
  publishActiveTracks()
  // The tiles and chips of agents say "can hear you" while it is on.
  if (session) render(session.participants(), meParticipant)
}

/** When this device last took the microphone, for the singular-role claim.
 *  Stamped when the mic comes on, so a device that has held it since the
 *  start is not outranked by its owner's other device toggling later. */
let micClaimedAt: number | undefined
/** Listening is independent of capture. Only Listen here takes an existing
 * speaker role away from another device. */
let monitorClaimedAt: number | undefined
/** Explicit escape hatch when a phone entered through the ordinary room link.
 * There is no safe way to infer physical proximity from room or network data,
 * so the person can silence this device while retaining its camera/share. */
let besideAnotherDevice = false
/** A deliberate take of a singular role from this person's other device.
 *  Stamped past every claim already seen rather than at this device's own
 *  clock: a phone whose clock runs a second or two ahead, or one that has
 *  just taken the role itself, would otherwise keep winning, and an unmute
 *  here would be undone on the next render - see `renderCallMedia`. */
function takeRole(role: SingularRole): number {
  try { return mediaSession()?.nextRoleClaim(role) ?? nowSeconds() }
  catch { return nowSeconds() }
}
/** A speaker claim that loses to any real one. A device with only a
 *  microphone on claims the speaker this weakly, so two devices of one
 *  person never both play sound unless the person asks. */
const WEAK_MONITOR_CLAIM = 1

/**
 * What this device is publishing, as the roster should advertise it: the
 * real track ids, which are what a volunteer carrying this device's media
 * has to match a forwarded track against - see `Mesh.#trackOwner`.
 */
function currentAdverts(): TrackAdvert[] {
  const adverts: TrackAdvert[] = []
  if (cameraTrack) adverts.push({ trackId: cameraTrack.id, role: 'camera' })
  if (micTrack) adverts.push({ trackId: micTrack.id, role: 'mic', ...(micTrack.enabled === false ? { muted: true } : {}) })
  if (screenTrack) adverts.push({ trackId: screenTrack.id, role: 'screen' })
  if (screenAudioTrack) adverts.push({ trackId: screenAudioTrack.id, role: 'screen-audio' })
  return adverts
}

function currentClaims(): Partial<Record<SingularRole, number>> {
  const claims: Partial<Record<SingularRole, number>> = {}
  if (!besideAnotherDevice && micTrack) {
    micClaimedAt ??= nowSeconds()
    claims.mic = micClaimedAt
  }
  if (!besideAnotherDevice && (onCall() || micTrack || cameraTrack || screenTrack)) {
    const owner = mediaSession()?.participants().find(view => view.participant === mediaMe())?.monitor
    if (monitorClaimedAt === undefined && (!owner || owner === myDeviceId)) monitorClaimedAt = nowSeconds()
    if (monitorClaimedAt !== undefined) claims.monitor = monitorClaimedAt
  }
  return claims
}

function toggleCompanionMode(): void {
  besideAnotherDevice = !besideAnotherDevice
  if (besideAnotherDevice) {
    if (micTrack) micTrack.enabled = false
    micClaimedAt = monitorClaimedAt = undefined
  } else {
    if (micTrack) micClaimedAt = takeRole('mic')
    if (micTrack || cameraTrack || screenTrack) monitorClaimedAt = takeRole('monitor')
  }
  publishActiveTracks()
  updateUi()
}

/** Send the live tracks to every peer, and tell the roster what they are.
 *  Both, every time: the peers carry the media, and the roster is what
 *  everybody else's tile reads to say "camera" or "connecting". */
function publishActiveTracks(): void {
  if (!micTrack) micClaimedAt = undefined
  const s = mediaSession()
  s?.publishTracks(activeTracks(), { audience })
  s?.advertise(currentAdverts(), currentClaims()).catch(() => {})
  if (s && !s.call && activeTracks().length > 0) {
    const visible = s.calls()[0]?.id
    const id = callToDeclare(visible, callWanted, newCallId)
    logCall('call-declared', undefined, !id ? 'none visible, none started' : `${id === visible ? 'joined' : 'started'} ${id.slice(0, 8)} with media`)
    if (!id) return
    leftCall = false
    s.setCall({ id, since: nowSeconds() }).catch(() => {})
  }
}

function setToggle(id: string, on: boolean): void {
  $(id).dataset.on = String(on)
  $(id).setAttribute('aria-pressed', String(on))
}

/** "No sound is shared", next to the share toggle - only while a share is
 *  live and the browser handed over no audio track: Firefox, Safari, a
 *  window share, or the box left unticked. The share still goes ahead, so
 *  this says why nobody can hear it rather than stopping it. Hidden the
 *  moment the share ends, so it never outlives the share it is about. */
function updateScreenAudioNote(): void {
  $('screenAudioNote').hidden = !screenTrack || !!screenAudioTrack
  $('screenAudioNote').textContent = window.kithmootDesktop
    ? 'No sound was captured. Check screen and system audio recording permissions, then restart sharing.'
    : 'No sound is shared. To share sound, share a browser tab and tick Share tab audio.'
}

/** Says why this device's own share is black, while it is. */
function renderRedactionNote(note: string | undefined): void {
  const line = document.getElementById('redactionNote')
  if (!line) return
  line.textContent = note ?? ''
  line.hidden = !note
}

/**
 * Hides or shows this device's whole outgoing share. The track stays live
 * and is never swapped, so nothing is renegotiated and no raw frame goes out
 * on the way in or the way back: the canvas simply covers the picture. The
 * share's sound is silenced with it.
 */
function setShareHidden(hidden: boolean): void {
  desktopRedaction.setHidden(hidden && !!screenTrack)
  if (screenAudioTrack) screenAudioTrack.enabled = !desktopRedaction.hidden
}

function updateRedactionControls(): void {
  const hide = document.getElementById('hideShare')
  if (hide) {
    const hidden = desktopRedaction.hidden
    hide.hidden = !screenTrack
    setToggle('hideShare', hidden)
    hide.textContent = hidden ? 'Show my share' : 'Hide my share'
    hide.title = hidden ? 'Let people see your share again' : 'Cover your whole share, and silence its sound, until you show it again'
    // An area share has no note of its own; a screen share says the same words.
    const line = document.getElementById('redactionNote')
    if (hidden) renderRedactionNote(coverCopy('hidden'))
    else if (line?.textContent === coverCopy('hidden')) renderRedactionNote(undefined)
  }
  const all = document.getElementById('toggleRedaction')
  if (!all) return
  // Each press adds a box, and the button says so once there is one.
  const add = document.getElementById('addRedaction')
  if (add) add.textContent = desktopRedaction.count === 0 ? 'Hide part of the screen' : 'Hide another part'
  all.hidden = desktopRedaction.count === 0
  setToggle('toggleRedaction', desktopRedaction.anyOn())
  all.textContent = desktopRedaction.anyOn() ? 'Redaction on' : 'Redaction off'
  all.title = desktopRedaction.anyOn() ? 'Show every boxed part of the screen in the share' : 'Black out every boxed part of the screen again'
}

function updateUi(): void {
  if ((callIsLive() || onCall()) && !docked()) setCallOpen(true)
  setToggle('toggleMic', !!micTrack?.enabled)
  setToggle('toggleCamera', !!cameraTrack)
  setToggle('toggleScreen', !!screenTrack)

  updateRedactionControls()
  const areaButton = document.getElementById('shareArea') as HTMLButtonElement | null
  if (areaButton) areaButton.disabled = !!screenTrack
  const share = $('toggleScreen')
  const sharing = !!screenTrack
  share.setAttribute('aria-label', sharing ? 'Stop screen sharing' : 'Screen share')
  share.title = sharing ? 'Stop sharing your screen' : 'Share your screen'
  const full = share.querySelector('.callFull')
  const short = share.querySelector('.callShort')
  if (full) full.textContent = sharing ? 'Stop sharing' : 'Screen share'
  if (short) short.textContent = sharing ? 'Stop' : 'Share'
  // Locked, not disabled: a press still says why, which a disabled button
  // cannot. See `meetingRefuses`. The usual title is kept aside and put
  // back when the lock lifts.
  const locked = !meetingLetsMeSend()
  for (const id of ['toggleMic', 'toggleCamera', 'toggleScreen']) {
    const button = $(id)
    button.classList.toggle('meetingLocked', locked)
    if (locked) {
      if (button.title !== MEETING_LOCKED) button.dataset.unlockedTitle = button.title
      button.setAttribute('aria-disabled', 'true')
      button.title = MEETING_LOCKED
    } else {
      button.removeAttribute('aria-disabled')
      if (button.title === MEETING_LOCKED) button.title = button.dataset.unlockedTitle ?? ''
    }
  }
  updateScreenAudioNote()
  // Only worth offering while there is something to float: this device's
  // own share, on a browser that can open the window at all.
  $('toggleFloatingMarks').hidden = !screenTrack || !floatingPreviewSupported()
  setToggle('toggleFloatingMarks', floatingSharePreview.isOpen)
  setToggle('toggleCompanion', besideAnotherDevice)
  $('companionNote').hidden = !besideAnotherDevice
  renderWakeLockNote()
  // A background control with no camera running is a control for nothing.
  // Both open themselves the first time they appear rather than hiding
  // behind a disclosure: blur is on by default, so the control that turns it
  // off has to be visible without hunting for it, and the paragraph saying
  // what neither effect can do is worth as much as the buttons above it.
  revealEffects('cameraEffects', !!camera)
  renderFacePrivacyState()
  revealEffects('voiceEffects', true)
  ;($('voicePreview') as HTMLButtonElement).disabled = !mic || mic.state.blocked
  if (camera) renderBackgroundChoices()
  if (session || dockedCall) {
    repaint()
  } else {
    $('micIndicator').textContent = micTrack?.enabled ? 'Mic is ready - not in a room yet' : ''
  }
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

/**
 * Which participants have said they are agents.
 *
 * Remembered rather than looked up live, because chat is durable and the
 * roster is not: a message from an agent that has since left the room would
 * otherwise lose its tag at exactly the moment there is nobody to ask. A key
 * this room's roster has never carried is not marked, which is honest - the
 * claim comes from the roster and from nowhere else.
 */
const agentParticipants = new Set<string>()
const agentDisplayNames = new Map<string, string>()
const receiptAgents = new Set<string>()
const requestStatusUpdates = new Map<HTMLElement, () => void>()
setInterval(() => {
  for (const [element, update] of requestStatusUpdates) {
    if (!element.isConnected) requestStatusUpdates.delete(element)
    else update()
  }
}, 5_000)

function participantIsAgent(participant: string): boolean {
  return agentParticipants.has(participant)
}

function render(views: ParticipantView[], me: string): void {
  // A private conversation is titled for the other person, whose name
  // arrives with their presence, not with the link.
  if (dmPeer(roomPolicy, me) && $('roomTitle').textContent !== currentRoomLabel()) renderRoomTitle()
  // A catalogue can arrive before its participant's roster entry. Refresh
  // an open completion when presence catches up, or the ^ menu stays empty
  // until the person types again.
  if (document.activeElement === $('chatInput')) renderMentionPicker()
  const knownAgentCount = agentParticipants.size
  for (const view of views) if (view.agent) {
    agentParticipants.add(view.participant)
    if (view.name) agentDisplayNames.set(view.participant, view.name)
    if (view.requestReceipts) receiptAgents.add(view.participant)
    else receiptAgents.delete(view.participant)
  }
  // Beside a docked call the room on screen carries no media, and the tiles,
  // sound and call controls are the call's.
  if (dockedCall) renderCallMedia(dockedCall.session.participants(), dockedCall.me)
  else renderCallMedia(views, me)
  renderDock()
  renderAgentsExplain(views)
  renderRoomWho()
  if (($('roomSheet') as HTMLDialogElement).open) {
    renderSheetRoster(views, me)
    if (infoPage === 'main') renderRoomInfo()
  }

  // Which tabs are worth showing depends on who is here (Agents appears
  // when an agent does), so a roster change can change the row.
  const tabKey = navTabs().map(([name]) => name ?? '').join('\n')
  // A message can arrive before its sender's presence. Learning that sender
  // is an agent changes unread classification even when the tabs stay equal.
  if (tabKey !== renderedTabKey || agentParticipants.size !== knownAgentCount) {
    renderedTabKey = tabKey; renderConversationNav()
  }
  if (collisionsChanged) {
    collisionsChanged = false
    repaintActiveChat()
  }
}

/** The call's half of `render`: this device's roles, remote sound, tiles and
 *  call controls, for whichever session carries the call. */
const convergingCalls = new WeakSet<RoomSession>()
function renderCallMedia(views: ParticipantView[], me: string): void {
  const owner = mediaSession()
  const preferred = owner?.calls()[0]
  const convergence = callToConverge(owner?.call?.id, preferred,
    !!activeRecording || currentRecordingView(owner).state !== 'off')
  if (owner && convergence && !convergingCalls.has(owner)) {
    // Media already belongs to the room. Agree on its deterministic call id
    // before signed recordings bind their inputs to one of two raced starts.
    // A recorded call requires the normal explicit admission instead.
    convergingCalls.add(owner)
    const project = callProjectContexts.get(owner)?.project
    callProjectContexts.set(owner, {call: convergence.id, project})
    logCall('call-declared', undefined, `converged simultaneous starts on ${convergence.id.slice(0, 8)}`)
    void owner.setCall(convergence).catch(error => {if (mediaSession() === owner) setStatus(describeError(error))})
      .finally(() => {convergingCalls.delete(owner)})
  }
  callStage.setScope(`${owner?.roomId ?? ''}:${owner?.call?.id ?? owner?.calls()[0]?.id ?? ''}`)
  const mine = views.find((v) => v.participant === me)

  // A paired phone and laptop are one participant. Whichever device most
  // recently claimed the mic and monitor wins; the others must enforce that
  // answer locally or the role markers are only decoration and two nearby
  // speakers feed two nearby microphones.
  if (mine?.mic && mine.mic !== myDeviceId && micTrack?.enabled) micTrack.enabled = false
  const monitorHere = !besideAnotherDevice && (!mine?.monitor || mine.monitor === myDeviceId)
  // Never my own voice. A second device of mine on the call sends its
  // microphone to this one like anybody else's, and playing it is how a
  // person on a phone and a laptop heard themselves back, twice, a beat
  // late. Somebody who has pressed Leave hears none of it either: the
  // tracks still arrive, because the room's mesh outlives the call, but
  // Leave has to mean quiet. See `leftCall`.
  const ownDevices = new Set(mine?.devices ?? [])
  // A phone filming you, seen on the laptop beside it, is a self-view too:
  // mirrored like this device's own camera, or left and right swap.
  for (const [key, entry] of remoteVideos) {
    const device = tileDevice(key)
    entry.el.classList.toggle('ownCameraView', device !== myDeviceId && ownDevices.has(device) && key === tileKey(device, 'camera'))
  }
  cachedMonitorHere = monitorHere
  cachedOwnDevices = ownDevices
  // Which participant each device belongs to, so the loop below can look up
  // a person's own volume level - see `previewVolumeLevel` for the same
  // lookup while a slider is mid-drag, between renders.
  const deviceOwner = new Map<string, string>()
  for (const view of views) for (const device of view.devices) deviceOwner.set(device, view.participant)
  for (const [key, audio] of remoteAudios) {
    const device = key.slice(0, key.indexOf('|'))
    // Meeting mode: somebody not on the stage is not played, whatever their
    // own app chose to send. See `meetingGated`.
    const muted = !monitorHere || leftCall || ownDevices.has(device) || meetingGated(device)
    const owner = deviceOwner.get(device)
    const level = owner !== undefined ? volumeLevel(owner) : 1
    remoteVolume.apply(key, audio.el, audio.track, level, muted)
  }
  feedRecorder()

  const micElsewhere = mine?.mic !== undefined && mine.mic !== myDeviceId
  {
    const twoDevices = (mine?.devices.length ?? 0) > 1
    // Both on the other device: one sentence for the two of them, in place
    // of the microphone line saying half of it again - see `.otherDevice`
    // in style.css, and `[data-other-device]` for the line it stands in for.
    const both = twoDevices && !monitorHere && micElsewhere
    const monEl = $('monitorIndicator')
    monEl.hidden = !twoDevices
    monEl.textContent = !twoDevices ? ''
      : monitorHere ? 'Sound plays on this device.'
      : both ? 'Mic and sound are on your other device.'
      : 'Sound plays on your other device.'
    ;($('listenHere') as HTMLButtonElement).hidden = !twoDevices || monitorHere
    $('deviceControls').toggleAttribute('data-other-device', both)
  }
  const micEl = $('micIndicator')
  if (mine?.mic) {
    micEl.textContent = mine.mic === myDeviceId
      ? (micTrack?.enabled ? 'Mic: this device' : 'Mic: this device (muted)')
      : 'Your microphone is on your other device.'
    micEl.classList.toggle('mine', mine.mic === myDeviceId)
  } else {
    micEl.textContent = micTrack ? 'Mic: on, not yet claimed' : 'Mic: off'
    micEl.classList.remove('mine')
  }
  ;($('claimMic') as HTMLButtonElement).hidden = !micElsewhere

  renderAssist()

  // After Leave, no pictures either. The mesh still delivers them - it is
  // the room's, not the call's - but a person who has pressed Leave is
  // shown the names and the banner, not the faces, until they press Join.
  // The poll puts them back the moment they do.
  if (leftCall) for (const entry of remoteVideos.values()) if (onScreen(entry)) parkPicture(entry.el)
  // Nor of anybody meeting mode keeps off the stage. Parked, not removed,
  // so a person made a speaker is back on screen at the next poll.
  for (const [key, entry] of remoteVideos) if (onScreen(entry) && meetingGated(tileDevice(key))) parkPicture(entry.el)

  const root = $('room')
  const kept = new Set<string>()
  let slot = 0
  const agentsRow = $('agentsRow')
  agentsRow.innerHTML = ''

  // Ask about every key in the room, so anyone with a published Nostr
  // profile is shown as having one. Cheap to repeat - the book only looks
  // up a key it has not seen.
  profiles.want(views.map((v) => v.participant))

  for (const view of views) {
    // An agent with nothing on screen - a keeper, a host, one that only
    // reads and writes - is a name in a row, not an empty tile taking a
    // person's space in the grid. One that publishes media is a tile like
    // anybody else.
    const showsMedia =
      view.participant === me
        ? localMediaEl.childElementCount > 0
        : view.devices.some((device) => (deviceMediaEls.get(device)?.childElementCount ?? 0) > 0)
    if (view.agent && !showsMedia) {
      const chip = document.createElement('span')
      chip.className = 'agentChip'
      const shown = shownAs(view.participant, view.name)
      chip.append(identityRun(shown, view.participant === me, false, false, true))
      const badge = document.createElement('span')
      badge.className = 'badge agent'
      badge.textContent = 'Agent'
      badge.title = 'An agent, not a person'
      chip.append(badge)
      if (agentsMayHear) chip.append(hearsYouNote())
      if (view.owner) chip.append(ownerRun(view.owner, true))
      else if (view.ownerClaim) chip.append(ownerClaimRun(view.ownerClaim, true))
      agentsRow.append(chip)
      continue
    }
    let box = tileBoxes.get(view.participant)
    if (!box) {
      box = document.createElement('div')
      tileBoxes.set(view.participant, box)
    }
    kept.add(view.participant)
    const sharedDevices = new Set(view.tracks.filter(track => track.role === 'screen').map(track => track.device))
    if (view.participant === me && screenTrack) sharedDevices.add(myDeviceId)
    const shareButtons = new Map([...box.querySelectorAll<HTMLButtonElement>(':scope > .shareExpand')].map(button => [button.dataset.shareDevice, button]))
    // Keep media holders and live share controls in place. Replacing an
    // Expand button during presence updates can interrupt a phone tap.
    for (const child of [...box.children]) {
      // The call stage's own controls (see call-stage.ts) are its to keep.
      if (child.hasAttribute('data-call-layout')) continue
      if (child instanceof HTMLButtonElement && child.classList.contains('shareExpand') && sharedDevices.has(child.dataset.shareDevice ?? '')) continue
      if (!child.classList.contains('media') || child.childElementCount === 0) child.remove()
    }
    box.className = 'participant'
    if (view.call) box.classList.add('onCall')
    // The claim this app exists to prove: two devices, one tile. Anything
    // else in the styling is decoration.
    if (view.devices.length > 1) box.classList.add('linked')

    // Which devices this tile speaks for. `render()` rebuilds the room from
    // scratch, so a tile rebuilt in the middle of a word has to come back
    // already lit rather than waiting for the next poll to notice.
    const tileDevices = view.participant === me ? [LOCAL_SPEAKING_KEY] : view.devices
    box.dataset.devices = tileDevices.join(' ')
    // Read by the call stage: who this tile is, and what to call them.
    box.dataset.participant = view.participant
    box.dataset.self = String(view.participant === me)
    if (tileDevices.some((d) => speakingMonitor.isSpeaking(d))) box.classList.add('speaking')

    const shown = shownAs(view.participant, view.name)
    box.dataset.name = shown.name ?? 'Somebody'

    const heading = document.createElement('h3')
    // The picture comes with the identity run now, ringed by what this
    // person has put in - see `pictureOf`.
    heading.append(identityRun(shown, view.participant === me, false, false, true))
    // In its own element so a tile with no picture in it can drop the
    // device count and stay one line wide. See `#room .participant` in
    // style.css for why that matters more than it sounds like it does.
    const devices = document.createElement('span')
    devices.className = 'devices'
    devices.textContent = ` · ${view.devices.length} device${view.devices.length === 1 ? '' : 's'}`
    heading.append(devices)
    if (view.devices.length > 1) {
      const badge = document.createElement('span')
      badge.className = 'badge'
      badge.textContent = 'one person'
      heading.append(badge)
    }
    if (view.agent) {
      // Self-declared, like a name: it says what this participant claims to
      // be, and it is what the "agents can hear me" switch acts on.
      const badge = document.createElement('span')
      badge.className = 'badge agent'
      badge.textContent = 'Agent'
      badge.title = 'This participant says it is an automated agent'
      heading.append(badge)
      if (agentsMayHear) heading.append(hearsYouNote())
      if (view.owner) heading.append(ownerRun(view.owner, true))
      else if (view.ownerClaim) heading.append(ownerClaimRun(view.ownerClaim, true))
    }
    if (view.participant !== me) {
      heading.append(verifyChip(view, shown.name ?? ''))
      if (volumeLevel(view.participant) === 0) heading.append(volumeMuteBadge())
      if (selfMutedMic(view)) heading.append(selfMuteBadge())
    }
    box.prepend(heading)
    const place = (mediaEl: HTMLDivElement | undefined, label = ''): void => {
      if (!mediaEl || mediaEl.childElementCount === 0) { if (mediaEl?.parentElement === box) mediaEl.remove(); return }
      mediaEl.dataset.cameraLabel = label
      // Read by the "person beside their screen" layout in style.css: a
      // share with no camera live beside it still shows whose it is.
      mediaEl.dataset.ownerName = shown.name ?? 'Somebody'
      if (mediaEl.parentElement !== box) box.append(mediaEl)
    }

    if (view.participant === me) {
      // Our own live media, in our own tile: the same elements that were the
      // preview before joining, moved here rather than duplicated (see
      // localMediaEl). A chip only for what has no picture - the mic - and
      // for a track advertised but not currently previewed.
      place(localMediaEl, 'This device')
      // My other devices' pictures, in the same tile. A phone's camera is
      // a picture of me, and the laptop I am also on is the natural place
      // to check what it is showing; leaving it out meant a person on two
      // devices never saw their own phone's camera on their desktop and
      // concluded the desktop was broken. Their sound stays muted, see the
      // rule at the top of `render`.
      for (const [index, device] of view.devices.filter(device => device !== myDeviceId).entries()) place(deviceMediaEls.get(device), `Your other device${view.devices.length > 2 ? ` ${index + 1}` : ''}`)
      box.append(
        trackChips(view, (track) => {
          const kind = previewKindOf(track.role)
          if (track.device !== myDeviceId) {
            const mediaEl = deviceMediaEls.get(track.device)
            const tag = track.role === 'mic' || track.role === 'screen-audio' ? 'audio' : 'video'
            return mediaEl?.querySelector(tag) ? 'live' : 'waiting'
          }
          return kind !== undefined && localPreviewEls.has(kind) ? 'live' : 'own'
        }),
      )
    } else {
      // Remote media: real video/audio wherever we have it, a waiting chip
      // wherever we do not (still negotiating, or never advertised).
      for (const [index, device] of view.devices.entries()) place(deviceMediaEls.get(device), view.devices.length > 1 ? `Device ${index + 1}` : '')
      box.append(
        trackChips(view, (track) => {
          const mediaEl = deviceMediaEls.get(track.device)
          const kind = track.role === 'mic' || track.role === 'screen-audio' ? 'audio' : 'video'
          return mediaEl?.querySelector(kind) ? 'live' : 'waiting'
        }),
      )
    }

    for (const device of sharedDevices) {
      const owner = mediaSession()
      const origin = callOrigin(owner)
      const source = () => screenSource(view.participant, device, owner, origin, shown.name ?? 'Somebody')
      const available = source()
      const ready = available?.track?.readyState === 'live'
      // The button is there from the moment the roster says a screen is
      // being shared, and only becomes pressable when the picture has
      // arrived. Missing entirely until then, it looked to the person
      // waiting as if there was nothing to expand, and on a phone the
      // double-tap that also opened the viewer is not a gesture anybody
      // finds. One tap on the preview opens it too.
      let expand = shareButtons.get(device)
      if (!expand) {
        expand = document.createElement('button')
        expand.type = 'button'; expand.className = 'shareExpand'
        expand.dataset.shareDevice = device
        box.append(expand)
      }
      // This device's own share while it may be filming KithMoot: opened in
      // the viewer, inside the captured window, it was the mirror again.
      // Asked again at the click, because an area can grow to fill the
      // screen after the tile was drawn.
      const mirrored = (): boolean => device === myDeviceId && shareMayShowItself
      expand.textContent = mirrored() ? 'Preview paused while sharing' : ready ? 'Expand screen share' : 'Screen share arriving…'
      expand.disabled = !ready || mirrored()
      expand.setAttribute('aria-label', `Expand screen share from ${shown.name ?? 'Somebody'}`)
      const openViewer = (): void => { if (!mirrored()) shareViewer.open(source, expand!) }
      expand.onclick = openViewer
      if (!ready) continue
      const preview = device === myDeviceId ? localPreviewEls.get('screen') : remoteVideos.get(tileKey(device, 'screen'))?.el
        ?? [...remoteVideos.values()].find(entry => entry.track === available.track)?.el
      if (preview) {
        preview.classList.add('screenPreview')
        if (device === myDeviceId) preview.ondblclick = openViewer
        else preview.onclick = openViewer
        // Marks drawn on this share show over its preview, so the person
        // sharing sees what is being pointed at without opening anything.
        if (!shareMarkOverlays.has(preview)) shareMarkOverlays.set(preview, shareViewer.overlay(preview, () => source()?.id))
      }
    }
    sweepShareMarkOverlays()
    // Into its place in the roster's order, moved only if it is not
    // already there.
    const at = root.children[slot] ?? null
    if (at !== box) root.insertBefore(box, at)
    slot++
  }
  for (const [participant, box] of tileBoxes) {
    if (kept.has(participant)) continue
    box.remove()
    tileBoxes.delete(participant)
  }
  // The stage lays itself out by how many faces are on it, and gives a
  // shared screen the whole width. See `#room[data-tiles]` in style.css.
  let tiles = 0, sharing = false
  for (const box of tileBoxes.values()) {
    if (box.querySelector('video')) tiles++
    if (box.querySelector('video.screenPreview')) sharing = true
  }
  root.dataset.tiles = String(tiles)
  root.classList.toggle('sharing', sharing)

  agentsRow.hidden = agentsRow.childElementCount === 0
  // Faces and voices, and only when there are some.
  //
  // Not "only when a picture has arrived": a tile that is still connecting
  // says which rung of the route ladder it is on, and that is exactly the
  // moment somebody wants to know. So the strip appears as soon as anybody
  // in the room is offering anything, and a room where nobody has turned
  // anything on shows nothing at all - which is most rooms, most of the
  // time, and is why this is not on the screen permanently.
  $('whoIsHere').hidden = !views.some((view) => view.call || view.tracks.length > 0) && localMediaEl.childElementCount === 0
  // Emptying the grid above detached our own holder if it was in a tile. If
  // no tile of ours was built this time - our entry has not come back from
  // the relay yet, or lapsed - it goes back to the preview strip in this same
  // synchronous pass, so it is never out of the document long enough for
  // the browser to pause the picture in it.
  if (!localMediaEl.isConnected) $('local').append(localMediaEl)

  renderCallState(views)
}

/** Small numbers read better as words in a sentence a stranger has to take
 *  in at a glance. Above ten the digits are clearer than the word. */
const COUNT_WORDS = ['No', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten']
function inWords(n: number): string {
  return COUNT_WORDS[n] ?? String(n)
}

/**
 * What the `agent` tag means, in one sentence with the tag set into it.
 *
 * This used to be a strip pinned above the conversation, permanently, in
 * every room. It was put there because a cold reader took five names for
 * five people and nothing on the screen said otherwise - and it worked, and
 * it was also one more thing competing with the conversation for ever after
 * the reader had understood it.
 *
 * So it is said where Signal says "messages are end-to-end encrypted": as
 * the first note at the head of the thread, in the conversation the person
 * came to read. After that the purple bubbles and the tags carry it. It
 * also lives permanently in the room's details, for anybody who comes back
 * looking for it.
 *
 * Returns a fragment rather than writing to one element, because it is now
 * said in two places and neither of them may be allowed to drift.
 */
function agentsSentence(count: number): DocumentFragment | undefined {
  if (count === 0) return undefined
  const run = document.createDocumentFragment()
  run.append(count === 1 ? 'One of these names is marked ' : `${inWords(count)} of these names are marked `)
  // The tag exactly as it appears on a name and on a bubble, so the
  // sentence and the thing it is about cannot be told apart.
  const badge = document.createElement('span')
  badge.className = 'badge agent'
  badge.textContent = 'Agent'
  run.append(badge)
  run.append(
    count === 1 ? ': a computer program, not a person. ' : ': computer programs, not people. ',
    'Somebody here started ',
    count === 1 ? 'it' : 'them',
    ', and everything ',
    count === 1 ? 'it says' : 'they say',
    ' is in the open for everybody to read.',
  )
  return run
}

function renderAgentsExplain(views: ParticipantView[]): void {
  const line = $('agentsExplain')
  line.textContent = ''
  const run = agentsSentence(views.filter((v) => v.agent).length)
  line.hidden = run === undefined
  if (run) line.append(run)
}

/**
 * Who is here, in words, for the one line under the room's name.
 *
 * The strip of chips this replaces said the same thing in a great deal more
 * space. The chips are not gone: they are in the room's details, one tap
 * away behind this very line, which is what it is for.
 */
/** The block in the middle of an empty room: shown while nobody else is here
 *  and nothing has been said, never in a private chat or a room with a member
 *  list (nobody is invited by link there), and gone the moment that changes. */
function renderEmptyRoom(): void {
  const me = meParticipant || currentParticipant()
  const alone = !(session?.participants() ?? []).some(view => view.participant !== me)
  const show = Boolean(session) && currentChannel === undefined && !roomPolicy?.members?.length && !roomUsesBothy && alone
    && (session?.chat.messages().length ?? 0) === 0
  if ($('emptyRoom').hidden === show) $('emptyRoom').hidden = !show
}
$('emptyCopyLink').addEventListener('click', () => {
  const link = ($('shareUrl') as HTMLInputElement).value
  navigator.clipboard.writeText(link)
    .then(() => setStatus('Invite link copied.', 'done'))
    .catch(() => { void copyInput('shareUrl').then(() => setStatus('Invite link copied.', 'done')) })
})
$('emptyShowQr').addEventListener('click', () => openInviteDialog(true, $('emptyShowQr')))

/** The header's mute line: what the room is doing about notifications, in
 *  words, beside the who line. Drawn from the same fact as the row's glyph. */
function renderRoomMuted(): void {
  const roomId = session ? currentRoomId() : undefined
  const mute = roomId ? roomMuteOf(roomId) : undefined
  $('roomMuted').hidden = mute === undefined
  $('roomMutedText').textContent = mute === undefined ? '' : mutedUntilText(mute, nowSeconds())
}

function renderRoomWho(): void {
  renderRoomMuted()
  const line = $('roomWho')
  const views = session?.participants() ?? []
  const where = conversationLabel(currentChannel)
  renderEmptyRoom()
  publishDesktopMenu()
  // A private chat says what it is, as the spec draws it (design-calm-shell 6.2).
  const me = meParticipant || currentParticipant()
  if (currentChannel === undefined && me && dmPeer(roomPolicy, me)) {
    line.textContent = isQuietPolicy(roomPolicy) ? 'Quiet chat' : 'Private chat'
    return
  }
  if (views.length === 0) {
    line.textContent = where
    return
  }
  const agents = views.filter((v) => v.agent).length
  const here = `${views.length} here`
  line.textContent = agents === 0 ? `${where} · ${here}` : `${where} · ${views.length - agents} ${views.length - agents === 1 ? 'person' : 'people'}, ${agents} agent${agents === 1 ? '' : 's'}`
}

/**
 * The full roster, in the room's details.
 *
 * The same run of name, short key and tags that a tile and a line of chat
 * use, so a person looks the same wherever they are drawn, and the same
 * "is this really them" control, which would otherwise have been lost with
 * the chips it used to sit on.
 */
function renderSheetRoster(views: ParticipantView[], me: string): void {
  const list = $('sheetRoster')
  // Presence can arrive between pointer-down and pointer-up, or while a
  // keyboard user adjusts volume. Keep controls connected across refreshes.
  const previous = new Map(Array.from(list.children, child => {
    const row = child as HTMLElement
    return [row.dataset.participant, row] as const
  }))
  // People first, then agents.
  const ordered = [...views.filter(view => !view.agent), ...views.filter(view => view.agent)]
  for (const [index, view] of ordered.entries()) {
    let row = previous.get(view.participant)
    previous.delete(view.participant)
    if (!row) {
      // A member is a row that opens: the name and its badges show, and what
      // can be done with them (volume, message, invite, check) is one tap in.
      row = document.createElement('details')
      row.className = 'rosterRow'
      row.dataset.participant = view.participant
      const summary = document.createElement('summary')
      summary.className = 'rosterSummary'
      const identity = document.createElement('span')
      identity.className = 'rosterIdentity'
      summary.append(identity)
      row.append(summary)
    }
    const identity = row.querySelector<HTMLElement>('.rosterIdentity')!
    identity.replaceChildren()
    const shown = shownAs(view.participant, view.name)
    identity.append(identityRun(shown, view.participant === me, false, false, true))
    if (view.agent) {
      const badge = document.createElement('span')
      badge.className = 'badge agent'
      badge.textContent = 'Agent'
      badge.title = 'An agent, not a person'
      identity.append(badge)
      if (view.owner) identity.append(ownerRun(view.owner))
      else if (view.ownerClaim) identity.append(ownerClaimRun(view.ownerClaim))
    }
    if (view.devices.length > 1) {
      const badge = document.createElement('span')
      badge.className = 'badge'
      badge.textContent = 'one person'
      identity.append(badge)
    }
    const existingCheck = row.querySelector<HTMLButtonElement>('.verifyChip')
    if (view.participant !== me) {
      const check = verifyChip(view, shown.name ?? '', existingCheck ?? undefined)
      // Said as the question it answers, not as a state: "not checked" was the
      // most common label in the room and told nobody anything.
      if (check.classList.contains('unknown') && check.textContent === 'not checked') check.textContent = 'Is this really them?'
      if (check.classList.contains('verified')) {
        const badge = document.createElement('span')
        badge.className = 'badge checked'
        badge.textContent = 'Checked'
        identity.append(badge)
      }
      if (!existingCheck) row.append(check)
    } else existingCheck?.remove()
    const card = view.participant !== me ? contactFor(deviceStore, view.participant) : undefined
    if (card) {
      const badge = document.createElement('span')
      badge.className = 'badge card'
      badge.textContent = `card: ${contactLabel(card)}`
      badge.title = `You hold this person's contact card, read ${new Date(card.readAt * 1000).toLocaleDateString()}. Its name is theirs to claim, like any other; the key is what the card binds.`
      identity.append(badge)
    }
    const action = (key: string, allowed: boolean): HTMLButtonElement | undefined => {
      let button = row.querySelector<HTMLButtonElement>(`[data-roster-action="${key}"]`)
      if (!allowed) { button?.remove(); return }
      if (!button) {
        button = document.createElement('button')
        button.type = 'button'
        button.className = 'dmButton quiet'
        button.dataset.rosterAction = key
        row.insertBefore(button, row.querySelector('.volumeRow'))
      }
      return button
    }
    // A word in private, from the room you are both in. A DM is a room of
    // two; see docs/messages.md. Not offered on a room that already is one.
    // An agent takes one too, from its owner or a room admin: those are
    // the people it answers to, and the agent's runner applies the same
    // rule at its end (`--dm` in kithmoot-agent), so the button is only
    // shown where it can work.
    const mayDmAgent = view.agent === true && (view.owner?.principal === me || admins.has(me))
    const mayDm = view.participant !== me && (!view.agent || mayDmAgent) && !dmPeer(roomPolicy, me)
    const dm = action('private', mayDm)
    if (dm) {
      // WebKit also loses a pressed native button when its unchanged text
      // is replaced: keeping the element alone does not keep the gesture.
      if (dm.textContent !== 'Message privately') dm.textContent = 'Message privately'
      dm.setAttribute('aria-label', `Message ${shown.name ?? shown.short} privately`)
      dm.onclick = () => { void startDirectMessage(view.participant, shown.name, false) }
    }
    // The same room of two, with its chat in drops. See src/quiet.ts.
    const hush = action('quiet', mayDm)
    if (hush) {
      if (hush.textContent !== 'Message quietly') hush.textContent = 'Message quietly'
      hush.title = QUIET_MEANING
      hush.setAttribute('aria-label', `Message ${shown.name ?? shown.short} quietly`)
      hush.onclick = () => { void startDirectMessage(view.participant, shown.name, true) }
    }
    // Bring them into another room of yours. The invite travels sealed to
    // them in this conversation, the same way a private conversation
    // starts, and a room that asks first lets somebody you invited straight
    // in. That pair is what a private room is: a link nobody is handed,
    // and people you chose.
    const invite = action('invite', view.participant !== me && !view.agent)
    if (invite) {
      if (invite.textContent !== 'Invite to a room') invite.textContent = 'Invite to a room'
      invite.setAttribute('aria-label', `Invite ${shown.name ?? shown.short} to a room`)
      invite.onclick = () => openInviteToRoom(view.participant, shown.name)
    }
    // How loud this person is, on this device only - one slider for the
    // person, whatever it takes to merge their devices into this one tile.
    // See the "Per-person volume" section above.
    if (view.participant !== me) {
      let volumeRow = row.querySelector<HTMLElement>('.volumeRow')
      if (!volumeRow) {
        volumeRow = document.createElement('div')
        volumeRow.className = 'volumeRow'
        const label = document.createElement('span')
        label.className = 'volumeLabel'
        label.textContent = 'Volume'
        const slider = document.createElement('input')
        slider.type = 'range'
        slider.className = 'volumeSlider'
        const out = document.createElement('output')
        out.className = 'volumeValue'
        volumeRow.append(label, slider, out)
        row.append(volumeRow)
      }
      const slider = volumeRow.querySelector<HTMLInputElement>('.volumeSlider')!
      const out = volumeRow.querySelector<HTMLOutputElement>('.volumeValue')!
      slider.min = '0'
      // A level above 100% needs the gain path; where that has actually
      // failed the slider is capped rather than offering a promise the
      // element cannot keep. See RemoteVolume.gainAvailable.
      slider.max = remoteVolume.gainAvailable ? '200' : '100'
      slider.step = '5'
      slider.setAttribute('list', 'volumeNotch')
      slider.dataset.participant = view.participant
      slider.setAttribute('aria-label', `Volume for ${shown.name ?? shown.short}`)
      const describe = (percent: number) => (percent === 0 ? 'Silenced for you' : `${percent}%`)
      const startPercent = Math.round(volumeLevel(view.participant) * 100)
      slider.value = String(startPercent)
      out.textContent = describe(startPercent)
      slider.setAttribute('aria-valuetext', describe(startPercent))
      slider.oninput = () => {
        let percent = Number(slider.value)
        // A little magnetism at 100%, the untouched level, so landing back
        // on it does not need a pixel-perfect drag.
        if (percent !== 100 && Math.abs(percent - 100) <= 7) { percent = 100; slider.value = '100' }
        out.textContent = describe(percent)
        slider.setAttribute('aria-valuetext', describe(percent))
        previewVolumeLevel(view, percent / 100)
      }
      slider.onchange = () => commitVolumeLevel(view.participant)
      const existingNote = row.querySelector('.volumeUnavailable')
      if (!remoteVolume.gainAvailable && !existingNote) {
        const note = document.createElement('p')
        note.className = 'note volumeUnavailable'
        note.textContent = 'Above 100% needs Web Audio, which is not available here, so this stays capped at 100%.'
        row.append(note)
      } else if (remoteVolume.gainAvailable) existingNote?.remove()
    } else {
      row.querySelector('.volumeRow')?.remove()
      row.querySelector('.volumeUnavailable')?.remove()
    }
    if (list.children[index] !== row) list.insertBefore(row, list.children[index] ?? null)
  }
  for (const row of previous.values()) row.remove()
}

// ---------------------------------------------------------------------------
// Direct messages
//
// A DM is a room: a persistent group whose link admits two people and
// nobody else. Starting one makes that room and sends its link, sealed to
// the other person, as a message in the room you are both already in. The
// person's other devices, and the recipient's, open it from there. See
// docs/messages.md and src/dm.ts.
// ---------------------------------------------------------------------------

/** NIP-44 between this participant and another: the signer's, or the local
 *  key's. Undefined on a paired secondary, which holds no participant key,
 *  and on a signer with no NIP-44. */
function peerCrypt(): PeerCrypt | undefined {
  if (nostrSession) {
    const nip44 = nostrSession.signer.nip44
    if (!nip44) return undefined
    return { encrypt: (peer, text) => nip44.encrypt(peer, text), decrypt: (peer, text) => nip44.decrypt(peer, text) }
  }
  try {
    return localPeerCrypt(participantKey())
  } catch {
    return undefined
  }
}

/** How long starting a conversation waits for the two DM relay lists before
 *  going ahead without them. A lookup that never answers must not leave a
 *  person staring at "Starting…". */
const DM_RELAY_LOOKUP_MS = 2_500

/** Relay URLs once each, however they were spelt: `wss://relay.example` and
 *  `wss://relay.example/` are one relay, and a pool refuses a list naming it twice. */
function distinctRelays(urls: string[]): string[] {
  const out: string[] = []
  for (const url of urls) {
    try {
      const normal = normaliseRelayConfig([url])[0]!.url
      if (!out.includes(normal)) out.push(normal)
    } catch { /* Not a relay a pool would take. */ }
  }
  return out
}

/** Kind 10050 lists for these authors from these relays, as many as arrive
 *  before every relay has finished or the wait is up. */
async function lookUpDmRelayLists(authors: string[], urls: string[], kinds: number[] = [KIND_DM_RELAYS]): Promise<NostrEvent[]> {
  const pool = relayConnections.pool('profiles', distinctRelays(urls))
  const found: NostrEvent[] = []
  try {
    await new Promise<void>(resolve => {
      const timer = setTimeout(resolve, DM_RELAY_LOOKUP_MS)
      pool.subscribe([{ kinds, authors }], event => found.push(event), () => { clearTimeout(timer); resolve() })
    })
  } finally {
    pool.close()
  }
  return found
}

/** Each project member's inbox relays, looked up once a session (and again
 *  after ten minutes), so a burst of project edits asks only once. */
const projectInboxes = new Map<string, { relays: string[]; at: number }>()
const PROJECT_INBOX_TTL_MS = 10 * 60 * 1000

/**
 * Hands a project wrap for `recipient` to where they read: their NIP-17 DM
 * relays, else their NIP-65 read relays (see `inboxRelays`). Without this a
 * project reached only members who happened to read one of the owner's own
 * relays. The wrap already names the recipient to every relay it goes to,
 * so looking their lists up tells the lookup relays nothing the wrap does
 * not; relays the owner already wrote it to are skipped.
 */
async function projectInboxTargets(recipient: string): Promise<string[]> {
  let inbox = projectInboxes.get(recipient)
  if (!inbox || Date.now() - inbox.at > PROJECT_INBOX_TTL_MS) {
    const own = relayConnections.configuration('default').map(relay => relay.url)
    const lists = await lookUpDmRelayLists([recipient], [...new Set([...own, ...RELAYS, ...PROFILE_RELAYS])], [KIND_DM_RELAYS, KIND_RELAY_LIST])
    inbox = { relays: inboxRelays(lists, recipient), at: Date.now() }
    projectInboxes.set(recipient, inbox)
  }
  const own = new Set(relayConnections.configuration('default').map(relay => relay.url))
  return inbox.relays.filter(url => !own.has(url))
}

async function deliverProjectWrap(wrap: NostrEvent, recipient: string): Promise<void> {
  const targets = await projectInboxTargets(recipient)
  if (!targets.length) return
  const pool = relayConnections.pool('project-inbox', targets)
  try { await pool.publish(wrap) } finally { pool.close() }
}

/**
 * The relays a new private conversation with `peer` is started on: the two
 * people's own DM relay lists (see `src/dm-relays.ts`), or the room it is
 * started from when neither has one. The other person's list is asked for
 * only while public profile lookups are on, the same switch that decides
 * whether anybody's key is sent to public relays at all; without it the
 * conversation goes where the starter chose, topped up from this room.
 */
async function relaysForConversationWith(me: string, peer: string): Promise<string[]> {
  if (!nostrSession) return relays
  const authors = profilesEnabled ? [me, peer] : [me]
  let lists: NostrEvent[] = []
  try {
    lists = await lookUpDmRelayLists(authors, [...new Set([...relays, ...RELAYS, ...PROFILE_RELAYS])])
  } catch { /* No lists is the old behaviour, not a failure. */ }
  return relaysForPrivateConversation({
    mine: latestDmRelayList(lists, me),
    theirs: profilesEnabled ? latestDmRelayList(lists, peer) : [],
    fallback: relays,
  })
}

let startingDm = false
async function startDirectMessage(peer: string, peerName: string | undefined, quiet: boolean): Promise<void> {
  const s = session
  const me = meParticipant
  if (!s || !me || startingDm || contactIsBlocked(peer)) return
  const who = peerName ?? 'Somebody'
  // One conversation per pair, and one quiet one: a quiet room and a plain
  // one are different rooms, since the plain one's chat is on the relay in
  // the open. Started twice, or from both ends, it is the room that
  // already exists - the earliest of them, the same choice every device
  // makes (see `preferredDm`).
  const existing = preferredDm(knownRooms(roomStore())
    .filter((room) => dmPeerOf(room) === peer && isQuietRoom(room) === quiet)
    .map((room) => ({ room: room.roomId, sentAt: room.openedAt, known: room })))
  if (existing) {
    setStatus(`Opening your ${quiet ? 'quiet' : 'private'} conversation with ${who}…`, 'progress')
    switchRoom(existing.known)
    return
  }
  const crypt = peerCrypt()
  if (!crypt) {
    setStatus(nostrSession
      ? 'This signer cannot encrypt, so it cannot send a private invitation. Sign in with a signer that supports NIP-44.'
      : 'A paired device cannot start a private conversation. Use the device that holds your identity.')
    return
  }
  startingDm = true
  try {
    setStatus(`Starting a ${quiet ? 'quiet' : 'private'} conversation with ${who}…`, 'progress')
    const secret = generateRoomSecret()
    const created = createRoomInvitation(true)
    const { roomId } = deriveRoom(secret)
    // Both the invitation and the link name the conversation's own relays:
    // a device that has never been in it fetches the invitation from the
    // relays the link names, so the two must agree.
    const dmRelays = await relaysForConversationWith(me, peer)
    storeInvitationOwner(created.invitation, secret, created.inviterSk)
    const roomRelays = invitationRelaysFrom(dmRelays)
    relayConnections.setRoomRelays(roomId, { fixed: roomRelays, signed: true })
    await publishGroupInvitation(created.invitation, secret, created.inviterSk, dmRelays, { forRoom: roomId, roomRelays })
    const policy: RoomPolicy = quiet ? { ...dmPolicy(me, peer), quiet: true } : dmPolicy(me, peer)
    const link = encodeRoomLink(joinLinkBase(), { invitation: created.invitation, relays: dmRelays, iceUrls, policy })
    const invite = await sealInvite(link, { to: peer, room: roomId, crypt })
    const text = inviteText()
    if (session !== s || contactIsBlocked(peer)) throw new Error('The room or contact permission changed.')
    const prepared = s.chat.prepare(text, { invite })
    await queueSend(prepared, 'Chat', { publish: async () => {
      if (session !== s || contactIsBlocked(peer)) throw new Error('This room invitation is no longer allowed.')
      await prepared.publish()
    } })
    const room = rememberRoom(roomStore(), { roomId, link, openedAt: nowSeconds(), ...(peerName ? { name: peerName } : {}) })
    bookmarks?.save(room)
    addSystemLine(`You started a ${quiet ? 'quiet' : 'private'} conversation with ${who}.`, nowSeconds(), room)
    setStatus(`${quiet ? 'Quiet' : 'Private'} conversation with ${who} started. It is in your rooms; ${who} will find it in theirs.`, 'done')
  } catch (err) {
    setStatus(describeError(err))
  } finally {
    startingDm = false
  }
}

/** Invitations this page has already acted on, by message id. */
const handledInvites = new Set<string>()

/**
 * Open every invitation in the main chat that is for this identity: one
 * addressed to it, or one it sent from another device. The room goes on
 * the list and, when signed in, into the bookmarks, and the chat says so
 * where the invitation sits.
 */
async function handleInvites(messages: ChatMessage[]): Promise<void> {
  const generation = roomGeneration
  const me = meParticipant
  if (!me) return
  for (const m of messages) {
    if (!m.invite || handledInvites.has(m.id)) continue
    if (m.invite.to !== me && m.participant !== me) continue
    if (knownRoom(roomStore(), m.invite.room)) { handledInvites.add(m.id); continue }
    // No key to open it with yet - a signer still restoring - is not a
    // decision, so the invitation is left for the next repaint.
    const crypt = peerCrypt()
    if (!crypt) continue
    handledInvites.add(m.id)
    const link = await openInvite(m.invite, { self: me, sender: m.participant, crypt })
    if (generation !== roomGeneration) return
    if (!link) continue
    let parsed: ReturnType<typeof parseRoomLink>
    try {
      parsed = parseRoomLink(link)
    } catch {
      continue
    }
    // Two kinds of sealed invite. A private conversation is a room of two,
    // named for the other person: the sender's name on the message when it
    // was sent to us, and the addressee's roster name when we sent it from
    // another device. An invite to a room of the sender's is named as the
    // room names itself.
    const privateConversation = dmPeer(parsed.policy, me) !== undefined
    const peerName = m.participant === me
      ? session?.participants().find((v) => v.participant === m.invite!.to)?.name
      : m.name ?? shownAs(m.participant).name
    const name = privateConversation ? peerName : parsed.name
    const room = rememberRoom(roomStore(), { roomId: m.invite.room, link, openedAt: m.sentAt, ...(name ? { name } : {}) })
    bookmarks?.save(room)
    const kind = isQuietRoom(room) ? 'quiet' : 'private'
    addSystemLine(privateConversation
      ? m.participant === me
        ? `You started a ${kind} conversation from another device. It is in your rooms.`
        : `${senderLabel(m)} started a ${kind} conversation with you. It is in your rooms.`
      : m.participant === me
        ? `You invited somebody to ${knownRoomLabel(room)} from another device.`
        : `${senderLabel(m)} invited you to ${knownRoomLabel(room)}. It is in your rooms.`, m.sentAt, room)
    if (roomsListShown) renderRooms()
  }
}

/**
 * What a chip says while a device's media has not arrived: which rung of
 * the route ladder the connection to it is on, and whether the ladder has
 * run out. "connecting…" alone told a person nothing about why, and told
 * anybody trying to help even less.
 */
function connectingWord(device: string): string {
  const route = session?.routes.get(device)
  if (!route) return 'connecting…'
  if (route.exhausted) return 'could not connect, trying again'
  switch (route.tier) {
    case 'turn':
      return turnRelayConfigured ? 'connecting via relay…' : 'no relay server, still trying…'
    case 'assist':
      return `connecting via ${nameOfDevice(route.endpoint)}…`
    case 'forwarder':
      return 'connecting via forwarder…'
    default:
      return 'connecting…'
  }
}

/** Builds the chip row for a tile. `status` decides whether a track gets a
 *  chip at all - 'live' tracks already have a real <video>/<audio> element
 *  in the tile, so a chip would just repeat it. */
function trackChips(
  view: ParticipantView,
  status: (track: ParticipantView['tracks'][number]) => 'own' | 'live' | 'waiting',
): HTMLDivElement {
  const chips = document.createElement('div')
  chips.className = 'tracks'
  for (const track of view.tracks) {
    const state = status(track)
    if (state === 'live') continue
    const chip = document.createElement('span')
    chip.className = 'track'
    const isLiveMic = view.mic === track.device && track.role === 'mic'
    chip.textContent =
      state === 'waiting' ? `${track.role} · ${connectingWord(track.device)}` : `${track.role}${isLiveMic ? ' · live mic' : ''}`
    chips.append(chip)
  }
  return chips
}

/** The newest catalogue from every host, by host participant. */
const catalogues = new Map<string, Extract<ControlMessage, { op: 'catalogue' }> & { at: number }>()
const controlSeen = new Set<string>()

// ---------------------------------------------------------------------------
// Host controls
//
// A keeper announces who may act on the room, signed by the authority key
// pinned in the link, because the control channel is one every member can
// write to and "I am the admin" is exactly what somebody would forge. What
// an admin can do: ask the keeper to remove somebody (a new epoch that
// person is not given), ask it to close the room, and ask a person to mute.
// The first two are enforced by the key; the third is manners, and says so.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Room relays: the room's authority adding relays for everybody
// ---------------------------------------------------------------------------
//
// A signed `relays` op on the control channel (see `room-relays.ts`). Every
// member adds the listed relays to the ones this device already uses for
// the room; nothing is taken away. The newest version is kept on the device,
// so a record that has scrolled out of the control log's window can still
// be reposted by anybody who holds it.

interface RoomRelayRecord { relays: string[]; version: number; sig: string }
const ROOM_RELAYS_PREFIX = 'kithmoot.room-relays.v1.'
/** A record older than this in the log is posted again, so a newcomer
 *  reading the last 30 days of the control channel still finds it. */
const ROOM_RELAYS_REPOST_SECONDS = 20 * 24 * 60 * 60
/** When the newest copy of the record in this room's log was sent. */
let roomRelaysSeenAt = 0
let roomRelaysRepostTimer: ReturnType<typeof setTimeout> | undefined

function loadRoomRelayRecord(roomId: string): RoomRelayRecord | undefined {
  try {
    const raw = JSON.parse(localStorage.getItem(ROOM_RELAYS_PREFIX + roomId) ?? 'null') as RoomRelayRecord | null
    return raw && Array.isArray(raw.relays) && Number.isSafeInteger(raw.version) && typeof raw.sig === 'string' ? raw : undefined
  } catch { return undefined }
}

function storeRoomRelayRecord(roomId: string, record: RoomRelayRecord): void {
  try { localStorage.setItem(ROOM_RELAYS_PREFIX + roomId, JSON.stringify(record)) } catch { /* Still applies to this visit. */ }
}

/** This device holds the key pinned in the link, not a delegated one. */
function isRoomAuthority(): boolean {
  return !!invitationAuthoritySk && invitationDelegation.length === 0 && roomAuthority() === getPublicKey(invitationAuthoritySk)
}

/** Add the record's relays to the room's own, which every member uses
 *  ahead of this device's: nothing this device chose is overwritten, and
 *  only the sixteen-relay pool cap ever leaves one of its own out. */
function adoptRoomRelays(record: RoomRelayRecord): string[] {
  const roomId = currentRoomId()
  const missing = record.relays.filter(url => !roomRelayConfig.some(relay => relay.url === url))
  if (!roomId || roomRelayScope === 'default') return []
  if (!relayConnections.setRoomRelays(roomId, { added: record.relays })) return []
  roomRelaysApplied(relayConnections.configuration(roomRelayScope, roomRelayConfig))
  return missing
}

function ingestRoomRelays(control: Extract<ControlMessage, { op: 'relays' }>, sentAt: number): void {
  const authority = roomAuthority(), s = session
  if (!authority || !s) return
  if (!verifyRoomRelays({ roomId: s.roomId, version: control.version, relays: control.relays, sig: control.sig, authority })) return
  const known = loadRoomRelayRecord(s.roomId)
  if (known && known.version === control.version) roomRelaysSeenAt = Math.max(roomRelaysSeenAt, sentAt)
  if (known && known.version >= control.version) return
  const record = { relays: control.relays, version: control.version, sig: control.sig }
  storeRoomRelayRecord(s.roomId, record)
  roomRelaysSeenAt = sentAt
  const added = adoptRoomRelays(record)
  if (added.length && !isRoomAuthority()) setStatus(`This room now also uses ${added.join(', ')}, as its owner asked.`)
}

async function postRoomRelays(s: RoomSession, record: RoomRelayRecord): Promise<void> {
  await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'relays', ...record }))
  roomRelaysSeenAt = nowSeconds()
}

/** A while after joining, once the control log has loaded, post the record
 *  again if the log's newest copy is about to fall out of its window. */
function scheduleRoomRelaysRepost(s: RoomSession): void {
  clearTimeout(roomRelaysRepostTimer)
  roomRelaysRepostTimer = setTimeout(() => {
    if (session !== s) return
    const record = loadRoomRelayRecord(s.roomId)
    if (!record || roomRelaysSeenAt > nowSeconds() - ROOM_RELAYS_REPOST_SECONDS) return
    postRoomRelays(s, record).catch(() => { /* Tried again on the next visit. */ })
  }, 30_000 + Math.random() * 30_000)
}

// ---------------------------------------------------------------------------
// The room's name, shared: any member renames it for everybody
//
// A `name` op on the control channel, under the current epoch (see
// `src/room-name.ts` and `docs/room-name.md`). The newest rename replaces the
// name this device holds, in the title, the rooms list and every link it
// hands on. Kept with its order key, so this device can post it again after
// a rekey, or when the last copy is about to leave the relays' window.

const ROOM_NAME_PREFIX = 'kithmoot.room-name.v1.'
const roomNameFollowers = new WeakMap<RoomSession, RoomNameFollower>()
const roomLogoFollowers = new WeakMap<RoomSession, RoomLogoFollower>()
let roomNameCarryTimer: ReturnType<typeof setTimeout> | undefined

function logoForRoom(roomId: string): RoomLogoRecord | undefined {
  const s = session?.roomId === roomId ? session : dockedCall?.session.roomId === roomId ? dockedCall.session : undefined
  return s ? roomLogoFollowers.get(s)?.current() ?? roomLogoCache.get(roomId)?.record : roomLogoCache.get(roomId)?.record
}

function displayedRoomLogo(roomId: string, selected?: string) {
  return inheritedRoomLogo(roomId, logoForRoom(roomId)?.image, sharedProjects.forRoom(roomId), selected)
}

function renderAdmissionRoomBrand(): void {
  const me = meParticipant || currentParticipant()
  let policy: RoomPolicy | undefined
  try { policy = parseRoomLink(location.href).policy } catch {
    $('arrivalRoomBrand').hidden = true; clearLogo($('arrivalLogo')); $('arrivalRoomBrandName').textContent = ''; return
  }
  const permitted = !session && !$('identity').hidden && $('arrivalActions').hidden &&
    !isQuietPolicy(policy) && !(me && dmPeer(policy, me)) && !conferenceEnded(roomEndsAt, nowSeconds())
  const brand = permitted ? projectAdmissionBrand(location.href, sharedProjects.joined(), currentRoomId(), roomProjectContext) : undefined
  $('arrivalRoomBrand').hidden = !brand
  $('arrivalRoomBrandName').textContent = brand ? `${brand.name} · ${brand.projectName}` : ''
  if (brand) renderLogo($('arrivalLogo'), brand.image, brand.name)
  else clearLogo($('arrivalLogo'))
}

function renderCurrentRoomLogo(): void {
  const me = meParticipant || currentParticipant()
  const roomId = currentRoomId(), image = roomId ? displayedRoomLogo(roomId, roomProjectContext) : undefined
  const show = !!roomId && (!!session || !!image) && !isQuietPolicy(roomPolicy) && !(me && dmPeer(roomPolicy, me))
  const icon = $('roomLogo')
  icon.hidden = !show
  if (show) renderLogo(icon, image, currentRoomLabel())
  else clearLogo(icon)
}

function renderRoomLogoControls(): void {
  const s = session, me = meParticipant || currentParticipant()
  const permitted = !!s && !isQuietPolicy(roomPolicy) && !(me && dmPeer(roomPolicy, me)) && !s.channel(CONTROL_CHANNEL).readOnly
  $('roomLogoControls').hidden = !permitted
  if (permitted) renderLogo($('roomLogoPreview'), displayedRoomLogo(s!.roomId, roomProjectContext), currentRoomLabel())
  else clearLogo($('roomLogoPreview'))
}

function adoptSharedRoomLogo(s: RoomSession, record: RoomLogoRecord | undefined): void {
  const temporary = s.endsAt !== undefined || roomIsDestruct(s.roomId) ||
    (session === s ? roomDestruct : dockedCall?.session === s && dockedCall.ui.roomDestruct)
  if (record) roomLogoCache.keep(s.roomId, record, s.epoch, !temporary)
  else roomLogoCache.forget(s.roomId)
  if (session === s) { renderCurrentRoomLogo(); renderRoomLogoControls() }
  renderRooms(); renderDock()
}

function followSharedRoomLogo(s: RoomSession): void {
  if (isQuietPolicy(roomPolicy) || dmPeer(roomPolicy, s.participant)) return
  let follower = roomLogoFollowers.get(s)
  if (!follower) {
    const seed = roomLogoCache.get(s.roomId)
    follower = followRoomLogo(s, { seed: seed?.record, seedEpoch: seed?.epoch,
      onLogo: record => adoptSharedRoomLogo(s, record) })
    roomLogoFollowers.set(s, follower)
  }
  adoptSharedRoomLogo(s, follower.current())
}

function closeRoomLogo(s: RoomSession): void {
  roomLogoFollowers.get(s)?.close(); roomLogoFollowers.delete(s)
}

function loadRoomNameRecord(roomId: string): Pick<RoomNameRecord, 'name' | 'id' | 'at'> | undefined {
  try {
    const raw = JSON.parse(localStorage.getItem(ROOM_NAME_PREFIX + roomId) ?? 'null') as Partial<RoomNameRecord> | null
    const name = sanitiseDisplayName(raw?.name)
    return raw && name && typeof raw.id === 'string' && /^[0-9a-f]{32}$/.test(raw.id) && Number.isSafeInteger(raw.at) && raw.at! > 0
      ? { name, id: raw.id, at: raw.at! }
      : undefined
  } catch { return undefined }
}

function storeRoomNameRecord(roomId: string, record: Pick<RoomNameRecord, 'name' | 'id' | 'at'>): void {
  try { localStorage.setItem(ROOM_NAME_PREFIX + roomId, JSON.stringify({ name: record.name, id: record.id, at: record.at })) } catch { /* Still applies to this visit. */ }
}

/** The room's name changed, by a rename this device read or made. */
function adoptSharedRoomName(s: RoomSession, record: RoomNameRecord): void {
  storeRoomNameRecord(s.roomId, record)
  if (session === s) {
    if (roomName === record.name) return
    roomName = record.name
    // The address bar too, so a link copied from it, or a reload, carries
    // the room's name as it is now.
    if (location.hash.length > 1) history.replaceState(null, '', encodeRoomUrl(joinLinkBase(), relays, iceUrls))
    rememberCurrentRoom()
    renderRoomTitle()
    renderRooms()
    return
  }
  // A room on the dock: its saved name moves now, and its screen when it
  // comes back (`followSharedRoomName` applies the current name again).
  saveKnownRoomName(s.roomId, record.name)
}

/** Move a saved room's name in the list, when it is a room this device
 *  keeps and the name is new. */
function saveKnownRoomName(roomId: string, name: string): void {
  const known = knownRoom(roomStore(), roomId)
  if (!known || known.name === name) return
  try {
    bookmarks?.save(rememberRoom(roomStore(), { roomId, link: known.link, name, openedAt: known.openedAt }))
  } catch { /* The name still shows in the room itself. */ }
  renderRooms()
}

/** A rename the rooms list read in a room this device is not in right now.
 *  Kept only when it is newer than the name this device already holds, so
 *  a watch reading a stale epoch cannot pull a name back. */
function adoptWatchedRoomName(roomId: string, record: RoomNameRecord): void {
  if (session?.roomId === roomId) return
  const kept = loadRoomNameRecord(roomId)
  if (kept && compareRoomNames(record, kept) <= 0) return
  storeRoomNameRecord(roomId, record)
  saveKnownRoomName(roomId, record.name)
}

// The epoch each room was in when this device was last inside it, with its
// secret, and the window's left epochs with theirs (app/src/room-epoch-store.ts):
// so opening the room starts where it is now, reading its last month, and the
// rooms list reads the room - its chat, who is there, its name - there too
// rather than where it began. The list follows a rekey by itself, with this
// device's own copy (`keepWatchedRekey`); opening the room writes the epoch
// here too. Forgotten with the room (`forgetLocally`, and `clearRoomLocally`
// drops every key naming it).

/** The epoch the rooms list reads a room under. */
function loadRoomEpoch(roomId: string): (EpochRoot & { epoch: number }) | undefined {
  return loadWatchedEpoch(deviceStore, roomId)
}

/** Write down the epoch `s` is in, and what it keeps of the epochs before,
 *  unless this device already holds a later one; and when the epoch is new,
 *  have the rooms list read the room there from now on. */
function rememberRoomEpoch(s: RoomSession): void {
  const current = s.currentEpoch()
  if (current.epoch < 1) return
  const before = loadRoomEpoch(s.roomId)?.epoch ?? 0
  try {
    storeKeptRoomEpoch(deviceStore, s.roomId, { epoch: current, past: s.pastSecrets(), removed: [...s.removed], members: s.memberList() }, nowSeconds())
  } catch { return /* The list reads the room where it began; opening it still works. */ }
  if (before >= current.epoch || !roomWatches.has(s.roomId)) return
  stopWatching(s.roomId)
  const known = knownRoom(roomStore(), s.roomId)
  if (known) watchKnownRoom(known)
}

/** A rekey the rooms list followed in a room not open here. Written down
 *  only: the watch has already moved itself, so it is not restarted. */
function keepWatchedRekey(roomId: string, roomSecret: Uint8Array, moved: WatchedRekey): void {
  if (session?.roomId === roomId) return
  try {
    keepFollowedRekey(deviceStore, roomId, { roomSecret, left: moved.left.epoch, next: moved.epoch, notice: moved.notice }, nowSeconds())
  } catch { /* Followed again from the epoch held, on the next look at the list. */ }
}

/** Follow `s`'s shared name, once per session; on a session already
 *  followed, show the name it holds now. */
function followSharedRoomName(s: RoomSession): void {
  rememberRoomEpoch(s)
  followSharedRoomLogo(s)
  let follower = roomNameFollowers.get(s)
  if (!follower) {
    follower = followRoomName(s, {
      seed: loadRoomNameRecord(s.roomId),
      onName: (record) => { if (record) adoptSharedRoomName(s, record) },
      onRename: (record, message) => {
        if (session !== s) return
        addSystemLine(`${personLabel(record.by)} renamed the room to “${record.name}”.`, message.sentAt)
      },
    })
    roomNameFollowers.set(s, follower)
  }
  const current = follower.current()
  if (current) adoptSharedRoomName(s, current)
}

/** A while from now, post the room's name again if this epoch's control
 *  log lacks a recent copy. Random, so members do not all post at once;
 *  a second copy is harmless. */
function scheduleRoomNameCarry(s: RoomSession, minMs: number, spreadMs: number): void {
  clearTimeout(roomNameCarryTimer)
  roomNameCarryTimer = setTimeout(() => {
    if (session !== s) return
    roomNameFollowers.get(s)?.carryIfDue().catch(() => { /* Tried again on the next visit or rekey. */ })
    roomLogoFollowers.get(s)?.carryIfDue().catch(() => { /* Retry on the next visit or rekey. */ })
  }, minMs + Math.random() * spreadMs)
}

/** Rename the room for everybody in it. */
async function renameRoomForEveryone(name: string): Promise<void> {
  const s = session
  const follower = s ? roomNameFollowers.get(s) : undefined
  if (!s || !follower) throw new Error('Join the room before renaming it.')
  const record = await follower.rename(name)
  // Shown now rather than when a relay echoes it back.
  adoptSharedRoomName(s, { ...record, by: s.participant })
}

/** The rename form in the room's details: the current name, and hidden in a
 *  direct message, whose title is the other person. */
function renderRoomRename(): void {
  renderRoomLogoControls()
  const form = $('roomRename') as HTMLFormElement
  const me = meParticipant || currentParticipant()
  form.hidden = !session || (me ? dmPeer(roomPolicy, me) !== undefined : false)
  const input = $('roomRenameInput') as HTMLInputElement
  if (document.activeElement !== input) input.value = roomName ?? ''
}

/** The authority: every member should use these relays too. */
async function shareRoomRelays(urls: string[]): Promise<string> {
  const s = session, sk = invitationAuthoritySk
  if (!s || !sk || !isRoomAuthority()) throw new Error('Only the person who made this room can change its relays for everyone.')
  const relays = canonicalRoomRelays(urls)
  if (!await confirmRoomAction({
    title: 'Use these relays for everyone?',
    message: `Everyone in this room will also connect to ${relays.join(', ')}. Whoever runs each relay will carry this room's messages and calls setup, encrypted, and can see when people are active. Nobody loses a relay they already use.`,
    confirmLabel: 'Use for everyone', cancelLabel: 'Cancel',
  })) return ''
  const version = Math.max(nowSeconds(), (loadRoomRelayRecord(s.roomId)?.version ?? 0) + 1)
  const record = { relays, version, sig: signRoomRelays({ roomId: s.roomId, version, relays, authoritySk: sk }) }
  storeRoomRelayRecord(s.roomId, record)
  await postRoomRelays(s, record)
  // A group link admits newcomers from its invitation event alone, so the
  // relays everyone now uses must hold it too, or somebody (or an agent
  // host) that later reads only from them cannot get in.
  const invitation = roomInvitationCapability
  if (invitation?.persistent) await publishGroupInvitation(invitation, roomSecret, sk, relays, { endsAt: roomEndsAt, destruct: roomDestruct, roomRelays: signedRoomRelays() })
  return 'Everyone in this room will add these relays the next time their app hears from it.'
}

/** Who may act on this room, as the keeper last announced it. */
let admins = new Set<string>()
let adminsAt = 0
/** The room's named channels, as the keeper last announced them and this
 *  client verified against the pinned authority. */
let channels: string[] = []
let channelsAt = 0
/** Which conversation the chat box is showing. `undefined` is the main
 *  chat, which is the room itself and has no name. */
let currentChannel: string | undefined
/** Channels this client has already opened a log for, so switching back to
 *  one does not resubscribe. */
const channelLogs = new Map<string, ReturnType<NonNullable<typeof session>['channel']>>()
/** How much has been said in each one, so a tab can show that there is
 *  something behind it without being opened first. */
const channelCounts = new Map<string, number>()
let conversationRead = new Map<string, Set<string>>()
/** The keeper's own participant, from its announcement. Not somebody an
 *  admin can remove: removing the keeper is closing the room. */
let keeperParticipant: string | undefined

/** A name for one person, for a status line: "Somebody" when they have none,
 *  and a short key only when two people in view claim the same name. */
function personLabel(pubkey: string): string {
  const shown = shownAs(pubkey, session?.participants().find((v) => v.participant === pubkey)?.name)
  // A short key only when two people in view claim the same name.
  if (shown.name === undefined) return 'Somebody'
  return nameCollides(pubkey, shown.name) ? `${shown.name} (${shown.short})` : shown.name
}

/**
 * Who to credit a screen-share mark to: the same name and short key
 * `personLabel` puts on a status line. Colour is not decided here - see
 * `colourForParticipant` and `coloursForShare` in share-marks.ts - because
 * "the blue arrow" has to mean the same arrow to everybody, including
 * whoever drew it, so it cannot depend on whether this participant happens
 * to be this device's own.
 */
function markAuthor(participant: string): MarkAuthor {
  const shown = shownAs(participant, mediaSession()?.participants().find(view => view.participant === participant)?.name)
  const label = shown.name !== undefined ? `${shown.name} (${shown.short})` : shown.short
  const mine = participant === mediaMe()
  return {
    key: participant,
    label: mine ? `${label} (you)` : label,
  }
}

/** Lines the room shows in the chat that nobody sent: an epoch change, a
 *  removal. Rendered locally, never published, and never mistaken for a
 *  message because they carry no sender. */
interface SystemLine {
  at: number
  text: string
  /** A room the line is about, offered as the way to it. */
  room?: KnownRoom
}
const systemLines: SystemLine[] = []

/**
 * "Rowan came in." and "Rowan left.", as lines in the conversation.
 *
 * Who is here is on the roster and in Room details, but a person reading
 * the chat wants to know when it changed, the way a channel says so. Read
 * off the roster, with a settle window: the roster is rebuilt from relay
 * replay for the first heartbeat after joining, and everybody already in
 * the room would otherwise "come in" one by one as their entries arrive.
 * Nothing here is on the wire; two devices may see the same person's
 * comings a heartbeat apart, and that is fine.
 */
const ROSTER_SETTLE_MS = 25_000
let presenceAnnouncements: PresenceAnnouncements | undefined
let departureNoticeTimer: ReturnType<typeof setTimeout> | undefined
let rosterJoinedAt = 0
let presenceNoticeTimer: ReturnType<typeof setTimeout> | undefined

function showPresenceNotice(text: string): void {
  const notice = $('presenceNotice')
  const generation = roomGeneration
  notice.textContent = text
  notice.hidden = false
  if (presenceNoticeTimer !== undefined) clearTimeout(presenceNoticeTimer)
  presenceNoticeTimer = setTimeout(() => {
    if (generation !== roomGeneration) return
    notice.hidden = true
    notice.textContent = ''
    presenceNoticeTimer = undefined
  }, 8_000)
}

function announceComings(views: ParticipantView[], me: string): void {
  const now = Date.now()
  if (!presenceAnnouncements) {
    presenceAnnouncements = new PresenceAnnouncements()
    rosterJoinedAt = now
  }
  // A room created in this tab has no replay population to suppress: every
  // other participant is genuinely a new arrival and should be announced at
  // once. A tab joining an established room still gets the replay settle
  // window, so people already present are not introduced as newcomers.
  const settled = startedHere || now - rosterJoinedAt > ROSTER_SETTLE_MS
  const label = (participant: string, name: string | undefined, agent: boolean) =>
    `${shownAs(participant, name).name ?? 'Somebody'}${agent ? ' (agent)' : ''}`
  for (const { person, arrived } of presenceAnnouncements.update(views.filter(v => v.participant !== me), now, settled)) {
    const text = `${label(person.participant, person.name, person.agent === true)} ${arrived ? 'came in.' : 'left.'}`
    addSystemLine(text)
    if (arrived) showPresenceNotice(text)
  }
  if (departureNoticeTimer !== undefined) clearTimeout(departureNoticeTimer)
  departureNoticeTimer = undefined
  const next = presenceAnnouncements.nextCheck
  if (next !== undefined) {
    const generation = roomGeneration
    departureNoticeTimer = setTimeout(() => {
      departureNoticeTimer = undefined
      if (session && generation === roomGeneration) announceComings(session.participants(), meParticipant)
    }, Math.max(1, next - now))
  }
}

function addSystemLine(text: string, at = nowSeconds(), room?: KnownRoom): void {
  systemLines.push(room ? { at, text, room } : { at, text })
  systemLines.sort((a, b) => a.at - b.at)
  // Keep local status lines until the chat exists and can render them.
  // Only the conversation on screen is repainted - the line belongs to the
  // main chat and waits there for somebody standing on another tab.
  try {
    repaintActiveChat()
  } catch {
    // Not joined yet.
  }
}

function renderRoomLockState(): void {
  const epoch = session?.epoch ?? 0
  const state = $('roomLockState')
  state.hidden = epoch === 0
  state.textContent = epoch > 0
    ? `The room lock has changed ${epoch === 1 ? 'once' : `${epoch} times`}. Removed members cannot read new messages.`
    : ''
  const quiet = $('quietState')
  quiet.hidden = !quietTransport
  quiet.textContent = quietTransport
    ? `${QUIET_MEANING} Relays hand back ${Math.round(QUIET_HISTORY_SECONDS / 86400)} days of it; older messages stay on the devices that read them. Being here still shows while you are here, and calls are not quiet. Dropped-file details travel inside chat without a bare file announcement.${quietTransport.canSend ? '' : ` ${QUIET_READ_ONLY}`}`
    : ''
}

/** What the room says while it has moved to a key this device does not hold
 *  yet. The session keeps asking the authority and every current member. */
const EPOCH_WAITING_NOTICE = 'This room has moved to a new key. Waiting for a member to bring this device up to date.'
/** The room answered, and has not let this person in yet: it removed
 *  somebody, so a newcomer waits for a member to say yes (#207). */
const EPOCH_LET_IN_NOTICE = 'Waiting for somebody in this room to let you in.'
/** How long a join that nobody could bring up to date waits before trying
 *  again. Each attempt already waited for an answer. */
const EPOCH_JOIN_RETRY_MS = 5_000

/** Show, or clear, the notice that this device is behind the room's key.
 *  Until it clears, what it sends reaches nobody who moved on, so the room
 *  must not look current. */
function renderEpochWaiting(waiting: boolean, why: EpochWaitReason = 'unanswered'): void {
  const notice = $('epochNotice')
  notice.textContent = waiting ? (why === 'unknown' ? EPOCH_LET_IN_NOTICE : EPOCH_WAITING_NOTICE) : ''
  notice.hidden = !waiting
}

function onEpochChange(notice: RekeyNotice): void {
  renderRoomLockState()
  renderHost()
  // The name rides into the new epoch, carried by whichever member gets
  // there first; and a rename read under the epoch left may no longer count.
  const s = session
  if (s) {
    rememberRoomEpoch(s)
    roomNameFollowers.get(s)?.refresh()
    roomLogoFollowers.get(s)?.refresh()
    if (!notice.closed) scheduleRoomNameCarry(s, 3_000, 12_000)
  }
  // Joining replays old rekeys; a state grant includes everyone ever
  // removed. Neither is a new event to announce in this visit's chat. Nor
  // is a scheduled turn of the key: nobody was removed, and a line every
  // week would say only that a week had passed.
  if ($('roomArea').hidden || notice.catchUp || notice.scheduled) return
  const by = notice.by ? ` by ${personLabel(notice.by)}` : ''
  for (const p of notice.removed) addSystemLine(`${personLabel(p)} was removed${by}.`, notice.at)
  addSystemLine(
    `The room moved to epoch ${notice.epoch}.${notice.removed.length ? ' Nothing from here on reaches who was removed; what they already read stays theirs.' : ''}`,
    notice.at,
  )
}

/** How many of a session's epoch gaps and conflicts this page has said. */
const epochTroubleShown = new WeakMap<RoomSession, { gaps: number; conflicts: number }>()

/**
 * Say, once each, the stretches of a room this device could not read and
 * any two rekeys that disagree. Called as they happen and again once the
 * room is on screen, since joining makes its jumps before there is a
 * conversation to say them in.
 */
function reportEpochTrouble(s: RoomSession): void {
  if ($('roomArea').hidden || session !== s) return
  const shown = epochTroubleShown.get(s) ?? { gaps: 0, conflicts: 0 }
  const gaps = s.epochGaps()
  const conflicts = s.epochConflicts()
  for (const gap of gaps.slice(shown.gaps)) {
    // From epoch 0 it is every newcomer to a room that has been rekeyed,
    // who was never owed what was said before they came.
    if (gap.from === 0) continue
    addSystemLine('This device was away while the room lock changed, so messages sent in that time cannot be read here.', gap.at)
  }
  for (const conflict of conflicts.slice(shown.conflicts)) {
    addSystemLine(`The room lock was changed from two places at once (epoch ${conflict.epoch}). Some people here may not see each other's messages until whoever holds the room changes it again from one device.`)
  }
  epochTroubleShown.set(s, { gaps: gaps.length, conflicts: conflicts.length })
}

const NOTICE_STORAGE_KEY = 'kithmoot.notice'

/**
 * Leave because the room said so, and say why on the page that comes back.
 * Media and the session are stopped first. The reason rides across the
 * reload into this room's door in session storage, so the person can read
 * it after the conversation has closed.
 */
/**
 * End a conference room on this screen when its end comes: written down as
 * ended, so the list says so, and left with the date. Re-armed in steps,
 * since a browser timer cannot wait as long as thirty days in one go.
 */
function scheduleConferenceEnd(s: RoomSession): void {
  const dock = dockedCall?.session === s ? dockedCall : undefined
  clearTimeout(dock ? dock.conferenceEndTimer : conferenceEndTimer)
  if (dock) dock.conferenceEndTimer = undefined
  else conferenceEndTimer = undefined
  const endsAt = s.endsAt
  if (endsAt === undefined) return
  const wait = Math.min(Math.max(0, (endsAt - nowSeconds()) * 1000), 2 ** 31 - 1)
  const timer = setTimeout(() => {
    // Navigation may have transferred this timer since it was armed.
    const owner = dockedCall?.session === s ? dockedCall : undefined
    if (!owner && session !== s) return
    if (owner) owner.conferenceEndTimer = undefined
    else conferenceEndTimer = undefined
    if (!conferenceEnded(endsAt, nowSeconds())) { scheduleConferenceEnd(s); return }
    markEnded(deviceStore, s.roomId, endsAt)
    if (bookmarks) markEnded(bookmarks.rooms, s.roomId, endsAt)
    if ((owner ? owner.ui.roomDestruct : roomDestruct) || roomIsDestruct(s.roomId)) {
      markRoomDestruct(s.roomId)
      destructSecrets.set(s.roomId, owner ? owner.ui.roomSecret : roomSecret)
      discardRoomRecording(s.roomId)
      if (owner) void endDockedCall('user', SELF_DESTRUCTED_MESSAGE)
      else stopInvitationHost()
      void runDueDestructs()
      return
    }
    if (owner) void endDockedCall('user', conferenceEndedMessage(endsAt))
    else { stopInvitationHost(); leaveWithNotice(conferenceEndedMessage(endsAt)) }
  }, wait)
  if (dock) dock.conferenceEndTimer = timer
  else conferenceEndTimer = timer
}

function leaveWithNotice(message: string): void {
  try {
    sessionStorage.setItem(NOTICE_STORAGE_KEY, message)
  } catch {
    // Storage may be unavailable. The room is still left.
  }
  leaveRoom()
}

/** An admin asked this device to stop sending. Honoured, and said so. */
function muteRequested(by: string): void {
  const what = describeStopped(stopSending())
  setStatus(`${personLabel(by)} asked you to mute. ${what}`)
  addSystemLine(`${personLabel(by)} asked you to mute. ${what}`)
}

function describeStopped(stopped: string[]): string {
  return stopped.length ? `Your ${stopped.join(', ')} ${stopped.length > 1 ? 'were' : 'was'} turned off.` : 'You were sending nothing.'
}

/** Everything this device sends to the call, off: microphone, camera and
 *  screen. Says which were on. Shared by an admin's mute and meeting mode. */
function stopSending(): string[] {
  const stopped: string[] = []
  if (micTrack) {
    micTrack.removeEventListener('ended', onMicEnded)
    micTrack.stop()
    mic?.stop()
    mic = undefined
    micTrack = undefined
    stopped.push('microphone')
  }
  if (camera) {
    camera.stop()
    camera = undefined
    cameraTrack = undefined
    localPreviewEls.get('camera')?.remove()
    localPreviewEls.delete('camera')
    stopped.push('camera')
  }
  if (screenTrack) {
    desktopShareArea.stop()
    shareMarksOverlay.close()
    screenTrack.stop()
    screenTrack = undefined
    shareMayShowItself = false
    desktopRedaction.setHidden(false)
    screenAudioTrack?.stop()
    screenAudioTrack = undefined
    localPreviewEls.get('screen')?.remove()
    localPreviewEls.delete('screen')
    stopped.push('screen share')
  }
  publishActiveTracks()
  updateUi()
  return stopped
}

function sendHostControl(message: ControlMessage, said: string): void {
  session
    ?.channel(CONTROL_CHANNEL)
    .send(encodeControl(message))
    .then(() => setStatus(said))
    .catch((err) => setStatus(describeError(err)))
}

// ---------------------------------------------------------------------------
// Meeting mode and recording: the room's authority moderating a call
//
// The policy and the recording notice are signed by the key pinned in the
// link (src/meeting.ts), so only the device holding it - the person who made
// the room - can change either, and any member may repost one. Both are kept
// per room id rather than per visit, so a call docked while another room is
// on screen is still held to the last policy its own room announced.
//
// The policy binds both ends. This device locks its own microphone, camera
// and screen share when it is not a speaker; and, the half that does not
// depend on anybody else's app being honest, it plays and shows nothing from
// a device whose owner is not on the stage. See `meetingGated`.
// ---------------------------------------------------------------------------

interface SignedMeeting extends MeetingPolicy { sig: string }
interface SignedRecording extends RecordingNotice { sig: string; live?: LiveRecordingState }
interface HeardRecording extends SignedRecording { since: number; heardAt: number }

const meetings = new Map<string, SignedMeeting>()
const recordings = new Map<string, HeardRecording>()
const recordingCaptures = new Map<string, RecordingCaptureNotice & { sig: string }>()
const memberRecordings = new Map<string, Map<string, { state: LiveRecordingState; since: number; heardAt: number }>>()
/** Raised hands in the room on screen: participant -> unix seconds raised. */
const handsUp = new Map<string, number>()
/** The newest hand message per participant, up or down, so an old "up"
 *  read after a newer "down" changes nothing. */
const handsAt = new Map<string, number>()
let meetingRepostTimer: ReturnType<typeof setTimeout> | undefined
/** How often the authority posts a meeting policy that is on again, so a
 *  member who arrives hours in still reads it from the control log. */
const MEETING_REPOST_MS = 30 * 60 * 1000

/** Said wherever a control is locked, the same way every time. */
const MEETING_LOCKED = 'This call is in meeting mode: only speakers can use a microphone, camera or screen share. Raise your hand to ask to speak.'

interface ActiveRecording {
  recorder: CallRecorder
  video?: RecordingVideo
  session: RoomSession
  callId: string
  epoch: number
  authoritySk: Uint8Array
  notice: SignedRecording
  capture: RecordingCaptureNotice & { sig: string }
  timer: ReturnType<typeof setInterval>
  elapsedTimer: ReturnType<typeof setInterval>
  discarded?: boolean
}
/** The recording this device is making, if it is making one. */
let activeRecording: ActiveRecording | undefined
/** A finished recording, held on this device until its owner shares,
 *  saves or discards it. Never uploaded without that choice. */
let pendingRecording: { file: File; roomId: string; url: string; addedTo?: ConversationDraft; attachment?: ChatAttachment } | undefined
let sharingRecording = false
const recordingStops = new Set<ActiveRecording>()

/** Destruction also drops an unsaved clip, including one still finalising. */
function discardRoomRecording(roomId: string): void {
  memberRecordings.delete(roomId)
  recordingCaptures.delete(roomId)
  if (activeRecording?.session.roomId === roomId) activeRecording.discarded = true
  for (const recording of recordingStops) if (recording.session.roomId === roomId) recording.discarded = true
  if (pendingRecording?.roomId === roomId) {
    URL.revokeObjectURL(pendingRecording.url)
    pendingRecording = undefined
    renderRecording()
  }
}

function roomMeeting(s = session): SignedMeeting | undefined {
  return s ? meetings.get(s.roomId) : undefined
}

function callMeeting(): SignedMeeting | undefined {
  return roomMeeting(mediaSession())
}

/**
 * Whether the call's meeting policy keeps `device`'s sound and pictures off
 * this device. A device nobody in the roster owns is kept off too while the
 * policy is on: a stage that lets in whoever it cannot place is no stage.
 */
function meetingGated(device: string): boolean {
  const policy = callMeeting()
  if (!policy?.on) return false
  const owner = mediaSession()?.participants().find(view => view.devices.includes(device))?.participant
  return owner === undefined || !meetingAllows(policy, owner, 'audio')
}

/** Whether this device may send to the call under its meeting policy. */
function meetingLetsMeSend(): boolean {
  return meetingAllows(callMeeting(), mediaMe(), 'audio')
}

/** Refuses, with the reason, turning something on that the policy locks. */
function meetingRefuses(): boolean {
  if (meetingLetsMeSend()) return false
  setStatus(MEETING_LOCKED)
  return true
}

function ingestMeeting(control: Extract<ControlMessage, { op: 'meeting' }>, sentAt: number): void {
  const authority = roomAuthority(), s = session
  if (!authority || !s) return
  const policy: MeetingPolicy = { on: control.on, speakers: control.speakers, version: control.version }
  if (!verifyMeetingPolicy({ roomId: s.roomId, policy, sig: control.sig, authority })) return
  adoptMeeting(s, { ...policy, sig: control.sig }, sentAt >= nowSeconds() - 60)
}

function adoptMeeting(s: RoomSession, next: SignedMeeting, fresh: boolean): void {
  const before = meetings.get(s.roomId)
  if (before && before.version >= next.version) return
  meetings.set(s.roomId, next)
  if (s === mediaSession()) {
    const me = mediaMe()
    const could = meetingAllows(before, me, 'audio')
    const can = meetingAllows(next, me, 'audio')
    if (!can && (micTrack || cameraTrack || screenTrack)) {
      setStatus(`Meeting mode: only speakers can talk or show video. ${describeStopped(stopSending())}`)
    } else if (can && !could && fresh) {
      setStatus('You are a speaker now. Your microphone and camera are yours to turn on.')
    }
    if (can && s === session && handsUp.has(me)) raiseHand(false)
  }
  if (fresh && !!before?.on !== next.on) {
    addSystemLine(next.on ? 'This call is now in meeting mode: only speakers can talk or show video.' : 'Meeting mode is off: everybody can talk again.')
  }
  if (s === session && isRoomAuthority()) scheduleMeetingRepost(s)
  repaint()
  renderMeeting()
  updateUi()
}

function ingestHand(participant: string, up: boolean, at: number): void {
  if ((handsAt.get(participant) ?? 0) > at) return
  handsAt.set(participant, at)
  if (up && at > nowSeconds() - HAND_TTL_SECONDS) {
    const news = !handsUp.has(participant) && at >= nowSeconds() - 30
    handsUp.set(participant, at)
    if (news && isRoomAuthority() && participant !== meParticipant) setStatus(`${personLabel(participant)} raised their hand.`)
  } else {
    handsUp.delete(participant)
  }
  renderMeeting()
}

function raiseHand(up: boolean): void {
  const s = session
  if (!s) return
  ingestHand(meParticipant, up, nowSeconds())
  s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'hand', up })).catch((err) => setStatus(describeError(err)))
}

function stagePolicy(): MeetingPolicy {
  return roomMeeting() ?? { on: false, speakers: [], version: 0 }
}

async function publishMeeting(next: MeetingPolicy): Promise<void> {
  const s = session, authoritySk = invitationAuthoritySk
  if (!s || !authoritySk || !isRoomAuthority()) throw new Error('Only the person who made this room can run it as a meeting.')
  const signed: SignedMeeting = { ...next, sig: signMeetingPolicy({ roomId: s.roomId, policy: next, authoritySk }) }
  await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'meeting', ...signed }))
  adoptMeeting(s, signed, true)
}

async function setMeetingMode(on: boolean): Promise<void> {
  let next = withMeetingMode(stagePolicy(), on, Date.now())
  // Whoever runs the meeting is on its stage.
  if (on && !next.speakers.includes(meParticipant)) next = withSpeaker(next, meParticipant, true, next.version)
  await publishMeeting(next)
}

async function setSpeaker(participant: string, speaking: boolean): Promise<void> {
  await publishMeeting(withSpeaker(stagePolicy(), participant, speaking, Date.now()))
}

function scheduleMeetingRepost(s: RoomSession): void {
  clearTimeout(meetingRepostTimer)
  meetingRepostTimer = setTimeout(() => {
    const policy = roomMeeting(s)
    if (session !== s || !policy?.on) return
    s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'meeting', ...policy })).catch(() => { /* Tried again next time. */ })
    scheduleMeetingRepost(s)
  }, MEETING_REPOST_MS)
}

function ingestRecording(control: Extract<ControlMessage, { op: 'recording' }>, sentAt: number): void {
  const authority = roomAuthority(), s = session
  if (!authority || !s) return
  const notice: RecordingNotice = { on: control.on, id: control.id, version: control.version }
  if (!verifyRecordingNotice({ roomId: s.roomId, notice, sig: control.sig, authority })) return
  adoptRecording(s, { ...notice, sig: control.sig }, sentAt)
}

function ingestRecordingCapture(control: Extract<ControlMessage, { op: 'recording-capture' }>): void {
  const s = session, authority = roomAuthority()
  if (!s || !authority || !verifyRecordingCaptureNotice({ roomId: s.roomId, notice: control, sig: control.sig, authority })) return
  const before = recordingCaptures.get(s.roomId)
  if (before && before.version >= control.version) return
  recordingCaptures.set(s.roomId, control)
  renderRecording()
}

/** Independent device notices: stopping one recording cannot clear another. */
function ingestLiveRecordings(s: RoomSession): void {
  const held = memberRecordings.get(s.roomId) ?? new Map<string, { state: LiveRecordingState; since: number; heardAt: number }>()
  let changed = false
  for (const { state, sentAt } of s.liveRecordings()) {
    if (!state.call || !state.device) {
      // Profile 3's root-signed presence warnings are also understood.
      if (state.capture) recordingCaptures.set(s.roomId, state.capture)
      adoptRecording(s, { ...state.recording }, sentAt)
      continue
    }
    const key = `${state.call}:${state.device}`, before = held.get(key)
    if (before && before.state.recording.version > state.recording.version) continue
    if (before && before.state.recording.version === state.recording.version && before.heardAt >= sentAt) continue
    held.set(key, { state, since: before?.state.recording.id === state.recording.id ? before.since : sentAt, heardAt: sentAt })
    changed = true
    const active = activeRecording
    if (active?.session === s && active.notice.live?.device === state.device && active.notice.live.call === state.call &&
        state.recording.version > active.notice.version && (!state.recording.on || state.recording.id !== active.notice.id)) void stopRecording()
  }
  if (held.size) memberRecordings.set(s.roomId, held)
  const active = activeRecording
  if (active?.session === s && active.notice.live && !participantRecordingReady(s)) void stopRecording('a call device cannot show the recording warning')
  if (changed) { renderRecording(); renderMeeting(); renderDock() }
}

function memberRecordingViews(s = session): Array<{ state: LiveRecordingState; view: ReturnType<typeof recordingView> }> {
  if (!s) return []
  // Two devices can start before either has received the other's presence.
  // Every active call in this room needs its warning, including late joiners.
  const calls = new Set(s.participants().flatMap(person => person.call ? [person.call.id] : []))
  if (s.call) calls.add(s.call.id)
  return [...(memberRecordings.get(s.roomId)?.values() ?? [])]
    .filter(heard => heard.state.call !== undefined && calls.has(heard.state.call))
    .map(heard => ({ state: heard.state, view: recordingView(heard.state.recording, heard.since, heard.heardAt, nowSeconds()) }))
    .filter(heard => heard.view.state !== 'off')
}

function currentRecordingCapture(s = session): RecordingCaptureNotice | undefined {
  if (!s) return undefined
  const live = memberRecordingViews(s).find(heard => heard.state.device === myDeviceId) ?? memberRecordingViews(s)[0]
  if (live?.state.capture) return live.state.capture
  const notice = recordings.get(s.roomId), capture = recordingCaptures.get(s.roomId)
  return notice?.on && capture?.id === notice.id && capture.version === notice.version ? capture : undefined
}

/** Who is recording, as their tile says it: the name, with the short key
 *  only when somebody else in view claims the same name, and "Somebody"
 *  when there is no name (design-calm-shell C7). */
function recorderLabel(s: RoomSession | undefined, recorder: string): string {
  const person = s?.participants().find(view => view.participant === recorder)
  const shown = shownAs(recorder, person?.name)
  if (shown.name === undefined) return 'Somebody'
  return nameCollides(recorder, shown.name) ? `${shown.name} (${shown.short})` : shown.name
}

function recordingCaptureDescription(s = session): string {
  const live = memberRecordingViews(s)
  if (live.length) return live.map(({ state }) => {
    const capture = state.capture
    if (!capture) return 'Call media may be included.'
    const who = recorderLabel(s, capture.recorder)
    const what = { audio: 'call audio', gallery: 'gallery video and call audio', speaker: 'speaker video and call audio', 'screen-camera': 'a screen share with camera and call audio' }[capture.capture]
    return `${who} is capturing ${what}.`
  }).join(' ')
  const capture = currentRecordingCapture(s)
  if (!capture) return 'Audio and video you share may be included.'
  const who = recorderLabel(s, capture.recorder)
  const what = { audio: 'call audio', gallery: 'gallery video and call audio', speaker: 'speaker video and call audio', 'screen-camera': 'a screen share with camera and call audio' }[capture.capture]
  return `${who} is capturing ${what}.`
}

function adoptRecording(s: RoomSession, notice: SignedRecording, sentAt: number): void {
  const before = recordings.get(s.roomId)
  if (before && before.version > notice.version) return
  if (before && before.version === notice.version) {
    before.heardAt = Math.max(before.heardAt, sentAt)
    renderRecording()
    return
  }
  const since = notice.on && before?.on && before.id === notice.id ? before.since : sentAt
  recordings.set(s.roomId, { ...notice, since, heardAt: sentAt })
  if (s === session && sentAt >= nowSeconds() - 60 && !!before?.on !== notice.on) {
    addSystemLine(notice.on ? 'This call is being recorded. Everybody on the call is told, and sees a notice until it stops.' : 'The recording has stopped.')
  }
  // The notice says this recording is over - stopped on another of the
  // owner's devices, say. An honest recorder does not outlast its notice.
  const active = activeRecording
  if (active && !active.notice.live && active.session === s && notice.version > active.notice.version && (!notice.on || notice.id !== active.notice.id)) {
    void stopRecording()
  }
  renderRecording()
}

/** What the room on screen should be told about recording, right now. */
function currentRecordingView(s = session): ReturnType<typeof recordingView> {
  const heard = s ? recordings.get(s.roomId) : undefined
  const legacy = recordingView(heard, heard?.since ?? 0, heard?.heardAt ?? 0, nowSeconds())
  const views = [legacy, ...memberRecordingViews(s).map(heard => heard.view)]
  return views.find(view => view.state === 'on') ?? views.find(view => view.state === 'unconfirmed') ?? { state: 'off' }
}

/**
 * Before this device joins a call that is being recorded, say so and ask.
 * Joining is the consent; declining keeps the person in the room, off the
 * call. The device doing the recording is not asked about its own.
 */
async function consentToRecordedCall(): Promise<boolean> {
  if (mediaSession()?.call) return true
  if (currentRecordingView().state === 'off' || activeRecording) return true
  return confirmRoomAction({
    title: 'This call is being recorded',
    message: `${recordingCaptureDescription()} If you join, the media you share may be recorded. You can stay in the room and read the chat without joining the call.`,
    confirmLabel: 'Join and be recorded',
    cancelLabel: 'Not now',
  })
}

/** Endpoint identities, rather than names, bind every exported picture. */
function recordingVideoPeople(s: RoomSession): RecordingPerson[] {
  const callId = s.call?.id
  const speaking = speakingMonitor.speaking()
  const people: RecordingPerson[] = []
  for (const view of s.participants()) {
    if (!callId || !view.call || view.call.id !== callId) continue
    for (const device of view.call.devices) {
      if (!view.devices.includes(device)) continue
      const local = view.participant === mediaMe() && device === myDeviceId
      const supported = local || (activeRecording?.notice.live ? view.recordingProfiles?.[device] === 4 : !!view.recordingProfiles?.[device])
      const permitted = !meetingGated(device)
      const name = shownAs(view.participant, view.name).name ?? shortKey(view.participant)
      const label = `${shortKey(view.participant)} · ${device.slice(0, 6)} · ${name}`
      const advert = view.tracks.some(track => track.device === device && track.role === 'camera')
      let camera = local ? cameraTrack : advert ? remoteVideos.get(tileKey(device, 'camera'))?.track : undefined
      if (!camera && !local && advert) camera = [...remoteVideos].find(([key, entry]) => tileDevice(key) === device && (fixedRemoteRoles.get(entry.track) ?? tileRole(key)) === 'camera')?.[1].track
      people.push({
        id: `${view.participant}:${device}`, label,
        camera: supported && permitted && camera?.readyState === 'live' ? camera : undefined,
        fallback: !supported ? 'Update this client to include video' : !permitted ? 'Media access restricted' : 'Camera off or unavailable',
        speaking: permitted && speaking.has(local ? LOCAL_SPEAKING_KEY : device),
        muted: !permitted || (local ? !micTrack?.enabled : !view.tracks.some(track => track.device === device && track.role === 'mic' && !track.muted)),
      })
    }
  }
  // Stable identity order through name changes and roster republishing.
  return people.sort((a, b) => a.id.localeCompare(b.id))
}

interface RecordingShareChoice { participant: string; device: string; label: string }

function recordingShareChoices(s: RoomSession): RecordingShareChoice[] {
  const choices: RecordingShareChoice[] = []
  for (const view of s.participants()) {
    if (!s.call || !view.call || view.call.id !== s.call.id) continue
    for (const device of view.call.devices) {
      const local = view.participant === mediaMe() && device === myDeviceId
      if (!local && !view.recordingProfiles?.[device] || meetingGated(device)) continue
      const source = screenSource(view.participant, device, s)
      if (!source || (source.status !== 'live' && source.status !== 'reconnecting')) continue
      choices.push({ participant: view.participant, device, label: `${source.owner?.name ?? shortKey(view.participant)} · ${shortKey(view.participant)} · ${device.slice(0, 6)}` })
    }
  }
  return choices
}

function recordingVideoSnapshot(s: RoomSession, callId: string, origin: ReturnType<typeof callOrigin>, selected?: RecordingShareChoice): RecordingVideoSnapshot | undefined {
  if (s !== mediaSession() || s.closed || s.call?.id !== callId) return undefined
  const snapshot: RecordingVideoSnapshot = {
    origin: `${origin?.roomName ?? 'Call'}${origin?.projectName ? ` · ${origin.projectName}` : ''} · ${s.roomId.slice(0, 8)} · ${callId.slice(0, 8)}`,
    people: recordingVideoPeople(s),
  }
  if (selected) {
    const person = s.participants().find(view => view.participant === selected.participant && view.call?.id === callId && view.call.devices.includes(selected.device))
    const local = selected.participant === mediaMe() && selected.device === myDeviceId
    const permitted = !!person && (local || (activeRecording?.notice.live ? person.recordingProfiles?.[selected.device] === 4 : !!person.recordingProfiles?.[selected.device])) && !meetingGated(selected.device)
    const source = permitted ? screenSource(selected.participant, selected.device, s, origin) : undefined
    snapshot.share = {
      label: source?.owner ? `${shortKey(selected.participant)} · ${selected.device.slice(0, 6)} · ${source.owner.name}` : `${shortKey(selected.participant)} · ${selected.device.slice(0, 6)} · ${selected.label}`,
      track: source?.status === 'live' ? source.track : undefined,
      camera: source?.status === 'live' ? source.camera : undefined,
      fallback: !person ? 'Share owner left the call' : !permitted ? 'Video access unavailable' : source?.status === 'ended' ? 'Selected screen share ended' : 'Selected screen share reconnecting',
    }
  }
  return snapshot
}

let recordingStartPending = false
async function startRecording(): Promise<void> {
  if (recordingStartPending) return
  recordingStartPending = true
  try { await beginRecording() }
  finally { recordingStartPending = false }
}

async function beginRecording(): Promise<void> {
  const s = mediaSession(), useLive = participantRecordingReady(s)
  const authoritySk = useLive && s ? recordingDeviceKeys.get(s) : legacyRecordingReady(s) ? callRecordingAuthority() : undefined
  if (!s || !authoritySk) throw new Error(recordingPermissionHint(s))
  if (activeRecording) return
  if (recordingStops.size) throw new Error('The previous recording is finishing. Try again when it is ready.')
  const replacing = pendingRecording
  if (!s.call) throw new Error('Join the call to record it.')
  const callId = s.call.id, epoch = s.epoch, origin = callOrigin(s)
  const options = document.createElement('fieldset')
  options.className = 'recordingChoices'
  const legend = document.createElement('legend')
  legend.textContent = 'What to record'
  options.append(legend)
  let shares = recordingShareChoices(s)
  const availableAudio = !!recordingMimeType()
  const availableVideo = !!recordingMimeType(true) && typeof HTMLCanvasElement.prototype.captureStream === 'function'
  if (!availableAudio && !availableVideo) throw new Error('This browser cannot record call audio or video.')
  let layout: 'audio' | VideoRecordingLayout = availableAudio ? 'audio' : 'gallery'
  for (const [value, label] of [['audio', 'Audio only'], ['gallery', 'Gallery and audio'], ['speaker', 'Speaker and audio'], ['screen-camera', 'Screen share with camera and audio']] as const) {
    const row = document.createElement('label')
    const input = document.createElement('input')
    input.type = 'radio'; input.name = 'recording-layout'; input.value = value; input.checked = value === layout
    input.disabled = value === 'audio' ? !availableAudio : !availableVideo || (value === 'screen-camera' && !shares.length)
    input.addEventListener('change', () => { layout = value; sharePicker.hidden = value !== 'screen-camera' })
    row.append(input, document.createTextNode(label + (input.disabled ? value === 'screen-camera' && availableVideo ? ' — no eligible screen share' : ' — unavailable in this browser' : '')))
    options.append(row)
  }
  const sharePicker = document.createElement('label')
  sharePicker.hidden = true
  sharePicker.textContent = 'Whose screen '
  const shareSelect = document.createElement('select')
  shareSelect.id = 'recordingShareSource'
  const refreshShares = () => {
    const before = shareSelect.value, beforeLabel = shareSelect.selectedOptions[0]?.textContent?.replace(/ — unavailable$/, '')
    shares = recordingShareChoices(s)
    const next = shares.map(share => ({ value: `${share.participant}:${share.device}`, label: share.label }))
    // A disappearing selected owner must not silently select another share.
    if (before && !next.some(share => share.value === before)) next.unshift({ value: before, label: `${beforeLabel ?? 'Selected share'} — unavailable` })
    if (JSON.stringify([...shareSelect.options].map(option => ({ value: option.value, label: option.textContent }))) !== JSON.stringify(next)) {
      shareSelect.replaceChildren(...next.map(share => {
        const option = document.createElement('option')
        option.value = share.value; option.textContent = share.label
        return option
      }))
      if (before) shareSelect.value = before
    }
    const screenChoice = options.querySelector<HTMLInputElement>('input[value="screen-camera"]')!
    screenChoice.disabled = !availableVideo || !shares.length
    screenChoice.parentElement!.lastChild!.textContent = 'Screen share with camera and audio' + (screenChoice.disabled ? availableVideo ? ' — no eligible screen share' : ' — unavailable in this browser' : '')
  }
  refreshShares()
  sharePicker.append(shareSelect); options.append(sharePicker)
  const excluded = recordingVideoPeople(s).filter(person => person.fallback.startsWith('Update'))
  const capabilities = document.createElement('p')
  capabilities.className = 'note'
  capabilities.textContent = 'Video is composed locally at 720p, 15 frames per second. Only the selected layout is captured. Pausing removes that interval from the saved file. Video recording pauses when this app is hidden; return and press Resume.'
    + (excluded.length ? ` Video excluded for older clients: ${excluded.map(person => person.label).join(', ')}. They appear by name and can still contribute call audio.` : '')
  options.append(capabilities)
  const temporary = dockedCall?.session === s ? dockedCall.ui.roomDestruct : roomDestruct
  const shareTimer = setInterval(refreshShares, 1000)
  let confirmed: boolean
  try { confirmed = await confirmRoomAction({
    title: `Record the call in ${callOrigin(s)?.roomName ?? 'this room'}?`,
    message: 'Everybody in the room is told who is recording and what you choose below. Late joiners are told before joining. The notice remains visible while paused. The authorised voices you hear and your own microphone are included. The recording stays on this device until you choose to save or share it. Browser file-size limits may stop it earlier.'
      + (temporary ? ' Recording creates retained history of this temporary meeting. Room destruction discards unsaved local recordings, but cannot delete copies somebody has already saved or shared.' : '')
      + (replacing ? ' Starting this recording replaces the previous local clip. Save or share that clip first if you want to keep it.' : ''),
    content: options,
    confirmLabel: 'Start recording',
  }) } finally { clearInterval(shareTimer) }
  if (!confirmed) return
  if (mediaSession() !== s || s.call?.id !== callId || s.epoch !== epoch || s.closed || activeRecording) return
  const chosen = layout as 'audio' | VideoRecordingLayout
  const selectedShare = shares.find(share => `${share.participant}:${share.device}` === shareSelect.value)
  if (chosen === 'screen-camera' && !selectedShare) throw new Error('Choose an eligible screen share before recording.')
  if (chosen !== 'audio' && document.hidden) throw new Error('Keep this app visible to start video recording.')
  const before = useLive ? memberRecordings.get(s.roomId)?.get(`${callId}:${myDeviceId}`)?.state.recording : recordings.get(s.roomId)
  const notice: RecordingNotice = { on: true, id: bytesToHex(randomBytes(16)), version: Math.max(Date.now(), (before?.version ?? 0) + 1) }
  const signed: SignedRecording = { ...notice, sig: signRecordingNotice({ roomId: s.roomId, notice, authoritySk }) }
  const captureNotice: RecordingCaptureNotice = { id: notice.id, version: notice.version, capture: chosen, recorder: mediaMe(), device: myDeviceId }
  const capture = { ...captureNotice, sig: signRecordingCaptureNotice({ roomId: s.roomId, notice: captureNotice, authoritySk }) }
  // Told first, recorded second. A recording nobody was told about is the
  // one thing this must never make, so a notice that fails to go out is a
  // recording that never starts.
  if (useLive) {
    const live: LiveRecordingState = { recording: { op: 'recording', ...signed }, capture: { op: 'recording-capture', ...capture }, call: callId, recorder: s.participant, device: s.device }
    signed.live = live
    try { await s.publishLiveRecording(live, () => mediaSession() === s && s.call?.id === callId && s.epoch === epoch && !s.closed) }
    catch (error) { await postRecordingOff(s, authoritySk, signed); throw error }
    ingestLiveRecordings(s)
  } else {
    await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'recording-capture', ...capture }))
    await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'recording', ...signed }))
    recordingCaptures.set(s.roomId, capture)
  }
  if (mediaSession() !== s || s.call?.id !== callId || s.epoch !== epoch || s.closed) { await postRecordingOff(s, authoritySk, signed); return }
  if (!useLive) adoptRecording(s, signed, nowSeconds())
  let recorder: CallRecorder
  let video: RecordingVideo | undefined
  try {
    if (chosen !== 'audio') video = new RecordingVideo({
      layout: chosen,
      snapshot: () => recordingVideoSnapshot(s, callId, origin, selectedShare),
      onFailure: reason => { void stopRecording(reason) },
    })
    recorder = new CallRecorder({
      maxBytes: Math.floor(MAX_UPLOAD_SOURCE_BYTES * 0.95),
      video: video?.track,
      onLimit: (reason) => { void stopRecording(reason) },
    })
  } catch (err) {
    video?.close()
    await postRecordingOff(s, authoritySk, signed)
    throw err
  }
  const timer = setInterval(() => {
    if (signed.live) {
      s.publishLiveRecording(signed.live, () => activeRecording?.notice === signed && mediaSession() === s && s.call?.id === callId && s.epoch === epoch)
        .then(() => ingestLiveRecordings(s)).catch(() => { void stopRecording('the recording warning could not be confirmed') })
      return
    }
    s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'recording-capture', ...capture }))
      .then(() => s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'recording', ...signed })))
      .then(() => adoptRecording(s, signed, nowSeconds()))
      .catch(() => { /* The next repost tries again; the notice shows as unconfirmed meanwhile. */ })
  }, RECORDING_REPOST_SECONDS * 1000)
  const elapsedTimer = setInterval(() => {
    feedRecorder()
    if (!document.hidden && !recorder.paused) renderRecordingElapsed()
  }, 1000)
  activeRecording = { recorder, video, session: s, callId, epoch, authoritySk, notice: signed, capture, timer, elapsedTimer }
  if (replacing && pendingRecording === replacing) discardPendingRecording()
  feedRecorder()
  renderRecording()
  renderMeeting()
}

async function postRecordingOff(s: RoomSession, authoritySk: Uint8Array, was: SignedRecording): Promise<void> {
  const notice: RecordingNotice = { on: false, id: was.id, version: Math.max(Date.now(), was.version + 1) }
  const signed: SignedRecording = { ...notice, sig: signRecordingNotice({ roomId: s.roomId, notice, authoritySk }) }
  if (was.live) {
    const live: LiveRecordingState = { recording: { op: 'recording', ...signed }, call: was.live.call, recorder: was.live.recorder, device: was.live.device }
    try { await s.publishLiveRecording(live); ingestLiveRecordings(s) }
    catch { /* Keep the warning visible if the stop could not be confirmed. */ }
    return
  }
  try {
    await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'recording', ...signed }))
  } catch {
    // The notice goes on saying "recording" until it is taken down: shown
    // as unconfirmed once the reposts stop, which is the honest failure.
  }
  if (recordings.has(s.roomId) || s === session) adoptRecording(s, signed, nowSeconds())
}

/** Stop recording, take the notice down, and hold the file for its owner. */
async function stopRecording(reason?: string): Promise<void> {
  const active = activeRecording
  if (!active) return
  activeRecording = undefined
  clearInterval(active.timer)
  clearInterval(active.elapsedTimer)
  const roomId = active.session.roomId
  recordingStops.add(active)
  renderRecording()
  renderMeeting()
  try {
    // The recorder stops before the notice comes down, never after.
    const blob = await active.recorder.stop()
    if (!active.discarded && blob.size > 0) {
      if (pendingRecording) URL.revokeObjectURL(pendingRecording.url)
      const file = new File([blob], recordingFileName(active.recorder.startedAt, active.recorder.mimeType), { type: active.recorder.mimeType.split(';')[0]! })
      pendingRecording = { file, roomId, url: URL.createObjectURL(file) }
      setStatus(`Recording stopped${reason ? ` because ${reason}` : ''}: ${formatBytes(file.size)}, on this device only. Share it in the room or save it.`)
    } else if (!active.discarded) {
      setStatus(`Recording stopped${reason ? ` because ${reason}` : ''}. Nothing was recorded.`)
    }
    // Saving local bytes does not depend on the relay confirming the warning.
    renderRecording()
    await postRecordingOff(active.session, active.authoritySk, active.notice)
  } finally {
    active.video?.close()
    recordingStops.delete(active)
    renderRecording()
    renderMeeting()
  }
}

/** Hand the recorder exactly what this device is playing, and its own
 *  microphone. A voice kept off the stage is never in the recording. */
function feedRecorder(): void {
  const active = activeRecording
  if (!active || active.session !== mediaSession()) return
  if (active.session.closed || active.session.epoch !== active.epoch || active.session.call?.id !== active.callId ||
      (active.notice.live && !participantRecordingReady(active.session))) {
    active.recorder.setTracks([])
    void stopRecording('the original call or recording permission changed')
    return
  }
  const tracks: MediaStreamTrack[] = []
  const callId = active.session.call?.id
  const callDevices = new Set(active.session.participants().filter(view => callId && view.call?.id === callId).flatMap(view => view.call!.devices))
  for (const [key, audio] of remoteAudios) {
    const device = tileDevice(key)
    const person = active.session.participants().find(view => view.devices.includes(device))
    if (callDevices.has(device) && (!active.notice.live || person?.recordingProfiles?.[device] === 4) && cachedMonitorHere && !cachedOwnDevices.has(device) && !meetingGated(device) && (!person || volumeLevel(person.participant) > 0)) tracks.push(audio.track)
  }
  if (micTrack?.enabled && meetingLetsMeSend()) tracks.push(micTrack)
  active.recorder.setTracks(tracks)
}

/** Recording ids whose stale notice this device is already taking down. */
const takingDown = new Set<string>()

function clockTime(seconds: number): string {
  return new Date(seconds * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

function renderRecordingElapsed(): void {
  const active = activeRecording
  const seconds = Math.floor((active?.recorder.elapsedMs ?? 0) / 1000)
  const minutes = Math.floor(seconds / 60)
  const elapsed = `${String(minutes).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')} recorded`
  for (const [id, visible] of [
    ['recordingElapsed', !!active && active.session === session],
    ['callDockRecordingElapsed', !!active && active.session === dockedCall?.session],
  ] as const) {
    const element = $(id)
    element.hidden = !visible
    if (visible && element.textContent !== elapsed) element.textContent = elapsed
  }
}

function renderRecordingPause(id: string, mine: boolean): void {
  const button = $(id) as HTMLButtonElement
  const recorder = activeRecording?.recorder
  button.hidden = !mine || !recorder?.canPause
  button.textContent = recorder?.paused ? 'Resume recording' : 'Pause recording'
  button.setAttribute('aria-pressed', String(!!recorder?.paused))
}

function toggleRecordingPause(): void {
  const active = activeRecording
  if (!active || active.session !== mediaSession()) return
  try {
    if (active.recorder.paused) {
      if (active.video && document.hidden) throw new Error('Return to this app before resuming video recording.')
      active.video?.resume()
      active.recorder.resume()
    } else {
      active.recorder.pause()
      active.video?.pause()
    }
    renderRecording()
  } catch (error) {
    setStatus(describeError(error))
  }
}

document.addEventListener('visibilitychange', () => {
  const active = activeRecording
  if (!document.hidden || !active?.video || active.recorder.paused) return
  try {
    if (!active.recorder.canPause) { void stopRecording('this browser cannot pause video safely while hidden'); return }
    active.recorder.pause(); active.video.pause()
    setStatus('Video recording paused because this app was hidden. Return and press Resume to continue; the hidden interval is omitted.')
    renderRecording()
  } catch {
    void stopRecording('this app could not pause safely when hidden')
  }
})

/** The recording notice every member sees, and the finished file its
 *  owner decides about. */
function renderRecording(): void {
  const banner = $('recordingBanner')
  const text = $('recordingBannerText')
  const stop = $('recordingStop') as HTMLButtonElement
  const view = currentRecordingView()
  const mine = activeRecording !== undefined && activeRecording.session === session
  // A notice gone quiet that this device could take down, and is not
  // itself keeping up: the recorder that posted it is gone.
  if (view.state === 'unconfirmed' && !activeRecording && isRoomAuthority() && session && invitationAuthoritySk) {
    const heard = recordings.get(session.roomId)
    if (heard && !takingDown.has(heard.id)) {
      takingDown.add(heard.id)
      void postRecordingOff(session, invitationAuthoritySk, heard).finally(() => takingDown.delete(heard.id))
    }
  }
  banner.hidden = view.state === 'off'
  banner.dataset.state = view.state
  stop.hidden = !mine
  renderRecordingPause('recordingPause', mine)
  renderRecordingElapsed()
  if (view.state === 'on') {
    text.textContent = mine
      ? activeRecording!.recorder.paused
        ? 'Your recording is paused. Paused time is omitted from the saved file. Everybody still sees the recording notice.'
        : `You are recording ${activeRecording!.capture.capture === 'audio' ? 'this call\'s audio' : `${activeRecording!.capture.capture === 'screen-camera' ? 'a screen share with camera' : activeRecording!.capture.capture + ' video'} and call audio`} (${formatBytes(activeRecording!.recorder.bytes)} so far). Everybody in the room can see this notice.`
      : `This call is being recorded, since ${clockTime(view.since)}. ${recordingCaptureDescription()} KithMoot cannot stop anybody recording with another app, recording or not.`
    if (mine && memberRecordingViews().some(heard => heard.state.device !== myDeviceId)) text.textContent += ` ${recordingCaptureDescription()}`
  } else if (view.state === 'unconfirmed') {
    text.textContent = `This call may still be recording: the notice was last confirmed at ${clockTime(view.lastHeard)}.`
  }
  $('callBay').classList.toggle('recording', view.state !== 'off')

  const ready = $('recordingReady')
  ready.hidden = !pendingRecording
  if (pendingRecording) {
    const draft = drafts.get(currentChannel)
    const waiting = !!draft.pendingFiles?.includes(pendingRecording.file)
    const staged = pendingRecording.addedTo === draft && !!pendingRecording.attachment && draft.attachments.includes(pendingRecording.attachment)
    $('recordingReadyText').textContent = `Your recording is ready: ${pendingRecording.file.name}, ${formatBytes(pendingRecording.file.size)}. `
      + (staged ? 'Added to your message draft; press Send to share it. You can still save this local copy.'
        : waiting ? 'Held on this device. Allow file storage and upload the selected file to add it to your message.'
          : 'Save it or add it to a message. Adding it keeps this local copy until you discard it.')
    const save = $('recordingSave') as HTMLAnchorElement
    save.href = pendingRecording.url
    save.download = pendingRecording.file.name
    const share = $('recordingShare') as HTMLButtonElement
    share.hidden = session?.roomId !== pendingRecording.roomId
    share.disabled = sharingRecording || !!draft.job || waiting || staged
  }
  renderDock()
}

setInterval(() => { if (activeRecording || session) renderRecording() }, 30_000)

function discardPendingRecording(): void {
  if (!pendingRecording) return
  URL.revokeObjectURL(pendingRecording.url)
  pendingRecording = undefined
  renderRecording()
}

$('recordingStop').addEventListener('click', () => { void stopRecording() })
$('recordingPause').addEventListener('click', toggleRecordingPause)
$('recordingShare').addEventListener('click', async () => {
  const pending = pendingRecording
  if (!pending || sharingRecording || session?.roomId !== pending.roomId) return
  if (!channelAvailable(currentChannel) || (currentChannel !== undefined && WRITTEN_BY_AGENTS.includes(currentChannel))) {
    setStatus('Choose a conversation you can send to before adding the recording. Your local copy is kept.')
    return
  }
  showMobileRoomView('chat')
  const draft = captureDraft()
  if (draft.job || draft.pendingFiles?.includes(pending.file)
    || pending.addedTo === draft && !!pending.attachment && draft.attachments.includes(pending.attachment)) return
  // Through the same door as a dropped file: sealed here, and uploaded only
  // to storage this person has already allowed, or held until they do.
  sharingRecording = true
  renderRecording()
  try { await shareDroppedFiles([pending.file]) }
  catch (err) { setStatus(describeError(err)) }
  finally { sharingRecording = false; renderRecording() }
})
$('recordingDiscard').addEventListener('click', async () => {
  if (!await confirmRoomAction({ title: 'Discard the local recording?', message: 'Files already added to a message draft remain there; remove them from that draft separately. Saved or sent copies stay.', confirmLabel: 'Discard', danger: true })) return
  discardPendingRecording()
})

/** Meeting mode, as each person needs it: the notice and the hand for an
 *  attendee, the stage and the recorder for whoever runs the room. */
function renderMeeting(): void {
  const policy = roomMeeting()
  const on = !!policy?.on
  const me = meParticipant
  const speaker = meetingAllows(policy, me, 'audio')
  const moderator = session !== undefined && isRoomAuthority()

  const notice = $('meetingNotice')
  notice.hidden = !on
  const raise = $('raiseHand') as HTMLButtonElement
  raise.hidden = !on || speaker
  const up = handsUp.has(me)
  raise.textContent = up ? 'Lower your hand' : 'Raise your hand'
  raise.setAttribute('aria-pressed', String(up))
  if (on) {
    const hands = [...handsUp.keys()].filter(p => !meetingAllows(policy, p, 'audio'))
    $('meetingNoticeText').textContent = moderator
      ? `Meeting mode is on. ${hands.length === 0 ? 'No hands raised.' : `${hands.length} ${hands.length === 1 ? 'hand' : 'hands'} raised.`}`
      : speaker
        ? 'Meeting mode: you are a speaker.'
        : up
          ? 'Meeting mode: your hand is up. The host can make you a speaker.'
          : 'Meeting mode: only speakers can talk or show video.'
  }

  const record = $('recordToggle') as HTMLButtonElement
  const recordingHere = activeRecording?.session === session && activeRecording !== undefined
  const recordLabel = recordingHere ? 'Stop recording' : 'Record call'
  record.hidden = !session && !recordingHere
  record.querySelector('.callWord')!.textContent = recordLabel
  record.querySelector('.callShort')!.textContent = recordingHere ? 'Stop' : 'Record'
  record.setAttribute('aria-label', recordLabel)
  record.setAttribute('aria-pressed', String(recordingHere))
  record.dataset.on = String(recordingHere)
  const canRecord = !!recordingMimeType() || (!!recordingMimeType(true) && typeof HTMLCanvasElement.prototype.captureStream === 'function')
  const permitted = mediaSession() === session && (participantRecordingReady(session) || legacyRecordingReady(session))
  record.disabled = !recordingHere && (!permitted || !session?.call || !canRecord)
  const authorityHint = $('recordingAuthorityHint')
  authorityHint.textContent = recordingPermissionHint(session)
  authorityHint.hidden = permitted || recordingHere || !session
  if (!authorityHint.hidden) record.setAttribute('aria-describedby', 'recordingAuthorityHint')
  else record.removeAttribute('aria-describedby')
  record.title = recordingHere ? 'Stop recording' : !permitted ? authorityHint.textContent! : record.disabled ? (canRecord ? 'Join the call to record it.' : 'This browser cannot record calls.') : 'Record audio or video'

  const panel = $('meetingPanel') as HTMLDetailsElement
  panel.hidden = !moderator
  if (!moderator) return
  const mode = $('meetingModeToggle') as HTMLButtonElement
  mode.textContent = on ? 'End meeting mode' : 'Start meeting mode'
  mode.setAttribute('aria-pressed', String(on))

  const list = $('meetingPeople')
  list.replaceChildren()
  const views = session?.participants() ?? []
  // Raised hands first, oldest first: who has waited longest.
  const order = (p: string): number => handsUp.get(p) ?? Infinity
  for (const view of [...views].sort((a, b) => order(a.participant) - order(b.participant))) {
    if (view.participant === me) continue
    const row = document.createElement('div')
    row.className = 'hostRow'
    const who = document.createElement('span')
    who.className = 'who'
    who.append(identityRun(shownAs(view.participant, view.name), false, false, false, true))
    if (view.agent) who.append(' (agent)')
    row.append(who)
    const isSpeaker = !!policy?.speakers.includes(view.participant)
    if (handsUp.has(view.participant) && !isSpeaker) {
      const hand = document.createElement('span')
      hand.className = 'note handRaised'
      hand.textContent = 'hand raised'
      row.append(hand)
    }
    const toggle = document.createElement('button')
    toggle.type = 'button'
    toggle.textContent = isSpeaker ? 'Stop speaker' : 'Make speaker'
    toggle.setAttribute('aria-pressed', String(isSpeaker))
    const label = personLabel(view.participant)
    toggle.addEventListener('click', () => {
      setSpeaker(view.participant, !isSpeaker)
        .then(() => setStatus(isSpeaker ? `${label} is no longer a speaker.` : `${label} is a speaker now.`))
        .catch((err) => setStatus(describeError(err)))
    })
    row.append(toggle)
    list.append(row)
  }
}

$('meetingModeToggle').addEventListener('click', () => {
  const on = !roomMeeting()?.on
  setMeetingMode(on).catch((err) => setStatus(describeError(err)))
})
$('recordToggle').addEventListener('click', () => {
  if (activeRecording) { void stopRecording(); return }
  startRecording().catch((err) => setStatus(describeError(err)))
})
$('raiseHand').addEventListener('click', () => raiseHand(!handsUp.has(meParticipant)))

/** A room left, or switched away from: its hands are its own, and a
 *  recording of its call stops with it. The policies stay, keyed by room,
 *  for a call still docked. */
function resetMeetingState(): void {
  handsUp.clear()
  handsAt.clear()
  clearTimeout(meetingRepostTimer)
}

// ---------------------------------------------------------------------------
// Approvals: an agent asks, in the room, and the right person answers
//
// The card is shown only to somebody the agent will listen to - a
// participant on the keeper's announced admin list, or the agent's verified
// principal - because an answer from anybody else is ignored by the agent
// and would be a button that does nothing. Everybody sees the outcome as a
// system line, judged by the same rule, so it is not a line anybody could
// put in the chat by answering a question that was not theirs.
// ---------------------------------------------------------------------------

interface OpenApproval {
  id: string
  from: string
  text: string
  options: string[]
  expiresAt?: number
  at: number
  answered?: { by: string; verdict: string }
}
const approvals = new Map<string, OpenApproval>()
let approvalTimer: ReturnType<typeof setTimeout> | undefined

/** Whether `participant` is somebody the agent `requester` will listen to. */
function canApprove(participant: string, requester: string): boolean {
  if (contactIsBlocked(requester) || contactIsBlocked(participant)) return false
  if (admins.has(participant)) return true
  const owner = session?.participants().find((v) => v.participant === requester)?.owner
  return owner !== undefined && owner.principal === participant
}

function verdictSentence(by: string, verdict: string, request: OpenApproval): string {
  const what = request.text.length > 80 ? `${request.text.slice(0, 77)}…` : request.text
  const said = verdict === 'approve' ? 'approved' : verdict === 'decline' ? 'declined' : `answered “${verdict}” to`
  return `${personLabel(by)} ${said} ${personLabel(request.from)}’s request: ${what}`
}

function renderApprovals(): void {
  const box = $('approvals')
  // Keep pending join controls connected when another request arrives,
  // including between pointer-down and pointer-up or while using Tab.
  const existingKnocks = new Map(Array.from(box.querySelectorAll<HTMLElement>('.approvalCard.knock'), card => [card.dataset.request, card]))
  const focusedKnock = document.activeElement?.closest<HTMLElement>('.approvalCard.knock')
  for (const child of Array.from(box.children)) if (!child.classList.contains('knock')) child.remove()
  const now = nowSeconds()
  let soonest: number | undefined
  for (const request of approvals.values()) {
    if (request.answered) continue
    if (request.expiresAt !== undefined && request.expiresAt <= now) continue
    if (!session || !canApprove(meParticipant, request.from)) continue
    if (request.expiresAt !== undefined && (soonest === undefined || request.expiresAt < soonest)) soonest = request.expiresAt
    const card = document.createElement('div')
    card.className = 'approvalCard'
    const who = document.createElement('span')
    who.className = 'who'
    const view = session.participants().find((v) => v.participant === request.from)
    who.append(identityRun(shownAs(request.from, view?.name), false, false, false, true))
    if (view?.owner) who.append(ownerRun(view.owner))
    else if (view?.ownerClaim) who.append(ownerClaimRun(view.ownerClaim))
    who.append(' asks:')
    const text = document.createElement('span')
    text.className = 'text'
    text.textContent = request.text
    const options = document.createElement('div')
    options.className = 'options'
    for (const option of request.options) {
      const button = document.createElement('button')
      button.type = 'button'
      button.textContent = option
      button.addEventListener('click', () => {
        if (!canApprove(meParticipant, request.from)) { renderApprovals(); return }
        for (const b of options.querySelectorAll('button')) (b as HTMLButtonElement).disabled = true
        sendHostControl({ op: 'approval', id: request.id, verdict: option }, `Answered ${option}.`)
      })
      options.append(button)
    }
    card.append(who, text, options)
    box.insertBefore(card, box.querySelector('.approvalCard.knock'))
  }
  for (const knock of knocks.values()) {
    if (knock.participant && contactIsBlocked(knock.participant)) continue
    let card = existingKnocks.get(knock.request)
    existingKnocks.delete(knock.request)
    if (!card) {
      card = document.createElement('div')
      card.className = 'approvalCard knock'
      card.dataset.request = knock.request
      card.tabIndex = -1
      const who = document.createElement('span')
      who.className = 'who'
      const evidence = document.createElement('span')
      evidence.className = 'note knockEvidence'
      evidence.textContent = `Device ${shortKey(knock.device)} · ${knock.kind === 'member' ? 'Account verified by this room’s device credential.' : knock.verifiedParticipant ? 'Account verified by a signature for this request.' : knock.participant ? 'Account claimed by the guest; not verified for this request.' : 'Name supplied by the guest.'}`
      const status = document.createElement('span')
      status.className = 'note knockStatus'
      status.setAttribute('role', 'status')
      const options = document.createElement('div')
      options.className = 'options'
      for (const [label, yes] of [['Let in', true], ['Decline', false]] as const) {
        const button = document.createElement('button')
        button.type = 'button'
        button.textContent = label
        if (yes) button.classList.add('primary')
        button.addEventListener('click', () => answerKnock(knock, yes))
        options.append(button)
      }
      card.append(who, evidence, status, options)
      box.append(card)
    }
    card.setAttribute('role', 'group')
    card.setAttribute('aria-label', `${knockLabel(knock)}’s join request`)
    const who = card.querySelector<HTMLElement>('.who')!
    who.replaceChildren()
    if (knock.participant) who.append(identityRun(shownAs(knock.participant, knock.name), false, false, false, true))
    else who.append(knock.name ?? 'Somebody')
    who.append(' wants to join.')
    const status = card.querySelector<HTMLElement>('.knockStatus')!
    const statusText = knock.state === 'sending' ? knock.declining ? 'Sending refusal…' : 'Sending invitation…'
      : knock.state === 'failed' ? knock.declining ? 'Refusal was not confirmed. The guest may still have received it.' : 'Invitation could not be sent. Check your connection and ask the guest to retry.' : ''
    if (status.textContent !== statusText) status.textContent = statusText
    const options = card.querySelector<HTMLElement>('.options')!
    if (knock.state === 'failed' && card.dataset.state !== 'failed') {
      options.replaceChildren()
      const dismiss = document.createElement('button')
      dismiss.type = 'button'
      dismiss.textContent = 'Dismiss'
      dismiss.addEventListener('click', () => {
        if (knocks.get(knock.request) !== knock) return
        knocks.delete(knock.request)
        clearTimeout(knock.timer)
        renderApprovals()
      })
      options.append(dismiss)
      if (knock.declining) {
        const retry = document.createElement('button'); retry.type = 'button'; retry.textContent = 'Retry decline'
        retry.addEventListener('click', () => { void sendKnockRefusal(knock) })
        options.append(retry)
      }
    }
    for (const button of options.querySelectorAll<HTMLButtonElement>('button')) button.disabled = knock.state === 'sending'
    card.dataset.state = knock.state
  }
  for (const card of existingKnocks.values()) card.remove()
  if (focusedKnock && (!focusedKnock.isConnected || !focusedKnock.contains(document.activeElement))) {
    const next = focusedKnock.isConnected ? focusedKnock : box.querySelector<HTMLElement>('.knock button:not([disabled])') ?? $('chatInput')
    next.focus({ preventScroll: true })
  }
  // A card leaves on its own when its question expires.
  if (approvalTimer !== undefined) clearTimeout(approvalTimer)
  approvalTimer = undefined
  if (soonest !== undefined) approvalTimer = setTimeout(renderApprovals, Math.max(0, (soonest - now) * 1000 + 50))
}

/** The Host panel: shown only to a participant on the announced list. */
function renderHost(): void {
  renderEndRoom()
  renderMeeting()
  renderRecording()
  const panel = $('hostPanel') as HTMLDetailsElement
  const isAdmin = session !== undefined && admins.has(meParticipant)
  panel.hidden = !isAdmin
  if (!isAdmin) return
  const list = $('hostList')
  list.innerHTML = ''
  for (const view of session!.participants()) {
    if (view.participant === meParticipant) continue
    const row = document.createElement('div')
    row.className = 'hostRow'
    const who = document.createElement('span')
    who.className = 'who'
    who.append(identityRun(shownAs(view.participant, view.name), false, false, false, true))
    if (view.agent) who.append(' (agent)')
    if (view.owner) who.append(ownerRun(view.owner))
    else if (view.ownerClaim) who.append(ownerClaimRun(view.ownerClaim))
    row.append(who)
    const label = personLabel(view.participant)
    if (view.participant === keeperParticipant) {
      const note = document.createElement('span')
      note.className = 'note'
      note.textContent = 'looks after this room'
      row.append(note)
      list.append(row)
      continue
    }
    const mute = document.createElement('button')
    mute.type = 'button'
    mute.textContent = 'Mute'
    mute.title = 'Ask their app to switch their camera and microphone off. It is a request, and nothing here can make them.'
    mute.addEventListener('click', () => sendHostControl({ op: 'mute', participant: view.participant }, `Asked ${label} to mute.`))
    const remove = document.createElement('button')
    remove.type = 'button'
    remove.className = 'danger'
    remove.textContent = 'Remove'
    remove.title = 'Move the room to a new key this person is not given.'
    remove.addEventListener('click', async () => {
      if (!await confirmRoomAction({ title: `Remove ${label}?`, message: 'The room will move to a new key that this person is not given. What they already read stays theirs. If they still have the invite link they can come back under a new name; replace the link as well when that matters.', confirmLabel: 'Remove from room', danger: true })) return
      // The keeper acts on a Remove up to a day after it was sent, so one
      // pressed while it is away (a restart, a deploy) waits for it.
      sendHostControl({ op: 'remove', participant: view.participant }, keeperHere()
        ? `Asked the keeper to remove ${label}.`
        : `Asked the keeper to remove ${label}. It is not in the room just now; it will act when it is back, if that is within a day.`)
    })
    row.append(mute, remove)
    list.append(row)
  }
}

$('closeRoom').addEventListener('click', async () => {
  if (!await confirmRoomAction({ title: 'Close this room for everybody?', message: 'The invite link will stop working and the agent keeping the room open will leave.', confirmLabel: 'Close room', danger: true })) return
  // Closing is live only: a keeper that is away never hears it.
  if (!keeperHere()) {
    setStatus('The keeper is not in the room just now, so the room cannot be closed. Try again when it is back.')
    return
  }
  sendHostControl({ op: 'close' }, 'Asked the keeper to close the room.')
})

/** Whether the room's keeper is on the roster now, as far as this device can tell. */
function keeperHere(): boolean {
  return keeperParticipant !== undefined && session !== undefined && session.participants().some((v) => v.participant === keeperParticipant)
}

function ingestControl(messages: ChatMessage[]): void {
  let changed = false
  for (const m of messages) {
    if (controlSeen.has(m.id)) continue
    controlSeen.add(m.id)
    const control = decodeControl(m.text)
    if (!control) continue
    switch (control.op) {
      case 'catalogue': {
        // Sent by the host it names, or it is somebody else's claim.
        if (control.host !== m.participant) break
        const have = catalogues.get(control.host)
        if (have && have.at > m.sentAt) break
        catalogues.set(control.host, { ...control, at: m.sentAt })
        assignmentPanel.refreshPeople()
        changed = true
        break
      }
      case 'invited':
        if (control.host === m.participant && m.sentAt >= nowSeconds() - 30) setStatus(`${control.name} is joining.`)
        break
      case 'dismissed':
        if (control.host === m.participant && m.sentAt >= nowSeconds() - 30) setStatus(`${control.name} has left${control.reason ? ` (${control.reason})` : ''}.`)
        break
      case 'error':
        if (control.host === m.participant && m.sentAt >= nowSeconds() - 30) setStatus(`Agent host: ${control.message}`)
        break
      case 'relays':
        ingestRoomRelays(control, m.sentAt)
        break
      case 'channels': {
        // Only a list the room's authority signed, and only the newest. An
        // unsigned one is exactly what a member holding the room key would
        // forge, which is the whole reason the list is signed at all.
        const authority = roomAuthority()
        if (!authority || !session || control.host !== m.participant) break
        if (!verifyChannels({ roomId: session.roomId, epoch: control.epoch, channels: control.channels, sig: control.sig, authority })) break
        if (m.sentAt < channelsAt) break
        channels = control.channels
        channelsAt = m.sentAt
        for (const name of channels) followNamedConversation(name)
        if (!$('roomArea').hidden) restoreConversation()
        // Keep unfinished work reachable when its conversation closes.
        // An empty conversation can return straight to the main chat.
        if (currentChannel !== undefined && !channelAvailable(currentChannel) && !draftHasWork(captureDraft())) selectChannel(undefined)
        else renderChannels()
        break
      }
      case 'admins': {
        // Only a list the room's authority signed, and only the newest.
        const authority = roomAuthority()
        if (!authority || !session || control.host !== m.participant) break
        if (!verifyAdmins({ roomId: session.roomId, epoch: control.epoch, admins: control.admins, sig: control.sig, authority })) break
        if (m.sentAt < adminsAt) break
        admins = new Set(control.admins)
        adminsAt = m.sentAt
        keeperParticipant = control.host
        renderHost()
        renderApprovals()
        renderChannels()
        break
      }
      case 'meeting':
        ingestMeeting(control, m.sentAt)
        break
      case 'recording':
        ingestRecording(control, m.sentAt)
        break
      case 'recording-capture':
        ingestRecordingCapture(control)
        break
      case 'hand':
        ingestHand(m.participant, control.up, m.sentAt)
        break
      case 'mute':
        // For this device, from somebody on the announced list, and recent:
        // a request replayed from last week is not one.
        if (control.participant !== meParticipant || !admins.has(m.participant)) break
        if (m.sentAt < nowSeconds() - 30) break
        muteRequested(m.participant)
        break
      case 'approval-request': {
        // Kept whoever asked: the card decides who sees it, and the answer
        // decides whose answer counts. An expired one is history.
        if (control.expiresAt !== undefined && control.expiresAt <= nowSeconds()) break
        if (approvals.has(control.id)) break
        approvals.set(control.id, {
          id: control.id,
          from: m.participant,
          text: control.text,
          options: control.options ?? [...DEFAULT_APPROVAL_OPTIONS],
          ...(control.expiresAt !== undefined ? { expiresAt: control.expiresAt } : {}),
          at: m.sentAt,
        })
        renderApprovals()
        break
      }
      case 'approval': {
        const request = approvals.get(control.id)
        if (!request || request.answered) break
        if (!canApprove(m.participant, request.from)) break
        if (request.expiresAt !== undefined && m.sentAt > request.expiresAt) break
        if (!request.options.includes(control.verdict)) break
        request.answered = { by: m.participant, verdict: control.verdict }
        addSystemLine(verdictSentence(m.participant, control.verdict, request))
        renderApprovals()
        break
      }
      default:
        break
    }
  }
  if (changed) {
    renderInvites()
    if (document.activeElement === $('chatInput')) renderMentionPicker()
  }
}

/** Which hosts are actually here. A catalogue from a host that has left is
 *  a menu for a kitchen that has closed. */
/**
 * How an agent gets into a room.
 *
 * This used to be hidden entirely whenever no computer in the room was
 * offering one, so somebody looking for "how do I invite an agent" found an
 * empty space and concluded the feature did not exist. An empty list with a
 * sentence saying why it is empty answers the question; no list at all
 * answers nothing. It lives on the Agents tab, which is where somebody
 * thinking about agents already is.
 */
function renderInvites(): void {
  const box = $('inviteAgents')
  const list = $('inviteList')
  const focused = document.activeElement as HTMLElement | null
  const focusKey = focused && list.contains(focused) ? focused.dataset.inviteAction : undefined
  list.innerHTML = ''
  // Shown whenever there is a room, now that it is in the room's details
  // rather than on the message screen. It used to appear only while the
  // agents' conversation was open, which after the move would have meant
  // switching to that conversation - closing the sheet - and opening the
  // sheet again to find this.
  if (!session) {
    box.hidden = true
    return
  }
  const present = new Set(session?.participants().map((v) => v.participant) ?? [])
  let rows = 0
  for (const [host, catalogue] of catalogues) {
    if (!present.has(host)) continue
    for (const entry of catalogue.agents) {
      const row = document.createElement('div')
      row.className = 'inviteRow'
      const running = catalogue.running.find((r) => r.id === entry.id)
      const button = document.createElement('button')
      button.type = 'button'
      button.dataset.inviteAction = JSON.stringify([host, entry.id, 'membership'])
      button.textContent = running ? `Dismiss ${entry.name}` : `Invite ${entry.name}`
      button.addEventListener('click', () => {
        button.disabled = true
        session
          ?.channel(CONTROL_CHANNEL)
          .send(encodeControl({ op: running ? 'dismiss' : 'invite', host, agent: entry.id }))
          .then(() => setStatus(running ? `Asked ${catalogue.name} to stop ${entry.name}.` : `Asked ${catalogue.name} to start ${entry.name}.`))
          .catch((err) => setStatus(describeError(err)))
          .finally(() => {
            button.disabled = false
          })
      })
      row.append(button)
      const desc = document.createElement('span')
      desc.className = 'desc'
      desc.textContent = `${entry.description ?? ''}${entry.listens ? ' Listens, when allowed.' : ''} · via ${catalogue.name}`
      row.append(desc)
      if (running) {
        const owner = running.participant
        const tag = document.createElement('span')
        tag.className = 'running'
        tag.textContent = owner && present.has(owner) ? 'in the room' : 'host reports it running'
        row.append(tag)
        if (owner && present.has(owner)) for (const action of entry.actions ?? []) {
          const capability = document.createElement('div')
          capability.className = 'inviteCapability'
          const choose = document.createElement('button')
          choose.type = 'button'
          choose.textContent = `Assign work: ${action.label}`
          choose.dataset.inviteAction = JSON.stringify([host, entry.id, action.id])
          choose.addEventListener('click', () => {
            const current = session
            const open = () => { if (current && session === current) assignmentPanel.offerTo(owner, action.id) }
            const sheet = $('roomSheet') as HTMLDialogElement
            if (sheet.open) { sheet.addEventListener('close', open, { once: true }); sheet.close() }
            else open()
          })
          const description = document.createElement('span')
          description.className = 'desc'
          description.textContent = action.description
          capability.append(choose, description)
          row.append(capability)
        }
      }
      list.append(row)
      rows++
    }
  }
  if (rows === 0) {
    const none = document.createElement('p')
    none.className = 'note'
    none.textContent =
      'Nobody here is offering one at the moment. An agent runs on somebody’s own computer, ' +
      'so one can only be asked in while that person has their agent host running and is in this room.'
    const guide = document.createElement('a')
    guide.href = 'https://github.com/ForgeSworn/kithmoot/blob/main/docs/agents.md'
    guide.target = '_blank'
    guide.rel = 'noopener noreferrer'
    guide.textContent = 'Agent setup guide ↗'
    list.append(none, guide)
  }
  box.hidden = false
  if (focusKey) (Array.from(list.querySelectorAll<HTMLElement>('[data-invite-action]')).find(button => button.dataset.inviteAction === focusKey) ?? box.querySelector<HTMLElement>('summary'))?.focus({ preventScroll: true })
}

// ---------------------------------------------------------------------------
// Attachments: files shared through Wildbloom
// ---------------------------------------------------------------------------

type OpenedAttachment = { url: string; name: string; type: string; size: number; text?: string; expanded?: boolean } | { error: string }

/** What has been fetched and opened, per log, per message, per attachment.
 *  An object URL is revoked when its message leaves the log and never
 *  before, so a re-render costs nothing and never fetches twice. */
const openedAttachments = new Map<string, OpenedAttachment>()
const attachmentViewer = new AttachmentViewer()
window.addEventListener('pagehide', () => attachmentViewer.close())

function attachmentKey(logId: string, messageId: string, index: number): string {
  return `${logId}/${messageId}/${index}`
}

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${Math.round(n / 1024)} KB`
  return `${(n / (1024 * 1024)).toFixed(1)} MB`
}

/** Drop what was opened for messages no longer in this log. */
function pruneOpenedAttachments(logId: string, messages: ChatMessage[]): void {
  const live = new Set<string>()
  for (const m of messages) (m.attachments ?? []).forEach((_, i) => live.add(attachmentKey(logId, m.id, i)))
  for (const [key, opened] of openedAttachments) {
    if (!key.startsWith(`${logId}/`) || live.has(key)) continue
    if ('url' in opened) { attachmentViewer.closeUrl(opened.url); URL.revokeObjectURL(opened.url) }
    openedAttachments.delete(key)
  }
}

/**
 * One attachment under a message. Nothing is fetched until the person
 * clicks: a fetch reaches the Blossom server, and that is a fact about
 * this device that a message from somebody else must not create on its
 * own. Once fetched, the envelope is checked against the hash the message
 * named before the key touches it, then opened here and shown inline if it
 * is a picture, or offered to save if it is anything else.
 */
function attachmentCard(logId: string, m: ChatMessage, index: number, a: ChatAttachment): HTMLElement {
  const generation = roomGeneration
  const card = document.createElement('span')
  card.className = 'attachment'
  const key = attachmentKey(logId, m.id, index)
  const render = (): void => {
    card.innerHTML = ''
    const label = document.createElement('span')
    label.className = 'label'
    label.textContent = `${a.name ?? 'Encrypted file'}${a.size !== undefined ? ` \u00b7 ${formatBytes(a.size)}` : ''}`
    card.append(label)
    const opened = openedAttachments.get(key)
    if (opened && 'url' in opened) {
      if (opened.type.startsWith('image/')) {
        const img = document.createElement('img')
        img.src = opened.url
        img.alt = opened.name
        const expand = document.createElement('button')
        expand.type = 'button'
        expand.className = 'attachmentImage'
        expand.setAttribute('aria-label', `Expand ${opened.name}`)
        expand.append(img)
        expand.onclick = () => attachmentViewer.open(opened, expand)
        card.append(expand)
      } else if (opened.type.startsWith('audio/') || opened.type.startsWith('video/')) {
        const player = document.createElement(opened.type.startsWith('audio/') ? 'audio' : 'video')
        player.controls = true
        player.preload = 'metadata'
        if (player instanceof HTMLVideoElement) player.playsInline = true
        player.src = opened.url
        player.setAttribute('aria-label', opened.name)
        card.append(player)
      } else if (opened.type === 'application/pdf') {
        const view = document.createElement('a')
        view.href = opened.url
        view.target = '_blank'
        view.rel = 'noopener noreferrer'
        view.textContent = `View ${opened.name}`
        card.append(view)
      } else if (opened.text !== undefined) {
        const preview = document.createElement('pre')
        preview.className = 'attachmentText'
        preview.textContent = opened.expanded ? opened.text : opened.text.slice(0, 600).replace(/[\uD800-\uDBFF]$/, '') + (opened.text.length > 600 ? '…' : '')
        card.append(preview)
        if (opened.text.length > 600) {
          const expand = document.createElement('button')
          expand.type = 'button'
          expand.textContent = opened.expanded ? 'Collapse' : 'Read more'
          expand.setAttribute('aria-expanded', String(!!opened.expanded))
          expand.onclick = () => { opened.expanded = !opened.expanded; render() }
          card.append(expand)
        }
        const copy = document.createElement('button')
        copy.type = 'button'
        copy.textContent = 'Copy full text'
        copy.onclick = async () => { copy.textContent = await copyMessageText(opened.text!) ? 'Copied' : 'Copy failed' }
        card.append(copy)
      } else {
        const note = document.createElement('span')
        note.textContent = 'Preview unavailable for this file type. Save it to open in a compatible app.'
        card.append(note)
      }
      const save = document.createElement('a')
      save.dataset.focusKey = `attachment-${index}`
      save.href = opened.url
      save.download = opened.name
      save.textContent = `Save ${opened.name} (${formatBytes(opened.size)})`
      card.append(save)
      return
    }
    const button = document.createElement('button')
    button.type = 'button'
    button.textContent = opened ? 'Try again' : 'Show'
    button.dataset.focusKey = `attachment-${index}`
    button.title = 'Fetch the encrypted file from where it is stored, check it, and open it here'
    button.addEventListener('click', async () => {
      button.disabled = true
      button.textContent = 'Fetching\u2026'
      try {
        const file = await fetchAttachmentBlob(a)
        if (generation !== roomGeneration) return
        const type = file.type.split(';')[0]!.trim().toLowerCase()
        const isText = type.startsWith('text/') || ['application/json', 'application/xml'].includes(type)
        // Never execute HTML/SVG/scripts as a document. Text is collapsed and
        // assigned through textContent, including untrusted markup.
        const text = isText ? await file.source.text() : undefined
        if (generation !== roomGeneration) return
        openedAttachments.set(key, {
          url: URL.createObjectURL(file.source), name: file.name, type, size: file.size,
          ...(text !== undefined ? { text } : {}),
        })
      } catch (err) {
        // The reason and nothing else: an error here never carries the key.
        if (generation !== roomGeneration) return
        openedAttachments.set(key, { error: describeError(err) })
      }
      render()
    })
    card.append(button)
    if (opened && 'error' in opened) {
      const why = document.createElement('span')
      why.className = 'why'
      why.textContent = opened.error
      card.append(why)
    }
  }
  render()
  return card
}

/**
 * The lane indicator. In the composer it is a lock and a word; on each
 * message it is the lock alone, an image whose name is the lane and whose
 * tooltip says what that lane gives away. Never colour alone: the name and
 * the tooltip carry the fact, the colour is a second cue.
 */
function laneChip(lane: Lane, glyphOnly = false): HTMLSpanElement {
  const span = document.createElement('span')
  span.className = `chip lane ${lane}${glyphOnly ? ' glyph' : ''}`
  const label = lane === 'public' ? 'Encrypted · public relay' : lane === 'sheltered' ? 'Encrypted · circle relay' : 'Encrypted · direct'
  const meaning = 'Message content is encrypted for this conversation. ' + LANE_MEANING[lane]
  span.append(icon('lock'))
  if (glyphOnly) {
    span.setAttribute('role', 'img')
  } else {
    const words = document.createElement('span')
    words.className = 'laneWords'
    words.textContent = label
    span.append(words)
  }
  span.title = meaning
  // The short label only (M9): the fuller meaning stays in the tooltip and
  // in Room details, not repeated in every message's accessible name.
  span.setAttribute('aria-label', label)
  return span
}

/**
 * What lane the next message would take, beside the box people type into,
 * so the answer is there before they send rather than after. Read off the
 * relays the conversation writes to; nothing to show when it cannot say.
 */
function renderLaneNote(): void {
  const note = $('laneNote')
  const lane = activeChat()?.sendLane()
  note.replaceChildren()
  if (!lane && !quietTransport) { note.hidden = true; return }
  note.hidden = false
  if (lane) {
    note.append(laneChip(lane))
    note.title = LANE_MEANING[lane]
  }
  if (quietTransport) note.append(quietChip(quietTransport.canSend))
}

/** The lane chip says where the bytes went; this one says what they give
 *  away. A quiet room's chat is one wrap a slot to a key the relay never
 *  sees again, so the relay cannot tell whether anything was said. */
function quietChip(canSend: boolean): HTMLSpanElement {
  const span = document.createElement('span')
  span.className = 'chip quiet'
  span.textContent = canSend ? '◌ quiet' : '◌ quiet, reading only'
  span.title = canSend ? QUIET_MEANING : `${QUIET_MEANING} ${QUIET_READ_ONLY}`
  span.setAttribute('aria-label', span.title)
  return span
}

const QUIET_MEANING = `Quiet room. Messages ride the gift-wrap stream as dead drops, one every ${slotWords()} at most, and a relay cannot tell whether anything was said, by whom, or when.`
const QUIET_READ_ONLY = 'This device reads and cannot post: two devices per person can, the one holding the identity and the one it paired.'

function renderChat(messages: ChatMessage[]): void {
  // A message on screen no longer needs its pending row.
  if (pendingSends.pending) void pendingSends.arrived(messages.map(message => message.id)).catch(() => setStatus('The message arrived, but this browser could not save its outbox state.'))
  outbox.render()
  renderLaneNote()
  // Minutes are written in paragraphs with their line breaks doing the
  // structural work, so the one log has to know which conversation it is
  // showing. See `#chatLog.minutes` in style.css.
  $('chatLog').classList.toggle('minutes', currentChannel === MINUTES_CHANNEL)
  renderLog('chatLog', undefined, messages, currentChannel === undefined ? systemLines : [])
  renderEmptyRoom()
  {
    const roster = session?.participants() ?? []
    const direct = dmPeer(roomPolicy, meParticipant) !== undefined
    const minutes = currentChannel === MINUTES_CHANNEL
    const reached: string[] = []
    const fromAgents: string[] = []
    for (const m of messages) {
      const cls = classifyMessage(m, meParticipant, roster, { direct, minutes })
      if (cls === null) continue
      reached.push(m.id)
      if (cls === 'agent') fromAgents.push(m.id)
    }
    callFocus.noteMessages(`${draftRoomKey()}|${currentChannel ?? ''}`, reached, fromAgents)
  }
  if (currentChannel === undefined) void handleInvites(messages)
  updateConversationSearch()
  if (currentChannel === undefined) noteChatRead(messages)
  markConversationRead()
  requestAnimationFrame(() => pageBackFromArchive(true))
}

/**
 * Step back through this device's archive: when the reader reaches the top
 * of the conversation, or when what is shown does not fill the log, as in a
 * room whose last word is older than the retention window. The log keeps
 * the reader's place while older messages arrive above it; see chat-scroll.ts.
 */
function pageBackFromArchive(onlyToFill = false): void {
  const log = currentChannel === undefined ? session?.chat : channelLogs.get(currentChannel)
  if (!log?.hasOlder) return
  const el = $('chatLog')
  if ($('roomArea').hidden || el.clientHeight === 0) return
  if (onlyToFill ? el.scrollHeight > el.clientHeight : el.scrollTop > 64) return
  void log.loadOlder()
}
$('chatLog').addEventListener('scroll', () => pageBackFromArchive(), { passive: true })

/**
 * Put back on the room's relays what they forgot and this device kept.
 *
 * Late, so it never competes with joining. Never a quiet room's chat, which
 * must not appear on a relay as bare room events; its rekeys ride in the
 * open like any room's, so they still count. Only the room's own pool is
 * written to. See `reseedRelays`.
 */
const RESEED_DELAY_MS = 5_000
function scheduleReseed(s: RoomSession, pool: ManagedRelayPool, quiet: boolean, authority: string | undefined): void {
  const archive = roomArchive
  if (!archive) return
  const alive = (): boolean => !pool.closed && (session === s || dockedCall?.session === s)
  setTimeout(() => {
    if (!alive()) return
    const since = nowSeconds() - CHAT_RETENTION_SECONDS
    const logs = [s.chat, ...[AGENT_CHANNEL, TRANSCRIPT_CHANNEL, MINUTES_CHANNEL, CONTROL_CHANNEL].map(name => s.channel(name))]
    const targets: ReseedTarget[] = [
      ...(quiet ? [] : logs.map(log => ({ kind: KINDS.CHAT, d: log.stream, since, limit: MAX_CHAT_MESSAGES }))),
      ...(authority ? [{ kind: KINDS.ROOM_REKEY, d: s.roomId, limit: 1_000, authors: [authority] }] : []),
    ]
    reseedRelays(pool, archive, targets, { alive })
      .then(report => { for (const [url, count] of report.reseeded) console.info(`room archive: returned ${count} event${count === 1 ? '' : 's'} to ${url}`) })
      .catch(error => console.warn('room archive reseed', error))
  }, RESEED_DELAY_MS)
}

function updateConversationSearch(): void {
  conversationSearch.update(conversationTabs().map(([channel, label]) => ({ channel, label, messages: conversationMessages(channel) })), currentChannel, message => {
    if (message.participant === meParticipant) return message.name ? `${message.name} (you)` : 'You'
    return shownAs(message.participant, message.name).name ?? message.participant.slice(0, 8)
  })
}

/**
 * Repaint whichever conversation is actually on screen.
 *
 * There is one log element and several conversations behind it, so anything
 * that repaints "the chat" has to say WHICH. Three callers did not: a new
 * message in the main chat, a profile arriving, and a system line all
 * redrew the log with the main chat whatever tab was selected. The tab
 * stayed lit, the words underneath it changed, and the box below carried on
 * writing to the conversation the person could no longer see. That is the
 * worst shape a bug can take in a room: you type into somewhere you are not
 * looking.
 *
 * Reads the already-open log rather than `activeChat`, which would open a
 * subscription as a side effect of a repaint.
 */
function repaintActiveChat(): void {
  const s = session
  if (!s) return
  const log = currentChannel === undefined ? s.chat : channelLogs.get(currentChannel)
  renderChat(log ? log.messages() : [])
}

// ---------------------------------------------------------------------------
// Channels
//
// Several conversations in one long-lived room. The mechanism was already
// here - a named channel takes its id and key from the room key by HKDF -
// and what was missing was discovery and a gate. The keeper publishes the
// list signed by the room's authority; this client believes that signature
// and nothing else, so typing a channel name into the chat creates nothing.
//
// The main chat is not in the list and never will be: it is the room, it
// has no name, and `deriveChannel` already spells that `undefined`.
// ---------------------------------------------------------------------------

/** The log currently shown by the composer. Named logs are followed when
 * the room announces them, so unread activity is visible before a click. */
function activeChat(): NonNullable<typeof session>['chat'] | undefined {
  const s = session
  if (!s) return undefined
  if (currentChannel === undefined) return s.chat
  return followNamedConversation(currentChannel)
}

function followNamedConversation(name: string): ReturnType<RoomSession['channel']> | undefined {
  if (!session) return undefined
  const owner = session
  let log = channelLogs.get(name)
  if (!log) {
    log = session.channel(name)
    channelLogs.set(name, log)
    channelCounts.set(name, log.messages().length)
    log.onChange(() => coalesceChatPaint(name, () => {
      if (session !== owner) return
      const messages = log!.messages()
      channelCounts.set(name, messages.length)
      if (currentChannel === name) renderChat(messages)
      renderChannels()
    }))
  }
  return log
}

/**
 * One repaint per burst, not one per message.
 *
 * A relay replays a room's history as a run of events, each in its own
 * websocket message, and each used to repaint the whole log: the log
 * cleared, every message rebuilt, the thread structure resolved, the
 * search index refreshed, notifications considered. Five hundred messages
 * of history was five hundred full repaints, which is the "ages loading
 * the chat" a person sees on opening a busy room or an agent's channel.
 * Now the listener records that a paint is owed and the last one in a
 * short window does it, reading the log's current messages when it runs.
 * A message typed live still lands inside the same window, which is under
 * a frame at 60 Hz.
 */
const CHAT_PAINT_COALESCE_MS = 40
const chatPaintTimers = new Map<string, { timer: ReturnType<typeof setTimeout>; paint: () => void }>()
function coalesceChatPaint(key: string, paint: () => void): void {
  const owed = chatPaintTimers.get(key)
  // The newest closure wins: a room switched inside the window hands in a
  // paint for the new log, and the old one's guard would have done nothing.
  if (owed) { owed.paint = paint; return }
  const entry = {
    paint,
    timer: setTimeout(() => {
      chatPaintTimers.delete(key)
      entry.paint()
    }, CHAT_PAINT_COALESCE_MS),
  }
  chatPaintTimers.set(key, entry)
}

function conversationStorageKey(): string {
  return `kithmoot.conversation.v1.${nostrSession?.pubkey ?? 'visitor'}.${currentRoomId()}`
}

function restoreConversation(): void {
  if (currentChannel !== undefined) return
  try {
    const name = sessionStorage.getItem(conversationStorageKey())
    if (name && (channelAvailable(name) || draftHasWork(drafts.get(name)))) selectChannel(name)
  } catch {
    // Storage may be unavailable; Chat remains a usable starting point.
  }
}

function selectChannel(name: string | undefined): void {
  messageActions.close(false)
  chatScroll.remember()
  captureDraft()
  try { sessionStorage.setItem(conversationStorageKey(), name ?? '') } catch { /* Optional tab preference. */ }
  currentChannel = name
  $('conversationHeading').textContent = conversationLabel(name)
  restoreDraft()
  delete $('channelClose').dataset.arm
  renderChannels()
  const log = activeChat()
  renderChat(log ? log.messages() : [])
  const input = $('chatInput')
  if (input instanceof HTMLTextAreaElement) {
    input.placeholder = name === undefined ? 'Say something' : `Say something in ${name}`
    growComposer(input)
  }
  // Asking an agent in belongs with the agents' conversation, and nowhere else.
  renderInvites()
  renderRoomWho()
  // You picked it: you are done with the sheet you picked it in.
  closeRoomSheet()
  markConversationRead()
  renderConversationNav()
  const nav = $('conversationNav')
  const selected = nav.querySelector<HTMLElement>('[aria-pressed="true"]')
  if (selected) {
    const tab = selected.getBoundingClientRect()
    const bounds = nav.getBoundingClientRect()
    if (tab.left < bounds.left) nav.scrollLeft -= bounds.left - tab.left
    else if (tab.right > bounds.right) nav.scrollLeft += tab.right - bounds.right
  }
  // Chromium resets a revealed textarea's selection after this click has
  // finished. Restore it on the next frame, unless the reader moved on.
  if (input instanceof HTMLTextAreaElement && !$('chatForm').hidden) {
    const draft = drafts.get(currentChannel)
    const { text, selectionStart, selectionEnd, selectionDirection } = draft
    requestAnimationFrame(() => {
      if (currentChannel !== name || input.value !== text || document.activeElement === input) return
      const focused = document.activeElement
      input.setSelectionRange(selectionStart, selectionEnd, selectionDirection)
      // WebKit focuses a textarea when restoring its selection. A catch-up
      // action has already put focus in the log; keep that deliberate choice.
      if (focused instanceof HTMLElement && document.activeElement === input) focused.focus({ preventScroll: true })
    })
  }
}

function channelAvailable(name: string | undefined): boolean {
  if (roomUsesBothy) return name === undefined
  return name === undefined || [AGENT_CHANNEL, TRANSCRIPT_CHANNEL, MINUTES_CHANNEL].includes(name) || channels.includes(name)
}

function captureDraft(): ConversationDraft {
  const draft = drafts.get(currentChannel)
  const input = $('chatInput') as HTMLTextAreaElement
  draft.text = input.value
  draft.selectionStart = input.selectionStart
  draft.selectionEnd = input.selectionEnd
  draft.selectionDirection = input.selectionDirection
  draft.event = ($('attachEvent') as HTMLInputElement).value
  draft.key = ($('attachKey') as HTMLInputElement).value
  return draft
}

function restoreDraft(): void {
  const draft = drafts.get(currentChannel)
  const input = $('chatInput') as HTMLTextAreaElement
  closeMentionPicker()
  input.value = draft.text
  showPasteSize()
  input.setSelectionRange(draft.selectionStart, draft.selectionEnd, draft.selectionDirection)
  growComposer(input)
  ;($('attachEvent') as HTMLInputElement).value = draft.event
  ;($('attachKey') as HTMLInputElement).value = draft.key
  renderStaged()
  $('attachStatus').textContent = draft.status
  renderComposerContext()
}

function renderDraftBadges(): void {
  for (const tab of document.querySelectorAll<HTMLButtonElement>('#channelBar button[data-channel], #conversationNav button[data-channel]')) {
    const name = tab.dataset.channel || undefined
    const draft = drafts.get(name)
    const badge = tab.querySelector<HTMLElement>('.draftBadge')!
    badge.textContent = !channelAvailable(name) ? 'Closed · Draft' : draft.job ? 'Adding files' : 'Draft'
    badge.hidden = !draftHasWork(draft)
  }
}

/** Async work may finish while another draft is on screen. Update its badge
 * without changing the current editor, attachment panel or keyboard focus. */
function draftChanged(draft: ConversationDraft): void {
  if (draft === drafts.get(currentChannel)) {
    renderStaged()
    $('attachStatus').textContent = draft.status
    renderComposer()
  }
  renderDraftBadges()
  renderWorkspace()
  if (pendingRecording) renderRecording()
}

/**
 * What each tab is for, in words that do not assume you already know.
 *
 * Every one of these used to be a paragraph inside a collapsed panel below
 * the chat, which is to say nobody read them. One sentence, on the tab it
 * is about, is worth four paragraphs nobody opens.
 */
function channelPurpose(name: string | undefined): string {
  if (name === undefined) {
    const me = meParticipant || currentParticipant()
    const peer = me ? dmPeer(roomPolicy, me) : undefined
    if (peer) return `Only you and ${dmPeerName(peer)} can read this.`
    return 'Everybody in this room can read this, and can write here too.'
  }
  if (name === AGENT_CHANNEL) {
    return (
      'The agents’ shared conversation. Messages appear here as they arrive. ' +
      'Everybody in this room can read and reply.'
    )
  }
  if (name === TRANSCRIPT_CHANNEL) {
    return (
      'If an agent was allowed to listen, what people said out loud is written down here. ' +
      'Nothing appears from anybody who has “Let agents hear me” switched off, and who said what is ' +
      'what the agent reckons, not proof.'
    )
  }
  if (name === MINUTES_CHANNEL) {
    const base = 'A short write-up of what a call came to: who was there, what was decided, who is doing what. '
    // The instruction is only true while something in the room answers it,
    // and it is printed only then. Typing !minutes into a room with no
    // scribe posted a plain message and produced nothing at all - no
    // minutes, no refusal, no error - and a person who follows a written
    // instruction and gets silence concludes they did it wrong.
    return minuteTakerHere()
      ? base + 'Type !minutes in the chat to ask for one now. Like the transcript it is one agent’s account, not proof.'
      : base +
          'Nothing in this room is writing them at the moment, so there is nobody to ask and nothing to type. ' +
          'Minutes are written by an agent somebody brings in; the Agents tab says who is here and how one is asked in. ' +
          'When one is, they would be that agent’s account, not proof.'
  }
  return `A separate conversation in this room called ${name}. Everybody here can read it.`
}

/**
 * Whether anything in this room writes the minutes.
 *
 * The browser cannot ask, so it goes on what it can actually see, and both
 * halves are evidence rather than a guess. Minutes already on the channel
 * mean something here has written them. Otherwise: an agent that listens,
 * running now, offered by a host that is still in the room - which is the
 * only kind of member that writes them.
 *
 * When this is false the Minutes tab says so instead of printing an
 * instruction, and a typed !minutes is answered on the spot.
 */
function minuteTakerHere(): boolean {
  if ((channelCounts.get(MINUTES_CHANNEL) ?? 0) > 0) return true
  const present = new Set(session?.participants().map((v) => v.participant) ?? [])
  for (const [host, catalogue] of catalogues) {
    if (!present.has(host)) continue
    for (const running of catalogue.running) {
      if (catalogue.agents.some((entry) => entry.id === running.id && entry.listens)) return true
    }
  }
  return false
}

/**
 * Whether a line of chat asks for the minutes.
 *
 * The same rule the scribe applies - `isMinutesRequest` in
 * src/node/scribe.ts - written again rather than imported, because that
 * module is a Node agent and has no business in a browser bundle. Kept
 * deliberately narrow: this only decides whether to answer a request that
 * nothing will pick up, so a miss costs the old silence and never a wrong
 * word about a request that was heard.
 */
function asksForMinutes(text: string): boolean {
  return (text.trim().split(/\s+/)[0] ?? '').toLowerCase() === '!minutes'
}

function conversationLabel(name: string | undefined): string {
  if (name === undefined) return 'Chat'
  if (name === AGENT_CHANNEL) return 'Agents'
  if (name === TRANSCRIPT_CHANNEL) return 'Transcript'
  if (name === MINUTES_CHANNEL) return 'Minutes'
  return name
}

function conversationTabs(): Array<[string | undefined, string]> {
  const names = new Set([AGENT_CHANNEL, TRANSCRIPT_CHANNEL, MINUTES_CHANNEL, ...channels])
  for (const draft of drafts.pending()) if (draft.channel !== undefined) names.add(draft.channel)
  return [[undefined, 'Chat'], ...Array.from(names, name => [name, conversationLabel(name)] as [string, string])]
}

function conversationMessages(name: string | undefined): ChatMessage[] {
  if (name !== undefined) return channelLogs.get(name)?.messages() ?? []
  // A room that is still joining has no chat yet, and the chats list beside
  // it counts unread on a timer, so a count taken then is nothing, not a throw.
  try { return session?.chat.messages() ?? [] } catch { return [] }
}

function unreadMessageIds(name: string | undefined): Set<string> {
  const read = conversationRead.get(name ?? '')
  const roster = session?.participants() ?? []
  const direct = dmPeer(roomPolicy, meParticipant) !== undefined
  const minutes = name === MINUTES_CHANNEL
  return new Set(Array.from(resolveConversation(conversationMessages(name)).byKey.values())
    .filter(message => !message.retracted && !read?.has(message.original.id) && reachesReader(message.original, meParticipant, roster, { direct, minutes }))
    .map(message => message.original.id))
}

function conversationUnread(name: string | undefined): number {
  return unreadMessageIds(name).size
}

/** The same unread messages as `unreadMessageIds`, split into what a
 *  person said and what an agent addressed to the viewer - see
 *  `classifyMessage` in `src/messages.ts` - for the two badges a
 *  conversation tab shows. */
function conversationUnreadSplit(name: string | undefined): UnreadSplit {
  const read = conversationRead.get(name ?? '')
  const roster = session?.participants() ?? []
  const direct = dmPeer(roomPolicy, meParticipant) !== undefined
  const minutes = name === MINUTES_CHANNEL
  let people = 0
  let agents = 0
  for (const message of resolveConversation(conversationMessages(name)).byKey.values()) {
    if (message.retracted || read?.has(message.original.id)) continue
    const cls = classifyMessage(message.original, meParticipant, roster, { direct, minutes })
    if (cls === 'person') people++
    else if (cls === 'agent') agents++
  }
  return { people, agents }
}

/** All unread conversations in the open room, including hidden call chat. */
function currentRoomUnreadSplit(): UnreadSplit {
  const total = { people: 0, agents: 0 }
  if (session) for (const [name] of conversationTabs()) {
    const split = conversationUnreadSplit(name)
    total.people += split.people
    total.agents += split.agents
  }
  return total
}

function nextUnreadConversation(): [string | undefined, string] | undefined {
  const tabs = conversationTabs()
  const index = tabs.findIndex(([name]) => name === currentChannel)
  return [...tabs.slice(index + 1), ...tabs.slice(0, index)].find(([name]) => conversationUnread(name) > 0)
}

/** A message behind a closed call-chat panel or a dialog has not been read. */
function canReadVisibleChat(): boolean {
  const log = $('chatLog')
  return !chatScroll.restoring && !(window.kithmootDesktop && !document.hasFocus())
    && !$('roomArea').hidden && document.visibilityState === 'visible'
    && log.getClientRects().length > 0 && log.clientHeight > 0
    && getComputedStyle(log).visibility === 'visible'
    && !document.querySelector('dialog[open], #messageActionPanel:popover-open')
    && log.scrollHeight - log.scrollTop - log.clientHeight < 48
}

function markConversationRead(): boolean {
  if (!canReadVisibleChat()) return false
  const key = currentChannel ?? ''
  const messages = conversationMessages(currentChannel)
  const previous = conversationRead.get(key)
  if (previous?.size === messages.length && messages.every(message => previous.has(message.id))) return false
  conversationRead.set(key, new Set(messages.map(message => message.id)))
  return true
}

/** Reading updates both the local badge and the position shared with other devices. */
function readVisibleConversation(): void {
  // A room can resize while admission is still establishing its chat log.
  if (joining) return
  const changed = markConversationRead()
  if (session && currentChannel === undefined) noteChatRead(session.chat.messages())
  if (changed) renderConversationNav()
}

/**
 * The tabs a room shows above its conversation: Chat, and the others only
 * once there is something in them. A room with no agent and no call was
 * showing Chat, Agents, Transcript and Minutes, three of them empty, to
 * everybody who walked in. Room details still lists every conversation.
 */
function navTabs(): Array<[string | undefined, string]> {
  const agentsHere = (session?.participants() ?? []).some(view => view.agent)
  const pending = new Set(Array.from(drafts.pending(), draft => draft.channel))
  return conversationTabs().filter(([name]) => {
    if (name === undefined || name === currentChannel || pending.has(name)) return true
    if ((channelCounts.get(name) ?? 0) > 0) return true
    // Agents: when one is here, or a host has said which could be asked in.
    if (name === AGENT_CHANNEL) return agentsHere || [...catalogues.values()].some(catalogue => catalogue.agents.length > 0)
    // A conversation somebody opened on purpose is shown even while empty.
    return name !== TRANSCRIPT_CHANNEL && name !== MINUTES_CHANNEL
  })
}

let renderedTabKey = ''
/** What this room's tasks come to, kept by the assignment panel and read by
 *  the Board tab. Starts empty so the tabs can draw before the panel exists. */
let assignmentSummary: BoardSummary = { total: 0, active: 0, needsYou: 0 }

/** The Board tab's state: undefined when this room has no board to open and
 *  none to make, else how many things on it wait for this person. A room has
 *  one when it holds tasks or a shared board; the first is "New task…" in the
 *  menu. */
function boardTab(): { needsYou: number } | undefined {
  if (!session) return undefined
  const shared = roomBoards.get(session)?.boards.length ?? 0
  // Only when there is something to show; the first task or board is made from
  // the ⋯ menu's New task….
  if (assignmentSummary.total === 0 && shared === 0) return undefined
  return { needsYou: assignmentSummary.needsYou }
}
/** A small unread badge, capped at "99+" so a busy agent channel does not
 *  smear the tab it sits in. Shared by every place that shows one, so a
 *  person's count and an agent's look and read the same way everywhere. */
function unreadBadge(className: string, count: number, label: string, opts: { standalone?: boolean } = {}): HTMLSpanElement {
  const badge = document.createElement('span')
  badge.className = className
  badge.textContent = count > 99 ? '99+' : String(count)
  badge.setAttribute('aria-label', label)
  // A plain `<span>` has no role that lets `aria-label` override its name,
  // so a screen reader announces only the digits inside a button's own
  // accessible name; standing alone, outside a labelled control, it needs
  // one that does, or the fuller label is never heard.
  if (opts.standalone) badge.setAttribute('role', 'img')
  return badge
}

function renderConversationNav(): void {
  renderWorkspace()
  renderedTabKey = navTabs().map(([name]) => name ?? '').join('\n')
  const next = nextUnreadConversation()
  $('nextUnread').hidden = !next
  $('nextUnread').textContent = next ? `Next unread: ${next[1]} (${conversationUnread(next[0])})` : ''
  $('nextUnread').title = $('nextUnread').textContent ?? ''
  const nav = $('conversationNav')
  const focused = document.activeElement as HTMLElement | null
  const focusedChannel = focused && nav.contains(focused) ? focused.closest<HTMLElement>('[data-channel]')?.dataset.channel : undefined
  const scroll = nav.scrollLeft
  nav.replaceChildren()
  const tabs = navTabs()
  const board = boardTab()
  nav.hidden = tabs.length + (board ? 1 : 0) < 2
  for (const [name, label] of tabs) {
    const button = document.createElement('button')
    button.type = 'button'
    button.dataset.channel = name ?? ''
    button.title = channelSummary(name)
    button.setAttribute('aria-pressed', String(name === currentChannel))
    button.append(label)
    const split = conversationUnreadSplit(name)
    if (split.people > 0) button.append(unreadBadge('conversationUnread', split.people, `${split.people} unread messages`))
    if (split.agents > 0) button.append(unreadBadge('conversationUnread agent', split.agents, `${split.agents} from agents`))
    const draft = document.createElement('span')
    draft.className = 'draftBadge'
    button.append(draft)
    button.addEventListener('click', () => selectChannel(name))
    nav.append(button)
  }
  if (board) {
    // The room's board opens over the conversation rather than beside it, so
    // this is a button that opens a dialog, not a tab that is selected.
    const button = document.createElement('button')
    button.type = 'button'
    button.dataset.board = 'true'
    button.setAttribute('aria-haspopup', 'dialog')
    button.setAttribute('aria-controls', 'boardsPanel')
    button.append('Board')
    if (board.needsYou > 0) {
      const badge = document.createElement('span')
      badge.className = 'conversationUnread'
      badge.setAttribute('aria-hidden', 'true')
      badge.textContent = String(board.needsYou)
      button.append(badge)
      button.setAttribute('aria-label', `Board, ${board.needsYou} need you`)
    }
    button.addEventListener('click', () => openRoomBoard(button))
    nav.append(button)
  }
  renderDraftBadges()
  nav.scrollLeft = scroll
  if (focusedChannel !== undefined) {
    Array.from(nav.querySelectorAll<HTMLButtonElement>('button')).find(button => button.dataset.channel === focusedChannel)?.focus({ preventScroll: true })
  } else if (focused?.dataset.board && nav.contains(focused)) {
    nav.querySelector<HTMLButtonElement>('button[data-board]')?.focus({ preventScroll: true })
  }
}

function renderChannels(): void {
  updateConversationSearch()
  const bar = $('channelBar')
  const focused = document.activeElement as HTMLElement | null
  const focusedChannel = focused && bar.contains(focused) ? focused.closest<HTMLButtonElement>('button[data-channel]')?.dataset.channel : undefined
  const s = session
  const tabs = conversationTabs()

  bar.hidden = !s
  bar.innerHTML = ''
  if (!bar.hidden) {
    for (const [name, label] of tabs) {
      const tab = document.createElement('button')
      tab.type = 'button'
      tab.dataset.channel = name ?? ''
      const on = currentChannel === name
      tab.setAttribute('aria-pressed', String(on))
      const heading = document.createElement('span')
      heading.className = 'channelName'
      heading.append(label)
      const draftBadge = document.createElement('span')
      draftBadge.className = 'draftBadge'
      heading.append(draftBadge)
      // A dot beside a conversation that has something in it. Nothing beside
      // one that does not, so an eye running down this list for the first
      // time goes to the places where somebody has actually said something.
      const said = name === undefined ? (session?.chat.messages().length ?? 0) : (channelCounts.get(name) ?? 0)
      if (said > 0) {
        const dot = document.createElement('span')
        dot.className = 'tabDot'
        dot.setAttribute('aria-label', 'has messages')
        heading.append(dot)
      }
      const desc = document.createElement('span')
      desc.className = 'channelDesc'
      desc.textContent = channelSummary(name)
      tab.append(heading, desc)
      tab.addEventListener('click', () => selectChannel(name))
      bar.append(tab)
    }
  }
  renderDraftBadges()
  if (focusedChannel !== undefined) {
    const replacement = Array.from(bar.querySelectorAll<HTMLButtonElement>('button[data-channel]')).find(button => button.dataset.channel === focusedChannel)
    ;(replacement ?? $('roomSheetClose')).focus({ preventScroll: true })
  }
  renderComposer()
  renderRoomWho()
  renderConversationNav()

  // Creating and closing a channel is structure, so it is an admin's to do
  // and the controls are absent rather than disabled for everybody else.
  //
  // And absent without a keeper, because there would be nobody to ask. The
  // list is signed by the room's authority, and the only process that holds
  // the authority key and stays in the room is its keeper - the browser that
  // opened the room holds that key too, but a second announcer would mean
  // two signed lists disagreeing, which is worse than not offering it. So
  // channels are a thing a room WITH a keeper has, which is the long-lived
  // room this is for; an ad-hoc call between two people has one
  // conversation and needs no tabs above it.
  const isAdmin = s !== undefined && admins.has(meParticipant) && keeperParticipant !== undefined
  $('channelNew').hidden = !isAdmin
  const close = $('channelClose')
  close.hidden = !isAdmin || currentChannel === undefined || !channelAvailable(currentChannel)
  if (!close.hidden && close.dataset.arm !== currentChannel) close.textContent = `Close ${currentChannel}`
}

/** A few words for the list of conversations. The careful version is
 *  `channelPurpose`, said at the head of the conversation itself, where
 *  there is room for it and where somebody is actually reading. */
function channelSummary(name: string | undefined): string {
  if (name === undefined) return 'Everybody here can read and write.'
  if (name === AGENT_CHANNEL) return 'What the agents say to each other.'
  if (name === TRANSCRIPT_CHANNEL) return 'What was said out loud, written down.'
  if (name === MINUTES_CHANNEL) return 'A write-up of what a call came to.'
  return 'Another conversation in this room.'
}

/**
 * The note at the head of a conversation: what this one is for, and whether
 * anything has been said in it.
 *
 * "Nothing here yet" is the sentence that makes an always-listed
 * conversation honest. Without it an empty Agents channel looks like
 * something that failed to load, and a person who has never used the app has
 * no way to tell the difference between "quiet" and "broken".
 */
function introLines(): DocumentFragment {
  const run = document.createDocumentFragment()
  const name = currentChannel

  // The room's own note first, and only in the room's own conversation: it
  // is about who is here, not about this channel.
  const agents = agentsSentence(name === undefined ? (session?.participants() ?? []).filter((v) => v.agent).length : 0)
  if (agents) {
    const p = document.createElement('p')
    p.className = 'system intro'
    p.append(agents)
    run.append(p)
  }

  const said = name === undefined ? (session?.chat.messages().length ?? 0) : (channelCounts.get(name) ?? 0)
  const empty =
    name === undefined
      ? ' Write a message below to start the conversation.'
      : ' Nothing has been said here yet.'
  const p = document.createElement('p')
  p.className = 'system intro'
  p.textContent = channelPurpose(name) + (said === 0 ? empty : '')
  run.append(p)
  return run
}

/** The two conversations nobody types into. Both are an agent writing
 *  something down, and a box under them said otherwise. */
const WRITTEN_BY_AGENTS: readonly string[] = [TRANSCRIPT_CHANNEL, MINUTES_CHANNEL]

/**
 * The box to write in, and whether this conversation has one.
 *
 * A record of what was said aloud, with a box under it offering to let you
 * type into the record, undermines the one claim the tab makes about
 * itself. So on those two the box goes and a line says where to write
 * instead - which is also the answer to "I typed in here and nothing
 * happened".
 */
function renderComposer(): void {
  const readOnly = currentChannel !== undefined && WRITTEN_BY_AGENTS.includes(currentChannel)
  const closed = !channelAvailable(currentChannel)
  const draft = drafts.get(currentChannel)
  $('chatForm').hidden = readOnly
  ;($('chatInput') as HTMLTextAreaElement).readOnly = closed
  ;($('emojiToggle') as HTMLButtonElement).disabled = readOnly || closed
  if (readOnly || closed) chatArtPicker.close()
  ;($('attachToggle') as HTMLButtonElement).disabled = closed
  ;($('chatForm').querySelector('button[type=submit]') as HTMLButtonElement).disabled = readOnly || closed || Boolean(draft.job) || Boolean(draft.pendingFiles?.length)
  $('attachStaged').hidden = readOnly
  $('attachPanel').hidden = readOnly || !draft.panelOpen
  const waiting = draft.pendingFiles ?? []
  $('pendingFileNames').hidden = !waiting.length
  $('pendingFileNames').textContent = waiting.length ? `On this device, not uploaded: ${waiting.map(file => file.name).join(', ')}` : ''
  $('pendingFileActions').hidden = !waiting.length
  ;($('uploadPendingFiles') as HTMLButtonElement).disabled = Boolean(draft.job) || closed || !blossomServer()
  ;($('clearPendingFiles') as HTMLButtonElement).disabled = Boolean(draft.job)

  for (const id of ['attachFile', 'attachAdd', 'attachEvent', 'attachKey']) {
    ;($(id) as HTMLInputElement | HTMLButtonElement).disabled = closed || Boolean(draft.job)
  }
  $('cancelFileWork').hidden = !draft.job
  const discard = $('discardDraft') as HTMLButtonElement
  discard.hidden = !draftHasWork(draft)
  $('draftHelp').hidden = drafts.pending().length === 0
  const note = $('readOnlyNote')
  note.hidden = !readOnly && !closed
  if (closed) {
    note.textContent = 'This conversation is closed. Your draft stays here for you to copy. You can discard it from Room details.'
    return
  }
  if (!readOnly) return
  note.textContent =
    currentChannel === MINUTES_CHANNEL
      ? 'Nothing is typed here. Minutes are written by an agent; the Chat tab is where you say something to the room.'
      : 'Nothing is typed here. This is written down by an agent as people speak; the Chat tab is where you say something to the room.'
}

/** Ask the keeper to open or close one. A request, not an announcement:
 *  what the room believes is the signed list that comes back. */
async function requestChannel(name: string, open: boolean): Promise<void> {
  const s = session
  if (!s) return
  try {
    await s.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'channel', name, open }))
  } catch (err) {
    setStatus(describeError(err))
  }
}

// ---------------------------------------------------------------------------
// When something was said
//
// There was no time on anything. A person reading a room they had just been
// let into could not tell a conversation from ten minutes ago from one from
// three weeks ago, which is the first thing anybody wants to know and the
// thing that decides whether to expect an answer.
//
// The form changes with the age, because the question does. Inside the hour
// what matters is how long ago; today, the clock; this week, which day;
// older than that, the date. The exact moment is always on the element's
// title for anybody who wants it.
// ---------------------------------------------------------------------------

const CLOCK = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' })
const WEEKDAY = new Intl.DateTimeFormat(undefined, { weekday: 'short' })
const DATE_SHORT = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' })
const DATE_YEAR = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric' })
const DATE_FULL = new Intl.DateTimeFormat(undefined, { dateStyle: 'full', timeStyle: 'short' })

const DAY_MS = 86_400_000

function sameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

/** `sentAt` is the sender's own clock in seconds, so a message can arrive
 *  dated slightly ahead of ours. Anything not yet past reads as just now
 *  rather than as a negative age. */
function whenWords(at: number, now: number = Date.now()): string {
  const then = new Date(at * 1000)
  const seconds = Math.round((now - then.getTime()) / 1000)
  if (seconds < 45) return 'just now'
  if (seconds < 3600) {
    const minutes = Math.max(1, Math.round(seconds / 60))
    return `${minutes} minute${minutes === 1 ? '' : 's'} ago`
  }
  const today = new Date(now)
  if (sameDay(then, today)) return CLOCK.format(then)
  if (sameDay(then, new Date(now - DAY_MS))) return `yesterday ${CLOCK.format(then)}`
  if (now - then.getTime() < 7 * DAY_MS) return `${WEEKDAY.format(then)} ${CLOCK.format(then)}`
  return then.getFullYear() === today.getFullYear() ? DATE_SHORT.format(then) : DATE_YEAR.format(then)
}

function messageWhen(at: number, now: number = Date.now()): string {
  const moment = new Date(at * 1000)
  const today = new Date(now)
  if (sameDay(moment, today)) return CLOCK.format(moment)
  const date = moment.getFullYear() === today.getFullYear() ? DATE_SHORT : DATE_YEAR
  return `${date.format(moment)} · ${CLOCK.format(moment)}`
}

function timeChip(at: number, exact = false): HTMLTimeElement {
  const el = document.createElement('time')
  el.className = 'when'
  const moment = new Date(at * 1000)
  el.dateTime = moment.toISOString()
  // Kept on the element so the once-a-minute pass can rewrite the words
  // without the log being rebuilt.
  el.dataset.at = String(at)
  el.dataset.exact = String(exact)
  el.textContent = exact ? messageWhen(at) : whenWords(at)
  el.title = DATE_FULL.format(moment)
  el.setAttribute('aria-label', DATE_FULL.format(moment))
  return el
}

/** "3 minutes ago" stops being true three minutes later. Only the words in
 *  the time elements already on screen are rewritten; nothing else moves. */
setInterval(() => {
  const now = Date.now()
  for (const el of document.querySelectorAll<HTMLTimeElement>('time.when[data-at]')) {
    const at = Number(el.dataset.at)
    if (Number.isFinite(at)) el.textContent = el.dataset.exact === 'true' ? messageWhen(at, now) : whenWords(at, now)
  }
}, 60_000)

// ---------------------------------------------------------------------------
// Mentions
//
// Saying somebody's name is how you address them, and for an agent it is
// what decides whether it answers at all. Who a message addresses is now on
// the wire (`ChatMessage.mentions`, see docs/messages.md), and one function,
// `mentionedBy` in src/messages.ts, reads it for the room and for every
// agent, so what the room SHOWS as addressed is exactly what an agent
// ANSWERS to. A message from before the field existed is read by name: an
// `@` before the name, or the name on its own as a whole word, without
// regard to case. What follows marks the names in the text either way, so a
// name still reads as a name in a room full of them.
//
// Bare names count deliberately: people were typing names here long before
// there was an @ to type, and the picker is there to make the good path
// easy rather than to make the old one fail.
// ---------------------------------------------------------------------------

/** The names this room knows: everybody on the roster right now, as they
 *  are actually shown - a profile name once one has arrived, not the
 *  announced name that got them in the door. Matches `myNames` below,
 *  which already prefers the shown name over the typed one. */
function rosterNames(): string[] {
  return (session?.participants() ?? []).map((v) => shownAs(v.participant, v.name).name?.trim() ?? '').filter((n) => n.length > 0)
}

/** What a message calls ME, so a mention of the reader can be marked as
 *  such. Both the name I typed and the one my profile carries. */
function myNames(): Set<string> {
  const mine = new Set<string>()
  const typed = joiningName()
  if (typed) mine.add(typed.toLowerCase())
  if (meParticipant) {
    const shown = shownAs(meParticipant).name
    if (shown) mine.add(shown.toLowerCase())
  }
  return mine
}

/**
 * A message's words: an http(s) URL as a real link, and the names in the
 * rest of it marked.
 *
 * A mention is set apart from ordinary words, and a mention of the reader
 * is set apart again - that is the one thing a person scans a busy room
 * for. Everything goes in through `textContent`; nothing here builds
 * markup out of somebody else's text.
 */
function appendWithMentions(into: HTMLElement, text: string, pattern: RegExp | undefined, mine: Set<string>): void {
  for (const token of splitLinks(text)) {
    if (token.kind === 'link') into.append(linkElement(token.url))
    else appendMentions(into, token.value, pattern, mine)
  }
}

/** A tappable, copyable link for a URL pasted into a message. Its visible
 *  text is the URL itself, so nothing is hidden behind different wording,
 *  and it opens in a new tab without handing the destination a reference
 *  back to this one. On a phone, an `a` is already exactly what steps aside
 *  from the bubble's hold-to-react gesture and its disabled callout menu -
 *  see the `a` exclusions in `reaction-hold.ts` and the `.reactableBubble a`
 *  rules in style.css - so a long press here gives the platform's own link
 *  menu instead of opening the reaction picker. */
function linkElement(url: string): HTMLAnchorElement {
  const a = document.createElement('a')
  a.href = url
  a.textContent = url
  a.target = '_blank'
  a.rel = 'noopener noreferrer'
  return a
}

function appendMentions(into: HTMLElement, text: string, pattern: RegExp | undefined, mine: Set<string>): void {
  for (const segment of segmentMentions(text, pattern, mine)) {
    if (!segment.mention) { into.append(segment.text); continue }
    const span = document.createElement('span')
    span.className = 'mention'
    if (segment.me) span.classList.add('me')
    span.textContent = segment.text
    into.append(span)
  }
}

/** Copy a message's exact text to the clipboard, for a phone where a
 *  bubble's own long-press is spoken for by the reaction picker and native
 *  text selection is off outside a link (see `.reactableBubble` in
 *  style.css). Falls back to a hidden textarea's `execCommand('copy')` the
 *  way `copyInput` above does for the invite link, for a browser that has
 *  no async clipboard API or refuses it here. */
async function copyMessageText(text: string): Promise<boolean> {
  let copied = false
  try {
    if (navigator.clipboard) { await navigator.clipboard.writeText(text); copied = true }
  } catch { /* Try the browser's selection-based copy below. */ }
  if (!copied) {
    const area = document.createElement('textarea')
    area.value = text
    area.style.position = 'fixed'
    area.style.opacity = '0'
    area.setAttribute('aria-hidden', 'true')
    document.body.append(area)
    area.focus()
    area.select()
    try { copied = document.execCommand('copy') } catch { /* Manual copying remains available. */ }
    area.remove()
  }
  setStatus(copied ? 'Message text copied.' : 'Could not copy automatically. Expand the message, then select and copy its text.', copied ? 'done' : 'problem')
  return copied
}

/**
 * One conversation into one element: the chat, the agents' channel, the
 * transcript. A transcript line names the speaker the transcriber claims,
 * beside a key exactly as a name is, and says who wrote it down.
 */
const expandedMessages = new Set<string>()

/** Latest message time already announced, per channel (`''` for the main
 *  chat). Lets `announceArrivals` tell a genuinely new message from a
 *  channel's history: the first render of a channel only records this
 *  high-water mark, and pagination that pulls in older messages never moves
 *  it forward, so neither reads out anything. */
const lastAnnouncedAt = new Map<string, number>()

/** Read new arrivals from others into `#chatArrivals`, a status region kept
 *  apart from `#chatLog` itself (see C10 in the 13 September accessibility
 *  pass): the log repaints in full on almost every change, and a screen
 *  reader watching the log as its own live region re-announces everything
 *  still on screen along with whatever is actually new. Your own messages
 *  are not announced - you just typed them. */
function announceArrivals(channelKey: string, conversation: { byKey: Map<string, ResolvedMessage> }): void {
  const previous = lastAnnouncedAt.get(channelKey)
  let latest = previous ?? 0
  const arrivals: string[] = []
  for (const r of conversation.byKey.values()) {
    const original = r.original
    if (original.sentAt > latest) latest = original.sentAt
    if (previous === undefined || original.sentAt <= previous) continue
    if (r.retracted || original.participant === meParticipant || r.shown.kind === 'transcript') continue
    const sender = shownAs(original.participant, original.name).name || 'Somebody'
    arrivals.push(`${sender}: ${r.shown.text.slice(0, 80)}`)
  }
  lastAnnouncedAt.set(channelKey, latest)
  if (!arrivals.length) return
  const region = $('chatArrivals')
  region.textContent = ''
  // A screen reader treats identical text as no change; the empty text set
  // first, and this set a tick later, makes the next arrival read out even
  // when it repeats the words of the one before it.
  requestAnimationFrame(() => { region.textContent = arrivals.join('; ') })
}

function renderLog(logId: string, countId: string | undefined, messages: ChatMessage[], system: SystemLine[] = []): void {
  const log = $(logId)
  // A receipt or roster update replaces the rows while someone may be
  // reading a reaction tooltip. Reopen that same message's details using
  // the new contents and anchor, after scroll restoration has finished.
  const openReaction = log.querySelector<HTMLElement>('.reactionDetails:popover-open')?.id
  let restoreReaction: (() => void) | undefined
  const unread = unreadMessageIds(currentChannel)
  const restoreScroll = chatScroll.before(currentChannel ?? '', unread, !!openReaction)
  log.innerHTML = ''
  // What this conversation is, at the top of it, the way a messaging app
  // puts the thing you should know once at the head of the thread.
  if (session) log.append(introLines())
  pruneOpenedAttachments(logId, messages)
  profiles.want(messages.flatMap((m) => (m.speaker ? [m.participant, m.speaker] : [m.participant])))

  const namesOfMine = myNames()
  const roster = session?.participants() ?? []
  // Cached by the exact set of names each pattern covers, because most
  // messages in a log share the same handful of participants: the whole
  // point of the comment this replaced still holds, just per message
  // rather than per log.
  const mentionPatterns = new Map<string, RegExp | undefined>()
  const mentionsFor = (message: Pick<ChatMessage, 'text' | 'mentions'>): RegExp | undefined => {
    const names = mentionedNames(message, roster, (p) => shownAs(p).name)
    const key = [...new Set(names)].sort().join('\0')
    if (!mentionPatterns.has(key)) mentionPatterns.set(key, mentionPattern(names))
    return mentionPatterns.get(key)
  }
  // The log as a person reads it rather than as the relay holds it: the
  // latest edit's words on each message, a retracted one shown as such,
  // replies under the message they answer. See `resolveConversation` and
  // docs/messages.md.
  const conversation = resolveConversation(messages)
  const requestStatuses = readAgentRequestStatuses(messages)
  const agentNames = new Map<string, string>()
  for (const message of messages) if (message.name) agentNames.set(message.participant, message.name)
  for (const view of roster) if (view.name) agentNames.set(view.participant, view.name)
  const writable = channelAvailable(currentChannel) && !(currentChannel && WRITTEN_BY_AGENTS.includes(currentChannel))

  // System lines sit in the log where they happened, and look like nothing
  // anybody sent: no name, no key, because nobody did.
  let nextSystem = 0
  const systemUpTo = (at: number): void => {
    // Strictly earlier, not "at or before". A line the page writes about a
    // message - the answer to a typed !minutes - is stamped in the same
    // second as the message itself, and `<=` put the answer above the
    // question.
    while (nextSystem < system.length && system[nextSystem]!.at < at) {
      const line = system[nextSystem]!
      const p = document.createElement('p')
      p.className = 'system'
      p.append(timeChip(line.at), line.text)
      if (line.room) {
        // "It is in your rooms" is an answer; the way there is a button.
        const room = line.room
        const open = document.createElement('button')
        open.type = 'button'
        open.className = 'quiet openRoom'
        open.textContent = 'Open it'
        open.setAttribute('aria-label', `Open ${knownRoomLabel(room)}`)
        open.addEventListener('click', () => switchRoom(room))
        p.append(' ', open)
      }
      log.append(p)
      nextSystem++
    }
  }

  const chip = (text: string, title: string, kind: string): HTMLSpanElement => {
    const span = document.createElement('span')
    span.className = `chip ${kind}`
    span.textContent = text
    span.title = title
    return span
  }

  const paint = (r: ResolvedMessage, into: HTMLElement, nested: boolean): void => {
    const m = r.shown
    const original = r.original
    if (!nested) systemUpTo(original.sentAt)

    // A transcript line is not a message somebody sent: it is a note of
    // what a microphone heard, written down by a third party. It keeps the
    // flat, italic form, because putting it in a speech bubble would claim
    // the speaker typed it.
    if (m.kind === 'transcript') {
      const p = document.createElement('p')
      p.className = 'transcript'
      p.dataset.messageId = original.id
      p.dataset.messageAuthor = original.participant
      const who = document.createElement('span')
      who.className = 'who'
      if (m.speaker) {
        const speakerName = session?.participants().find((v) => v.participant === m.speaker)?.name
        who.append(identityRun(shownAs(m.speaker, speakerName), m.speaker === meParticipant, false, false, true))
        who.append(' said: ')
      } else {
        who.append('somebody said: ')
      }
      const by = document.createElement('span')
      by.className = 'who'
      by.append(' · heard by ')
      by.append(identityRun(shownAs(m.participant, m.name), false, false, false, true))
      p.append(timeChip(original.sentAt, true), who)
      appendWithMentions(p, m.text, mentionsFor(m), namesOfMine)
      p.append(by)
      for (const [i, a] of (m.attachments ?? []).entries()) p.append(attachmentCard(logId, m, i, a))
      p.append(artworkCards(m.artwork, (file, trigger) => attachmentViewer.open(file, trigger), m.text))
      into.append(p)
      return
    }

    const mine = original.participant === meParticipant
    const fromAgent = participantIsAgent(original.participant)
    const row = document.createElement('div')
    row.className = `msg ${mine ? 'mine' : 'theirs'}${fromAgent ? ' fromAgent' : ''}${r.retracted ? ' retracted' : ''}`
    row.dataset.messageId = original.id
    row.dataset.messageAuthor = original.participant
    row.dataset.sentAt = String(original.sentAt)
    row.dataset.senderGroup = JSON.stringify([original.participant, original.name, original.owner, original.ownerClaim, fromAgent, original.kind])
    const previous = into.lastElementChild as HTMLElement | null
    const previousAt = Number(previous?.dataset.sentAt)
    if (!r.retracted && previous?.classList.contains('msg') && !previous.classList.contains('retracted') &&
      previous.dataset.senderGroup === row.dataset.senderGroup && original.sentAt - previousAt >= 0 &&
      original.sentAt - previousAt < 5 * 60 && new Date(original.sentAt * 1000).toDateString() === new Date(previousAt * 1000).toDateString()) row.classList.add('continuation')
    // Addressed to the reader, by the field on the wire or by name on a
    // message from before the field existed: the one thing a person scans
    // a busy room for, and exactly what an agent would answer to. Your own
    // message is not addressed to you, whatever names it says.
    if (!mine && !r.retracted && meParticipant && mentionedBy(m, meParticipant, roster)) row.classList.add('mentionsMe')

    // Who said it, above the bubble, the way every group chat does it.
    // Left-alignment says "not you"; in a room of six it does not say WHO,
    // and this is the same name-and-key run the tiles use - a line of chat
    // is exactly where a name alone would be most convincing and least
    // checkable, so the short pubkey comes with it. The name on the message
    // is the sender's own claim, carried with it (see ChatMessage.name).
    const header = document.createElement('div')
    header.className = 'messageHeader'
    {
      const sender = document.createElement('div')
      sender.className = 'sender'
      const shown = shownAs(original.participant, original.name)
      const person = document.createElement('button'); person.type = 'button'; person.className = 'messagePerson'
      person.setAttribute('aria-label', `View details for ${shown.name ?? shown.short}`)
      person.setAttribute('aria-haspopup', 'dialog'); person.append(identityRun(shown, mine, true, false, true))
      // Your own name is not drawn above your bubble; the button stays in the page
      // for a screen reader and is not a tab stop nobody can see.
      if (mine) person.tabIndex = -1
      person.onclick = () => {
        const current = session?.participants().find(view => view.participant === original.participant)
        const me = meParticipant
        const permitted = current && me && current.participant !== me && !dmPeer(roomPolicy, me) &&
          (!current.agent || current.owner?.principal === me || admins.has(me))
        participantCard.open(shownAs(original.participant, original.name), person,
          permitted ? () => { void startDirectMessage(original.participant, shown.name, false) } : undefined)
      }
      sender.append(person)
      // The tag, in the same place and the same colour as on the roster, so
      // a bubble from a program is recognisable without reading a word.
      if (fromAgent) {
        const badge = document.createElement('span')
        badge.className = 'badge agent'
        badge.textContent = 'Agent'
        badge.title = 'An agent, not a person'
        sender.append(badge)
      }
      // Whose agent wrote this, from the proof carried on the message and
      // verified as at its send time - see ChatMessage.owner.
      if (original.owner) sender.append(ownerRun(original.owner))
      else if (original.ownerClaim) sender.append(ownerClaimRun(original.ownerClaim))
      header.append(sender)
    }
    if (r.edited && !r.retracted) {
      header.append(chip('edited', `Edited${r.edits.length > 1 ? ` ${r.edits.length} times` : ''}. Earlier versions are kept on every device that received them.`, 'edited'))
    }
    if (r.orphan) header.append(chip('in a thread', 'Part of a thread whose first message is not loaded here.', 'orphan'))
    if (nested && r.reply && r.thread && !sameRef(r.reply, r.thread)) {
      const target = conversation.byKey.get(refKey(r.reply))
      header.append(chip(`replying to ${target ? senderLabel(target.original) : personLabel(r.reply.participant)}`, 'Answers a message further up this thread.', 'replyTo'))
    }
    row.append(header)

    const body = document.createElement('div')
    body.className = 'messageBody'
    const bubble = document.createElement('div')
    bubble.className = 'bubble'
    const text = document.createElement('span')
    text.className = 'text'
    if (r.retracted) {
      // A placeholder rather than nothing: something was said here, and a
      // gap where a message was is a thing people argue about. Cooperative,
      // and the title says so.
      text.textContent = 'Message retracted'
      bubble.title = 'Retracted by its author. Every device that already received it still holds it, and the relays hold it encrypted; it is marked, not erased.'
      bubble.append(text)
      row.append(bubble)
      into.append(row)
      if (!nested && r.replies.length) paintThread(r, into)
      return
    }
    // textContent, never innerHTML: this is somebody else's text. The line
    // breaks in it are kept - the box people type into makes them now - and
    // the names in it are marked. Yours too, except in your own message:
    // saying your own name is not being addressed.
    const expansionKey = `${currentRoomId()}:${logId}:${m.participant}:${m.id}`
    const messageText = artworkMessageText(m.text, m.artwork)
    const long = messageText.length > 700 || messageText.split('\n').length > 12
    const paintText = () => {
      text.replaceChildren()
      const shown = long && !expandedMessages.has(expansionKey) ? messageText.slice(0, 600).replace(/[\uD800-\uDBFF]$/, '') + '…' : messageText
      appendWithMentions(text, shown, mentionsFor(m), mine ? new Set<string>() : namesOfMine)
      paintCustomEmoji(text)
      if (isCultEmoji(shown.trim()) || isOriginalEmoji(shown.trim())) text.classList.add('cultSticker')
    }
    paintText()
    text.hidden = !messageText
    bubble.append(text)
    if (long) {
      bubble.classList.add('longMessage')
      const tools = document.createElement('div'); tools.className = 'longMessageTools'
      const expand = document.createElement('button'); expand.type = 'button'
      const paintExpand = () => {
        expand.textContent = expandedMessages.has(expansionKey) ? 'Collapse' : 'Read more'
        expand.setAttribute('aria-expanded', String(expandedMessages.has(expansionKey)))
      }
      paintExpand()
      expand.onclick = event => {
        event.stopPropagation()
        if (expandedMessages.has(expansionKey)) expandedMessages.delete(expansionKey)
        else expandedMessages.add(expansionKey)
        paintText(); paintExpand()
      }
      const copy = document.createElement('button'); copy.type = 'button'; copy.textContent = 'Copy'
      copy.onclick = event => { event.stopPropagation(); void copyMessageText(m.text).then(ok => { copy.textContent = ok ? 'Copied' : 'Copy failed' }) }
      tools.append(expand, copy); bubble.append(tools)
    }
    for (const [i, a] of (m.attachments ?? []).entries()) bubble.append(attachmentCard(logId, m, i, a))
    bubble.append(artworkCards(m.artwork, (file, trigger) => attachmentViewer.open(file, trigger), m.text))
    // The time it was first said (an edit does not move a message) and the
    // lane it travelled, from where the bytes went and never from what the
    // message says about itself: the last line of the bubble, at the right.
    // The lane is a lock whose name and tooltip are the same everywhere.
    const meta = document.createElement('span')
    meta.className = 'messageMeta'
    meta.append(timeChip(original.sentAt, true))
    if (original.lane) meta.append(laneChip(original.lane, true))
    bubble.append(meta)
    body.append(bubble)
    row.append(body)
    if (mine && !m.reaction && !m.retracts) {
      const status = document.createElement('p')
      status.className = 'agentRequestStatus'
      const update = () => {
        const current = session?.participants() ?? []
        const agents: RequestAgent[] = [...agentParticipants].map(participant => ({
          participant,
          name: current.find(v => v.participant === participant)?.name ??
            agentDisplayNames.get(participant) ?? agentNames.get(participant),
          present: current.some(v => v.participant === participant),
          requestReceipts: receiptAgents.has(participant),
        }))
        const text = requestStatuses(original, agents, Date.now()).join(' ')
        if (status.textContent !== text) status.textContent = text
        status.hidden = !text
      }
      update()
      row.append(status)
      requestStatusUpdates.set(status, update)
    }
    const reactions = reactionsFor(messages, original)
    const react = (emoji: string): boolean => {
      const chat = activeChat() ?? session?.chat
      if (!chat || !meParticipant) return false
      try {
        const reaction = toggleReaction(chat.messages(), original, meParticipant, emoji)
        const text = reactionText(reaction)
        const prepared = chat.prepare(text, { reaction })
        void queueSend(prepared, currentChannel ?? 'Chat').then(() => {
        if (reaction.active) {
          const current = Array.from(log.querySelectorAll<HTMLElement>('[data-message-id]'))
            .find(row => row.dataset.messageId === original.id && row.dataset.messageAuthor === original.participant)
          const anchor = current?.querySelector<HTMLElement>('.bubble')
          if (anchor) showReactionFeedback(anchor, emoji)
        }
        }).catch(error => setStatus(describeError(error)))
        return true
      } catch (error) { setStatus(describeError(error)); return false }
    }
    if (writable) {
      bubble.classList.add('reactableBubble')
      const more = document.createElement('button')
      more.type = 'button'
      more.className = 'messageMore'
      more.append(icon('more'))
      more.dataset.tip = 'Reply, react and more'
      more.dataset.focusKey = 'message-actions'
      more.setAttribute('aria-label', `Actions for message from ${senderLabel(original)}`)
      more.setAttribute('aria-haspopup', 'dialog')
      more.setAttribute('aria-controls', 'messageActionPanel')
      more.setAttribute('aria-expanded', 'false')
      // What a message offers, once, for the panel behind its ⋯ and for the
      // menu a right-click opens: the same actions, the same handlers.
      const messageActionList = (): MessageAction[] => {
        const actions: MessageAction[] = [
          { label: `Reply to ${senderLabel(original)}`, text: 'Reply', run: () => setComposing({ replyTo: original }) },
          { label: 'Copy text', text: 'Copy text', run: () => { void copyMessageText(m.text) } },
          { label: 'Send as task', text: 'Send as task', run: () => assignmentPanel.offerMessage({ id: m.id, participant: m.participant, channel: currentChannel ?? 'chat' }, false) },
          { label: 'Summarise this', text: 'Summarise this', run: () => assignmentPanel.offerMessage({ id: m.id, participant: m.participant, channel: currentChannel ?? 'chat' }, true) },
        ]
        if (mine && !original.kind) actions.push(
          { label: 'Edit this message', text: 'Edit message', run: () => setComposing({ editing: original }, resolveConversation(activeChat()?.messages() ?? []).byKey.get(refKey({ messageId: original.id, participant: original.participant }))?.shown ?? m) },
          { label: 'Retract this message', text: 'Retract message', danger: true, run: () => { void retractMessage(original) } },
        )
        return actions
      }
      const reactionChoices = (anchor: HTMLElement): MessageAction[] => REACTION_EMOJIS.map<MessageAction>(base => {
        const emoji = preferredReaction(base)
        const mineToo = reactions.get(emoji)?.some(entry => entry.reaction!.active && entry.participant === meParticipant)
        return { label: `${mineToo ? 'Remove' : 'Add'} ${emoji} reaction`, text: emoji, pressed: mineToo, run: () => react(emoji) }
      }).concat([{ label: 'More emoji reactions', text: '+', pressed: false, run: () => chatArtPicker.openReaction(anchor, react) }])
      const openActions = (anchor: HTMLElement, reactionsOnly = false): void => {
        messageActions.open(anchor, reactionsOnly ? [] : messageActionList(), reactionChoices(anchor))
      }
      // Right-click (and the desktop's own context menu with it) opens the
      // app's menu where the pointer is: Reply, React, Copy text and the rest,
      // as the ⋯ offers them. Links, pictures and media keep the browser's
      // own menu, which is what they are for; a touch press is the hold that
      // already opens the reactions.
      bubble.addEventListener('contextmenu', event => {
        if ((event as PointerEvent).pointerType === 'touch' || (event.target as Element).closest('a[href], video, audio, img, canvas, input, textarea, select, [contenteditable="true"], .messageControls, .messageReactions')) return
        event.preventDefault()
        openMessageMenu(more, event.clientX, event.clientY, messageActionList(), reactionChoices(more), senderLabel(original))
      })
      more.addEventListener('click', () => openActions(more))
      const addReaction = document.createElement('button')
      addReaction.type = 'button'
      addReaction.className = 'messageReact'
      addReaction.append(icon('smile'))
      addReaction.dataset.tip = 'Add a reaction'
      addReaction.dataset.focusKey = 'add-reaction'
      addReaction.setAttribute('aria-label', `React to message from ${senderLabel(original)}`)
      addReaction.setAttribute('aria-haspopup', 'dialog')
      addReaction.setAttribute('aria-controls', 'messageActionPanel')
      addReaction.setAttribute('aria-expanded', 'false')
      // On touch React is not drawn (More is), and holding a bubble still opens
      // the reaction choices, anchored to the button that is.
      addReaction.addEventListener('click', () => openActions(addReaction.getClientRects().length ? addReaction : more, true))
      const controls = document.createElement('div')
      controls.className = 'messageControls'
      controls.append(addReaction, more)
      body.append(controls)
    }
    const reactionBar = document.createElement('div'); reactionBar.className = 'messageReactions'
    reactionBar.setAttribute('aria-label', 'Message reactions')
    for (const [emoji, updates] of reactions) {
      const entries = updates.filter(entry => entry.reaction!.active)
      if (!entries.length) continue
      const button = document.createElement('button'); button.type = 'button'
      const mineToo = entries.some(entry => entry.participant === meParticipant)
      button.append(emojiGlyph(emoji), document.createTextNode(` ${entries.length}`))
      button.dataset.focusKey = `reaction-${emoji}`
      button.setAttribute('aria-pressed', String(mineToo))
      button.setAttribute('aria-label', `${mineToo ? 'Remove' : 'Add'} ${emoji} reaction, ${entries.length}`)
      button.setAttribute('aria-disabled', String(!writable))
      button.addEventListener('click', () => {
        if (!writable || button.getAttribute('aria-disabled') === 'true') return
        button.setAttribute('aria-disabled', 'true')
        if (!react(emoji)) button.setAttribute('aria-disabled', 'false')
      })
      const chip = document.createElement('span')
      chip.className = 'reactionChip'
      const details = document.createElement('span')
      details.className = 'reactionDetails'
      details.popover = 'manual'
      details.id = `reaction-details-${original.participant}-${original.id}-${encodeURIComponent(emoji)}`
      details.setAttribute('role', 'tooltip')
      const heading = document.createElement('strong')
      heading.textContent = `${emoji} Reactions`
      details.append(heading)
      for (const entry of entries) {
        const shown = shownAs(entry.participant, entry.name)
        const person = document.createElement('span')
        person.className = 'reactionPerson'
        person.append(pictureOf(shown, true, 'Somebody')!)
        const info = document.createElement('span')
        info.className = 'reactionPersonInfo'
        const name = document.createElement('strong')
        name.textContent = `${shown.name ?? 'Somebody'}${entry.participant === meParticipant ? ' (you)' : ''}`
        info.append(name)
        if (shown.nip05) {
          const address = document.createElement('span')
          address.className = 'nip05'
          address.textContent = shown.nip05.startsWith('_@') ? shown.nip05.slice(2) : shown.nip05
          address.title = 'This domain maps the Nostr address to this public key.'
          info.append(address)
        }
        const timestamp = document.createElement('time')
        timestamp.dateTime = new Date(entry.sentAt * 1000).toISOString()
        const received = entry.reaction?.receipt === 'received'
        timestamp.textContent = `${received ? 'Received' : 'Reacted'} ${new Date(entry.sentAt * 1000).toLocaleString()}`
        info.append(timestamp)
        if (received) {
          const receipt = document.createElement('span')
          receipt.className = 'reactionReceipt'
          receipt.textContent = 'Room connection; reply may still be pending.'
          info.append(receipt)
        }
        person.append(info)
        details.append(person)
      }
      button.setAttribute('aria-describedby', details.id)
      let hideTimer: ReturnType<typeof setTimeout> | undefined
      const keepDetails = (): void => { clearTimeout(hideTimer) }
      const hideDetails = (): void => { keepDetails(); if (details.matches(':popover-open')) details.hidePopover() }
      const queueHideDetails = (): void => { keepDetails(); hideTimer = setTimeout(hideDetails, 150) }
      const showDetails = (): void => {
        if (dismissedReaction === details.id) return
        keepDetails()
        // Top layer: a long list of names must not be clipped by the chat log.
        document.querySelectorAll<HTMLElement>('.reactionDetails:popover-open').forEach(other => { if (other !== details) other.hidePopover() })
        details.showPopover()
        positionReactionDetails(details)
      }
      button.addEventListener('pointerenter', showDetails)
      button.addEventListener('pointerleave', queueHideDetails)
      details.addEventListener('pointerenter', keepDetails)
      details.addEventListener('pointerleave', queueHideDetails)
      button.addEventListener('focus', showDetails)
      button.addEventListener('blur', hideDetails)
      if (details.id === openReaction) restoreReaction = showDetails
      chip.append(button, details)
      reactionBar.append(chip)
    }
    if (reactionBar.childElementCount) row.append(reactionBar)
    into.append(row)
    if (!nested && r.replies.length) paintThread(r, into)
  }

  // Replies sit under their root, indented and ruled, in time order. One
  // level: a reply to a reply still sits in the same thread and says which
  // message it answers in a chip, which is how Slack shows the same thing.
  const paintThread = (root: ResolvedMessage, into: HTMLElement): void => {
    const thread = document.createElement('div')
    thread.className = 'thread'
    thread.setAttribute('role', 'group')
    thread.setAttribute('aria-label', `${root.replies.length} ${root.replies.length === 1 ? 'reply' : 'replies'}`)
    for (const reply of root.replies) paint(reply, thread, true)
    into.append(thread)
  }

  for (const r of conversation.stream) paint(r, log, false)
  systemUpTo(Number.POSITIVE_INFINITY)
  if (countId) $(countId).textContent = conversation.byKey.size ? `(${conversation.byKey.size})` : ''
  restoreScroll()
  messageActions.refresh()
  restoreReaction?.()
  if (logId === 'chatLog') announceArrivals(currentChannel ?? '', conversation)
}

/**
 * Every remote video element, live or not, with what it takes to decide
 * which of those it currently is.
 *
 * Kept here rather than looked up in the DOM because a renegotiation hands
 * the same track over again and `ontrack` fires afresh: a DOM lookup finds
 * nothing for an element that has been taken off screen, so it builds a new
 * one and puts the stale picture back.
 */
interface RemoteVideo {
  el: HTMLVideoElement
  container: HTMLDivElement
  track: MediaStreamTrack
  /** `currentTime` at the last check - a picture that is moving is live. */
  last: number
  /** Consecutive checks with no new frame. */
  stalled: number
  /**
   * Whether this picture has ever moved.
   *
   * A picture that has not started is not a picture that has stopped, and
   * the two must not be treated alike. `ontrack` fires when the answer is
   * applied, which is seconds before the first frame is decoded on any real
   * link - DTLS, SRTP and a keyframe all still to come. Judging a
   * just-arrived element by the stall rule gave it about three seconds to
   * produce a frame or be taken off screen, and taking it off screen was
   * what stopped its clock for good (see `parkPicture`). On a slow link, or a
   * machine busy encoding its own blurred camera, that is how a room where
   * everything negotiated perfectly ended up with nobody visible in it.
   */
  played: boolean
  /** When this picture was first seen frozen while its packets kept
   *  arriving, so the wait for it to come back on its own is bounded. See
   *  `FROZEN_REBIND_MS`. */
  frozenSince?: number
}

const remoteVideos = new Map<string, RemoteVideo>()
/** Fixed profile-2 role learned from ontrack; receiver ids are not role identity. */
const fixedRemoteRoles = new WeakMap<MediaStreamTrack, TrackAdvert['role']>()

/** Follow the advertised screen role across a track replacement or reconnect. */
function screenSource(participant: string, device: string, owner = mediaSession(), origin = callOrigin(owner), lastName?: string): ShareSource | undefined {
  // A viewer may survive navigation, but never follow another call or a
  // same-named participant in the conversation being read.
  if (!owner || owner !== mediaSession() || !origin) return undefined
  if (origin.callId && origin.callId !== owner.call?.id) return undefined
  const person = owner.participants().find(view => view.participant === participant && view.devices.includes(device))
  const advert = person?.tracks.find(track => track.device === device && track.role === 'screen')
  const local = participant === mediaMe() && device === myDeviceId
  let track = local
    ? screenTrack : advert ? remoteVideos.get(tileKey(device, 'screen'))?.track : undefined
  // The advert says a screen is on and a picture from that device is
  // playing in another slot: the binding had not caught up when the tile
  // was built. Any live video from the device that is not its camera is
  // the share, and "Expand" must not be missing while the picture is
  // plainly there.
  if (!track && advert && device !== myDeviceId) {
    for (const [key, entry] of remoteVideos) {
      if (tileDevice(key) !== device || entry.track.readyState !== 'live') continue
      if ((fixedRemoteRoles.get(entry.track) ?? tileRole(key)) !== 'screen') continue
      track = entry.track
      break
    }
  }
  if (track?.readyState !== 'live') track = undefined
  const name = shownAs(participant, person?.name).name ?? lastName ?? 'Somebody'
  const cameraAdvert = person?.tracks.some(track => track.device === device && track.role === 'camera')
  const camera = local ? cameraTrack : cameraAdvert ? remoteVideos.get(tileKey(device, 'camera'))?.track : undefined
  const status = !person || (origin.callId && (person.call?.id !== origin.callId || !person.call.devices.includes(device))) ? 'left'
    : !advert && !(local && screenTrack) ? 'ended' : track ? 'live' : 'reconnecting'
  return {
    id: advert?.trackId ?? track?.id ?? `${participant}:${device}:screen`, track: status === 'live' ? track : undefined,
    title: `${local ? 'Your screen' : `${name}’s screen`} · ${origin.roomName}${origin.projectName ? ` · ${origin.projectName}` : ''}`,
    owner: { participant, device, name }, origin, status,
    camera: camera?.readyState === 'live' ? camera : undefined,
    speaking: tileBoxes.get(participant)?.classList.contains('speaking') ?? false,
  }
}
/** `last` is the element's clock at the previous poll, exactly as a picture's
 *  is: a sound that is decoding is a sound whose packets are arriving, which
 *  is the RTP half of the liveness rule where the browser will not tell us
 *  about synchronisation sources. */
const remoteAudios = new Map<string, { el: HTMLAudioElement; track: MediaStreamTrack; last: number }>()

/**
 * The key our own microphone is tapped under.
 *
 * NOT `myDeviceId`. The mic can be switched on before joining - that is the
 * ordinary path, and the one the acceptance test drives - and `myDeviceId`
 * is empty until the join builds the device key. Keying the local tap on it
 * registered every pre-join microphone under `''`, so a person's own tile
 * never lit while everybody else's did. A constant cannot be too early, and
 * cannot collide with a device id, which is 64 hex characters.
 */
/**
 * The trust chip on somebody else's tile.
 *
 * Three states, and only one of them is an accusation:
 *
 *   new       never verified. Not a warning - most people are new, and
 *             colouring that as a problem teaches people to ignore it.
 *   verified  this exact key was verified on this device before.
 *   changed   a key you verified uses this name, and this is not it. This
 *             is the one that matters, and it is the shape the September
 *             incident took.
 *
 * Clicking it shows the words to say. See `src/verification.ts` for what
 * they do and do not prove - the panel says so too, because a verification
 * story that overclaims is worse than none.
 */
function verifyChip(view: ParticipantView, name: string, existing?: HTMLButtonElement): HTMLButtonElement {
  const chip = existing ?? document.createElement('button')
  chip.type = 'button'
  chip.className = 'verifyChip'
  // A tile can be painted while this device has no identity in the room on
  // screen: a docked call's tiles outlive the room they came from. With no
  // observer there is no record to read, and a chip is never worth a throw
  // that takes the rest of the paint with it.
  const observer = meParticipant
  const seen: ReturnType<typeof participantVerification> = /^[0-9a-f]{64}$/.test(observer)
    ? participantVerification(scopedVerificationStore(deviceStore, observer), view.participant, name)
    : { status: 'unknown' }
  const shown = contactCheckView(grantedContactView, view.participant, seen)
  chip.classList.add(shown.status)
  let label = shown.label
  chip.title = shown.title

  try {
    if (channelChecks?.list(view.participant).some(row => !row.state && !row.declined && row.request.expiresAt > Math.floor(Date.now() / 1000))) {
      label = 'check requested'
      chip.title = 'They asked to compare words. Open to accept or decline.'
    }
  } catch { /* Saved protocol failure is explained when the dialog opens. */ }
  if (chip.textContent !== label) chip.textContent = label
  chip.onclick = () => showVerification(view, name, seen.status)
  return chip
}

/**
 * The words, and the one button that means "yes, that is them".
 *
 * A real dialog rather than `confirm()`: the words have to be read carefully
 * and said out loud, and a browser alert with newlines in it is the wrong
 * furniture for the one security ritual this app has. `showModal` brings the
 * focus trap and Escape with it.
 */
let channelChecks: ChannelChecks | undefined
/** The session `channelChecks` was made for. A room's session is set before
 *  its join finishes and its checks after, so for a moment they disagree. */
let channelChecksSession: typeof session
function showVerification(view: ParticipantView, name: string, status: string): void {
  const current = session, checks = channelChecks
  if (!current || !checks || contactIsBlocked(view.participant)) return
  showChannelCheckDialog({ checks, peer: view.participant, name: name || short(view.participant) || view.participant, changed: status === 'key-changed',
    current: () => session === current && channelChecks === checks && !contactIsBlocked(view.participant),
    onCompared: () => {
      rememberVerified(scopedVerificationStore(deviceStore, current.participant), view.participant, name, Date.now())
      render(current.participants(), meParticipant)
    },
  })
}

const LOCAL_SPEAKING_KEY = 'self'

/**
 * Who is talking. Keyed by device, because that is what carries a track -
 * a person with two devices lights up when either of them speaks, which is
 * the same grouping rule the tiles already use.
 *
 * Repaints only the class on the affected tiles, never the room: `render()`
 * rebuilds every element it touches, and doing that twenty times a second
 * would throw away every `<video>` in the grid mid-frame.
 */
const speakingMonitor = new SpeakingMonitor({
  onChange: () => paintSpeaking(),
})

/** Applies the current speaking state to whichever tiles are on screen.
 *  Cheap enough to call on every change and on every render. */
function paintSpeaking(): void {
  // Nobody meeting mode keeps off the stage lights up, either.
  const speaking = new Set([...speakingMonitor.speaking()].filter(device => !meetingGated(device)))
  // Tiles and the controls pane's name chips alike: both carry the devices
  // they speak for, and both light from this rather than from a render.
  for (const box of document.querySelectorAll<HTMLElement>('[data-devices]')) {
    const devices = (box.dataset.devices ?? '').split(' ').filter(Boolean)
    box.classList.toggle('speaking', devices.some((d) => speaking.has(d)))
  }
  paintSpeakingLine()
}

/** How long a name stays on the "Speaking:" line after that person stops -
 *  long enough to smooth over the gaps inside ordinary speech, without
 *  leaving the line stuck on somebody who has clearly finished. */
const SPEAKING_LINE_HOLD_MS = 1000

/** When each name last spoke enough to be held on the line, keyed by
 *  participant. This device (`LOCAL_SPEAKING_KEY`) is never entered here -
 *  it is never shown on the line. Kept across calls to `paintSpeakingLine`
 *  so a name does not drop the instant its tile's own `speaking` class
 *  does. */
const speakingLineHeld = new Map<string, number>()
let speakingLineTimer: ReturnType<typeof setTimeout> | undefined

/**
 * The plain-text "Speaking: A, B" line beside the call controls.
 *
 * Built from the tiles' own `speaking` class, so it can never disagree with
 * the ring round a picture - and from their `data-name`, so it says exactly
 * what the tile's own label says. This device is never listed here: seeing
 * your own name on a line while you are talking is pointless, so the line
 * only ever names other people. Your own tile still gets its speaking ring,
 * so you can tell your mic is live; when you are the only one speaking the
 * line is empty, exactly as when nobody is.
 *
 * Not an aria-live region, and nothing here writes to one: the owner does
 * not want speakers announced over a screen reader. It is ordinary text
 * that a screen reader user can navigate to like any other line - see
 * `speakerAnnouncement` in call-stage.ts for the separate, opt-in spoken
 * version.
 */
function paintSpeakingLine(): void {
  const line = document.getElementById('speakingLine')
  if (!line) return
  const now = Date.now()
  for (const box of document.querySelectorAll<HTMLElement>('#room > .participant[data-devices]')) {
    if (!box.classList.contains('speaking')) continue
    if (box.dataset.self === 'true') continue // never held for the line - see doc comment above
    const key = box.dataset.participant
    if (key) speakingLineHeld.set(key, now + SPEAKING_LINE_HOLD_MS)
  }

  const names: string[] = []
  let soonest = Infinity
  for (const [key, until] of speakingLineHeld) {
    if (until <= now) { speakingLineHeld.delete(key); continue }
    soonest = Math.min(soonest, until)
    const box = document.querySelector<HTMLElement>(`#room > .participant[data-participant="${CSS.escape(key)}"]`)
    names.push(box?.dataset.name || 'Somebody')
  }

  const text = names.length ? `Speaking: ${names.join(', ')}` : ''
  if (line.textContent !== text) line.textContent = text
  if (line.hidden !== (names.length === 0)) line.hidden = names.length === 0

  // Nothing else repaints this line when a held name's time is up - a tile
  // that has gone quiet fires no event of its own - so a timer is set for
  // whichever name is due off soonest, and cleared and reset every time
  // this runs rather than left to stack up.
  if (speakingLineTimer !== undefined) { clearTimeout(speakingLineTimer); speakingLineTimer = undefined }
  if (soonest !== Infinity) speakingLineTimer = setTimeout(paintSpeakingLine, Math.max(50, soonest - now))
}

// ---------------------------------------------------------------------------
// Per-person volume
//
// One slider per PERSON, not per device - in this app the person is the
// member, and a phone and a laptop of the same person are one tile already
// (see `ParticipantView.devices`). It sets how loud that person is on this
// device only: nothing is published, and it never survives to another
// device of yours or to anybody else's screen. See remote-volume.ts for the
// gain path this routes through, and volume-store.ts for what is
// remembered between visits.
// ---------------------------------------------------------------------------

const remoteVolume = new RemoteVolume()

// ---------------------------------------------------------------------------
// The browser has paused the sound
//
// A device that has never had a gesture on this page - the update-and-rejoin
// path is the one that matters, but any future one counts too - gets muted
// video, which the autoplay policy allows, and remote audio that silently
// does not play. See app/src/autoplay-banner.ts for the decision; this is
// the browser half - the banner, and one tap resuming everything blocked.
// ---------------------------------------------------------------------------

const autoplayBanner = new AutoplayBannerState()

function renderAutoplayBanner(): void {
  $('autoplayBanner').hidden = !autoplayBanner.visible
}

function reportAutoplayBlock(error: unknown): void {
  const activation = (navigator as Navigator & { userActivation?: UserActivation }).userActivation
  // Not `onCall()`: that is whether this device pressed Join call, and a
  // person who has only walked into a room where a call is already on -
  // the auto-join path this banner exists for - never presses anything.
  // `session` here is "in the room at all"; `leftCall` is the one thing
  // that actually excuses this device from hearing it - see
  // shouldShowAutoplayBanner.
  const shown = autoplayBanner.blocked(error, { inRoom: session !== undefined, audioDeliberatelyMuted: !cachedMonitorHere || leftCall }, activation)
  if (shown) { callTimeline.record('autoplay-blocked'); renderAutoplayBanner() }
}

/** One tap resumes every remote `<audio>` this page has paused, and the two
 *  AudioContexts that can also be caught by the same policy: the gain path
 *  a loud slider opens in `RemoteVolume`, and the analyser behind the
 *  speaking indicator. Never the thing that leaves the banner up for a
 *  reason it cannot explain: a play() that still fails here shows the
 *  banner again, via the same `reportAutoplayBlock` path. */
function resumeBlockedAudio(): void {
  remoteVolume.resume()
  speakingMonitor.resume()
  for (const { el } of remoteAudios.values()) {
    if (!el.paused) continue
    void el.play().then(
      () => { autoplayBanner.resumed(); callTimeline.record('autoplay-resumed'); renderAutoplayBanner() },
      (err) => reportAutoplayBlock(err),
    )
  }
  // Nothing was paused - a track arriving just as this was pressed, say.
  // The tap still counts as a gesture and the banner still has no reason
  // left to be up.
  if ([...remoteAudios.values()].every(({ el }) => !el.paused)) { autoplayBanner.resumed(); callTimeline.record('autoplay-resumed'); renderAutoplayBanner() }
}

$('autoplayBannerButton').addEventListener('click', resumeBlockedAudio)

/** This device's own opinion of how loud each other participant is, from 0
 *  (silenced for this device) to 2 (200%). 1 is the untouched default and
 *  is never written to storage - see volume-store.ts. */
const volumeLevels = new Map<string, number>()

/** This browser's level for `participant`: the one a slider was left at
 *  this visit, else the one remembered from before, else 100%. */
function volumeLevel(participant: string): number {
  let level = volumeLevels.get(participant)
  if (level === undefined) {
    level = loadVolumeLevel(deviceStore, participant) ?? 1
    volumeLevels.set(participant, level)
  }
  return level
}

/** The one-speaker rule and Leave, as last computed by `render()` - read by
 *  the slider between renders so dragging it does not have to walk the
 *  roster again on every tick. */
let cachedMonitorHere = true
let cachedOwnDevices = new Set<string>()

/**
 * Routes `level` to every device of `view`'s that currently has live remote
 * audio, without rebuilding any UI. The slider's `input` listener calls
 * this on every tick so dragging stays smooth - replacing the element mid
 * drag would end the gesture - and `commitVolumeLevel` remembers the level
 * once it settles.
 */
function previewVolumeLevel(view: ParticipantView, level: number): void {
  volumeLevels.set(view.participant, level)
  for (const device of view.devices) {
    for (const [key, audio] of remoteAudios) {
      if (!key.startsWith(`${device}|`)) continue
      const muted = !cachedMonitorHere || leftCall || cachedOwnDevices.has(device) || meetingGated(device)
      remoteVolume.apply(key, audio.el, audio.track, level, muted)
    }
  }
  paintVolumeMute(view.participant, level === 0)
}

/** Remembers the level a slider was left at - see volume-store.ts. */
function commitVolumeLevel(participant: string): void {
  storeVolumeLevel(deviceStore, participant, volumeLevels.get(participant) ?? 1)
}

function volumeMuteBadge(): HTMLElement {
  const badge = document.createElement('span')
  badge.className = 'badge muted'
  badge.textContent = '\u{1F507} silenced for you'
  badge.title = 'Silenced for you'
  return badge
}

/** Whether the device currently holding this person's mic has muted itself
 *  - `TrackAdvert.muted`, not our own volume slider. Distinct state, distinct
 *  badge: this one is what THEY did, `volumeMuteBadge` is what WE did. */
function selfMutedMic(view: ParticipantView): boolean {
  const micDevice = view.mic
  if (!micDevice) return false
  return view.tracks.some((t) => t.role === 'mic' && t.device === micDevice && t.muted === true)
}

function selfMuteBadge(): HTMLElement {
  const badge = document.createElement('span')
  badge.className = 'badge muted-self'
  badge.textContent = '\u{1F3A4} muted'
  badge.title = 'This person has muted their own microphone'
  return badge
}

/** No microphone at all, which is a different thing again from a live one
 *  its owner has muted: there is no advert, so nothing is being sent. Worth
 *  saying on a name chip, where there is no track chip to read it from. */
function noMicBadge(): HTMLElement {
  const badge = document.createElement('span')
  badge.className = 'badge mic-off'
  badge.textContent = '\u{1F507} mic off'
  badge.title = 'Not sending any sound'
  return badge
}

/** Keeps a tile's "silenced for you" tag in step with the slider while it
 *  is being dragged, without waiting for the next full render. */
function paintVolumeMute(participant: string, silenced: boolean): void {
  const heading = tileBoxes.get(participant)?.querySelector('h3')
  if (!heading) return
  const existing = heading.querySelector<HTMLElement>('.badge.muted')
  if (silenced && !existing) heading.append(volumeMuteBadge())
  else if (!silenced && existing) existing.remove()
}

/**
 * Where a picture waits while it is off screen.
 *
 * Off everybody's screen, and never out of the document - which are not the
 * same thing, though the code this replaces assumed they were. Chromium runs
 * the internal pause steps on a media element the moment it leaves the
 * document, and a paused element's `currentTime` never advances again: not
 * while it is out, and not when it is put back. So "take it off screen and
 * put it back when it starts moving again" could never fire. Taking it off
 * screen was what stopped the clock it was being judged by, and a picture
 * that went off once was off for the rest of the call.
 *
 * Parked here it is at least still in the document, so nothing runs the
 * pause steps on it and the element survives to be put back. What it does
 * NOT reliably do is keep advancing: `display:none` takes it out of the
 * rendering tree, and a browser is free to stop feeding it there - measured
 * on 18 September 2026, a parked picture's clock stopped and never started
 * again. So the clock is not the way back. Arriving packets are, which is
 * read off the receiver and does not care where the element is - see
 * `trackReceivingRtp`.
 *
 * The holder is `display:none`: out of the room's layout and - the part that
 * matters - out of `#room .participant`, which is what "off everybody else's
 * screen" has to mean.
 */
function parkPicture(el: HTMLVideoElement): void {
  $('parked').append(el)
}

/**
 * Put a media element back where people can see or hear it, playing.
 *
 * Removing an element from the document runs the browser's pause steps, so
 * one that actually left has to be resumed. One that was only parked -
 * `display:none`, still in the document - was assumed not to need it, and
 * that assumption is not free: a paused element with packets arriving is
 * silent or still for as long as nobody asks it to play, and nothing else
 * here asks. `play()` on an element that is already playing is a no-op, so
 * the question to ask is simply whether it is paused.
 */
function restoreRemoteElement(el: HTMLMediaElement, container: HTMLElement): void {
  container.append(el)
  if (el instanceof HTMLVideoElement && el.hasAttribute('data-gallery-off-page')) return
  if (el.paused) void el.play().catch((err) => { if (el instanceof HTMLAudioElement) reportAutoplayBlock(err) })
}

/** Whether this picture is currently on screen, in its own device's tile. */
function onScreen(entry: RemoteVideo): boolean {
  return entry.el.parentElement === entry.container
}

/**
 * Take a picture off screen when it stops moving, and put it back when it
 * starts again.
 *
 * The obvious signal - the track's own `muted` flag - is not trustworthy
 * enough to hang this on. Measured in Chromium: a remote track can arrive
 * `muted`, decode and paint frames perfectly well, and never fire `unmute`
 * at all; gate the picture on that flag and a live participant is invisible.
 * The reverse happens too - a camera switched off before its first frame
 * leaves a track that was muted on arrival and never unmuted, so no `mute`
 * ever fires either and a frozen frame sits on everybody else's screen for
 * the rest of the call.
 *
 * Whether the picture is actually moving has neither problem, and it is also
 * the thing a person in the room is really asking. It only answers honestly
 * for an element that is still in the document, though - see `parkPicture`,
 * which is why one that goes off screen is parked rather than removed - and
 * only for one that has started at all, which is why `played` gates the
 * stall count rather than the clock doing it alone.
 */
/** The advert half of the liveness rule, and the counter behind it - see
 *  app/src/remote-tiles.ts, which owns both halves and is tested without a
 *  browser. */
const tileLiveness = new TileLiveness()

/**
 * Whether the roster still says this device is sending this role.
 *
 * The far end stopping a share or a camera removes the sender, and a
 * removed sender does NOT end the receiver's track in any browser - it
 * mutes it, which the stall rule cannot tell from a still picture, and a
 * muted screen share decodes nothing, so the element sat on everybody's
 * screen as a black box for the rest of the call. What the far end does
 * say, and says promptly, is its roster advert: `publishActiveTracks`
 * republishes the full set on every toggle.
 *
 * It is no longer the whole truth, though. A second tab of the same device
 * key publishes presence with no tracks at all, overwrites the entry, and
 * everybody took A's pictures down while A's packets were still arriving.
 * So this is one half of the rule and inbound RTP is the other, and a tile
 * comes down only when both agree. Undefined while the roster has nothing
 * to say about the device at all: a device between heartbeats is not a
 * device that has turned everything off.
 */
function advertised(key: string): boolean | undefined {
  const device = tileDevice(key), role = tileRole(key)
  const person = mediaSession()?.participants().find(view => view.devices.includes(device))
  if (!person) return undefined
  if (!role) return false
  return person.tracks.some(track => track.device === device && track.role === role)
}

/** Everything this device is advertising right now. */
function advertsFor(device: string): TrackAdvert[] {
  const person = mediaSession()?.participants().find(view => view.devices.includes(device))
  return person?.tracks.filter(track => track.device === device) ?? []
}

/** The remote device an `openConnections` key belongs to. */
function connectionDevice(key: string): string | undefined {
  return /^[^:]+:([0-9a-f]{64}):\d+$/.exec(key)?.[1]
}

/** When RTP was last seen moving on a track, on `performance.now()`'s clock. */
const trackProgressAt = new WeakMap<MediaStreamTrack, number>()
/** When RTP alone was last seen arriving, never written by a painted frame.
 *  See `trackReceivingRtp`. */
const rtpAt = new WeakMap<MediaStreamTrack, number>()
/** The newest synchronisation-source timestamp seen for a track, so the next
 *  look can tell "still arriving" from "the same packets as before". */
const rtpTimestamps = new WeakMap<MediaStreamTrack, number>()

/**
 * Note whether anything has arrived on this receiver since the last look.
 *
 * `getSynchronizationSources()` is synchronous, needs no `await` in a
 * one-second poll, and reports only sources heard from recently - so a
 * receiver whose sender the far end removed falls silent here within its
 * window while a live one keeps handing back a rising timestamp. Where a
 * browser does not fill it in for this kind, a playing element's own clock
 * says the same thing and `syncRemoteVideos` feeds that in instead.
 */
function noteRtp(receiver: RTCRtpReceiver, track: MediaStreamTrack, now: number): void {
  let latest = 0
  for (const source of receiver.getSynchronizationSources?.() ?? []) if (source.timestamp > latest) latest = source.timestamp
  if (latest === 0) return
  if (latest > (rtpTimestamps.get(track) ?? 0)) {
    trackProgressAt.set(track, now)
    // RTP only, kept apart from the store above, which a painted frame also
    // writes to. "Packets are arriving" and "a frame was painted recently"
    // are different questions, and the park rule needs the first one: read
    // off the second, a picture that had just stopped answered "yes" for the
    // whole grace window afterwards, and a decoder wedged with packets still
    // coming in answered "yes" for ever.
    rtpAt.set(track, now)
  }
  rtpTimestamps.set(track, latest)
}

/** Note that this track's media moved, however we came to know it. */
function noteProgress(track: MediaStreamTrack, now: number): void {
  trackProgressAt.set(track, now)
}

/** Whether media has moved on this track inside the liveness window. */
function trackProgressing(track: MediaStreamTrack, now: number): boolean {
  const at = trackProgressAt.get(track)
  return at !== undefined && now - at < RTP_GRACE_MS
}

/** Whether PACKETS have arrived on this track inside the liveness window,
 *  whatever the element on it has painted. */
function trackReceivingRtp(track: MediaStreamTrack, now: number): boolean {
  const at = rtpAt.get(track)
  return at !== undefined && now - at < RTP_GRACE_MS
}

/**
 * What this page is receiving from `device`, with the two facts the tile
 * mapping needs about each receiver: the transceiver direction, which is how
 * a stale receiver is told from a live one, and whether its packets are
 * moving, which is how two live-looking ones are told apart.
 */
function deviceReceivers(device: string, now: number): ReceiverFacts[] {
  const facts: ReceiverFacts[] = []
  for (const [key, pc] of openConnections) {
    if (pc.connectionState !== 'connected') continue
    if (connectionDevice(key) !== device) continue
    for (const transceiver of pc.getTransceivers()) {
      const track = transceiver.receiver?.track
      if (!track) continue
      noteRtp(transceiver.receiver, track, now)
      facts.push({ track, direction: transceiver.currentDirection, progressing: trackProgressing(track, now), role: fixedRemoteRoles.get(track) })
    }
  }
  return facts
}

/** What each tile of this kind is showing now, so a picture that is playing
 *  is never moved to another slot behind the viewer's back. */
function boundTracks(device: string, kind: MediaKind): Map<TrackAdvert['role'], MediaStreamTrack> {
  const bound = new Map<TrackAdvert['role'], MediaStreamTrack>()
  for (const role of ROLES_BY_KIND[kind]) {
    const entry = kind === 'video' ? remoteVideos.get(tileKey(device, role)) : remoteAudios.get(tileKey(device, role))
    if (entry) bound.set(role, entry.track)
  }
  return bound
}

/** Which tile this track belongs on, or nothing if every slot of its kind is
 *  already held by a receiver with a better claim. */
function tileKeyFor(device: string, track: MediaStreamTrack): string | undefined {
  const kind = kindOf(track.kind)
  const binding = bindRoles({
    kind,
    adverts: advertsFor(device),
    receivers: deviceReceivers(device, performance.now()),
    bound: boundTracks(device, kind),
    prefer: track,
  })
  for (const [role, chosen] of binding) if (chosen === track) return tileKey(device, role)
  return undefined
}

function syncRemoteVideos(): void {
  let changed = false
  const now = performance.now()
  // One look at every receiver first, so the RTP half of the liveness rule
  // is up to date for every tile before any of them is judged by it.
  for (const device of new Set([...remoteVideos.keys(), ...remoteAudios.keys()].map(tileDevice))) deviceReceivers(device, now)
  for (const [key, entry] of remoteVideos) {
    const clock = entry.el.currentTime
    const moving = clock > entry.last + 0.001
    entry.last = clock
    if (moving) {
      noteProgress(entry.track, now)
      // Keep a newly negotiated sink connected so it can decode, but do not
      // let its empty black rectangle take half of a grouped person's card.
      // The first painted frame makes it a picture and earns its place.
      if (entry.el.classList.contains('awaitingFrame')) { entry.el.classList.remove('awaitingFrame'); changed = true }
    }
    const progressedAt = trackProgressAt.get(entry.track)
    if (progressedAt !== undefined) tileLiveness.progressed(key, progressedAt)
    if (entry.track.readyState === 'ended' || tileLiveness.gone(key, advertised(key), now)) {
      if (onScreen(entry)) changed = true
      entry.el.remove()
      remoteVideos.delete(key)
      callTimeline.record('tile-orphaned', short(key.split('|')[0]), 'video')
      continue
    }
    // A manual gallery page hides only its video sink. Incoming packets,
    // call audio and independent popouts remain live; a paused off-page
    // clock must not be diagnosed as a broken decoder or rebound by recovery.
    if (entry.el.hasAttribute('data-gallery-off-page')) {
      entry.el.pause(); entry.stalled = 0; entry.frozenSince = undefined
      continue
    }
    // What to do about this picture is decided in app/src/remote-tiles.ts,
    // which owns the rule and is tested without a browser. Packets are read
    // off the receiver rather than off the element: a parked element's clock
    // stops, and so does a wedged decoder's while the packets keep coming.
    const { action, state } = judgePicture(
      { stalled: entry.stalled, played: entry.played, onScreen: onScreen(entry), frozenSince: entry.frozenSince },
      { moving, arriving: trackReceivingRtp(entry.track, now), visible: $('callStage').checkVisibility(), at: now },
    )
    entry.stalled = state.stalled
    entry.played = state.played
    entry.frozenSince = state.frozenSince
    if (action === 'restore' && !leftCall && !meetingGated(tileDevice(key))) {
      restoreRemoteElement(entry.el, entry.container)
      changed = true
    }
    if (action === 'park') {
      parkPicture(entry.el)
      changed = true
    }
    if (action === 'rebind') {
      // The same track, a new decoder. Cheap, and at worst it repeats every
      // fifteen seconds for as long as the picture stays frozen.
      entry.el.srcObject = new MediaStream([entry.track])
      entry.last = -1
      if (!leftCall && entry.el.paused) void entry.el.play().catch(() => { /* the next pass tries again */ })
      callTimeline.record('tile-bound', short(tileDevice(key)), 'video')
    }
  }
  // Sound, by the same liveness rule. A screen share that ends, or a
  // microphone whose sender the far end removed, leaves a silent element
  // behind otherwise. A mic muted with `track.enabled = false` keeps
  // sending packets, so its element is kept on purpose: it stays silent,
  // nothing about the tile claims otherwise, and the sound is there the
  // instant the mic comes back.
  for (const [key, entry] of remoteAudios) {
    const clock = entry.el.currentTime
    if (clock > entry.last + 0.001) noteProgress(entry.track, now)
    entry.last = clock
    const progressedAt = trackProgressAt.get(entry.track)
    if (progressedAt !== undefined) tileLiveness.progressed(key, progressedAt)
    if (entry.track.readyState !== 'ended' && !tileLiveness.gone(key, advertised(key), now)) continue
    entry.el.remove()
    remoteAudios.delete(key)
    remoteVolume.detach(key)
    const device = tileDevice(key)
    const remaining = [...remoteAudios].find(([other]) => other.startsWith(`${device}|`))
    if (remaining) speakingMonitor.watch(device, remaining[1].track)
    else speakingMonitor.unwatch(device)
    changed = true
  }
  tileLiveness.retain([...remoteVideos.keys(), ...remoteAudios.keys()])
  if (changed) repaint()
}

setInterval(syncRemoteVideos, 1000)

/**
 * Put a remote track on its device's tile.
 *
 * `slot` is which of the device's four slots this is - see
 * app/src/remote-tiles.ts. Nothing here goes on the receiver's own id: it is
 * the sender's id in Chromium, a locally minted one in Firefox, and neither
 * of them follows a `replaceTrack`. The `ontrack` path works the slot out
 * for itself; the recovery poll has already worked out the whole device's
 * binding and passes the answer in, so the two cannot disagree and put the
 * same track on two tiles in turn.
 */
function attachRemoteTrack(device: string, track: MediaStreamTrack, slot?: string): void {
  const key = slot ?? tileKeyFor(device, track)
  if (!key) return
  let mediaEl = deviceMediaEls.get(device)
  if (!mediaEl) {
    mediaEl = document.createElement('div')
    mediaEl.className = 'media'
    deviceMediaEls.set(device, mediaEl)
  }
  const container = mediaEl

  // A track can arrive before its roster advert and be guessed into the
  // everyday slot for its kind. Once the advert says otherwise, move the
  // existing element rather than displaying the same receiver twice under
  // two names.
  if (track.kind === 'video' && !remoteVideos.has(key)) {
    const alias = [...remoteVideos].find(([, entry]) => entry.track === track)
    if (alias) { remoteVideos.delete(alias[0]); remoteVideos.set(key, alias[1]); callTimeline.record('tile-bound', short(device)) }
  }
  if (track.kind === 'audio' && !remoteAudios.has(key)) {
    const alias = [...remoteAudios].find(([, entry]) => entry.track === track)
    // Any route the old key held is torn down rather than left dangling
    // under a name `remoteAudios` no longer has; `render()` opens a fresh
    // one under the new key on its next pass.
    if (alias) { remoteAudios.delete(alias[0]); remoteAudios.set(key, alias[1]); remoteVolume.detach(alias[0]); callTimeline.record('tile-bound', short(device)) }
  }

  // One element PER TRACK, not per kind. A device sharing its screen while
  // its camera is on sends two video tracks, and a room where the second one
  // lands on top of the first is a room where turning on a screen share
  // makes your face disappear - which is exactly what it used to do, since
  // the lookup was by tag and the second `srcObject` assignment simply
  // replaced the first. Same for audio: a screen share with sound is a
  // second audio track alongside the mic.
  if (track.kind === 'video') {
    const existing = remoteVideos.get(key)
    const el = existing?.el ?? document.createElement('video')
    // The same key, a different track object: the mesh rebuilt the
    // connection to this device - a rung down the ladder, or a fresh one
    // after a rest - and the far end's track arrived again on it. The
    // element is kept, so the picture never blinks, but everything that
    // judges it has to follow the new track: the stall poller reads
    // `entry.track.readyState`, and the old track ends the moment the old
    // connection closes. Left pointing at the old one, the poller and the
    // old track's `ended` both took the element off the screen while it
    // was showing live frames from the new one, and nothing put it back -
    // `ontrack` for that track had already fired. That was a picture gone
    // for the rest of the call, on a connection that was working.
    const replaced = existing !== undefined && existing.track !== track
    if (!existing || replaced) el.srcObject = new MediaStream([track])
    if (existing) existing.track = track
    if (!existing) {
      el.autoplay = true
      el.playsInline = true
      el.muted = true
      // `ontrack` precedes the first decoded frame. Keep a tiny transparent
      // sink in the rendering tree so Chromium continues decoding; the HTML
      // `hidden` attribute maps to display:none and can suspend the decoder,
      // leaving videoHeight at zero forever. The first moving frame removes
      // this class in syncRemoteVideos above.
      el.classList.add('awaitingFrame')
      el.dataset.track = track.id
      remoteVideos.set(key, { el, container, track, last: -1, stalled: 0, played: false })
      if (meetingGated(device)) parkPicture(el)
      else container.append(el)
      callTimeline.record('track-added', short(device), 'video')
    } else if (!onScreen(existing) && !meetingGated(device)) {
      // Parked, and the far end is publishing this track again - a
      // renegotiation hands the same track over and `ontrack` fires afresh.
      // Back on screen, with the stall count reset: if it really is still
      // frozen, the next two checks say so and park it again.
      restoreRemoteElement(el, container)
      existing.stalled = 0
    }
    // `autoplay` is a request, not proof of playback. WebKit can leave this
    // connected element paused after replacing its MediaStream, so explicitly
    // resume it while this device is still on the call.
    if (!leftCall && el.paused) void el.play().catch(() => { /* A later recovery tick or user gesture retries. */ })
    if (replaced) {
      // A new track has never played, whatever the old one did, and the
      // clock it is judged by starts again.
      existing!.last = -1
      existing!.stalled = 0
      existing!.played = false
      el.classList.add('awaitingFrame')
    }
    track.addEventListener('ended', () => {
      // Only the track currently on this element may take it down. The
      // one this listener was registered for may have been replaced since,
      // in which case its ending is old news about a closed connection.
      if (remoteVideos.get(key)?.track !== track) return
      el.remove()
      remoteVideos.delete(key)
      callTimeline.record('track-removed', short(device), 'video')
      repaint()
    })
  } else {
    // Audio is never taken off screen for going quiet. A picture that
    // outlives its media is a lie about what the room can see; an `<audio>`
    // element that outlives its media is simply silent - and removing one
    // costs real sound, because a track with no sink is never decoded and
    // reports exactly zero energy, which is how a room with no audio
    // elements at all looked in the first place.
    const existing = remoteAudios.get(key)
    const el = existing?.el ?? document.createElement('audio')
    if (!existing) {
      el.autoplay = true
      el.dataset.track = track.id
      remoteAudios.set(key, { el, track, last: -1 })
      container.append(el)
      callTimeline.record('track-added', short(device), 'audio')
    } else if (!el.isConnected) {
      restoreRemoteElement(el, container)
    }
    // Same rule as the picture: a rebuilt connection hands the same track id
    // over as a new object, and only the track on the element now may end
    // it. Reassigned only when it changed, so a renegotiation that hands the
    // same track back does not restart the element mid-word.
    if (!existing || existing.track !== track) {
      el.srcObject = new MediaStream([track])
      if (existing) existing.track = track
    }
    if (!leftCall && el.paused) void el.play().catch((err) => reportAutoplayBlock(err))
    // Tap it for the speaking indicator. Keyed by device rather than by
    // track, so a device sending both a microphone and its screen's audio
    // lights its tile from whichever is making noise - which is what a
    // person watching the grid means by "they are talking".
    speakingMonitor.watch(device, track)
    track.addEventListener('ended', () => {
      if (remoteAudios.get(key)?.track !== track) return
      el.remove()
      remoteAudios.delete(key)
      remoteVolume.detach(key)
      speakingMonitor.unwatch(device)
      paintSpeaking()
      callTimeline.record('track-removed', short(device), 'audio')
      repaint()
    })
  }

  repaint()
}

/**
 * Chromium can decode a receiver while omitting the `track` event during a
 * rapid peer rebuild. The RTP counters then climb but the app has no media
 * element, which is the exact blank-tile failure a person sees. Connections
 * are already retained for diagnostics, so reconcile their live receivers
 * with the UI as a recovery path. Re-attaching the same object is skipped.
 */
/**
 * Take down a tile showing a receiver the mapping no longer binds.
 *
 * The liveness rule is about a far end that stopped: no advert, no packets,
 * so the tile goes. It cannot answer the other case, and a far end toggling
 * its camera makes that case every time. The receiver it leaves behind is
 * not gone - its transceiver stays, `getSynchronizationSources` reports its
 * last sources, its counters stand - so the advert half never agrees and the
 * tile stays for ever. Measured in Firefox, where a receiver's id matches no
 * advert: three video receivers for one camera, two of them stale, two
 * elements on that person's tile and neither of them the live one.
 *
 * `bindRoles` already knows which receivers this device should be showing.
 * Anything else is a tile nothing is claiming, whatever its counters say.
 */
function dropUnboundTiles(device: string, kind: MediaKind, binding: ReadonlyMap<TrackAdvert['role'], { readonly id: string }>): void {
  const keep = new Set<unknown>(binding.values())
  const tiles = kind === 'video' ? remoteVideos : remoteAudios
  for (const [key, entry] of tiles) {
    if (tileDevice(key) !== device) continue
    if (keep.has(entry.track)) continue
    if (kind === 'video') {
      const video = entry as RemoteVideo
      if (onScreen(video)) changedTiles = true
      video.el.remove()
      remoteVideos.delete(key)
      callTimeline.record('tile-orphaned', short(device), 'video')
    } else {
      entry.el.remove()
      remoteAudios.delete(key)
      remoteVolume.detach(key)
      speakingMonitor.unwatch(device)
      changedTiles = true
      callTimeline.record('track-removed', short(device), 'audio')
    }
    tileLiveness.forget(key)
  }
}

/** Set by a tile coming down outside `syncRemoteVideos`, so the grid is
 *  repainted once rather than per tile. */
let changedTiles = false

function recoverRemoteTracks(): void {
  const session = mediaSession()
  if (!session) return
  const now = performance.now()
  const devices = new Set<string>()
  for (const [key, pc] of openConnections) {
    if (pc.connectionState !== 'connected') continue
    const device = connectionDevice(key)
    if (device && session.participants().some(view => view.devices.includes(device))) devices.add(device)
  }
  for (const device of devices) {
    const receivers = deviceReceivers(device, now)
    const adverts = advertsFor(device)
    for (const kind of ['video', 'audio'] as const) {
      // The same decision `attachRemoteTrack` makes, made for the whole
      // device at once: who should hold each slot, given what the roster
      // advertises, what the tiles show now, and whose packets are moving.
      const binding = bindRoles({ kind, adverts, receivers, bound: boundTracks(device, kind) })
      dropUnboundTiles(device, kind, binding)
      for (const [role, chosen] of binding) {
        const track = chosen as MediaStreamTrack
        if (track.readyState !== 'live') continue
        const key = tileKey(device, role)
        const entry = kind === 'video' ? remoteVideos.get(key) : remoteAudios.get(key)
        // Nothing on screen, no advert and no packets: the far end really
        // did stop. `syncRemoteVideos` took the element down; opening a new
        // one here every two seconds would be the black box again, on a
        // timer. A slot that is advertised, or whose packets are moving, is
        // a slot somebody should be seeing.
        if (!entry && advertised(key) === false && !trackProgressing(track, now)) continue
        // Safari can keep the sink connected but pause it when a rebuilt peer
        // swaps in a new MediaStream. A connected element is not necessarily a
        // playing one; make the recovery path repair both states.
        if (entry?.track !== track || !entry.el.isConnected || entry.el.paused) attachRemoteTrack(device, track, key)
      }
    }
  }
  if (changedTiles) {
    changedTiles = false
    repaint()
  }
}

setInterval(recoverRemoteTracks, 2000)

// ---------------------------------------------------------------------------
// Diagnostics
// ---------------------------------------------------------------------------

const short = (hex: string | undefined) => (hex ? hex.slice(0, 8) : hex)

/**
 * What this page knows about its own connections, as text to paste into a
 * bug report: the browser, who is here and what they advertise, every
 * route and its rung, every peer connection with its states, its tracks and
 * the counters that say whether media is moving, and every remote element
 * with whether it is on screen and advancing.
 *
 * Deliberately no addresses: candidate TYPES say whether a pair went
 * direct or through TURN, which is what a report needs, and a person's IP
 * is not something a "copy" button should put on their clipboard.
 */
async function collectDiagnostics(): Promise<string> {
  const s = mediaSession()
  const pick = (r: Record<string, unknown>, keys: string[]) =>
    Object.fromEntries(keys.filter((k) => r[k] !== undefined).map((k) => [k, r[k]]))
  const connections = await Promise.all(
    [...openConnections].map(async ([key, pc]) => {
      const stats: Record<string, unknown>[] = []
      try {
        const report = await pc.getStats()
        report.forEach((raw) => {
          const r = raw as unknown as Record<string, unknown>
          switch (r.type) {
            case 'inbound-rtp':
            case 'outbound-rtp':
              stats.push(pick(r, ['type', 'kind', 'bytesReceived', 'bytesSent', 'packetsReceived', 'packetsSent', 'packetsLost', 'framesDecoded', 'framesEncoded', 'framesReceived', 'framesSent', 'frameWidth', 'frameHeight', 'codecId', 'pliCount', 'nackCount', 'jitterBufferDelay']))
              break
            // Tells this device whether the far end is actually receiving
            // what it sends - see PairSample.outboundAcknowledged.
            case 'remote-inbound-rtp':
              stats.push(pick(r, ['type', 'kind', 'packetsLost', 'roundTripTime']))
              break
            case 'candidate-pair':
              if (r.nominated === true || r.selected === true) stats.push(pick(r, ['type', 'state', 'localCandidateId', 'remoteCandidateId', 'bytesSent', 'bytesReceived', 'currentRoundTripTime', 'availableOutgoingBitrate']))
              break
            case 'local-candidate':
            case 'remote-candidate':
              stats.push(pick(r, ['type', 'id', 'candidateType', 'protocol', 'relayProtocol', 'networkType']))
              break
            case 'codec':
              stats.push(pick(r, ['type', 'id', 'mimeType', 'clockRate']))
              break
          }
        })
      } catch {
        stats.push({ error: 'getStats failed' })
      }
      return {
        key: key.replace(/:([0-9a-f]{64}):/, (_m, k: string) => `:${k.slice(0, 8)}:`),
        connectionState: pc.connectionState,
        iceConnectionState: pc.iceConnectionState,
        iceGatheringState: pc.iceGatheringState,
        signalingState: pc.signalingState,
        senders: pc.getSenders().map((sn) => (sn.track ? `${sn.track.kind}:${sn.track.readyState}${sn.track.muted ? ':muted' : ''}${sn.track.enabled ? '' : ':disabled'}` : 'none')),
        // The transceiver's direction belongs on this line, not just the
        // track's state: a receiver whose `currentDirection` no longer says
        // `recv` is one the tile mapping will not bind, and a report that
        // says only `live:muted` cannot tell that apart from a tile that is
        // simply quiet. `mid` names the m-line, so two transceivers of the
        // same kind on one connection are told apart at a glance.
        receivers: pc.getTransceivers().map((tr) => {
          const track = tr.receiver?.track
          const where = `${tr.mid ?? '-'}:${tr.currentDirection ?? 'unnegotiated'}`
          return track ? `${track.kind}:${track.readyState}${track.muted ? ':muted' : ''}@${where}` : `none@${where}`
        }),
        stats,
      }
    }),
  )
  const out = {
    at: new Date().toISOString(),
    build: document.querySelector('script[src*="/assets/index-"]')?.getAttribute('src') ?? 'dev',
    ua: navigator.userAgent,
    visibility: document.visibilityState,
    me: {
      participant: short(mediaMe()),
      device: short(myDeviceId),
      publishing: currentAdverts().map((a) => a.role),
      callProfile,
      agentsMayHear,
      effect: $('effectMode').textContent,
      screenAudio: screenAudioTrack
        ? { present: true, muted: screenAudioTrack.muted, readyState: screenAudioTrack.readyState }
        : { present: false },
      wakeLock: callWakeLock.state,
    },
    participants: s?.participants().map((v) => ({
      name: v.name,
      participant: short(v.participant),
      agent: v.agent === true,
      devices: v.devices.map(short),
      tracks: v.tracks.map((t) => `${t.role}@${short(t.device)}${t.muted ? '(muted)' : ''}`),
      mic: short(v.mic),
      call: v.call ? { id: short(v.call.id), devices: v.call.devices.map(short) } : undefined,
      recordingProfiles: Object.entries(v.recordingProfiles ?? {}).map(([device, profile]) => ({ device: short(device), profile })),
    })),
    recording: activeRecording ? { capture: activeRecording.capture.capture, videoInputs: recordingVideoPeople(activeRecording.session).map(person => ({ label: person.label, fallback: person.fallback, camera: !!person.camera })) } : undefined,
    recordingWarnings: s?.liveRecordings().map(({ state, sentAt }) => ({
      on: state.recording.on, id: short(state.recording.id), version: state.recording.version,
      call: short(state.call), device: short(state.device), sentAt,
    })),
    routes: s ? [...s.routes].map(([d, r]) => ({ device: short(d), tier: r.tier, endpoint: short(r.endpoint), connected: r.connected, exhausted: r.exhausted })) : [],
    connections,
    pictures: [...remoteVideos].map(([key, v]) => ({
      device: short(tileDevice(key)),
      role: tileRole(key),
      onScreen: onScreen(v),
      played: v.played,
      stalled: v.stalled,
      currentTime: Number(v.el.currentTime.toFixed(2)),
      paused: v.el.paused,
      size: `${v.el.videoWidth}x${v.el.videoHeight}`,
      track: `${v.track.readyState}${v.track.muted ? ':muted' : ''}`,
    })),
    sounds: [...remoteAudios].map(([key, a]) => ({
      device: short(tileDevice(key)),
      role: tileRole(key),
      inDocument: a.el.isConnected,
      paused: a.el.paused,
      currentTime: Number(a.el.currentTime.toFixed(2)),
      track: `${a.track.readyState}${a.track.muted ? ':muted' : ''}`,
    })),
    // A count, never the keys or the levels themselves - which people have
    // been turned up or down is nobody's business but this browser's.
    volume: { customLevels: volumeLevelCount(deviceStore), gainAvailable: remoteVolume.gainAvailable },
  }
  // Per-pair health: one line per connection, built from the same stats
  // pass above. `label` counts inbound-rtp entries of the same kind
  // (camera plus screen video, say) rather than trying to name them.
  const routeTiers = new Map((s ? [...s.routes] : []).map(([d, r]) => [short(d), r.tier]))
  // Only profile-2 pairs have one of these, and by default no pair does.
  // What it adds is the pair's own account of itself - which generation,
  // where on the health ladder, which slot it has judged dead in each
  // direction, and how much signalling the far end never acknowledged.
  const pairProfiles = new Map((s?.pairs ?? []).map((p) => [short(p.device), p]))
  const kindCounts = new Map<string, number>()
  const pairSamples: PairSample[] = connections.map((c) => {
    const device = /:([0-9a-f]{8}):/.exec(c.key)?.[1]
    kindCounts.clear()
    const slots = c.stats
      .filter((r) => r.type === 'inbound-rtp')
      .map((r) => {
        const kind = String(r.kind ?? 'unknown')
        const n = (kindCounts.get(kind) ?? 0) + 1
        kindCounts.set(kind, n)
        const label = n === 1 ? kind : `${kind}#${n}`
        const counter = Number(r.kind === 'audio' ? r.packetsReceived ?? 0 : r.framesDecoded ?? r.packetsReceived ?? 0)
        return { label, counter }
      })
    const pair = device ? pairProfiles.get(device) : undefined
    return {
      device: device ?? 'unknown',
      tier: device ? routeTiers.get(device) : undefined,
      connectionState: c.connectionState,
      signalingState: c.signalingState,
      slots,
      outboundAcknowledged: c.stats.some((r) => r.type === 'remote-inbound-rtp'),
      ...(pair
        ? {
            profile: {
              generation: pair.generation,
              ladder: pair.ladder,
              unacked: pair.unacked,
              ...(pair.inbound ? { inbound: pair.inbound as Record<string, string> } : {}),
              ...(pair.rtcp ? { rtcp: pair.rtcp as Record<string, string> } : {}),
              unexpectedNegotiations: pair.unexpectedNegotiations,
            },
          }
        : {}),
    }
  })
  // Inside the JSON, not appended after it: the report is pasted into bug
  // threads by people and parsed by the acceptance suite, and text after a
  // closing brace serves neither.
  return JSON.stringify({
    ...out,
    callTimeline: callTimeline.format(),
    pairSummary: pairHealthSampler.snapshot(pairSamples),
  }, null, 1)
}

// Acceptance builds read connection state directly, without a report control,
// clipboard writes or a report textarea. This hook is absent from release builds.
if (import.meta.env.VITE_TEST_DIAGNOSTICS === 'true') {
  Object.defineProperty(window, '__kithmootCollectDiagnostics', { value: collectDiagnostics })
}

// ---------------------------------------------------------------------------
// Joining
// ---------------------------------------------------------------------------

interface EntryMediaChoice {
  mic: boolean
  camera: boolean
}

function entryMediaChoice(): EntryMediaChoice {
  return {
    mic: ($('joinMic') as HTMLInputElement).checked,
    camera: ($('joinCamera') as HTMLInputElement).checked,
  }
}

/** Honour the two explicit choices made at the invitation door. Failure to
 *  open one device never throws the person back out of a room they joined;
 *  it leaves that device off and says which permission or device failed. */
async function enableEntryMedia(choice: EntryMediaChoice): Promise<void> {
  if (!choice.mic && !choice.camera) return
  const failures: string[] = []
  try {
    await joinCall()
  } catch (error) {
    setStatus(`You are in, but the call could not start: ${describeError(error)}.`)
    return
  }

  if (choice.mic && !micTrack?.enabled) {
    try { await toggleMic() } catch (error) { failures.push(`microphone: ${describeError(error)}`) }
  }
  if (choice.camera && !cameraTrack) {
    try { await toggleCamera() } catch (error) { failures.push(`camera: ${describeError(error)}`) }
  }
  ;($('joinMic') as HTMLInputElement).checked = false
  ;($('joinCamera') as HTMLInputElement).checked = false

  if (failures.length) {
    setStatus(`You are in, but ${failures.join('; ')}.`)
    return
  }
  const enabled = [choice.mic ? 'microphone' : '', choice.camera ? 'camera' : ''].filter(Boolean).join(' and ')
  setStatus(`You joined with your ${enabled} on.`, 'done')
}

/** Whether a join failed only because its relays could not be reached in
 *  time - never because a relay looked at the event and refused it. Kept in
 *  one place because both the retry loop below and the final status message
 *  need to agree on what counts as "the relays refused" versus "we could
 *  not reach them", and `relay-pool.ts` is the only thing that actually
 *  knows which happened. */
function isUnreachableRelayFailure(error: unknown): boolean {
  return error instanceof Error && /no relay could be reached in time/.test(error.message)
}

async function startSession(asVisitor = false, retry?: { deadline: number, signerRetried?: boolean }): Promise<void> {
  const generation = roomGeneration
  if (!retry && (joining || session || loginBusy)) return
  legacyMessagesPanel?.close()
  if (!retry) applyHideIpDefault()
  const requestedMedia = entryMediaChoice()
  // Beside a docked call this room is for reading and writing: it never
  // carries this device's microphone, camera or relaying.
  let chatOnly = docked()
  joining = true
  if (!retry) armStopOpening()
  const deadline = retry?.deadline ?? Date.now() + 20_000
  if (!retry) setStatus('Joining the room…', 'progress')
  const joinBtn = $('join') as HTMLButtonElement
  joinBtn.disabled = true
  joinBtn.textContent = 'Joining…'
  $('joinRoomForm').setAttribute('aria-busy', 'true')
  // Set once this attempt hands off to a retried one, so the `finally`
  // below leaves the busy state in place instead of re-enabling the form
  // between attempts the person never asked to see.
  let retrying = false

  try {
    if (browserMlsPanel || import.meta.env.DEV && (browserMlsGrantPanel || browserMlsRoomPanel)) await pauseBrowserMls()
    roomUsesBothy = !!await browserRoomRoutes.selected(deriveRoom(roomSecret).roomId)
    chatOnly = chatOnly || roomUsesBothy
    // A restored signer can arrive after the invitation. Joining first
    // would mint a visitor identity that a known-contact clerk rejects,
    // even though the account UI subsequently says we are signed in.
    // A room this device holds the account's pass for does not wait for
    // the signer to come back: that wait is the whole problem when it will
    // not. Bookmarks and the rest follow when it does.
    if (identityRestoring && !accountPassForRoom()) {
      setStatus('Reconnecting your sign-in…', 'progress')
      await identityReady
      if (generation !== roomGeneration) return
      setStatus('Joining the room…', 'progress')
    }
    if (needsAccountReconnect() && !asVisitor) {
      setStatus('Your Nostr account is not connected. Continue to reconnect it, or join with just a name.')
      ;($('join') as HTMLButtonElement).focus()
      return
    }
    const deviceSk = deviceKey()
    // A device key is per room. Beside a docked call `myDeviceId` stays the
    // call's, because every media decision is made against it.
    const deviceId = getPublicKey(deviceSk)
    if (!chatOnly) myDeviceId = deviceId
    const credential = loadCredential()

    // The design says the room names its own STUN and TURN - never an
    // operator's default baked into the app - so the ICE list comes from
    // the room's own URL (or the room-settings field when creating one),
    // never a constant here. resolveIceServers only ever adds to that list
    // (a minted credential for this app's own default TURN, if configured
    // and actually in play - see isDefaultIceUrls) and never blocks
    // joining if the credential endpoint is absent or unreachable.
    // Chat does not need TURN credentials. Prepare them in the background,
    // unless this device explicitly requires a relay before any media can
    // connect. Capture this room's URLs: a late fetch must not affect another.
    const roomIceUrls = [...iceUrls]
    const relayOnly = ($('joinRelayOnly') as HTMLInputElement).checked
    let resolvedIceServers = relayOnly
      ? await resolveIceServers(roomIceUrls)
      : (isDefaultIceUrls(roomIceUrls) ? originStunGuess(location) : roomIceUrls).map(urls => ({ urls }))
    if (generation !== roomGeneration) return
    if (relayOnly) relayOnlyIceConfiguration(resolvedIceServers)
    turnRelayConfigured = resolvedIceServers.some(server => toUrlList(server.urls).some(url => url.startsWith('turn')))

    // A real RTCPeerConnection genuinely has everything RTCPeerConnectionLike
    // needs - its on* handlers just carry the full, specific DOM event type
    // rather than the narrow shape Peer actually reads, which is a sound
    // narrowing at runtime but not something TS's structural checker allows
    // for property-typed callbacks without a cast.
    //
    // The ICE list is split by rung, which is what actually inverts the
    // selection order. ICE will relay through any TURN server it is given,
    // happily and immediately, so a connection handed the TURN credentials on
    // the first attempt has not "tried direct first" in any sense that costs
    // less - it has simply tried everything at once and taken whatever
    // connected. Keeping TURN out of the list until the mesh asks for the
    // TURN rung is the only way the earlier rungs mean anything.
    const withoutTurn = (servers: RTCIceServer[]) =>
      servers.filter((server) => !toUrlList(server.urls).some((url) => url.toLowerCase().startsWith('turn')))
    let stunOnly = withoutTurn(resolvedIceServers)
    // A minted TURN credential lasts an hour. A standing room lasts longer,
    // and the TURN rung is built from whatever these hold at the moment a
    // pair needs it - which, two hours in, was an expired credential, and a
    // person whose Wi-Fi had just changed could not be reached again.
    // Refreshed well inside the credential's life, and never blocking: a
    // refresh that fails leaves the last good list in place.
    // A docked call keeps refreshing its own credentials while another room
    // is on screen, so the guard is the session, not the screen.
    let created: RoomSession | undefined
    const alive = (): boolean => created ? session === created || dockedCall?.session === created : generation === roomGeneration
    const refreshIce = (): void => {
      resolveIceServers(roomIceUrls)
        .then((fresh) => {
          if (!alive()) return
          // Do not replace a working relay-only allocation list with a STUN
          // fallback after a credential refresh failure. Keeping the last
          // good credential is safe until it expires; replacing it would
          // silently defeat the person's explicit IP-privacy choice.
          if (relayOnly) relayOnlyIceConfiguration(fresh)
          resolvedIceServers = fresh
          stunOnly = withoutTurn(fresh)
          turnRelayConfigured = fresh.some(server => toUrlList(server.urls).some(url => url.startsWith('turn')))
        })
        .catch(() => {})
    }
    if (!chatOnly && !relayOnly && isDefaultIceUrls(roomIceUrls)) refreshIce()
    const ownConnections = new Set<string>()
    const factory: PeerFactory = (context?: PeerContext) => {
      const configuration = relayOnly
        ? relayOnlyIceConfiguration(resolvedIceServers)
        : { iceServers: context?.tier === 'turn' ? resolvedIceServers : stunOnly }
      const pc = new RTCPeerConnection(configuration)
      // Every connection contributes to the reachability measurement. It
      // costs nothing - these candidates were gathered anyway - and it is the
      // only honest source for whether this device could carry anybody.
      pc.addEventListener('icecandidate', (event) => {
        if (event.candidate) reachability.add({ candidate: event.candidate.candidate })
      })
      // Registered so the uplink probe has something to sample, under a key
      // unique to this connection rather than to its rung: the mesh opens a
      // fresh connection when it escalates, and the one being replaced lives
      // on until it closes itself.
      const key = `${context?.tier ?? 'direct'}:${context?.remoteDevice ?? 'unknown'}:${++connectionSeq}`
      openConnections.set(key, pc)
      ownConnections.add(key)
      pc.addEventListener('connectionstatechange', () => {
        if (pc.connectionState !== 'closed' && pc.connectionState !== 'failed') return
        openConnections.delete(key)
        uplink.forget(key)
      })
      return pc as unknown as RTCPeerConnectionLike
    }

    // A paired device joins on its credential alone. Only a device that
    // actually holds the participant key passes one.
    const name = joiningName()
    // Held here as well as inside the session, because a file dropped into
    // the chat announces itself with a kind-1063 event on the room's own
    // relays, through the sockets the room already has open - in an
    // ordinary room only; a quiet room sends no such announcement. See
    // `shareDroppedFile`.
    if (roomUsesBothy) {
      if (!nostrSession) throw new Error('Reconnect this room’s account before resuming its Bothy route.')
      await browserLink.resume(nostrSession.pubkey)
      browserRoomRoutes.changed()
    }
    const pool = configuredPool(relays)
    sessionTransport = pool
    const poolCreatedAt = Date.now()
    // A quiet room's chat rides in drops: wrap the pool, and the session
    // hands the wrapper the epoch key. The device holding the identity is
    // slot 0, the device it paired slot 1; each draws from its own half of
    // the member's drop keys, so no key is used twice. See src/quiet.ts.
    const sessionRoomId = deriveRoom(roomSecret).roomId
    // Where this device last left the room, so the session opens there and
    // reads the last month, rather than replaying every rekey from epoch 0
    // and stalling at one sealed to a seal key since dropped.
    const kept = loadKeptRoomEpoch(deviceStore, sessionRoomId)
    const keptEpoch = kept ? { epoch: kept.epoch, pastEpochs: kept.past } : {}
    quietTransport = isQuietPolicy(roomPolicy)
      ? quietRoomTransport(pool, {
          policy: roomPolicy!,
          participant: credential ? credential.pubkey : currentIdentity().pubkey,
          slot: credential ? 1 : 0,
          used: loadQuietState(deviceStore, sessionRoomId, nowSeconds()).used,
          reservedCounters: epoch => cadenceReservedCounters(deviceStore, sessionRoomId, deviceId, epoch),
          intervalSeconds: QUIET_SLOT,
          onUsed: () => persistQuiet(),
          onPosted: () => persistQuiet(),
          onError: (error) => console.warn('quiet room', error),
        })
      : undefined
    const transport: RelayTransport = quietTransport ?? pool
    // A server forwarder terminates ordinary WebRTC DTLS-SRTP. Only pass one
    // to the session when this browser has a live encoded-frame worker; the
    // mesh then refuses promotion until that worker has received the epoch
    // key and can attach a transform to every forwarded endpoint.
    const forwarderMedia = new BrowserForwarderMediaPipeline()
    const forwarderMediaOptions = forwarderMedia.available
      ? { forwarderMedia: () => forwarderMedia.ready, forwarderMediaPipeline: forwarderMedia }
      : {}
    sessionAuthority = roomAuthority()
    const s = credential
      ? new RoomSession({
          isBlocked: contactIsBlocked,
          transport,
          secret: roomSecret,
          credential,
          deviceSk,
          factory: roomUsesBothy ? undefined : factory,
          policy: roomPolicy,
          name,
          // Off unless the kill switch says otherwise, and a pair uses it
          // only when the far end's roster entry says 2 as well.
          callProfile,
          recordingProfile: 4,
          trackRole: activeTrackRole,
          ...(chatOnly ? {} : { assist: currentAssistOffer, relay: peerRelay }),
          ...forwarderMediaOptions,
          ...(roomArchive ? { archive: roomArchive } : {}),
          // Epochs: follow a rekey signed by the room's authority, and ask it
          // first if the responder said the room is ahead of the secret we
          // were handed. See src/epoch.ts and docs/decisions.md.
          authority: roomAuthority(),
          expectedEpoch,
          ...keptEpoch,
          // A conference room: everything signed for it lapses at its end.
          endsAt: roomEndsAt,
          onEpoch: notice => { if (created && session === created) onEpochChange(notice) },
          onEpochWaiting: (waiting, why) => { if (created && session === created) renderEpochWaiting(waiting, why) },
          onUnknownAsking: asker => { if (created) askAboutUnknown(created, asker) },
          onEpochGap: () => { if (created) reportEpochTrouble(created) },
          onEpochConflict: () => { if (created) reportEpochTrouble(created) },
          onRemoved: (notice) => {
            if (created && dockedCall?.session === created) void endDockedCall('user', `You were removed from ${dockedCall.label}${notice.by ? ` by ${personLabel(notice.by)}` : ''}.`)
            else if (created && session === created) leaveWithNotice(`You were removed from this room${notice.by ? ` by ${personLabel(notice.by)}` : ''}.`)
          },
          onClosed: (notice) => {
            if (created && dockedCall?.session === created) dockedRoomClosed(created.roomId, notice)
            else if (created && session === created) roomWasClosed(notice)
          },
          // The indicator has to move the moment this device starts or stops
          // carrying somebody, not on the next poll tick.
          onRelayStart: () => renderAssist(),
          onRelayStop: () => renderAssist(),
          // The chips say which rung a connection is on, so they move when it does.
          onRoute: (device, route) => {
            callTimeline.record('route-tier-change', short(device), route.tier)
            repaint()
          },
          onDiagnostic: (event) => callTimeline.record(event.kind, short(event.device), event.detail),
        })
      : new RoomSession({
          isBlocked: contactIsBlocked,
          transport,
          secret: roomSecret,
          // A local key or an external signer - the session cannot tell,
          // and does not need to. See src/identity.ts.
          identity: currentIdentity(),
          // Coming back to a room should not wait on a bunker: the
          // credential minted last time is offered, and the session uses it
          // only if it is still this device's and still good. Kept by the
          // room id this session was built for, which a docked call may
          // not share with the screen.
          resume: loadOwnCredentialFor(deviceStore, sessionRoomId, nowSeconds()),
          sealKeys: loadOwnSealKeysFor(deviceStore, sessionRoomId),
          onCredential: (minted, sealSk) => {
            try { storeOwnCredentialFor(deviceStore, sessionRoomId, minted, sealSk) } catch { /* storage may be unavailable */ }
          },
          deviceSk,
          factory: roomUsesBothy ? undefined : factory,
          policy: roomPolicy,
          name,
          // Off unless the kill switch says otherwise, and a pair uses it
          // only when the far end's roster entry says 2 as well.
          callProfile,
          recordingProfile: 4,
          trackRole: activeTrackRole,
          ...(chatOnly ? {} : { assist: currentAssistOffer, relay: peerRelay }),
          ...forwarderMediaOptions,
          ...(roomArchive ? { archive: roomArchive } : {}),
          // Epochs: follow a rekey signed by the room's authority, and ask it
          // first if the responder said the room is ahead of the secret we
          // were handed. See src/epoch.ts and docs/decisions.md.
          authority: roomAuthority(),
          expectedEpoch,
          ...keptEpoch,
          // A conference room: everything signed for it lapses at its end.
          endsAt: roomEndsAt,
          onEpoch: notice => { if (created && session === created) onEpochChange(notice) },
          onEpochWaiting: (waiting, why) => { if (created && session === created) renderEpochWaiting(waiting, why) },
          onUnknownAsking: asker => { if (created) askAboutUnknown(created, asker) },
          onEpochGap: () => { if (created) reportEpochTrouble(created) },
          onEpochConflict: () => { if (created) reportEpochTrouble(created) },
          onRemoved: (notice) => {
            if (created && dockedCall?.session === created) void endDockedCall('user', `You were removed from ${dockedCall.label}${notice.by ? ` by ${personLabel(notice.by)}` : ''}.`)
            else if (created && session === created) leaveWithNotice(`You were removed from this room${notice.by ? ` by ${personLabel(notice.by)}` : ''}.`)
          },
          onClosed: (notice) => {
            if (created && dockedCall?.session === created) dockedRoomClosed(created.roomId, notice)
            else if (created && session === created) roomWasClosed(notice)
          },
          // The indicator has to move the moment this device starts or stops
          // carrying somebody, not on the next poll tick.
          onRelayStart: () => renderAssist(),
          onRelayStop: () => renderAssist(),
          // The chips say which rung a connection is on, so they move when it does.
          onRoute: (device, route) => {
            callTimeline.record('route-tier-change', short(device), route.tier)
            repaint()
          },
          onDiagnostic: (event) => callTimeline.record(event.kind, short(event.device), event.detail),
        })
    // Who the room removed and who it knows, as kept: a session that opens
    // past the rekeys that said so would otherwise not know until the next.
    if (kept) {
      s.forgetParticipants(kept.removed)
      s.rememberMembers(kept.members)
    }
    session = s
    created = s
    recordingDeviceKeys.set(s, deviceSk)
    sessionConnections.set(s, ownConnections)
    // Said in the call's More menu, so the person can see what they chose at
    // the door. It cannot change on a call.
    sessionRelayOnly.set(s, relayOnly)
    meParticipant = s.participant
    // This device is in the room as this identity: a link to the room opens
    // it from now on, for the same identity only. Local, never bookmarked.
    if (generation === roomGeneration) {
      const joined = currentRoomId()
      if (joined) { try { markRoomJoined(roomStore(), joined, nowSeconds(), s.participant) } catch { /* Storage may be unavailable; the door is the fallback. */ } }
    }

    s.onChange((views) => {
      const isDocked = dockedCall?.session === s
      if (session !== s && !isDocked) return
      ingestLiveRecordings(s)
      if (s === mediaSession()) {
        const byDevice = new Map<string, string[]>()
        for (const view of views) for (const t of view.tracks) byDevice.set(t.device, [...(byDevice.get(t.device) ?? []), t.role])
        for (const change of advertTracker.update([...byDevice].map(([device, roles]) => ({ device, roles })))) {
          if (change.added.length > 0) callTimeline.record('advert-change', short(change.device), `+${change.added.join(',')}`)
          if (change.removed.length > 0) callTimeline.record('advert-change', short(change.device), `-${change.removed.join(',')}`)
        }
      }
      // The call's roster moves the tiles and the dock; the room on screen
      // is repainted with its own roster.
      if (isDocked) { repaint(); return }
      announceComings(views, meParticipant)
      assignmentPanel.refreshPeople()
      render(views, meParticipant)
      renderInvites()
      renderHost()
      // The owner of an agent that asked may only now be known.
      renderApprovals()
    })
    s.onRemoteTrack(({ device, track, role }) => {
      // Profile 2's fixed slot is authoritative. Discarding it here made the
      // UI guess from browser-local receiver ids and arrival order, so an
      // idle camera receiver could take the screen slot and the real share
      // remained attached to a decoder that never received its frames.
      if (role) fixedRemoteRoles.set(track, role)
      if (s === mediaSession()) attachRemoteTrack(device, track, role ? tileKey(device, role) : undefined)
      else track.stop()
    })
    s.onAnnotation(({ participant, annotation }) => {
      if (s !== mediaSession()) return
      shareViewer.receive(annotation, markAuthor(participant))
      notifyDrawingOnMyShare(participant, annotation)
    })

    // A half-open socket from before this pool even connected would not be
    // this pool's problem, but the tab going to the background any time
    // after it did is: a cheap round trip here catches it before the join
    // event is the thing that discovers it, the slow and public way.
    if (lastHiddenAt >= poolCreatedAt) await pool.probe().catch((err) => callTimeline.record('probe-failed', undefined, describeError(err)))
    await s.join(chatOnly ? [] : currentAdverts(), chatOnly ? {} : currentClaims())
    if (session !== s) return
    // Another tab of this browser, same account, may already be on this
    // room's call under the identical device key - see call-tab-lock.ts.
    // Asked once, now, because a fresh tab's own heartbeat asserting no
    // tracks is exactly the contradiction that orphans that tab's live
    // media a few seconds later.
    if (!chatOnly) {
      const lockKey = callLockKey()
      if (lockKey) {
        callTabLock.askHeldElsewhere(lockKey).then((held) => {
          if (!held || session !== s || callLockKey() !== lockKey || onCall()) return
          heldElsewhereKey = lockKey
          s.pausePresence()
          renderCallTabNotice()
        }).catch(() => {})
      }
    }
    await requeueQuiet(s)
    await resumePending(s)
    // A reply draft reads its original message from the new session. Its
    // logs must exist before restoring that context.
    selectRoomDrafts()
    void assignmentPanel.attach(s)
    iceRefreshTimer = setInterval(refreshIce, ICE_REFRESH_MS)
    scheduleConferenceEnd(s)
    if (!chatOnly) s.publishTracks(activeTracks(), { audience })

    // What lands while this tab is in the background is worth a
    // notification, if the person asked for them. Followed from now, so
    // the history the log replays on open is never news.
    if (window.kithmootDesktop) {
      // A room first watched before we joined had no device/seal keys.
      // Rebuild its watch now so it follows rekeys after we switch away.
      stopWatching(s.roomId)
      for (const room of knownRooms(roomStore())) watchKnownRoom(room)
    }
    const joinedRoomId = currentRoomId() ?? s.roomId
    const roomLabelNow = () => currentRoomLabel()
    followReadPositions(joinedRoomId, deriveRoom(roomSecret).roomKey, s.endsAt)
    const notifyChat = notifier.follow({ roomId: joinedRoomId, channel: 'chat', room: roomLabelNow, sender: senderLabel, roster: () => s.participants(), direct: () => dmPeer(roomPolicy, meParticipant) !== undefined })
    s.chat.onChange(() => coalesceChatPaint(dockedCall?.session === s ? 'docked-chat' : 'chat', () => {
      // A docked call's room still tells the person when somebody writes.
      if (session !== s) { if (dockedCall?.session === s) notifyChat(s.chat.messages()); return }
      const messages = s.chat.messages()
      // Only when the main chat is the conversation on screen. Repainting
      // regardless put the main chat under whichever tab was selected and
      // left the tab lit, so the page said one thing and showed another.
      if (currentChannel === undefined) renderChat(messages)
      // The dot on the Chat tab is how somebody standing elsewhere learns
      // there is something to come back to.
      renderChannels()
      noteChatRead(messages)
      notifyChat(messages)
    }))
    renderChat(s.chat.messages())
    noteChatRead(s.chat.messages())
    notifyChat(s.chat.messages())
    // The side conversations: what the agents say to each other, what a
    // listening agent heard, and what a scribe made of it. Subscribed now
    // rather than when somebody opens the tab, because a relay replays a
    // durable kind to a new subscriber and an hour's backlog arriving after
    // a click reads as a broken tab.
    //
    // They used to be three panels stacked under the chat AS WELL AS three
    // tabs above it, so the same words were on the page twice and neither
    // copy said it was the same conversation. Now the tab is the only
    // place, and this only has to keep the tab's count and repaint the log
    // when the tab somebody is looking at is the one that changed.
    const followChannel = (name: string, notify?: (messages: ChatMessage[]) => void): void => {
      const log = s.channel(name)
      channelLogs.set(name, log)
      const arrived = (messages: ChatMessage[]): void => {
        if (session !== s) return
        channelCounts.set(name, messages.length)
        notify?.(messages)
        if (currentChannel === name) renderChat(messages)
        renderChannels()
      }
      log.onChange(arrived)
      arrived(log.messages())
    }
    followChannel(AGENT_CHANNEL, notifier.follow({ roomId: joinedRoomId, channel: 'agents', room: roomLabelNow, sender: senderLabel, roster: () => s.participants(), direct: () => dmPeer(roomPolicy, meParticipant) !== undefined }))
    followChannel(TRANSCRIPT_CHANNEL)
    followChannel(MINUTES_CHANNEL, notifier.follow({ roomId: joinedRoomId, channel: 'minutes', room: roomLabelNow, sender: senderLabel, roster: () => s.participants(), direct: () => dmPeer(roomPolicy, meParticipant) !== undefined }))
    // Agent hosts say what they can run on the control channel; a person
    // asks on it. Asked once on arrival, so a host that has been quiet for
    // an hour says again.
    const checksLog = s.channel(CHECK_CHANNEL)
    const checks = new ChannelChecks({ local: s.participant, context: s.roomId, store: deviceStore,
      current: () => session === s, allowed: peer => !contactIsBlocked(peer), send: text => checksLog.send(text) })
    channelChecks = checks
    channelChecksSession = s
    const seenChecks = new Set<string>()
    let checkingMessages = false, checksDirty = false
    const ingestChecks = async () => {
      if (checkingMessages) { checksDirty = true; return }
      checkingMessages = true
      try {
        do {
          checksDirty = false
          for (const message of checksLog.messages()) {
            if (session !== s) return
            if (seenChecks.has(message.id)) continue
            // ChatLog has already authenticated the device credential and
            // participant. Shared room encryption alone is not that proof.
            try { await checks.receive(message.participant, message.text) }
            catch { /* A malformed message or failed storage must not grant trust. */ }
            seenChecks.add(message.id)
            if (seenChecks.size > 1000) seenChecks.delete(seenChecks.values().next().value!)
          }
        } while (checksDirty && session === s)
        if (session === s) render(s.participants(), meParticipant)
      } finally { checkingMessages = false }
    }
    checksLog.onChange(() => { void ingestChecks() })
    void ingestChecks()
    const control = s.channel(CONTROL_CHANNEL)
    control.onChange((messages) => { if (session === s) ingestControl(messages) })
    ingestControl(control.messages())
    followSharedRoomName(s)
    attachRoomBoards(s)
    scheduleRoomNameCarry(s, 30_000, 30_000)
    control.send(encodeControl({ op: 'catalogue?' })).catch(() => {})
    scheduleReseed(s, pool, !!quietTransport, sessionAuthority)
    scheduleRoomRelaysRepost(s)
    renderRoomLockState()
    renderHost()
    // Empty until the keeper answers the `catalogue?` above with its signed
    // list, which is the only thing this client will believe.
    renderChannels()

    joinBtn.hidden = true
    $('identity').hidden = true
    // What sits under the way in goes with it. These are the entry screen's
    // own explanations, and a message screen carries a header, the
    // conversation and the box to type in.
    $('identityMore').hidden = true
    $('roomArea').hidden = false
    reportEpochTrouble(s)
    // "Invitation accepted. Go in when you are ready." has been acted on.
    // A line about getting in is stale the moment you are in.
    setStatus('')
    const pass = accountPassForRoom()
    if (pass && meParticipant === pass.pubkey) {
      const until = new Date(Number(pass.tags.find(tag => tag[0] === 'expiration')?.[1]) * 1000)
      setStatus(`Your Nostr signer is not connected, so you are in on this device's pass for this room until ${until.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}. Reconnect before then to stay.`)
    }
    showRoomTools()
    // The join screen has gone and the room is on: the last chance for the
    // masthead to have changed height.
      renderNudgeChoice()
    // The offer starts at whatever the person has already chosen, which is
    // off unless they turned it on before joining.
    lastOffering = currentAssistOffer() !== null
    startAssistPolling()
    render(s.participants(), meParticipant)
    // History may have arrived while the join screen still hid the log.
    // Restore this room's reading place only once it can be measured.
    chatScroll.resume(draftRoomKey())
    restoreConversation()
    repaintActiveChat()
    // The door that was pressed has gone, taking the focus with it: with a
    // pointer, the cursor goes to the message box. A touch screen is left
    // alone, so no keyboard rises over the conversation.
    if (matchMedia('(pointer: fine)').matches && (!document.activeElement || document.activeElement === document.body)) ($('chatInput') as HTMLElement).focus({ preventScroll: true })
    if (!chatOnly) await enableEntryMedia(requestedMedia)
  } catch (err) {
    const failed = session
    if (generation !== roomGeneration) return
    const failedTransport = sessionTransport
    await closeFailedRoomWithCatalogues(failed,failedTransport,()=>failed?closeRoomBoardCatalogues(failed):Promise.resolve(),()=>{
      if(session===failed&&sessionTransport===failedTransport){session=undefined;sessionTransport=undefined;resetIncomingCall()}
    })
    if(generation!==roomGeneration)return
    if (iceRefreshTimer !== undefined) clearInterval(iceRefreshTimer)
    iceRefreshTimer = undefined
    // A relay that timed out never looked at the event; a phone whose
    // socket went half-open in the background is not a room that said no.
    // `relay-pool.ts` retries the timeout itself first, so seeing one here
    // at all means every relay stayed unreachable through those retries -
    // worth trying the whole join again, not handing back an error that
    // reads like a refusal.
    if (isUnreachableRelayFailure(err) && Date.now() < deadline) {
      retrying = true
      setStatus("Still reaching the room's relays\u2026", 'progress')
      await new Promise(resolve => setTimeout(resolve, 1_000))
      if (generation === roomGeneration) { await startSession(asVisitor, { deadline, signerRetried: retry?.signerRetried }); return }
      return
    }
    // The room has moved to a new key and nobody who holds it answered:
    // not a refusal, and not this device's fault. Say so plainly and keep
    // trying, for as long as the person stays on this screen, until a
    // member comes online and brings this device up to date.
    if (err instanceof EpochUnreachableError) {
      retrying = true
      console.error('join waiting for the room key:', describeError(err))
      setStatus(err.unknown ? EPOCH_LET_IN_NOTICE : EPOCH_WAITING_NOTICE, 'progress')
      await new Promise(resolve => setTimeout(resolve, EPOCH_JOIN_RETRY_MS))
      if (generation === roomGeneration) { await startSession(asVisitor, { deadline: Date.now() + 20_000, signerRetried: retry?.signerRetried }); return }
      return
    }
    // A bunker that did not answer is asleep or waiting for a yes; see
    // signer-timeout.ts. Tried once more while the person goes to look.
    if (isSignerTimeout(err) && !retry?.signerRetried) {
      retrying = true
      console.error('join waiting for signer:', describeError(err))
      setStatus(SIGNER_WAITING, 'progress')
      if (generation === roomGeneration) { await startSession(asVisitor, { deadline: Date.now() + 20_000, signerRetried: true }); return }
      return
    }
    const message = describeError(err)
    if (isSignerTimeout(err)) {
      console.error('join failed:', message)
      setStatus(SIGNER_SILENT)
    } else if (message.includes('expired')) {
      forgetCredential()
      setStatus('This device\u2019s pass for this room has run out. Ask your other device for a new one.')
    } else if (isNetworkFailure(err)) {
      // A relay-pool failure is the jargon this collapses (M6): the room's
      // own words stay in the console, for a bug report, and the person
      // reads the plain instruction instead of "every relay rejected\u2026".
      console.error('join failed:', message)
      setStatus(describeFailureForPerson(err))
    } else {
      // Anything else already says something a person can act on - a TURN
      // relay missing, a stale invitation - so it keeps saying it.
      setStatus(`Could not join the room. ${message}. Check your connection or sign-in, then try again.`)
    }
  } finally {
    if (!retrying) {
      disarmStopOpening()
      joining = false
      joinBtn.disabled = false
      $('joinRoomForm').removeAttribute('aria-busy')
      renderIdentity()
    }
  }
}

/**
 * The newest message on screen is the newest read, once it has actually
 * been on screen: a tab in the background is not being read, whatever its
 * log holds, so it catches up when it comes back. This is what the unread
 * count on the rooms list is measured against.
 */
function noteChatRead(messages: ChatMessage[]): void {
  if (currentChannel !== undefined || !canReadVisibleChat()) return
  const roomId = currentRoomId()
  if (!roomId) return
  let newest = 0
  let newestId: string | undefined
  for (const m of messages) {
    if (m.sentAt > newest || (m.sentAt === newest && newestId !== undefined && m.id > newestId)) {
      newest = m.sentAt
      newestId = m.id
    }
  }
  if (newest > 0) {
    markRead(roomStore(), roomId, newest, messages.filter(m => m.sentAt === newest).map(m => m.id))
    updateDesktopUnread()
    readSync?.note(roomId, { '': newestId ? { at: newest, id: newestId } : { at: newest } })
  }
}

document.addEventListener('visibilitychange', () => {
  if (document.visibilityState !== 'visible') return
  notifier.seen()
  if (!session) return
  try {
    noteChatRead(session.chat.messages())
  } catch {
    // Not joined yet: there is no chat to have read.
  }
})
window.addEventListener('focus', () => {
  notifier.seen()
  if (joining) return
  if (markConversationRead()) renderConversationNav()
  if (session) noteChatRead(session.chat.messages())
})
$('chatLog').addEventListener('scroll', () => {
  if (session && !joining && currentChannel === undefined) noteChatRead(session.chat.messages())
})

// ---------------------------------------------------------------------------
// Your rooms
//
// The rooms this device has been in, shown when the app opens with no link
// on it. Each is watched from outside while the list is on screen - see
// app/src/room-watch.ts - which needs the room key, and this list holds no
// keys of its own: it uses whatever the app already keeps. A room this
// device created or joined as a group retains its key until forgotten;
// temporary rooms retain their shorter local lifetimes. A room whose
// key this device does not hold right now says so, and opening it is what
// gets the key back.
// ---------------------------------------------------------------------------

const roomWatches = new Map<string, { pool: ManagedRelayPool; watch: RoomWatch }>()
let workspaceWork: WorkspaceWorkPanel | undefined
let boardsPanel: BoardsPanel | undefined
const roomBoards = new Map<RoomSession, RoomBoards>()
const openingRoomBoards = new Map<RoomSession, RoomBoards>()
const closingRoomBoards = new Map<RoomSession, Promise<void>>()
/** Revocation is immediate. Keep captured closing owners until their join
 * succeeds; a failed close cannot turn into permission to clear the signer. */
function closeRoomBoardCatalogues(selected?:RoomSession):Promise<void> {
  const owners=new Map([...roomBoards,...openingRoomBoards])
  for(const [s,boards]of owners){if(selected&&s!==selected)continue
    roomBoards.delete(s);openingRoomBoards.delete(s)
    const job=Promise.resolve().then(()=>boards.close());closingRoomBoards.set(s,job)
    void job.then(()=>{if(closingRoomBoards.get(s)===job)closingRoomBoards.delete(s)},()=>{})
    boards.revoke()
  }
  return Promise.all([...closingRoomBoards].filter(([s])=>!selected||s===selected).map(([,job])=>job)).then(()=>{})
}
function attachRoomBoards(s: RoomSession): void {
  const account = nostrSession
  if (!account?.signer.nip44 || s.participant !== account.pubkey || roomBoards.has(s) || openingRoomBoards.has(s) || closingRoomBoards.has(s)) return
  const current=()=>nostrSession===account&&(session===s||dockedCall?.session===s)
  const custody=legacyRoomBoardCatalogueCustody({account:account.pubkey,roomId:s.roomId,
    store:isQuietPolicy(roomPolicy)?memoryDeviceStore():deviceStore,
    crypt:signerSelfCrypt({pubkey:account.pubkey,nip44:account.signer.nip44}),current})
  const boards = new RoomBoards(s, {custody,current,
    changed: () => { boardsPanel?.sync(); renderConversationNav() }, report: error => setStatus(describeError(error))})
  openingRoomBoards.set(s,boards)
  void boards.open().then(()=>{
    if(openingRoomBoards.get(s)!==boards)return boards.close()
    if(!current())return closeRoomBoardCatalogues(s)
    openingRoomBoards.delete(s);roomBoards.set(s,boards);boardsPanel?.sync();if(session===s)renderConversationNav()
  }).catch(async error=>{if(openingRoomBoards.get(s)===boards)await closeRoomBoardCatalogues(s);else await boards.close();if(current())setStatus(describeError(error))})
    .catch(error=>{if(current())setStatus(describeError(error))})
}
let roomsTimer: ReturnType<typeof setInterval> | undefined
/** Whether the start page (no room open) is what the main pane shows. The
 *  list column itself is on screen whenever there is anything to list. */
let roomsListShown = false

/** The chip chosen above the list: everything, what has unread messages,
 *  what mentions you, or one project's key (see `projectChoices`). */
let listFilter = 'all'

/** The room secret behind a known room, when this device holds it: the
 *  creator's record, this tab's admission, or one the person chose to
 *  keep. */
function secretForKnownRoom(link: RoomLink): Uint8Array | undefined {
  if (link.secret) return link.secret
  if (!link.invitation) return undefined
  return (
    loadInvitationOwner(link.invitation)?.roomSecret ??
    loadCachedAdmission(link.invitation)?.secret ??
    loadKeptAdmission(deviceStore, deriveInvitationId(link.invitation), nowSeconds())?.secret
  )
}

function watchKnownRoom(room: KnownRoom): void {
  // The room on screen, or at its door, is not watched a second time.
  if (room.roomId === currentRoomId()) return
  if (roomWatches.has(room.roomId) || room.endedAt !== undefined || conferenceEnded(room.endsAt, nowSeconds())) return
  let link: RoomLink
  try {
    link = parseRoomLink(room.link)
  } catch {
    return
  }
  const secret = secretForKnownRoom(link)
  if (!secret) return
  const { roomId, roomKey } = deriveRoom(secret)
  // A key that does not open this room is not this room's key.
  if (roomId !== room.roomId) return
  const pool = relayConnections.pool(`room:${room.roomId}`, link.relays)
  // A message in a room on the list is a message in a room not on screen,
  // and the list is what this device reads other rooms with.
  const notify = notifier.follow({
    roomId,
    channel: 'chat',
    room: () => knownRoomLabel(knownRoom(roomStore(), roomId) ?? room),
    sender: senderLabel,
    // The viewer is never in `present()` here - this device is not in the
    // room - so a name-in-text mention of them would otherwise be missed.
    roster: () => [...watch.present(), { participant: meParticipant || currentParticipant() || '', name: joiningName() }],
    direct: () => dmPeerOf(room) !== undefined,
  })
  const epoch = loadRoomEpoch(roomId)
  // The epochs before it, when what this device kept says where the room is.
  const kept = loadKeptRoomEpoch(deviceStore, roomId)
  const pastEpochs = kept && epoch && kept.epoch.epoch === epoch.epoch ? pastRootsOf(kept) : []
  // This device's copy of a rekey opens with its key for the room and the
  // seal keys its credentials named there, as the session's does.
  const authority = link.invitation?.inviter
  const deviceSk = loadDeviceKeyFor(deviceStore, roomId) ?? loadDeviceKeyFor(browserDeviceStore(sessionStorage), roomId)
  let named: RoomNameRecord | undefined
  const followName = (): void => {
    const name = watch.roomName()
    if (!name || name === named) return
    named = name
    adoptWatchedRoomName(roomId, name)
  }
  const followLogo = (): void => {
    if (session?.roomId === roomId) return
    const logo = watch.roomLogo(), kept = roomLogoCache.get(roomId)
    if (!logo) { if (kept && kept.epoch < watch.epoch) roomLogoCache.forget(roomId); return }
    if (kept?.epoch === watch.epoch && compareRoomLogos(logo, kept.record) === 0) return
    roomLogoCache.keep(roomId, logo, watch.epoch, room.endsAt === undefined && !room.destruct)
  }
  const watch = new RoomWatch({
    transport: pool,
    roomId,
    roomKey,
    policy: link.policy,
    quiet: isQuietPolicy(link.policy),
    logo: roomLogoCache.get(roomId),
    ...(epoch ? { epoch } : {}),
    ...(pastEpochs.length ? { pastEpochs } : {}),
    // Following the authority's rekeys, so a room not opened since its key
    // turned still shows what is said in it. A device the rekey left out
    // (removed, or the room closed) has no copy, and the room reads quiet
    // here until it is opened, as before.
    ...(authority && deviceSk ? {
      authority,
      deviceSk,
      sealSks: () => loadOwnSealKeysFor(deviceStore, roomId).reverse(),
      onEpoch: (moved: WatchedRekey) => keepWatchedRekey(roomId, secret, moved),
      // Closed while this device was not in it: the list says so, and a
      // room that self-destructs is tidied away from here.
      onClosed: (notice: { destruct?: true }) => {
        if (notice.destruct) { markRoomDestruct(roomId); destructSecrets.set(roomId, secret) }
        for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) markEnded(store, roomId, nowSeconds())
        queueMicrotask(() => {
          stopWatching(roomId)
          if (roomIsDestruct(roomId)) void runDueDestructs()
          renderRooms()
        })
      },
    } : {}),
    onChange: () => {
      // The name first, so the redraw below shows it.
      followName()
      followLogo()
      renderRooms()
      notify(watch.messages())
    },
  })
  followName()
  followLogo()
  notify(watch.messages())
  roomWatches.set(room.roomId, { pool, watch })
  followReadPositions(roomId, roomKey, room.endsAt)
}

function stopWatching(roomId: string): void {
  const watched = roomWatches.get(roomId)
  if (!watched) return
  roomWatches.delete(roomId)
  // A socket that is already going down must not stop the list drawing.
  try { watched.watch.close() } catch { /* Closing a closed watch is not news. */ }
  try { watched.pool.close() } catch { /* Nor is closing its pool. */ }
}

/** Chats the list is watching: a relay connection each, so the previews,
 *  times and counts are the room's own and not a guess. Run from the start
 *  page and from inside a room alike, because the list is in both. */
function startListWatches(): void {
  const rooms = navigationRooms()
  const ids = new Set(rooms.map(room => room.roomId))
  for (const roomId of roomWatches.keys()) if (!ids.has(roomId)) stopWatching(roomId)
  for (const room of rooms) {
    // The room on screen has a session of its own.
    if (room.roomId === currentRoomId()) stopWatching(room.roomId)
    else watchKnownRoom(room)
  }
  // Presence lapses by the clock, not by an event, so the list is redrawn
  // on a timer as well as on every change.
  if (rooms.length && roomsTimer === undefined) roomsTimer = setInterval(renderRooms, 5000)
}

function showRoomsList(): void {
  pendingJoin = false
  $('nostrOption').hidden = true
  $('home').hidden = false
  $('identity').hidden = true
  $('identityMore').hidden = true
  $('homeStatus').append($('status'))
  // Notifications & sound lives in Settings now, not loose on the page -
  // see enterSettings, which is the only thing that ever unhides it here.
  $('notify').hidden = true
  roomsListShown = true
  // The start page is the list level: below 900 px it is what shows.
  closeDetail()
  renderWayBack()
  startListWatches()
  renderRooms()
}

/** A room is on screen, or its door. The list stays: it is a column of the
 *  shell, not a page, and it keeps watching what it lists. */
function hideRoomsList(): void {
  legacyMessagesPanel?.close()
  roomsListShown = false
  $('home').hidden = true
  startListWatches()
  renderRooms()
}

/** The order the list last drew in, held while focus or the pointer is
 *  inside it (spec section 7: "rows never reorder under the user"). */
let lastRoomOrder: string[] | undefined

function roomIsEnded(room: KnownRoom): boolean {
  return room.endedAt !== undefined || conferenceEnded(room.endsAt, nowSeconds())
}

/** Unread messages from people in a room the list is watching. */
function roomUnreadPeople(room: KnownRoom): number {
  const watched = roomWatches.get(room.roomId)
  if (!watched || !watched.watch.readsChat) return 0
  return watched.watch.unread(room.readAt, meParticipant || currentParticipant() || '', joiningName(), room.readIds).people
}

/** Whether a message since this room was last read names the viewer or
 *  replies to them: the Mentions chip and the @ on the row. */
function roomHasMention(room: KnownRoom): boolean {
  const watched = roomWatches.get(room.roomId)
  const self = meParticipant || currentParticipant() || ''
  if (!watched?.watch.readsChat || !self) return false
  const roster = [...watched.watch.present(), { participant: self, name: joiningName() }]
  return workspaceMentions(watched.watch.messages(), self, room, roster).length > 0
}

/** Private conversations somebody has asked this account for, shown above
 *  every chat while they wait. The same filter the contacts sheet uses. */
function waitingInvitations() {
  const state = contactInbox?.snapshot(), self = nostrSession?.pubkey
  if (!state || !self) return []
  return state.invitations.filter(invitation => invitation.sender !== self && !bookmarks?.forgotten(invitation.room) && !knownRoom(roomStore(), invitation.room))
}

/** The chips above the list. Projects stop being sections: each one is a
 *  chip, and only when some exist (Q6). Drawn only when the set changes, so
 *  a chip a person is pressing is never replaced under them. */
function renderChatFilters(projects: Array<{ key: string; name: string }>): void {
  const group = $('chatFilters')
  const wanted: Array<[string, string]> = [['all', 'All'], ['unread', 'Unread'], ['mentions', 'Mentions'], ...projects.map(p => [p.key, p.name] as [string, string])]
  if (!wanted.some(([key]) => key === listFilter)) listFilter = 'all'
  const shape = JSON.stringify(wanted)
  if (group.dataset.shape !== shape) {
    group.dataset.shape = shape
    group.replaceChildren(...wanted.map(([key, label]) => {
      const chip = document.createElement('button')
      chip.type = 'button'
      chip.className = 'chip'
      chip.dataset.filter = key
      chip.textContent = label
      chip.addEventListener('click', () => { listFilter = key; lastRoomOrder = undefined; renderRooms() })
      return chip
    }))
  }
  for (const chip of group.querySelectorAll<HTMLButtonElement>('.chip')) chip.setAttribute('aria-pressed', String(chip.dataset.filter === listFilter))
}

const FOLD_PREFIX = 'kithmoot.home.fold.'

function sectionFolded(section: RoomSection): boolean {
  if (!FOLDABLE[section]) return false
  try { return localStorage.getItem(FOLD_PREFIX + section) !== 'open' } catch { return true }
}

function setSectionFolded(section: RoomSection, folded: boolean): void {
  try { localStorage.setItem(FOLD_PREFIX + section, folded ? 'closed' : 'open') } catch { /* Folding still works for this visit. */ }
}

/** The section each room was drawn in, held with the order while the pointer
 *  or focus is in the list: reading a room moves it between sections, which
 *  is a reorder like any other. */
let lastRoomSections: Map<string, RoomSection> | undefined

function sectionHead(section: RoomSection, count: number, folded: boolean): HTMLLIElement {
  const row = document.createElement('li')
  row.className = 'roomSection'
  row.dataset.section = section
  const heading = document.createElement('h3')
  if (FOLDABLE[section]) {
    const fold = document.createElement('button')
    fold.type = 'button'
    fold.className = 'sectionFold'
    fold.dataset.section = section
    fold.setAttribute('aria-expanded', String(!folded))
    fold.textContent = sectionHeading(section, count, folded)
    heading.append(fold)
  } else {
    heading.textContent = sectionHeading(section, count, false)
  }
  row.append(heading)
  return row
}

function listHeading(text: string): HTMLLIElement {
  const row = document.createElement('li')
  row.className = 'roomSection'
  const heading = document.createElement('h3')
  heading.textContent = text
  row.append(heading)
  return row
}

let roomListPress = false, roomListPaintPending = false
document.addEventListener('pointerdown', event => {
  if ((event.target as Element | null)?.closest('#roomList .open')) roomListPress = true
}, { capture: true, passive: true })
const releaseRoomListPress = (): void => {
  setTimeout(() => {
    roomListPress = false
    if (roomListPaintPending) { roomListPaintPending = false; renderRooms() }
  }, 0)
}
for (const type of ['pointerup', 'pointercancel']) window.addEventListener(type, releaseRoomListPress, { capture: true })
window.addEventListener('blur', releaseRoomListPress)

function renderRooms(): void {
  // A conference room ends by the clock, with no event to say so. The list
  // is redrawn on a timer, so this is where one that has ended is written
  // down as ended and stops being watched.
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) {
    for (const roomId of endLapsedConferences(store, nowSeconds())) stopWatching(roomId)
  }
  // And a self-destructing one is tidied away, here as at launch.
  if (!destructRun && dueDestructRooms().some(room => !destructing.has(room.roomId))) void runDueDestructs()
  retryFileDeletes()
  workspaceWork?.sync()
  boardsPanel?.sync()
  updateDesktopUnread()
  // People is for somebody signed in with Nostr, and nobody else (Q14).
  setPeopleAvailable(!!nostrSession)
  // A contact's page reads what these watches hear: who has come into a room.
  // Queued, so nothing in People can stop the list below from being drawn.
  queueMicrotask(renderPeople)
  publishDesktopMenu()
  const importable = browserRoomsToImport()
  $('importBrowserRooms').hidden = !nostrSession || importable.length === 0
  $('importBrowserRooms').textContent = `Add the ${importable.length === 1 ? 'room' : `${importable.length} rooms`} already here`
  const rooms = navigationRooms()
  profiles.want(rooms.flatMap(room => { const peer = dmPeerOf(room); return peer ? [peer] : [] }))
  const queryField = $('homeRoomQuery') as HTMLInputElement
  const query = queryField.value.trim().toLocaleLowerCase()
  const projects = projectChoices(rooms)
  renderChatFilters(projects)
  const project = listFilter.startsWith('shared:') || listFilter.startsWith('project:') ? listFilter : '*'
  const activityOf = (room: KnownRoom): number => activityAt(room, roomWatches.get(room.roomId)?.watch.messages() ?? [])
  const unreadOf = (room: KnownRoom): number => session && room.roomId === currentRoomId() ? currentRoomUnreadSplit().people : roomUnreadPeople(room)
  const passes = (room: KnownRoom): boolean =>
    listFilter === 'unread' ? unreadOf(room) > 0 : listFilter === 'mentions' ? roomHasMention(room) : true
  const matched = rooms.filter(room => matchesRoom(room, query, project) && passes(room))
  const pins = loadPins(localStorage)
  const pinned = (room: KnownRoom) => pins.has(room.roomId)
  const sorted = pinnedFirst(sortByActivity(matched, activityOf), pinned)
  const list = $('roomList')
  const held = list.contains(document.activeElement) || list.matches(':hover')
  let filtered = sorted
  if (!held) lastRoomSections = undefined
  if (held && lastRoomOrder) {
    const byId = new Map(sorted.map(room => [room.roomId, room]))
    const inOrder = lastRoomOrder.map(id => byId.get(id)).filter((room): room is KnownRoom => room !== undefined)
    const seen = new Set(inOrder.map(room => room.roomId))
    filtered = [...inOrder, ...sorted.filter(room => !seen.has(room.roomId))]
  } else {
    lastRoomOrder = sorted.map(room => room.roomId)
  }
  const invitations = waitingInvitations()
  // A muted room's number stays on its row, but is not counted on the rail.
  setCounts({ chats: [...rooms].reduce((total, room) => total + (roomIsMuted(room.roomId) ? 0 : unreadOf(room)), 0) + invitations.length })
  renderInvitations()
  const hidden = disconnectedAccountRooms()
  // A signed-in account keeps the list on screen even before its first room
  // or project arrives: the reconnect banner lives in it, and it must stay
  // reachable from the first moment somebody who can use it is signed in.
  // A sign-in from an earlier visit is restored after the first paint, and
  // a bunker can take seconds. Until it lands this is somebody whose rooms
  // are on their way, not a stranger to welcome, and the rooms this browser
  // holds on its own are not the list they are about to see.
  const restoring = identityRestoring && !!expectedAccount && !nostrSession
  const destroyed = tombstones(deviceStore, nowSeconds())
  const returning = rooms.length > 0 || destroyed.length > 0 || !!nostrSession || accountDisconnected() || restoring
  $('home').dataset.state = returning ? 'returning' : 'cold'
  $('home').setAttribute('aria-labelledby', 'homeHeading')
  $('rooms').hidden = !returning
  document.documentElement.dataset.list = returning ? 'on' : 'off'
  renderHomeSyncStatus()
  $('accountReconnect').hidden = !accountDisconnected()
  $('homeSignIn').hidden = !!nostrSession || restoring || returning
  // A returning list keeps the way to sign in on the rail, where Settings is.
  $('headerSignIn').hidden = !!nostrSession || restoring || !returning
  list.hidden = restoring
  $('roomsEmpty').textContent = restoring ? 'Loading your chats…' : ''
  $('roomsEmpty').hidden = !restoring
  if (accountDisconnected()) {
    // The account by its name, never its key. One button, whatever the signer.
    const who = expectedAccount ? shownAs(expectedAccount).name ?? lastKnownProfileNames.get(expectedAccount) : undefined
    $('accountReconnectText').textContent = who ? `Reconnect ${who} to see its rooms.` : 'Reconnect your Nostr account to see its rooms.'
    $('accountReconnectButton').textContent = 'Reconnect'
  }
  $('clearHomeRoomQuery').hidden = !query
  // Nothing matches: say so, with a way back to everything.
  const filtering = !!query || listFilter !== 'all'
  const noMatch = filtering && !filtered.length && !invitations.length && rooms.length > 0
  const results = $('homeRoomResults')
  results.hidden = !noMatch
  results.replaceChildren()
  if (noMatch) {
    results.append('No chats match. ')
    const clear = document.createElement('button')
    clear.type = 'button'
    clear.className = 'quiet linkish'
    clear.dataset.action = 'clear-filters'
    clear.textContent = 'Clear'
    clear.addEventListener('click', () => {
      queryField.value = ''
      listFilter = 'all'
      lastRoomOrder = undefined
      renderRooms()
      queryField.focus({ preventScroll: true })
    })
    results.append(clear)
  }
  const busy = switchingBlocked()
  // Leaving for the start page ends the room's session, which unsent work would not survive.
  $('appHome').setAttribute('aria-disabled', String(hasUnsentWork()))
  $('workspaceNote').textContent = !session ? ''
    : busy ? 'Finish sending or stop adding files before switching. You can also open the other room in a new tab.'
    : callIsLive() || onCall() ? 'Your call carries on while you visit other rooms. Choose its room again, or Back to the call, to return.'
    : hasUnsentWork() ? 'Your drafts stay here while you switch.' : ''
  const focused = document.activeElement as HTMLElement | null
  const focusedRoom = focused && list.contains(focused) ? focused.closest<HTMLElement>('[data-room]')?.dataset.room : undefined
  const action = focused?.dataset.action
  // A row's menu lives inside the row, so redrawing the rows takes an open
  // menu away from under the person about to choose from it: a preview
  // arriving was enough. Held until the menu closes, then drawn.
  const openMenu = Array.from(list.querySelectorAll<HTMLElement>('.rowMenuPopover')).find(menu => {
    try { return menu.matches(':popover-open') } catch { return false }
  })
  if (openMenu) {
    if (!openMenu.dataset.redraw) {
      openMenu.dataset.redraw = 'pending'
      openMenu.addEventListener('toggle', () => renderRooms(), { once: true })
    }
    return
  }
  // A repaint must not replace a row between a press and its click.
  if (roomListPress) { roomListPaintPending = true; return }
  list.innerHTML = ''
  // Rooms that self-destructed, greyed, naming none (D2), until dismissed or
  // a week has passed: nobody is left wondering where a room went.
  if (!query && listFilter === 'all') for (const tombstone of destroyed) list.append(tombstoneRow(tombstone.id, tombstone.at))
  // Pinned, then one group of chats, then Older and Ended folded away. A
  // search, a chip, or a short list is one flat list with the pinned first,
  // and never hides a match in a closed fold.
  const flat = !!query || listFilter !== 'all' || rooms.length <= SECTION_THRESHOLD
  if (flat) {
    const heads = filtered.some(pinned) || invitations.length > 0
    let section = ''
    for (const room of filtered) {
      const here = pinned(room) ? 'Pinned' : 'Chats'
      if (heads && here !== section) { section = here; list.append(listHeading(here)) }
      list.append(roomRow(room, project))
    }
  } else {
    const now = nowSeconds()
    const freshSection = (room: KnownRoom): RoomSection =>
      sectionOf({ pinned: pinned(room), ended: roomIsEnded(room), unread: roomUnreadPeople(room), activity: activityOf(room) }, now)
    let sectionFor = freshSection
    const kept = lastRoomSections
    if (held && kept) sectionFor = room => kept.get(room.roomId) ?? freshSection(room)
    else lastRoomSections = new Map(filtered.map(room => [room.roomId, freshSection(room)] as const))
    const where = (room: KnownRoom): RoomSection => sectionFor(room)
    const pinnedRooms = filtered.filter(room => where(room) === 'pinned')
    const chats = filtered.filter(room => ['unread', 'recent', 'other'].includes(where(room)))
    if (pinnedRooms.length) { list.append(listHeading('Pinned')); for (const room of pinnedRooms) list.append(roomRow(room, project)) }
    if (chats.length) { list.append(listHeading('Chats')); for (const room of chats) list.append(roomRow(room, project)) }
    for (const fold of ['older', 'ended'] as const) {
      const members = filtered.filter(room => where(room) === fold)
      if (!members.length) continue
      const folded = sectionFolded(fold)
      list.append(sectionHead(fold, members.length, folded))
      if (!folded) for (const room of members) list.append(roomRow(room, project))
    }
  }
  // The list is one tab stop. Arrow keys move between rows; the row in the
  // room that is open, or the one the person was on, is the stop.
  const opens = Array.from(list.querySelectorAll<HTMLButtonElement>('.roomRow .open'))
  const stop = opens.find(open => open.closest<HTMLElement>('[data-room]')?.dataset.room === focusedRoom)
    ?? opens.find(open => open.getAttribute('aria-current') === 'true') ?? opens[0]
  for (const open of opens) open.tabIndex = open === stop ? 0 : -1
  for (const menu of list.querySelectorAll<HTMLElement>('.rowMenu')) menu.tabIndex = -1
  if (focusedRoom && action) {
    const row = Array.from(list.children).find(row => (row as HTMLElement).dataset.room === focusedRoom)
    const replacement = row?.querySelector<HTMLElement>(`[data-action="${action}"]`)
    ;(replacement ?? queryField).focus({ preventScroll: true })
  }
}

function browserRoomsToImport(): KnownRoom[] {
  return nostrSession ? knownRooms(deviceStore).filter(room => !knownRoom(roomStore(), room.roomId)) : []
}

function confirmRoomAction(options: ConfirmActionOptions): Promise<boolean> {
  const room = session
  const account = nostrSession?.pubkey
  const generation = roomGeneration
  return confirmAction({ ...options, isCurrent: () => room === session && account === nostrSession?.pubkey && generation === roomGeneration })
}

function chooseRoomAction(options: ChooseActionOptions): ReturnType<typeof chooseAction> {
  const room = session
  const account = nostrSession?.pubkey
  const generation = roomGeneration
  return chooseAction({ ...options, isCurrent: () => room === session && account === nostrSession?.pubkey && generation === roomGeneration })
}

function confirmDiscardAndLeave(): Promise<boolean> {
  return confirmRoomAction({ title: 'Leave and discard your draft?', message: 'Unsent messages and files in every room visited in this tab will be discarded.', confirmLabel: 'Discard and leave', cancelLabel: 'Keep working', danger: true })
}

async function importBrowserRooms(): Promise<void> {
  const rooms = browserRoomsToImport()
  if (!bookmarks || !rooms.length) return
  const destination = nostrSession?.signer.nip44
    ? 'Their names and invitation links will be encrypted to your Nostr key and sent to relays.'
    : 'This signer cannot encrypt, so these bookmarks will stay in this browser only.'
  if (!await confirmRoomAction({ title: 'Add these rooms to your account?', message: `${rooms.map(knownRoomLabel).join('\n')}\n\n${destination}`, confirmLabel: 'Add rooms' })) return
  for (const room of rooms) bookmarks.save(room)
  renderRooms()
}

/** What a row's second line, time, unread pill, presence and accessible
 *  description say, worked out once so the row can just render it. Line 2
 *  follows the precedence in the spec's copy table: ended, then no key held,
 *  then quiet, then the newest message, then "No messages yet". */
interface RoomRowState {
  preview: string
  time: string
  unreadVisible?: string
  unreadSpoken?: string
  unreadCount: number
  agentCount: number
  presence?: { visible: string; spoken: string }
  presenceCount: number
  /** A message since the room was last read names the viewer. */
  mention?: boolean
  description: string
}

const NO_MESSAGES = 'No messages yet'
/** A room whose history this device has not loaded has no last line to show. */
const CATCH_UP = 'Open it to catch up.'
/** A drawing pin, in the text's own colour: an emoji pin is red in every theme. */
/** A symbol from the icon sprite, for decoration beside text. */
function spriteIcon(name: string): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('class', 'i')
  svg.setAttribute('aria-hidden', 'true')
  svg.setAttribute('focusable', 'false')
  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use')
  use.setAttribute('href', `#i-${name}`)
  svg.append(use)
  return svg
}

function pinIcon(): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('viewBox', '0 0 24 24')
  svg.setAttribute('width', '14')
  svg.setAttribute('height', '14')
  svg.setAttribute('fill', 'currentColor')
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
  path.setAttribute('d', 'M16 9V4h1a1 1 0 0 0 0-2H7a1 1 0 0 0 0 2h1v5c0 1.66-1.34 3-3 3v2h5.97v7l1 1 1-1v-7H19v-2c-1.66 0-3-1.34-3-3z')
  svg.append(path)
  return svg
}

function roomRowState(room: KnownRoom): RoomRowState {
  // The room on screen is read from its own session, not from a second
  // connection the list would hold to it.
  const here = !!session && room.roomId === currentRoomId()
  const time = formatActivityTime(activityAt(room, here ? conversationMessages(undefined) : roomWatches.get(room.roomId)?.watch.messages() ?? []))
  if (room.endedAt !== undefined || conferenceEnded(room.endsAt, nowSeconds())) {
    const preview = room.endsAt !== undefined && room.endsAt <= (room.endedAt ?? room.endsAt)
      ? `Conference room. Ended ${formatConferenceEnd(room.endsAt)}.`
      : 'Ended. Its invite link no longer works.'
    return { preview, time, unreadCount: 0, agentCount: 0, presenceCount: 0, description: preview }
  }
  const watched = roomWatches.get(room.roomId)
  if (!watched && !here) {
    const preview = CATCH_UP
    return { preview, time, unreadCount: 0, agentCount: 0, presenceCount: 0, description: preview }
  }
  if (watched && !watched.watch.readsChat && !here) {
    // A quiet room's chat is not read from the list: it would cost the whole
    // gift-wrap stream per room in the background. Open it to read.
    const preview = 'Quiet room. Open it to read.'
    return { preview, time, unreadCount: 0, agentCount: 0, presenceCount: 0, description: preview }
  }

  const self = meParticipant || currentParticipant() || ''
  const messages = here ? conversationMessages(undefined) : watched!.watch.messages()
  const latest = messages.reduce<ChatMessage | undefined>((best, m) => (!best || m.sentAt > best.sentAt ? m : best), undefined)
  const nameOf = (participant: string): string =>
    shownAs(participant, messages.find((m) => m.participant === participant)?.name).name ?? 'Somebody'
  const preview = (latest && previewLine(latest, self, nameOf)) ?? NO_MESSAGES

  // The room on screen counts what is unread in every one of its
  // conversations, including a call's hidden chat; the rest count from
  // their watch against the saved read position.
  const split = here ? currentRoomUnreadSplit() : watched!.watch.unread(room.readAt, self, joiningName(), room.readIds)
  const mention = !here && roomHasMention(room)
  const unreadVisible = split.people > 0 ? (split.people > 99 ? '99+' : String(split.people)) : undefined
  const unreadSpoken = split.people > 0 ? `${split.people} unread` : undefined

  const present = here ? [] : watched!.watch.present()
  const presence = present.length > 0 ? presenceText(present) : undefined
  if (present.length) profiles.want(present.map((p) => p.participant))

  const description = [unreadSpoken, mention ? 'Mentions you' : '', preview, time, presence?.spoken].filter(Boolean).map(part => part!.replace(/([^.])\.$/, '$1')).join('. ')
  return { preview, time, unreadVisible, unreadSpoken, unreadCount: split.people, agentCount: split.agents, presence, presenceCount: present.length, mention, description }
}

/** One row of the rooms list: the whole name and preview area is a single
 *  button (kept as `data-action="open"` and `aria-label="Open {room}"`, for
 *  the specs that already read that), a `⋯` menu for the actions that used
 *  to sit on the row at the same weight as opening it, and a hidden
 *  description carrying the fuller sentence a screen reader wants. */
function roomRow(room: KnownRoom, project?: string): HTMLLIElement {
  const label = knownRoomLabel(room)
  const state = roomRowState(room)
  const row = document.createElement('li')
  row.className = 'roomRow'
  row.dataset.room = room.roomId

  const descId = `roomDesc-${room.roomId}`

  const open = document.createElement('button')
  open.type = 'button'
  open.className = 'open'
  open.dataset.action = 'open'
  open.setAttribute('aria-label', `Open ${label}`)
  open.setAttribute('aria-describedby', descId)
  // Nothing is switched while a send or an upload is in flight.
  open.disabled = switchingBlocked() && room.roomId !== currentRoomId()
  // The chat on screen is the selected row.
  if (room.roomId === currentRoomId()) open.setAttribute('aria-current', 'true')
  open.addEventListener('click', () => { void switchRoom(room, project) })

  const ended = roomIsEnded(room)
  const pinned = loadPins(localStorage).has(room.roomId)
  if (state.unreadCount > 0) row.classList.add('hasUnread')
  const avatar = document.createElement('span')
  avatar.className = 'roomAvatar'
  const peer = dmPeerOf(room)
  // A private chat wears the person's avatar: their initial and the colour
  // People gives them.
  avatar.dataset.slot = ended ? 'ended' : String(avatarSlot(peer ?? room.roomId))
  avatar.setAttribute('aria-hidden', 'true')
  avatar.textContent = avatarInitial(peer ? dmPersonName(room, peer) : label)
  if (!peer && !isQuietRoom(room)) renderLogo(avatar, displayedRoomLogo(room.roomId, project), label)
  const picture = peer ? profiles.get(peer)?.picture : undefined
  if (picture) {
    const image = document.createElement('img')
    image.alt = ''
    image.loading = 'lazy'
    image.referrerPolicy = 'no-referrer'
    image.src = picture
    image.addEventListener('error', () => image.remove(), { once: true })
    avatar.append(image)
  }
  const text = document.createElement('span')
  text.className = 'roomText'
  const name = document.createElement('span')
  name.className = 'roomName'
  name.textContent = label
  text.append(name)
  // An empty room is one line: "No messages yet" under every quiet room was
  // most of what a long list said. The description below still says it.
  if (state.preview !== NO_MESSAGES && state.preview !== CATCH_UP) {
    const preview = document.createElement('span')
    preview.className = 'roomPreview'
    preview.textContent = state.preview
    text.append(preview)
  }
  // The countdown, for a room that ends and has not yet.
  const countingDown = room.endsAt !== undefined && !ended
  if (countingDown) {
    const pill = fusePill(room.endsAt!, room.startsAt, !!room.destruct)
    pill.setAttribute('aria-hidden', 'true')
    text.append(pill)
  }
  open.append(avatar, text)

  const aside = document.createElement('div')
  aside.className = 'roomAside'
  const time = document.createElement('span')
  time.className = 'roomTime'
  if (pinned) {
    const pin = document.createElement('span')
    pin.className = 'roomPin'
    pin.setAttribute('aria-hidden', 'true')
    pin.append(pinIcon())
    time.append(pin)
  }
  const mute = roomMuteOf(room.roomId)
  if (mute !== undefined) {
    const glyph = document.createElement('span')
    glyph.className = 'roomMute'
    glyph.setAttribute('aria-hidden', 'true')
    glyph.append(spriteIcon('bellOff'))
    time.append(glyph)
  }
  time.append(state.time)
  aside.append(time)
  if (state.mention) {
    const at = document.createElement('span')
    at.className = 'mentionMark'
    at.textContent = '@'
    at.setAttribute('aria-label', 'Mentions you')
    aside.append(at)
  }
  if (state.unreadVisible) {
    const pill = document.createElement('span')
    pill.className = 'unread'
    pill.dataset.count = String(state.unreadCount)
    if (mute !== undefined) pill.dataset.muted = 'true'
    pill.textContent = state.unreadVisible
    pill.setAttribute('aria-label', state.unreadSpoken!)
    aside.append(pill)
  }
  if (state.agentCount > 0) aside.append(unreadBadge('unread agent', state.agentCount, `${state.agentCount} from agents`, { standalone: true }))
  if (state.presence) {
    const here = document.createElement('span')
    here.className = 'here'
    here.dataset.count = String(state.presenceCount)
    here.textContent = state.presence.visible
    here.setAttribute('aria-label', state.presence.spoken)
    aside.append(here)
  }

  const description = document.createElement('span')
  description.id = descId
  description.className = 'sr-only'
  const spokenFuse = countingDown ? fuseSpoken(room) : undefined
  // Each part loses its own full stop before they are joined, so no pair of
  // them reads "one.. 01:49".
  const unstopped = (part: string): string => part.replace(/([^.])\.$/, '$1')
  const spoken = [pinned ? 'Pinned' : '', mute !== undefined ? mutedUntilText(mute, nowSeconds()) : '', spokenFuse ?? '', state.description].filter(Boolean).map(unstopped)
  description.textContent = spoken.join('. ') + (state.description || !spoken.length ? '' : '.')

  const [menuOpener, menu] = roomRowMenu(room, label)
  row.append(open, aside, menuOpener, menu)
  // Right-click, and the Menu key or Shift+F10 on the focused row, open the
  // same menu where the pointer is (or the row, for a key).
  row.addEventListener('contextmenu', event => {
    event.preventDefault()
    const at = event.clientX || event.clientY ? { x: event.clientX, y: event.clientY } : { x: row.getBoundingClientRect().left + 16, y: row.getBoundingClientRect().bottom }
    rowMenuHandles.get(menu)?.openAt(at.x, at.y)
  })
  row.append(description)
  return row
}

/** A self-destructed room's row: the time it went, and Dismiss. */
function tombstoneRow(id: string, at: number): HTMLLIElement {
  const row = document.createElement('li')
  row.className = 'roomRow tombstoneRow'
  row.dataset.tombstone = id
  const text = document.createElement('span')
  text.className = 'tombstoneText'
  text.textContent = tombstoneText(at)
  const dismiss = document.createElement('button')
  dismiss.type = 'button'
  dismiss.className = 'quiet'
  dismiss.dataset.action = 'dismiss'
  dismiss.textContent = 'Dismiss'
  dismiss.setAttribute('aria-label', `Dismiss: ${tombstoneText(at)}`)
  dismiss.addEventListener('click', () => {
    dismissTombstone(deviceStore, id)
    renderRooms()
    ;$('homeRoomQuery').focus({ preventScroll: true })
  })
  row.append(text, dismiss)
  return row
}

let messageMenuCount = 0
/** The menu a right-click on a message opens, on the shared menu helper: the
 *  message's own actions as items, and its reactions behind React. It is made
 *  when asked for and goes when it closes, because the log it belongs to is
 *  drawn again whenever anything arrives. */
function openMessageMenu(opener: HTMLElement, x: number, y: number, actions: MessageAction[], reactions: MessageAction[], from: string): void {
  messageActions.close(false)
  const menu = document.createElement('div')
  menu.id = `messageMenu-${++messageMenuCount}`
  menu.setAttribute('aria-label', `Message from ${from}`)
  const named = (item: HTMLElement, action: MessageAction): void => { item.setAttribute('aria-label', action.label) }
  const [reply, ...rest] = actions
  if (reply) named(menuItem(menu, reply.text ?? reply.label, reply.run, { icon: 'reply', action: 'reply' }), reply)
  menuSubmenu(menu, 'React', sub => {
    for (const choice of reactions) {
      const more = choice.text === '+'
      named(menuItem(sub, more ? 'More emoji…' : choice.text ?? choice.label, choice.run, more ? { action: 'react-more' } : { checked: Boolean(choice.pressed), toggle: true, action: 'react' }), choice)
    }
  }, { icon: 'smile' })
  for (const action of rest) named(menuItem(menu, action.text ?? action.label, action.run, { danger: action.danger }), action)
  document.body.append(menu)
  const handle = wireMenu(opener, menu)
  menu.addEventListener('toggle', event => { if ((event as ToggleEvent).newState === 'closed') queueMicrotask(() => menu.remove()) })
  handle.openAt(x, y)
}

/** Mark a room read from its list row: everything it holds counts as seen,
 *  as though it had been opened. Only this device's read position moves (and
 *  the account's, where it syncs one); nothing is sent to the room. */
function markRoomRead(room: KnownRoom): void {
  const here = !!session && room.roomId === currentRoomId()
  const messages = here ? conversationMessages(undefined) : roomWatches.get(room.roomId)?.watch.messages() ?? []
  let newest = 0
  let newestId: string | undefined
  for (const m of messages) {
    if (m.sentAt > newest || (m.sentAt === newest && newestId !== undefined && m.id > newestId)) { newest = m.sentAt; newestId = m.id }
  }
  if (newest > 0) {
    markRead(roomStore(), room.roomId, newest, messages.filter(m => m.sentAt === newest).map(m => m.id))
    readSync?.note(room.roomId, { '': newestId ? { at: newest, id: newestId } : { at: newest } })
    updateDesktopUnread()
  }
  if (here) markConversationRead()
  renderRooms()
}

/** The row's `⋯` menu, on the shared menu helper (app/src/menu.ts): a native
 *  popover with the full keyboard model. Copy invite link is here because
 *  getting a friend in is one of the five stranger-test tasks and the link
 *  already sits on the row; Forget keeps its existing confirmation. Right-
 *  click, and the Menu key on the focused row, open the same menu. */
function roomRowMenu(room: KnownRoom, label: string): [HTMLButtonElement, HTMLDivElement] {
  const id = `roomMenu-${room.roomId}`
  const opener = document.createElement('button')
  opener.type = 'button'
  opener.className = 'rowMenu'
  opener.textContent = '⋯'
  opener.setAttribute('aria-label', `More for ${label}`)

  const menu = document.createElement('div')
  menu.id = id
  menu.className = 'rowMenuPopover'

  menuItem(menu, 'Mark as read', () => markRoomRead(room), { action: 'mark-read' })
  menuItem(menu, 'Copy invite link', () => {
    navigator.clipboard.writeText(room.link)
      .then(() => setStatus('Invite link copied.'))
      .catch((err) => setStatus(describeError(err)))
  })
  if (room.roomId !== currentRoomId()) menuItem(menu, 'Open in a new tab', () => {
    window.open(joinLinkBase() + new URL(room.link, location.href).hash, '_blank', 'noopener,noreferrer')
  }, { action: 'new-tab' })
  notificationsSubmenu(menu, room.roomId)
  const pinned = loadPins(localStorage).has(room.roomId)
  menuItem(menu, pinned ? 'Unpin' : 'Pin', () => {
    togglePinned(room)
    // The row moves; focus goes with it, to its ⋯ button.
    $('roomList').querySelector<HTMLElement>(`[data-room="${room.roomId}"] .rowMenu`)?.focus({ preventScroll: false })
  }, { action: 'pin' })
  menuItem(menu, 'Add to a project', () => openProjectEditor(room, opener))
  menuItem(menu, roomProject(deviceStore, nostrSession?.pubkey, room.roomId) ? 'Change local group' : 'Group on this browser', () => openLocalGroupEditor(room, opener))
  // The room on screen is left first; forgetting it from under the person would strand the conversation they are reading.
  if (room.roomId !== currentRoomId()) menuItem(menu, 'Forget this room', () => forgetKnownRoom(room), { danger: true, action: 'forget' })

  rowMenuHandles.set(menu, wireMenu(opener, menu))
  return [opener, menu]
}
const rowMenuHandles = new WeakMap<HTMLElement, MenuHandle>()

/** Opening a room from the list is opening its link. */
/** The other member of a direct message this identity is in, off the
 *  room's link, or undefined for any other room. Cached by link, because
 *  the rooms list asks on every repaint. */
const dmPeerCache = new Map<string, string | undefined>()
/** Whether a known room's link says it is a quiet one. */
function isQuietRoom(room: Pick<KnownRoom, 'link'>): boolean {
  try { return isQuietPolicy(parseRoomLink(room.link).policy) } catch { return false }
}

function dmPeerOf(room: Pick<KnownRoom, 'link'>): string | undefined {
  const me = meParticipant || currentParticipant()
  if (!me) return undefined
  const key = `${me}:${room.link}`
  if (!dmPeerCache.has(key)) {
    let peer: string | undefined
    try { peer = dmPeer(parseRoomLink(room.link).policy, me) } catch { peer = undefined }
    dmPeerCache.set(key, peer)
  }
  return dmPeerCache.get(key)
}

/** What to call a room on the list: a direct message is named for the
 *  person on the other end, everything else by `roomLabel`. */
/** The name a joined project gives this room, if any. */
function projectRoomName(roomId: string | undefined): string | undefined {
  if (!roomId) return undefined
  return sanitiseDisplayName(sharedProjects.sharedRooms().find(room => room.roomId === roomId)?.name)
}

function knownRoomLabel(room: KnownRoom): string {
  const peer = dmPeerOf(room)
  if (!peer) return roomLabel({ roomId: room.roomId, name: room.name ?? projectRoomName(room.roomId) })
  // A private chat is called by the person, as in any messenger (design-calm-shell
  // 6.2); a quiet one keeps its word, because it works differently.
  const name = dmPersonName(room, peer)
  return isQuietRoom(room) ? `Quiet: ${name}` : name
}

/** The person on the other end of a known private chat: the name remembered
 *  when the conversation was started or received, then whatever a profile
 *  says, then the key. A DM link carries no room name. */
function dmPersonName(room: KnownRoom, peer: string): string {
  return room.name ?? shownAs(peer).name ?? 'Private chat'
}

/** The room this page is in, named the same way. */
/** What to call the person on the other end of the room this page is in:
 *  what the roster says, then the name remembered when the conversation
 *  was started or received, then the key. */
function dmPeerName(peer: string): string {
  const onRoster = session?.participants().find((v) => v.participant === peer)?.name
  const remembered = knownRooms(roomStore()).find((room) => room.roomId === currentRoomId())?.name
  return shownAs(peer, onRoster ?? remembered).name ?? 'Private chat'
}

function currentRoomLabel(): string {
  const me = meParticipant || currentParticipant()
  const peer = me ? dmPeer(roomPolicy, me) : undefined
  if (peer) return isQuietPolicy(roomPolicy) ? `Quiet: ${dmPeerName(peer)}` : dmPeerName(peer)
  return roomLabel({ roomId: currentRoomId() ?? '', name: roomName })
}

function openKnownRoom(room: KnownRoom): void {
  void switchRoom(room)
}

function projectOf(room: Pick<KnownRoom, 'roomId'>): string | undefined {
  const shared = sharedProjects.forRoom(room.roomId)
  return shared.length ? shared.map(p => p.definition!.name).join(', ') : roomProject(deviceStore, nostrSession?.pubkey, room.roomId)
}

function projectChoices(rooms: KnownRoom[]): Array<{ key: string; name: string }> {
  const shared = sharedProjects.joined().filter(p => p.definition!.rooms.some(r => rooms.some(room => room.roomId === r.room)))
  const labels = [...new Set(rooms.filter(r => !sharedProjects.forRoom(r.roomId).length).map(r => roomProject(deviceStore, nostrSession?.pubkey, r.roomId)).filter((name): name is string => !!name))]
  const duplicate = (name: string) => shared.filter(p => p.definition!.name === name).length + labels.filter(label => label === name).length > 1
  return [
    ...shared.map(p => ({ key: `shared:${p.key}`, name: p.definition!.name + (duplicate(p.definition!.name) ? ` · ${p.owner === nostrSession?.pubkey ? 'Yours' : shownAs(p.owner).name ?? npubEncode(p.owner).slice(0, 12) + '…'} · ${p.project.slice(0, 6)}` : '') })),
    ...labels.map(name => ({ key: `project:${name}`, name: name + (duplicate(name) ? ' · Personal label' : '') })),
  ].sort((a, b) => a.name.localeCompare(b.name) || a.key.localeCompare(b.key))
}

function navigationRooms(): KnownRoom[] {
  const rooms = knownRooms(roomStore())
  for (const room of sharedProjects.sharedRooms()) if (!rooms.some(r => r.roomId === room.roomId)) rooms.push(room)
  const current = currentRoomId()
  if (current && !rooms.some(room => room.roomId === current)) {
    rooms.unshift({ roomId: current, name: roomName, link: encodeRoomUrl(joinLinkBase(), relays, iceUrls), openedAt: nowSeconds(), readAt: 0 })
  }
  return rooms
}

function matchesRoom(room: KnownRoom, query: string, project = '*'): boolean {
  const shared = sharedProjects.forRoom(room.roomId)
  const local = roomProject(deviceStore, nostrSession?.pubkey, room.roomId)
  const inProject = project === '*' || (project.startsWith('shared:') ? shared.some(p => `shared:${p.key}` === project) : project === '' ? !shared.length && !local : !shared.length && `project:${local}` === project)
  return inProject
    && `${knownRoomLabel(room)} ${room.roomId} ${projectOf(room) ?? ''}`.toLocaleLowerCase().includes(query)
}

function projectNames(rooms: KnownRoom[]): string[] {
  return [...new Set(rooms.map(projectOf).filter((name): name is string => Boolean(name)))].sort((a, b) => a.localeCompare(b))
}

function fillProjectFilter(id: string, rooms: KnownRoom[]): void {
  const select = $(id) as HTMLSelectElement
  const value = select.value
  const options: Array<[string, string]> = [['*', 'All projects'], ...projectChoices(rooms).map(p => [p.key, p.name] as [string, string]), ['', 'No project']]
  // Do not replace a native select while the person is choosing from it.
  if (JSON.stringify(Array.from(select.options).map(option => [option.value, option.text])) === JSON.stringify(options)) return
  select.replaceChildren(...options.map(([value, label]) => new Option(label, value)))
  select.value = options.some(([key]) => key === value) ? value : '*'
  const filter = select.closest<HTMLElement>('.projectFilter')
  if (filter) filter.hidden = projectNames(rooms).length === 0
}

/** Whether projects are worth a control at all: somebody has made one, or
 *  there are enough rooms that grouping them would help. */
function organising(): boolean {
  const rooms = navigationRooms()
  return !!nostrSession?.signer.nip44 || rooms.length >= 3 || projectNames(rooms).length > 0
}

function projectButton(room: KnownRoom): HTMLButtonElement {
  const button = document.createElement('button')
  button.type = 'button'
  button.className = 'quiet organiseRoom'
  button.dataset.action = 'project'
  const shared = !!nostrSession?.signer.nip44
  button.textContent = shared ? 'Project' : 'Local group'
  button.setAttribute('aria-label', shared ? `Add ${knownRoomLabel(room)} to a project` : `Set local group for ${knownRoomLabel(room)}`)
  button.addEventListener('click', () => shared ? openProjectEditor(room, button) : openLocalGroupEditor(room, button))
  return button
}

/** Forget a room from wherever rooms are listed - the switch-rooms dialog
 *  still shows this as a row button; the home list moved it into its `⋯`
 *  menu instead (see `roomRowMenu`). */
function forgetButton(room: KnownRoom, text: string): HTMLButtonElement {
  const forget = document.createElement('button')
  forget.type = 'button'
  forget.className = 'forget quiet'
  forget.dataset.action = 'forget'
  forget.setAttribute('aria-label', `Forget ${knownRoomLabel(room)}`)
  forget.title = `Forget ${knownRoomLabel(room)}`
  forget.textContent = text
  forget.addEventListener('click', () => forgetKnownRoom(room))
  return forget
}

let projectRoom: KnownRoom | undefined
let projectReturn: HTMLElement | undefined
let projectReturnList: HTMLElement | undefined
function openProjectEditor(room: KnownRoom, opener: HTMLElement): void {
  sharedProjects.open(opener, room)
}

function openLocalGroupEditor(room: KnownRoom, opener: HTMLElement): void {
  projectRoom = room
  projectReturn = opener
  projectReturnList = opener.closest<HTMLElement>('#roomList') ?? undefined
  $('projectRoomName').textContent = knownRoomLabel(room)
  ;($('projectName') as HTMLInputElement).value = roomProject(deviceStore, nostrSession?.pubkey, room.roomId) ?? ''
  $('projectSuggestions').replaceChildren(...projectNames(navigationRooms()).map(name => new Option(name, name)))
  $('projectError').hidden = true
  ;($('projectEditor') as HTMLDialogElement).showModal()
  $('projectName').focus()
}

/** Everything that draws from what the app knows of its rooms: the list, its
 *  counts, the rail. One list now, so one renderer; callers that said
 *  "workspace" before still mean this. */
function renderWorkspace(): void {
  renderRooms()
}

let previousRoom: KnownRoom | undefined
let switchDestination: KnownRoom | undefined

/** How long a room may take to open before the way out is offered. */
const STOP_OPENING_AFTER_MS = 8_000
let stopOpeningTimer: ReturnType<typeof setTimeout> | undefined

/** Offer a way out of a room that is taking too long to open: a tester's
 *  old room sat on "Opening" until the app was killed. */
function armStopOpening(): void {
  clearTimeout(stopOpeningTimer)
  // Finishing either way disarms this first, so firing means still waiting.
  stopOpeningTimer = setTimeout(() => { $('stopOpening').hidden = false }, STOP_OPENING_AFTER_MS)
}

function disarmStopOpening(): void {
  clearTimeout(stopOpeningTimer)
  stopOpeningTimer = undefined
  $('stopOpening').hidden = true
}

/** A switch from the rail that turns into asking to be let in: this device
 *  holds no key for the room, so somebody inside has to answer, and that can
 *  take minutes. The desktop's "Opening…" line over the old room hid the
 *  door saying so, and the way back with it, for the whole wait; the person
 *  saw a room that never opened. The door is shown instead, with its Stop at
 *  once, since this wait is on a person and not on the network. */
function showDoorWhileSwitching(): void {
  if (!switchingRoom || import.meta.env.VITE_DESKTOP !== 'true') return
  delete document.documentElement.dataset.roomSwitching
  $('roomSwitchProgress').hidden = true
  $('roomArea').removeAttribute('aria-busy')
  $('roomArea').hidden = true
  $('stopOpening').hidden = false
}

/** The door while a room you already know is opening: its name and a
 *  word about connecting, never "pick a name", which belongs to invitations. */
function showOpening(room: KnownRoom): void {
  renderAdmissionRoomBrand()
  $('arrivalTitle').textContent = `Opening ${knownRoomLabel(room)}`
  // One line of progress: the status under the title, which joining
  // itself goes on to update.
  $('arrivalLead').hidden = true
  if (!$('status').textContent) setStatus('Connecting to the room…', 'progress')
  $('joinRoomForm').hidden = true
  $('identityMore').hidden = true
  $('arrivalActions').hidden = true
}

/** A room was asked for: show the chats destination, and below 900 px push
 *  the room over the list. */
function showRoomPane(): void {
  if (currentDestination() !== 'chats') openDestination('chats')
  openDetail()
}

async function switchRoom(room: KnownRoom, project?: string): Promise<void> {
  if (switchingRoom) return
  legacyMessagesPanel?.close()
  if (session && room.roomId === currentRoomId()) {
    if (project !== undefined) { roomProjectContext = project; renderCurrentRoomLogo(); renderRoomLogoControls() }
    showRoomPane()
    chatScroll.latest()
    markConversationRead()
    renderConversationNav()
    return
  }
  if (switchingBlocked()) { renderRooms(); return }
  // Nothing a person navigates to ends a call. See `DockedCall`.
  let intent = switchIntent({ onCall: callIsLive() || onCall(), dockedRoomId: dockedCall?.room.roomId, destination: room.roomId })
  const dockRoom = intent === 'dock' ? dockableRoom() : undefined
  if (intent === 'dock' && !dockRoom) {
    // A room this device has no link kept for cannot be come back to.
    if (!await confirmRoomAction({ title: `Switch to ${knownRoomLabel(room)}?`, message: 'This leaves your current call. Your microphone and camera will be off in the other room.', confirmLabel: 'Leave call and switch' })) return
    intent = 'plain'
  }
  if (switchingRoom || switchingBlocked()) { renderRooms(); return }
  showRoomPane()
  const account = nostrSession?.pubkey
  const identity = identityGeneration
  if (session) previousRoom = navigationRooms().find(room => room.roomId === currentRoomId())
  switchDestination = room
  linkArrivalOver = true
  captureDraft()
  switchingRoom = true
  armStopOpening()
  if (import.meta.env.VITE_DESKTOP === 'true' && !$('roomArea').hidden) {
    document.documentElement.dataset.roomSwitching = 'true'
    $('roomSwitchProgress').textContent = `Opening ${knownRoomLabel(room)}…`
    $('roomSwitchProgress').hidden = false
    $('roomArea').setAttribute('aria-busy', 'true')
  }
  $('roomArea').inert = $('rooms').inert = true
  $('joinRoomForm').inert = $('accountHome').inert = true
  ;($('homeRoomQuery') as HTMLInputElement).disabled = true
  try {
    if (intent === 'dock' && dockRoom) dockCall(dockRoom)
    await closeRoomSession({ backgroundFarewell: true })
    resetRoomState()
    if (intent === 'undock') { resumeDockedCall(); return }
    roomProjectContext = project
    const hash = new URL(room.link, location.href).hash
    // Bookmarks provide an invitation fragment, never an external redirect.
    history.replaceState(null, '', joinLinkBase() + hash)
    $('identity').hidden = false
    setStatus('')
    showOpening(room)
    if (!await roomFromLocation()) throw new Error('The room has no invitation link.')
    if ((sharedProjects.forRoom(room.roomId).length || dmPeerOf(room)) && currentRoomId() !== room.roomId) throw new Error('This invitation opened a different room. Ask the sender to correct it before continuing.')
    showRoomUi()
    renderIdentity()
    if (($('join') as HTMLButtonElement).disabled) return
    if (account !== nostrSession?.pubkey || identity !== identityGeneration) {
      setStatus('Check your sign-in before entering: the account used to switch rooms is not available.')
      return
    }
    // A room you have been in is not an invitation: it goes straight in
    // under the name it already has, so the door's name form stays away
    // unless joining fails and there is something to change.
    showOpening(room)
    await startSession()
    if (!session) {
      $('joinRoomForm').hidden = false
      renderArrival()
    }
  } catch (error) {
    showArrivalFailure(error)
    // Keep the room list within reach when admission fails. Drafts in the
    // previous room remain in memory and return with its next successful join.
  } finally {
    disarmStopOpening()
    switchingRoom = false
    delete document.documentElement.dataset.roomSwitching
    if (import.meta.env.VITE_DESKTOP === 'true') $('roomSwitchProgress').hidden = true
    $('roomArea').removeAttribute('aria-busy')
    if (!session) $('roomArea').hidden = true
    $('roomArea').inert = $('rooms').inert = false
    $('joinRoomForm').inert = $('accountHome').inert = false
    ;($('homeRoomQuery') as HTMLInputElement).disabled = false
    renderWorkspace()
    if (session) previousRoom = switchDestination = undefined
    const back = $('returnToPreviousRoom')
    back.hidden = !previousRoom
    if (previousRoom) back.textContent = `Back to ${knownRoomLabel(previousRoom)}`
    const conversation = $('chatForm').hidden ? $('chatLog') : $('chatInput')
    ;(session ? conversation : previousRoom ? back : $('join')).focus({ preventScroll: true })
  }
}

/** Everything of the call's own on this page: local capture, remote media,
 *  tiles. Done when a room closes with no docked call, and when a docked
 *  call ends. */
function tearDownCallMedia(): void {
  shareViewer.endCall()
  floatingSharePreview.close()
  stopLocalMedia()
  void callWakeLock.release()
  speakingMonitor.retain([])
  remoteVolume.retain([])
  for (const entry of [...remoteVideos.values(), ...remoteAudios.values()]) {
    entry.track.stop()
    entry.el.pause()
    entry.el.srcObject = null
    entry.el.remove()
  }
  remoteVideos.clear()
  remoteAudios.clear()
  for (const el of deviceMediaEls.values()) el.remove()
  deviceMediaEls.clear()
  for (const box of tileBoxes.values()) box.remove()
  tileBoxes.clear()
  leftCall = false
  callWanted = false
}

/** Stop the room completely before any other room can own the controls. */
async function closeRoomSession(options: { backgroundFarewell?: boolean } = {}): Promise<void> {
  const pendingRoom = currentRoomId()
  if (pendingRoom) pendingSends.release(pendingRoom)
  if (browserMlsPanel || import.meta.env.DEV && (browserMlsGrantPanel || browserMlsRoomPanel)) await pauseBrowserMls()
  chatScroll.suspend()
  const generation=++roomGeneration
  const old = session,transport=sessionTransport
  // A docked call outlives the room on screen: its session, relays, media,
  // tab lock and timers are left exactly as they are. `dockCall` has already
  // taken them out of the globals this clears.
  const keepCall = docked()
  const boardsClosing=old&&!keepCall?closeRoomBoardCatalogues(old):Promise.resolve()
  const recordingStop = activeRecording?.session === old && old !== dockedCall?.session
    ? stopRecording().catch(err => setStatus(describeError(err))) : undefined
  if (!keepCall) {
    ++callGeneration
    const key = callLockKey()
    if (key) callTabLock.release(key)
  }
  if(!keepCall)tearDownCallMedia()
  await boardsClosing
  if(generation!==roomGeneration||session!==old||sessionTransport!==transport)return
  if (heldElsewhereKey !== undefined) { heldElsewhereKey = undefined; renderCallTabNotice() }
  persistQuiet()
  session = undefined
  sessionTransport = undefined
  resetIncomingCall()
  quietTransport = undefined
  assignmentPanel.detach()
  contextPanel.close()
  messageActions.close(false)
  conversationSearch.reset()
  chatArtPicker.close()
  participantCard.close()
  if (!keepCall) {
    shareViewer.endCall()
    floatingSharePreview.close()
  } else shareViewer.closeInline()
  hideDrawingNotice()
  closeMentionPicker()
  closeRoomSheet()
  for (const dialog of document.querySelectorAll<HTMLDialogElement>('dialog[open]:not([data-keep-open])')) dialog.close()
  stopInvitationHost()
  pairingHost?.close()
  pairingTransport?.close()
  pairingHost = pairingTransport = undefined
  if (iceRefreshTimer !== undefined) clearInterval(iceRefreshTimer)
  if (approvalTimer !== undefined) clearTimeout(approvalTimer)
  iceRefreshTimer = approvalTimer = undefined
  if (!keepCall) {
    if (assistTimer !== undefined) clearInterval(assistTimer)
    assistTimer = undefined
  }
  presenceAnnouncements = undefined
  if (departureNoticeTimer !== undefined) clearTimeout(departureNoticeTimer)
  departureNoticeTimer = undefined
  if (presenceNoticeTimer !== undefined) clearTimeout(presenceNoticeTimer)
  presenceNoticeTimer = undefined
  $('presenceNotice').hidden = true
  $('presenceNotice').textContent = ''
  renderEpochWaiting(false)
  forgetKnocks()
  if (!keepCall) {
    tileLiveness.retain([])
    $('agentsRow').replaceChildren()
  }
  const preview = $('voicePreviewAudio') as HTMLAudioElement
  preview.pause()
  if (preview.src) URL.revokeObjectURL(preview.src)
  preview.removeAttribute('src')
  preview.hidden = true
  if (!keepCall) peerRelay.close()
  setCallOpen(false)
  updateUi()
  if (document.documentElement.dataset.roomSwitching !== 'true') $('roomArea').hidden = true
  // Keep the original roster transport until its recording stop has settled,
  // but stop media and free the controls immediately. Never clean up global connections later:
  // by then they may belong to the newly opened room.
  if (old && old === dockedCall?.session) return
  if (old) closeRoomLogo(old)
  const own = old ? sessionConnections.get(old) : undefined
  for (const [key, pc] of openConnections) {
    if (keepCall && !own?.has(key)) continue
    pc.close()
    uplink.forget(key)
    openConnections.delete(key)
  }
  const finished = (recordingStop ? recordingStop.then(() => old?.leave()) : old?.leave() ?? Promise.resolve())
    .finally(() => transport?.close())
  if (options.backgroundFarewell) void finished.catch(() => {})
  else await finished
}

function resetRoomState(): void {
  $('arrivalRoomBrand').hidden = true; clearLogo($('arrivalLogo')); $('arrivalRoomBrandName').textContent = ''
  roomProjectContext = undefined
  admissionController?.abort()
  admissionController = undefined
  guestAdmissionPreview?.close()
  guestAdmissionPreview = undefined
  for (const opened of openedAttachments.values()) if ('url' in opened) URL.revokeObjectURL(opened.url)
  attachmentViewer.close()
  openedAttachments.clear()
  catalogues.clear()
  controlSeen.clear()
  admins.clear()
  adminsAt = channelsAt = 0
  resetMeetingState()
  if (activeRecording && activeRecording.session !== dockedCall?.session) void stopRecording()
  roomRelaysSeenAt = 0
  clearTimeout(roomRelaysRepostTimer)
  clearTimeout(roomNameCarryTimer)
  channels = []
  channelLogs.clear()
  channelCounts.clear()
  conversationRead = new Map()
  currentChannel = undefined
  keeperParticipant = undefined
  agentParticipants.clear()
  agentDisplayNames.clear()
  receiptAgents.clear()
  requestStatusUpdates.clear()
  handledInvites.clear()
  approvals.clear()
  systemLines.length = 0
  roomSecret = undefined!
  roomPolicy = undefined
  roomName = undefined
  roomInvitationCapability = undefined
  invitationAuthoritySk = undefined
  invitationDelegation = []
  expectedEpoch = undefined
  admittedRoom = undefined
  roomEndsAt = undefined
  roomDestruct = false
  roomStartsAt = undefined
  clearTimeout(conferenceEndTimer)
  conferenceEndTimer = undefined
  startedHere = false
  meParticipant = ''
  roomRelayScope = 'default'
  relays = RELAYS
  roomRelayConfig = relayConnections.configuration('default')
  roomRelayHints = []
  iceUrls = DEFAULT_ICE_URLS
  // Carrying others, and this device's key, belong to the docked call.
  if (!docked()) {
    myDeviceId = ''
    assistEnabled = false
    lastOffering = false
    peerRelay.reopen()
  }
  drafts = new ConversationDrafts()
  restoreDraft()
  chatScroll.suspend()
  $('chatLog').replaceChildren()
  $('conversationHeading').textContent = 'Chat'
  ;($('chatInput') as HTMLTextAreaElement).placeholder = 'Say something'
  for (const id of ['pairUrl', 'copyPair', 'stopPairing', 'pairQrWrap']) $(id).hidden = true
  ;($('pairUrl') as HTMLInputElement).value = ''
  ;($('shareQrDetails') as HTMLDetailsElement).open = false
  $('inviteStatus').textContent = ''
  render([], '')
  renderHost()
  renderApprovals()
}

/** Repaint the room on screen and the call, wherever each is. */
function repaint(): void {
  if (session) render(session.participants(), meParticipant)
  else if (dockedCall) render([], '')
}

/** Whether the call on screen can be docked: it needs a room to come back to. */
function dockableRoom(): KnownRoom | undefined {
  const roomId = currentRoomId()
  if (!session || !roomId) return undefined
  return navigationRooms().find(room => room.roomId === roomId) ?? knownRoom(roomStore(), roomId)
}

/** Keep the call on this page while another room opens in front of it. The
 *  caller closes the room on screen next; everything the call needs has
 *  been taken out of the globals that closing clears. */
function dockCall(room: KnownRoom): void {
  legacyMessagesPanel?.close()
  dockedCall = {
    session: session!, transport: sessionTransport, quiet: quietTransport, iceRefreshTimer, conferenceEndTimer,
    room, label: currentRoomLabel(), me: meParticipant, ui: captureRoomUi(),
  }
  iceRefreshTimer = undefined
  conferenceEndTimer = undefined
  document.documentElement.dataset.callDocked = 'true'
}

/** Back in the docked call's room: its screen as it was left, no rejoin. The
 *  caller has closed the room that was on screen. */
function resumeDockedCall(): void {
  const c = dockedCall
  if (!c) return
  legacyMessagesPanel?.close()
  dockedCall = undefined
  delete document.documentElement.dataset.callDocked
  restoreRoomUi(c.ui)
  const s = c.session
  session = s
  sessionTransport = c.transport
  quietTransport = c.quiet
  iceRefreshTimer = c.iceRefreshTimer
  conferenceEndTimer = c.conferenceEndTimer
  meParticipant = c.me
  history.replaceState(null, '', joinLinkBase() + new URL(c.room.link, location.href).hash)
  showRoomUi()
  renderIdentity()
  serveCurrentInvitation()
  selectRoomDrafts()
  void assignmentPanel.attach(s)
  followReadPositions(s.roomId, deriveRoom(roomSecret).roomKey, s.endsAt)
  // What arrived while the call was docked: the logs kept listening, and
  // only the screen stopped following them.
  for (const [name, log] of channelLogs) channelCounts.set(name, log.messages().length)
  ingestControl(s.channel(CONTROL_CHANNEL).messages())
  followSharedRoomName(s)
  scheduleRoomRelaysRepost(s)
  renderRoomLockState()
  renderHost()
  renderChannels()
  ;($('join') as HTMLButtonElement).hidden = true
  $('identity').hidden = true
  $('identityMore').hidden = true
  $('roomArea').hidden = false
  // What happened to the room's epochs while the call was docked.
  reportEpochTrouble(s)
  setStatus('')
  showRoomTools()
  renderNudgeChoice()
  setCallOpen(true)
  updateUi()
  chatScroll.resume(draftRoomKey())
  restoreConversation()
  repaintActiveChat()
  noteChatRead(s.chat.messages())
  renderCallTabNotice()
}

/** Leave a docked call, and with it the call's room: none of it is on
 *  screen, so there is nothing of the room to stay in. */
async function endDockedCall(reason: 'user' | 'preempted' = 'user', notice?: string): Promise<void> {
  const c = dockedCall
  if (!c) return
  const boardsClosing=closeRoomBoardCatalogues(c.session)
  const key = callLockKey()
  // The warning needs its original transport; microphone and camera shutdown
  // must never wait for that transport's receipt.
  const recordingStop = activeRecording?.session === c.session
    ? stopRecording().catch(err => setStatus(describeError(err))) : undefined
  clearTimeout(c.conferenceEndTimer)
  dockedCall = undefined
  delete document.documentElement.dataset.callDocked
  ++callGeneration
  if (key && reason === 'user') callTabLock.release(key)
  if (c.iceRefreshTimer !== undefined) clearInterval(c.iceRefreshTimer)
  tearDownCallMedia()
  closeRoomLogo(c.session)
  tileLiveness.retain([])
  $('agentsRow').replaceChildren()
  autoplayBanner.hide()
  renderAutoplayBanner()
  peerRelay.close()
  peerRelay.reopen()
  window.kithmootDesktop?.setCallActive(false)
  // The room on screen is this device's only room now.
  myDeviceId = session?.device ?? ''
  const own = sessionConnections.get(c.session)
  for (const [k, pc] of openConnections) {
    if (!own?.has(k)) continue
    pc.close()
    uplink.forget(k)
    openConnections.delete(k)
  }
  updateUi()
  renderDock()
  renderWorkspace()
  setStatus(notice ?? `You left the call in ${c.label}.`, 'done')
  await boardsClosing
  if (reason === 'preempted') await c.session.farewellCall().catch(() => {})
  void (recordingStop ? recordingStop.then(() => c.session.leave()) : c.session.leave())
    .finally(() => c.transport?.close()).catch(() => {})
}

/** The call surface is a permanent sibling of the route panels. Navigation
 *  changes its presentation, never its parent or the media elements in it. */
function renderDock(): void {
  const surface = $('callSurface')
  const dock = $('callDock')
  const c = dockedCall
  const owner = mediaSession()
  const live = !!owner?.call
  const scope = live ? `${owner!.roomId}:${owner!.call!.id}` : ''
  if (scope !== callSurfaceScope) { callSurfaceScope = scope; galleryCollapsed = false }
  surface.hidden = !c && ($('roomArea').hidden || ($('callBay').hidden && $('whoIsHere').hidden && $('roomArea').dataset.mobileView !== 'call' && import.meta.env.VITE_DESKTOP !== 'true'))
  surface.toggleAttribute('data-live', live)
  surface.toggleAttribute('data-gallery-collapsed', live && galleryCollapsed)
  $('callSurfaceHeader').hidden = !live
  const origin = callOrigin(owner)
  // A private chat's call is with the person, not in a room.
  const originText = origin ? `Call ${origin.direct ? 'with' : 'in'} ${origin.roomName}${origin.projectName ? ` · ${origin.projectName}` : ''}` : ''
  $('callSurfaceLogo').hidden = !live || !owner
  if (live && owner) {
    const project = callProjectContext(owner)
    const policy = dockedCall?.session === owner ? dockedCall.ui.roomPolicy : roomPolicy
    $('callSurfaceLogo').hidden = isQuietPolicy(policy) || !!dmPeer(policy, mediaMe())
    if (!$('callSurfaceLogo').hidden) renderLogo($('callSurfaceLogo'), displayedRoomLogo(owner.roomId, project), origin?.roomName ?? 'Call')
    else clearLogo($('callSurfaceLogo'))
  }
  else clearLogo($('callSurfaceLogo'))
  if ($('callSurfaceOrigin').textContent !== originText) $('callSurfaceOrigin').textContent = originText
  const collapse = $('callGalleryCollapse')
  collapse.textContent = galleryCollapsed ? 'Show gallery' : 'Hide gallery'
  collapse.setAttribute('aria-expanded', String(!galleryCollapsed))
  dock.hidden = !c
  if (!c) return
  const text = dockLabel(c.label)
  if ($('callDockText').textContent !== text) $('callDockText').textContent = text
  renderDockElapsed()
  setToggle('callDockMic', !!micTrack?.enabled)
  const view = currentRecordingView(c.session)
  const recordingMine = activeRecording?.session === c.session
  const notice = $('callDockRecordingNotice')
  notice.hidden = view.state === 'off'
  notice.textContent = view.state === 'unconfirmed' ? 'Recording notice is unconfirmed.' : recordingMine ? activeRecording!.recorder.paused ? 'Your recording is paused.' : `You are recording this call. ${recordingCaptureDescription(c.session)}` : `This call is being recorded. ${recordingCaptureDescription(c.session)}`
  renderRecordingElapsed()
  $('callDockBack').setAttribute('aria-label', `Return to the call in ${c.label}`)
}

/** The dock's clock: how long the call has been going, written once a second
 *  and never announced (the element says `aria-live="off"`). */
function renderDockElapsed(): void {
  const since = dockedCall?.session.call?.since
  const text = since === undefined ? '' : `· ${callElapsed(since, nowSeconds())}`
  if ($('callDockElapsed').textContent !== text) $('callDockElapsed').textContent = text
  // The same clock over the conversation of the call this device is on.
  const here = mediaSession()?.call?.since
  const line = here === undefined ? '' : `· ${callElapsed(here, nowSeconds())}`
  if ($('callChatBarElapsed').textContent !== line) $('callChatBarElapsed').textContent = line
}
setInterval(() => { if (dockedCall || !$('callChatBar').hidden) renderDockElapsed() }, 1000)
new MutationObserver(renderDockElapsed).observe($('callChatBar'), { attributes: true, attributeFilter: ['hidden'] })

new MutationObserver(renderDock).observe($('roomArea'), { attributes: true, attributeFilter: ['hidden', 'data-mobile-view'] })

/** What `resetRoomState` clears about the room on screen, kept for a docked
 *  call so coming back to its room needs no rejoin. */
interface RoomUiState {
  catalogues: Map<string, Extract<ControlMessage, { op: 'catalogue' }> & { at: number }>
  controlSeen: Set<string>
  admins: Set<string>
  adminsAt: number
  channelsAt: number
  channels: string[]
  channelLogs: Map<string, ReturnType<NonNullable<typeof session>['channel']>>
  channelCounts: Map<string, number>
  conversationRead: Map<string, Set<string>>
  currentChannel: string | undefined
  keeperParticipant: string | undefined
  agentParticipants: Set<string>
  agentDisplayNames: Map<string, string>
  receiptAgents: Set<string>
  handledInvites: Set<string>
  approvals: Map<string, OpenApproval>
  systemLines: SystemLine[]
  roomSecret: Uint8Array
  roomPolicy: RoomPolicy | undefined
  roomUsesBothy: boolean
  roomEndsAt: number | undefined
  roomDestruct: boolean
  roomStartsAt: number | undefined
  roomName: string | undefined
  roomProjectContext: string | undefined
  roomInvitationCapability: RoomInvitation | undefined
  invitationAuthoritySk: Uint8Array | undefined
  invitationDelegation: InvitationDelegation[]
  expectedEpoch: number | undefined
  admittedRoom: SavedRoomAdmission | undefined
  startedHere: boolean
  roomRelayScope: string
  relays: string[]
  roomRelayConfig: RelayConfig[]
  roomRelayHints: string[]
  iceUrls: string[]
  sessionAuthority: string | undefined
  presenceAnnouncements: PresenceAnnouncements | undefined
}

function captureRoomUi(): RoomUiState {
  return {
    catalogues: new Map(catalogues), controlSeen: new Set(controlSeen), admins, adminsAt, channelsAt, channels,
    channelLogs: new Map(channelLogs), channelCounts: new Map(channelCounts), conversationRead, currentChannel,
    keeperParticipant, agentParticipants: new Set(agentParticipants), agentDisplayNames: new Map(agentDisplayNames),
    receiptAgents: new Set(receiptAgents), handledInvites: new Set(handledInvites), approvals: new Map(approvals),
    systemLines: [...systemLines], roomSecret, roomPolicy, roomUsesBothy, roomEndsAt, roomDestruct, roomStartsAt, roomName, roomProjectContext, roomInvitationCapability, invitationAuthoritySk,
    invitationDelegation, expectedEpoch, admittedRoom, startedHere, roomRelayScope, relays, roomRelayConfig, roomRelayHints, iceUrls,
    sessionAuthority, presenceAnnouncements,
  }
}

function restoreRoomUi(ui: RoomUiState): void {
  const refill = <K, V>(into: Map<K, V>, from: Map<K, V>) => { into.clear(); for (const [k, v] of from) into.set(k, v) }
  const refillSet = <V>(into: Set<V>, from: Set<V>) => { into.clear(); for (const v of from) into.add(v) }
  refill(catalogues, ui.catalogues)
  refillSet(controlSeen, ui.controlSeen)
  refill(channelLogs, ui.channelLogs)
  refill(channelCounts, ui.channelCounts)
  refillSet(agentParticipants, ui.agentParticipants)
  refill(agentDisplayNames, ui.agentDisplayNames)
  refillSet(receiptAgents, ui.receiptAgents)
  refillSet(handledInvites, ui.handledInvites)
  refill(approvals, ui.approvals)
  systemLines.length = 0
  systemLines.push(...ui.systemLines)
  ;({ admins, adminsAt, channelsAt, channels, conversationRead, currentChannel, keeperParticipant, roomSecret, roomPolicy, roomUsesBothy, roomEndsAt, roomDestruct, roomStartsAt, roomName, roomProjectContext,
    roomInvitationCapability, invitationAuthoritySk, invitationDelegation, expectedEpoch, admittedRoom, startedHere, roomRelayScope,
    relays, roomRelayConfig, roomRelayHints, iceUrls, sessionAuthority, presenceAnnouncements } = ui)
}

async function forgetKnownRoom(room: KnownRoom): Promise<void> {
  if (await browserRoomRoutes.selected(room.roomId)) throw new Error('Withdraw this room’s Bothy permissions before forgetting it.')
  // Saved under an account whose signer is not here: a local forget would
  // look done and the bookmark would come back at the next sign-in.
  if (disconnectedAccountRooms().some(saved => saved.roomId === room.roomId)) {
    const signer = signerLabel(expectedMethod)
    const choice = await chooseRoomAction({
      title: `Reconnect before forgetting ${knownRoomLabel(room)}?`,
      message: `This room is also saved to your Nostr account (${npubEncode(expectedAccount!)}), and ${signer} is not connected in this tab. `
        + 'Forgetting it here removes it from this browser only; it comes back the next time you sign in. '
        + `Reconnect ${signer} first to remove it from your account on every device.`,
      confirmLabel: 'Reconnect first',
      alternativeLabel: 'Forget in this browser only',
      alternativeDanger: true,
    })
    if (choice === 'cancel') return
    if (choice === 'confirm') {
      await signInWithNostr().catch(e => setStatus(describeError(e)))
      const saved = nostrSession && knownRoom(roomStore(), room.roomId)
      if (!saved) { if (nostrSession) setStatus('Signed in, and this room is not saved to that account. Nothing was forgotten.'); return }
      return forgetKnownRoom(saved)
    }
    forgetLocally(room.roomId)
    return
  }
  if (!await confirmRoomAction({ title: `Forget ${knownRoomLabel(room)}?`, message: `Remove it ${nostrSession ? 'from your Nostr room bookmarks on all devices' : 'on this device'}. You will need its invitation link to come back. This does not revoke access or erase relay history.`, confirmLabel: 'Forget room', danger: true })) return
  try { await contactInbox?.forgetRoom(room.roomId) }
  catch { setStatus('The private invitation could not be forgotten. Nothing was removed; check storage and retry.'); return }
  if (bookmarks) bookmarks.remove(room.roomId)
  forgetLocally(room.roomId)
}

/** The room forgotten here only; an account bookmark is the caller's job.
 *  The browser's own list entry goes too, or it would be offered straight
 *  back as a room "already here" to add to the account. */
function forgetLocally(roomId: string): void {
  roomLogoCache.forget(roomId)
  if (session?.roomId === roomId) closeRoomLogo(session)
  if (dockedCall?.session.roomId === roomId) closeRoomLogo(dockedCall.session)
  workspaceWork?.forget(roomId)
  stopWatching(roomId)
  // The room is not this browser's any more: no more read positions for it.
  readSync?.forget(roomId)
  retireMeetingCode({ roomId })
  forgetRoomAccess(deviceStore, roomId)
  forgetRoomAccess(browserDeviceStore(sessionStorage), roomId)
  forgetOwnCredentials(deviceStore, roomId)
  forgetQuietState(deviceStore, roomId)
  forgetRoom(deviceStore, roomId)
  forgetRoomUploads(deviceStore, roomId)
  // A pin names the room too, and a forgotten room is not one to name.
  setPinned(localStorage, roomId, false)
  // Its keys go with it: the device key, and the epochs the list read it
  // under and a session opened it in. The archive's records go too where
  // this device can still name them: the room's rekeys, and its main chat in
  // epoch 0 and in every epoch those records name, read before their keys
  // go. Named channels, and the main chat of epochs before the window, stay
  // as ciphertext nothing here opens any more.
  const epochIds = keptEpochIds(deviceStore, roomId)
  deviceStore.remove(DEVICE_PREFIX + roomId)
  browserDeviceStore(sessionStorage).remove(DEVICE_PREFIX + roomId)
  try { forgetRoomEpoch(deviceStore, roomId) } catch { /* Storage unavailable: nothing is held there. */ }
  const archive = roomArchive
  if (archive) {
    const streams = [{ kind: KINDS.CHAT, d: roomId }, { kind: KINDS.ROOM_REKEY, d: roomId }, ...epochIds.map(d => ({ kind: KINDS.CHAT, d }))]
    void Promise.all(streams.map(stream => archive.forget(stream))).catch(error => console.warn('room archive could not forget a room', error))
  }
  renderRooms()
}

// ---------------------------------------------------------------------------
// The way back
//
// "Your rooms" leaves the room AND takes the invitation off the address
// bar, and the list it lands on has no link on it anywhere. For a browser
// that made the room that is survivable; for one that was admitted on a
// link it was the end of the session, because on that path the link IS the
// key and there was no second copy of it on the page, in the list, or in
// the history. One press, no warning, no way back.
//
// So the link is written down before it is taken off the address bar, and
// offered on the list as a button. Session storage: it is about this visit,
// and it must not outlive the tab that held the room.
// ---------------------------------------------------------------------------

const WAY_BACK_KEY = 'kithmoot.way-back'

/** The link that opens the room this page is in, and what to call it. */
let wayBackLink: string | undefined

function rememberWayBack(): void {
  const roomId = currentRoomId()
  if (!roomId) return
  try {
    sessionStorage.setItem(
      WAY_BACK_KEY,
      JSON.stringify({ link: encodeRoomUrl(joinLinkBase(), relays, iceUrls), name: currentRoomLabel() }),
    )
  } catch {
    // No storage. The room may still be on the list below; there is just no
    // button at the top of it.
  }
}

function forgetWayBack(): void {
  wayBackLink = undefined
  try {
    sessionStorage.removeItem(WAY_BACK_KEY)
  } catch {
    // Nothing kept, nothing to forget.
  }
}

/** The button at the top of the list, when this tab left a room to get
 *  here. Named after the room, so it reads as where you came from rather
 *  than as another way in. */
function renderWayBack(): void {
  const button = $('backToRoom')
  let kept: { link?: unknown; name?: unknown } | undefined
  try {
    const raw = sessionStorage.getItem(WAY_BACK_KEY)
    kept = raw ? (JSON.parse(raw) as { link?: unknown; name?: unknown }) : undefined
  } catch {
    kept = undefined
  }
  wayBackLink = typeof kept?.link === 'string' ? kept.link : undefined
  button.hidden = wayBackLink === undefined
  if (wayBackLink === undefined) return
  const name = typeof kept?.name === 'string' && kept.name ? kept.name : 'the room you were in'
  button.textContent = `Back to ${name}`
  // Already on the list, so the way to it is not the thing to offer.
  $('doorToRooms').hidden = true
  $('roomNav').hidden = false
}

/**
 * The rooms list, with the call docked above it. No reload: a reload is what
 * ends a call, and nothing a person navigates to ends a call. Opening a room
 * from the list goes through `switchRoom`, which brings the call's own room
 * back without a rejoin.
 */
async function homeKeepingCall(): Promise<void> {
  if (switchingRoom) return
  if (hasUnsentWork() && !await confirmDiscardAndLeave()) return
  if (!dockedCall) {
    const room = dockableRoom()
    // A room this device kept no link for cannot be come back to.
    if (!room) {
      if (!await confirmRoomAction({ title: 'Leave this call?', message: 'You will return to all rooms. Your microphone and camera will turn off.', confirmLabel: 'Leave call' })) return
      return backToRooms()
    }
    dockCall(room)
  }
  switchingRoom = true
  try {
    await closeRoomSession({ backgroundFarewell: true })
    resetRoomState()
    history.replaceState(null, '', joinLinkBase())
    $('roomArea').hidden = true
    showRoomsList()
    renderDock()
  } finally {
    switchingRoom = false
  }
}

/** Back to the list: leave the room if in it, and open the app with no
 *  link on it. A reload for the same reason `leaveRoom` reloads. */
async function backToRooms(): Promise<void> {
  if (hasUnsentWork() && !await confirmDiscardAndLeave()) return
  const s = session
  session = undefined
  sessionTransport = undefined
  resetIncomingCall()
  // Written down BEFORE the link comes off the address bar, because after
  // that this page no longer knows it.
  rememberWayBack()
  s?.leave()
  history.replaceState(null, '', joinLinkBase())
  approvedReload()
}

// ---------------------------------------------------------------------------
// Notifications
//
// From this open app, and from nowhere else: there is no server to push
// from. The rule for when a message is worth one is in app/src/notify.ts;
// this is the browser around it - permission, the system notification, and
// what a click on one does.
// ---------------------------------------------------------------------------

function zenBellEnabled(): boolean { return (deviceStore.get('kithmoot.zen-bell') ?? deviceStore.get('kithmoot.desktop-bell')) !== 'false' }
const APP_TITLE = document.title
document.addEventListener('pointerdown', () => {
  if (notifySettings(deviceStore).enabled) void unlockZenChime()
}, { once: true })
window.kithmootDesktop?.onOpenRoom(roomId => {
  const room = knownRoom(roomStore(), roomId)
  if (room && roomId !== currentRoomId()) openKnownRoom(room)
})

/** Use the same resolved messages/read positions as chat, not the number of banners. */
function updateDesktopUnread(): void {
  const self = meParticipant || currentParticipant() || ''
  const selfName = joiningName()
  let { people, agents } = session && currentRoomId() && roomIsMuted(currentRoomId()!) ? { people: 0, agents: 0 } : currentRoomUnreadSplit()
  for (const room of knownRooms(roomStore())) {
    if (session && room.roomId === currentRoomId()) continue
    if (roomIsMuted(room.roomId)) continue
    const watched = roomWatches.get(room.roomId)
    if (!watched) continue
    const split = watched.watch.unread(room.readAt ?? 0, self, selfName, room.readIds)
    people += split.people
    agents += split.agents
  }
  // The bell still rings for a tag: it is addressed to this person, unlike
  // the agent chatter that never reaches this count at all.
  const count = people + agents
  window.kithmootDesktop?.setUnread(count)
  if (!window.kithmootDesktop) updateAppBadge(count)
  document.title = titleWithCount('KithMoot', count)
}


/** How a sender is named in a notification, and the accessible name for a
 *  message's own React and Actions buttons: the name alone, the way a
 *  person would say it out loud. The short code only joins in when two
 *  people in view share the name and the name alone would not tell them
 *  apart - the same `nameCollides` rule `identityRun` draws the code under
 *  a name for (M9: "React to message from Wren (npub…)" on every message,
 *  whether or not there was another Wren to tell apart from). */
function senderLabel(m: ChatMessage): string {
  const shown = shownAs(m.participant, m.name)
  if (shown.name === undefined) return 'Somebody'
  return nameCollides(m.participant, shown.name) ? `${shown.name} (${shown.short})` : shown.name
}

const notifier = new Notifier({
  settings: roomId => {
    const settings = notifySettings(deviceStore)
    const level = roomNotificationLevel(deviceStore, nostrSession?.pubkey, roomId, notificationProjectsForRoom(roomId), nowSeconds())
    return { ...settings, enabled: settings.enabled && level !== 'off', mentionsOnly: level === 'mentions' }
  },
  hidden: () => document.hidden || Boolean(window.kithmootDesktop && !document.hasFocus()),
  shownRoomId: () => (session ? currentRoomId() : undefined),
  self: () => meParticipant || currentParticipant(),
  deliver: (content, arrival) => deliverNotification(content, arrival),
  onPending: (count) => {
    updateDesktopUnread()
  },
})

/**
 * One notification, through the service worker's registration when there
 * is one - that is what survives the tab being put in the background on a
 * phone - and through the page otherwise. The room's link rides in the
 * notification's data, for the click: it is the same link this device
 * already keeps for the room, held by the same browser.
 */
async function deliverNotification(content: NotificationContent, arrival: Arrival): Promise<void> {
  if (window.kithmootDesktop) {
    const bell = zenBellEnabled()
    window.kithmootDesktop.notify({ ...content, roomId: arrival.roomId, silent: true })
    if (bell && !callIsLive() && !onCall()) void playZenChime()
    return
  }
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return
  if (!document.hidden && zenBellEnabled() && !callIsLive() && !onCall()) void playZenChime()
  const url = knownRoom(roomStore(), arrival.roomId)?.link
  const options: NotificationOptions = { body: content.body, tag: content.tag, data: { url }, silent: !zenBellEnabled() || callIsLive() || onCall() || !document.hidden }
  let registration: ServiceWorkerRegistration | undefined
  try {
    registration = await navigator.serviceWorker?.getRegistration()
  } catch {
    registration = undefined
  }
  if (registration?.showNotification) {
    await registration.showNotification(content.title, options)
    return
  }
  const shown = new Notification(content.title, options)
  shown.onclick = () => {
    window.focus()
    shown.close()
    if (url) openLink(url)
  }
}

async function deliverIncomingCallAlert(content: NotificationContent, roomId: string): Promise<void> {
  if (window.kithmootDesktop) {
    window.kithmootDesktop.notify({ ...content, roomId, silent: false })
    return
  }
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return
  const url = knownRoom(roomStore(), roomId)?.link
  const options: NotificationOptions = { body: content.body, tag: content.tag, data: { url }, silent: false }
  let registration: ServiceWorkerRegistration | undefined
  try { registration = await navigator.serviceWorker?.getRegistration() } catch { registration = undefined }
  if (registration?.showNotification) {
    await registration.showNotification(content.title, options)
    return
  }
  const shown = new Notification(content.title, options)
  shown.onclick = () => { window.focus(); shown.close(); if (url) openLink(url) }
}

/** Whether a link opens the room this page is already on. */
function alreadyHere(url: string): boolean {
  try {
    const link = parseRoomLink(url)
    if (link.invitation) {
      return roomInvitationCapability !== undefined && deriveInvitationId(link.invitation) === deriveInvitationId(roomInvitationCapability)
    }
    if (link.secret) return currentRoomId() === deriveRoom(link.secret).roomId
  } catch {
    // Not a room link.
  }
  return false
}

/** Open a room link from a notification: this app's own links only, and
 *  a reload for the reason `openKnownRoom` reloads. */
async function openLink(url: string): Promise<void> {
  let target: URL
  try {
    target = new URL(url, location.href)
  } catch {
    return
  }
  if (target.origin !== location.origin || !target.href.startsWith(joinLinkBase())) return
  if (alreadyHere(target.href)) return
  if ((hasUnsentWork() || callIsLive() || onCall()) && !await confirmRoomAction({ title: 'Open the other room?', message: 'This leaves your call and discards unfinished messages and files in this tab.', confirmLabel: 'Leave and open room', danger: true })) return
  history.replaceState(null, '', target.href)
  approvedReload()
}

navigator.serviceWorker?.addEventListener('message', (event) => {
  const data = event.data as { type?: unknown; url?: unknown } | null
  if (data && data.type === 'kithmoot:open' && typeof data.url === 'string') openLink(data.url)
})

function notificationProjectsForRoom(roomId: string): string[] {
  const shared = sharedProjects.forRoom(roomId)
  if (shared.length) return shared.map(project => `shared:${project.key}`)
  const personal = roomProject(deviceStore, nostrSession?.pubkey, roomId)
  return personal ? [`project:${personal}`] : []
}

function selectedNotificationScope(): NotificationScope {
  const select = $('notificationScope') as HTMLSelectElement
  try { return JSON.parse(select.value) as NotificationScope } catch { return { kind: 'default' } }
}

function renderNotificationScopes(): void {
  const select = $('notificationScope') as HTMLSelectElement
  const previous = select.value
  const rooms = navigationRooms()
  const choices: { scope: NotificationScope; label: string }[] = [{ scope: { kind: 'default' }, label: 'All projects and rooms' }]
  for (const project of projectChoices(rooms)) choices.push({ scope: { kind: 'project', id: project.key }, label: `Project: ${project.name}` })
  for (const room of rooms) choices.push({ scope: { kind: 'room', id: room.roomId }, label: `Room: ${roomLabel(room)}` })
  select.replaceChildren(...choices.map(({ scope, label }) => new Option(label, JSON.stringify(scope))))
  if ([...select.options].some(option => option.value === previous)) select.value = previous
  const scope = selectedNotificationScope()
  const mode = $('notificationMode') as HTMLSelectElement
  mode.options[0]!.disabled = scope.kind === 'default'
  mode.value = notificationMode(deviceStore, nostrSession?.pubkey, scope)
}

function renderNotifyChoice(): void {
  renderNotificationScopes()
  const settings = notifySettings(deviceStore)
  const supported = Boolean(window.kithmootDesktop) || typeof Notification !== 'undefined'
  const granted = Boolean(window.kithmootDesktop) || (supported && Notification.permission === 'granted')
  const on = settings.enabled && granted
  setToggle('toggleNotify', on)
  $('toggleNotify').setAttribute('aria-pressed', String(on))
  ;($('toggleNotify') as HTMLButtonElement).disabled = !supported
  $('desktopNotifySound').hidden = false
  const bell = zenBellEnabled()
  setToggle('toggleNotifyBell', bell)
  $('toggleNotifyBell').setAttribute('aria-pressed', String(bell))
  const textToggle = $('toggleNotifyText') as HTMLButtonElement
  textToggle.hidden = !on
  setToggle('toggleNotifyText', settings.showText)
  textToggle.setAttribute('aria-pressed', String(settings.showText))
  const note = $('notifyNote')
  if (!supported) {
    note.textContent = 'This browser cannot show notifications.'
  } else if (!window.kithmootDesktop && Notification.permission === 'denied') {
    note.textContent = 'Your browser is blocking notifications for this site. You will have to allow them in the browser\u2019s own settings first.'
  } else if (on && window.kithmootDesktop) {
    note.textContent = 'On while KithMoot is open or minimised. For the Dock count on macOS, allow KithMoot notifications and Badge application icon in System Settings → Notifications. The bell is quiet during calls. Message text stays private unless you enable previews. Quiet rooms are checked while open.'
  } else if (on) {
    note.textContent = settings.showText
      ? 'On: when somebody writes in a room you are not looking at, your device shows you the room, who wrote, and what they said.'
      : 'On: when somebody writes in a room you are not looking at, your device shows you the room and who wrote. What they actually said stays in here unless you ask for it.'
  } else if (window.kithmootDesktop) {
    note.textContent = 'Off. Enable notifications for saved rooms while KithMoot is open or minimised. Quitting stops delivery.'
  } else {
    note.textContent =
      'Off. Enable alerts for messages in rooms you are not reading. Message previews are off by default.'
  }
}

async function setNotify(on: boolean): Promise<void> {
  if (on) void unlockZenChime()
  if (!window.kithmootDesktop && on && typeof Notification !== 'undefined' && Notification.permission !== 'granted') {
    // Asked from the click, which is the only place a browser will grant it.
    const permission = await Notification.requestPermission()
    if (permission !== 'granted') {
      setNotifySettings(deviceStore, { enabled: false })
      renderNotifyChoice()
      return
    }
  }
  setNotifySettings(deviceStore, { enabled: on })
  renderNotifyChoice()
  updateDesktopUnread()
}

// ---------------------------------------------------------------------------
// Being nudged by the keeper
//
// The keeper is the one party always in the room, and a Nostr key is an
// address a DM can reach. A member signed in with one can ask the keeper,
// on the control channel, to say when there are new messages and they are
// away. A name-only identity has no inbox to read a DM from, so it is not
// offered the switch. What was last asked for is remembered per room on
// this device; the keeper holds the truth of it.
// ---------------------------------------------------------------------------

const NUDGE_PREFIX = 'kithmoot.nudge.'

function nudgeWanted(roomId: string): boolean {
  try {
    return localStorage.getItem(NUDGE_PREFIX + roomId) === 'true'
  } catch {
    return false
  }
}

function renderNudgeChoice(): void {
  const row = $('nudgeRow')
  const roomId = currentRoomId()
  row.hidden = !session || !nostrSession || !roomId
  const on = roomId !== undefined && nudgeWanted(roomId)
  setToggle('toggleNudge', on)
  $('toggleNudge').setAttribute('aria-pressed', String(on))
}

async function setNudge(on: boolean): Promise<void> {
  const roomId = currentRoomId()
  if (!session || !nostrSession || !roomId) return
  await session.channel(CONTROL_CHANNEL).send(encodeControl({ op: 'nudge', on }))
  try {
    if (on) localStorage.setItem(NUDGE_PREFIX + roomId, 'true')
    else localStorage.removeItem(NUDGE_PREFIX + roomId)
  } catch {
    // Storage may be unavailable; the keeper still heard.
  }
  renderNudgeChoice()
  setStatus(on ? 'Asked the computer that looks after this room to nudge you when you miss messages.' : 'Asked it to stop nudging you.')
}

