/**
 * Ending a browser room, from the browser that holds its authority.
 *
 * A browser room has no keeper, so its creator's browser is the only one
 * that can announce for it: exactly what a keeper's closeRoom does, from
 * here. The link is retired first, saying the room ended, so a newcomer is
 * told that rather than only that the link is stale; then the final epoch
 * is published with nobody kept, and every member's session leaves on it.
 * A room with a keeper keeps using the keeper, and a browser whose link
 * was replaced no longer holds the key its members follow.
 */
let sessionAuthority: string | undefined
let endingRoom = false

function canEndRoom(): boolean {
  if (roomUsesBothy || !session || session.closed || keeperParticipant !== undefined) return false
  if (!roomInvitationCapability || !invitationAuthoritySk || invitationDelegation.length !== 0 || !sessionAuthority) return false
  return getPublicKey(invitationAuthoritySk) === sessionAuthority
}

function renderEndRoom(): void {
  const hidden = !canEndRoom()
  $('endRoom').hidden = hidden
  $('endRoomNote').hidden = hidden
  $('selfDestructNow').hidden = hidden
  renderMeetingCode()
}

/** Get a meeting code: only the room's creator (the End room check), for
 *  any room that has not ended. */
function meetingCodeOffered(): boolean {
  const roomId = currentRoomId()
  if (!roomId || !roomInvitationCapability || !canEndRoom()) return false
  return meetingCodeEligible({ endsAt: roomEndsAt, now: nowSeconds() })
}

/** Whether the host has set Add a password by hand since the sheet opened;
 *  until then it follows the room: on without a waiting room, off with one. */
let meetingCodePasswordTouched = false

function renderMeetingCodePassword(on: boolean): void {
  setToggle('meetingCodePassword', on)
  $('meetingCodePasswordNote').textContent = on
    ? 'The code service keeps only a copy locked with four password words, which it never sees. The link carries them.'
    : 'Anyone with the code gets the invite link, and the code service can read it.'
}

/** Whether the host chose Send the password separately. A choice about what
 *  the link says, not about the code: both ways the service holds the same
 *  sealed copy. Off until chosen, and kept for this page's life. */
function meetingCodeSeparate(): boolean {
  return $('meetingCodeSeparate').dataset.on === 'true'
}

function renderMeetingCode(): void {
  const offered = meetingCodeOffered()
  $('meetingCodeRow').hidden = !offered
  const record = offered ? loadMeetingCode(deviceStore, deriveInvitationId(roomInvitationCapability!), nowSeconds()) : undefined
  $('meetingCodeShown').hidden = !record
  $('getMeetingCode').hidden = !!record
  $('meetingCodePasswordRow').hidden = !!record
  if (!record) {
    const roomId = currentRoomId()
    if (offered && roomId && !meetingCodePasswordTouched) renderMeetingCodePassword(!knockOn(roomId))
    return
  }
  // With a password the one link joins in a tap: the words ride in its
  // fragment, which no server receives. Sent separately, the link is bare
  // and the words are shown to send on their own. Reading the code out
  // loud needs the words either way, so they are never only in the link.
  const separate = !!record.words && meetingCodeSeparate()
  $('meetingCode').textContent = displayMeetingCode(record.code)
  ;($('meetingCodeLink') as HTMLInputElement).value = meetingCodeLink(record.code, separate ? undefined : record.words)
  $('meetingCodeSeparateRow').hidden = !record.words
  setToggle('meetingCodeSeparate', separate)
  $('meetingCodeSeparateNote').textContent = separate
    ? 'The link leaves the words out. Send them in a different message.'
    : 'The link carries the words after its #, which no server receives, so one tap joins.'
  $('meetingCodeWordsRow').hidden = !separate
  $('meetingCodeWords').textContent = separate ? record.words ?? '' : ''
  $('meetingCodeAloud').hidden = !record.words || separate
  $('meetingCodeAloudWords').textContent = record.words && !separate ? record.words : ''
  $('meetingCodeExpiry').textContent = `This code works until ${formatConferenceEnd(record.expires)}. Ending the room or making a new link stops it sooner.`
  $('shareMeetingCode').hidden = navigator.share === undefined
}

async function getMeetingCode(): Promise<void> {
  if (!meetingCodeOffered()) throw new Error('Only the browser that started this room can get a meeting code for it.')
  const invitation = roomInvitationCapability!, roomId = currentRoomId()!
  const link = ($('shareUrl') as HTMLInputElement).value, expires = meetingCodeExpiry(roomEndsAt, nowSeconds())
  // With a password the link is sealed here, under words the service never
  // sees, and the words are kept with the code so this sheet can show them.
  const issued = $('meetingCodePassword').dataset.on === 'true'
    ? await issueSealedMeetingCode(meetingCodes, link, expires)
    : await meetingCodes.create(link, expires)
  try {
    // The link may have been replaced while the service answered.
    if (roomInvitationCapability !== invitation) throw new Error('The room link changed. Get a new code for the new link.')
    storeMeetingCode(deviceStore, deriveInvitationId(invitation), { ...issued, roomId })
  } catch (error) {
    // A code whose delete token cannot be kept must not stay live.
    void meetingCodes.remove(issued.code, issued.deleteToken).catch(() => {})
    throw error
  }
  renderMeetingCode()
}

/** What Copy and Share send. A code with its words in the link is just that
 *  one link: a bare code in the text would ask a guest for words they were
 *  never shown. Sent separately, or with no password, it is the code and the
 *  bare link, and the words (when there are any) are a line of their own. */
function meetingCodeMessage(): { text: string; words: string; withWords: boolean } {
  const link = ($('meetingCodeLink') as HTMLInputElement).value
  const words = $('meetingCodeWordsRow').hidden ? '' : $('meetingCodeWords').textContent ?? ''
  const withWords = !$('meetingCodeAloud').hidden
  if (withWords) return { text: link, words: '', withWords }
  const code = `Meeting code ${$('meetingCode').textContent}: ${link}`
  return { text: words ? `${code}\nPassword words: ${words}` : code, words, withWords }
}

async function copyMeetingCode(): Promise<void> {
  const { text, words, withWords } = meetingCodeMessage()
  try {
    await navigator.clipboard.writeText(text)
    $('meetingCodeStatus').textContent = words
      ? 'Code, short link and password words copied, on separate lines. Send the words separately from the code.'
      : withWords ? 'Link copied. It joins in one tap, with the password words inside.' : 'Code and short link copied.'
  } catch {
    const input = $('meetingCodeLink') as HTMLInputElement
    input.focus(); input.select()
    $('meetingCodeStatus').textContent = 'Automatic copy was unavailable. Select the link and copy it with your keyboard or touch menu.'
  }
}

async function endRoomForEveryone(destruct = false): Promise<void> {
  if (!canEndRoom()) throw new Error('Only the browser that started this room can end it.')
  const s = session!, invitation = roomInvitationCapability!, authoritySk = invitationAuthoritySk!
  const retirement = configuredPool(relays)
  try {
    await retirement.publish(encodeInvitationRetirement({ invitation, inviterSk: authoritySk, now: nowSeconds(), ended: true, endsAt: roomEndsAt }))
  } finally {
    closeWhenSettled(retirement)
  }
  retireMeetingCode({ roomId: s.roomId })
  stopInvitationHost()
  endingRoom = true
  // Self-destruct rides in the closing rekey, inside its encryption; the
  // retirement above is plain JSON and says only that the room ended.
  const flagged = destruct || roomDestruct
  try { await s.rekey({ authoritySk, closed: true, by: meParticipant, ...(flagged ? { destruct: true } : {}) }) }
  catch (err) { endingRoom = false; throw err }
}

/** A saved room whose link turned out to be retired because the room ended:
 *  the list should say so rather than go on offering to open it. */
function markLinkEnded(href: string): void {
  let id: string
  try {
    const invitation = parseRoomLink(href).invitation
    if (!invitation) return
    id = deriveInvitationId(invitation)
  } catch { return }
  const found = new Map<string, KnownRoom>()
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) {
    for (const room of knownRooms(store)) {
      try {
        const saved = parseRoomLink(room.link).invitation
        if (saved && deriveInvitationId(saved) === id && !found.has(room.roomId)) found.set(room.roomId, room)
      } catch { /* A link that does not parse names no room. */ }
    }
  }
  for (const room of found.values()) void learnDestructAtDoor(room)
}

/** The room's authority closed it: this browser, a keeper, or the browser
 *  that started it. Written down either way, so the list says so. */
function roomWasClosed(notice: { by?: string; destruct?: true; refused?: true }): void {
  const s = session
  // Self-destruct is learned before the room is marked ended, so the kept
  // admission the tidy-up reads with is not dropped first.
  const flagged = !!s && (notice.destruct === true || roomDestruct || roomIsDestruct(s.roomId))
  if (s && flagged) { markRoomDestruct(s.roomId); destructSecrets.set(s.roomId, roomSecret) }
  if (s) {
    markEnded(deviceStore, s.roomId, nowSeconds())
    if (bookmarks) markEnded(bookmarks.rooms, s.roomId, nowSeconds())
  }
  // The closing rekey can be heard more than once: from the call that made
  // it and again off the relay. A tidy-up leaves by itself, for its report.
  if (tidyUpRunning || (s && destructing.has(s.roomId))) return
  if (s && flagged) { void runDueDestructs(); return }
  // Told by the authority's refusal, which carries no flag: the closing
  // rekey may still say the room self-destructs.
  if (s && notice.refused && sessionAuthority) {
    const roomId = s.roomId, secret = roomSecret
    void closingRekeyDestructs(s.roomId, sessionAuthority, s.epochKeys(), [...relays]).catch(() => false).then(destructs => {
      // A join that was refused may have given up on the session meanwhile:
      // the room is still tidied away if it self-destructs.
      if (!destructs) { if (session === s) leaveWithNotice('This room was ended by the person who started it.'); return }
      destructSecrets.set(roomId, secret)
      markRoomDestruct(roomId)
      void runDueDestructs()
    })
    return
  }
  if (endingRoom) {
    leaveWithNotice('You ended this room for everyone. Its invite link no longer works.')
    return
  }
  leaveWithNotice(keeperParticipant === undefined
    ? 'This room was ended by the person who started it.'
    : `This room was closed${notice.by ? ` by ${personLabel(notice.by)}` : ''}.`)
}

