/** Leave every local media source before returning to this room's door. */
async function leaveRoom(): Promise<void> {
  closeAllDrafts()
  // Leaving the room beside a docked call goes back to the call.
  if (dockedCall) { await switchRoom(dockedCall.room); return }
  ;($('leave') as HTMLButtonElement).disabled = true
  // Leaving is on purpose: the link to this room is an invitation again, and
  // the page that reloads below meets its door, not the room it just left.
  const leaving = currentRoomId()
  if (leaving) for (const store of new Set([roomStore(), deviceStore])) { try { clearRoomJoined(store, leaving) } catch { /* Storage may be unavailable. */ } }
  await closeRoomSession()
  approvedReload()
}

// ---------------------------------------------------------------------------
// Leave and tidy up. The steps and their order live in room-tidy-up.ts; this
// is where the keys, relays, tabs and storage they act on come from.
// ---------------------------------------------------------------------------

const roomTabs = typeof BroadcastChannel === 'undefined' ? undefined : new RoomTabs(
  () => session ? currentRoomId() : undefined,
  async roomId => { if (session && currentRoomId() === roomId) await leaveForTidyUp() },
)

interface TidyUpContext {
  roomId: string
  /** Undefined only for a self-destructing room whose key this device no
   *  longer holds: its read position cannot be named, so it is not deleted. */
  roomKey?: Uint8Array
  roomRelays: string[]
  invitation?: RoomInvitation
  inviterSk?: Uint8Array
  deviceSk: Uint8Array
  account?: SignetSession
  canEnd: boolean
}

let tidyUpContext: TidyUpContext | undefined
let tidyUpRunning = false

function tidyUpAccount(roomId: string): SignetSession | undefined {
  return nostrSession && bookmarks && knownRoom(bookmarks.rooms, roomId) ? nostrSession : undefined
}

async function openTidyUp(): Promise<void> {
  const s = session
  const roomId = currentRoomId()
  if (!s || !roomId) return
  // Saved to an account whose signer is not here: tidying would clear this
  // browser and leave the account's records behind. See C10.
  if (accountDisconnected() && disconnectedAccountRooms().some(room => room.roomId === roomId)) {
    const signer = signerLabel(expectedMethod)
    setStatus(`This room is saved to your Nostr account, and ${signer} is not connected in this tab. Leave the room, reconnect ${signer}, then tidy up so your account’s records go too.`)
    return
  }
  const owner = invitationDelegation.length === 0 && invitationAuthoritySk && roomInvitationCapability ? roomInvitationCapability : undefined
  tidyUpContext = {
    roomId,
    roomKey: deriveRoom(roomSecret).roomKey,
    roomRelays: [...relays],
    invitation: owner,
    inviterSk: owner ? invitationAuthoritySk : undefined,
    deviceSk: deviceKey(),
    account: tidyUpAccount(roomId),
    canEnd: canEndRoom(),
  }
  closeRoomSheet()
  renderTidyUpPlan()
  $('tidyUpResults').replaceChildren()
  ;($('tidyUpRun') as HTMLButtonElement).hidden = false
  ;($('tidyUpCancel') as HTMLButtonElement).hidden = false
  ;($('tidyUpDone') as HTMLButtonElement).hidden = true
  ;($('tidyUpTombstone') as HTMLInputElement).disabled = false
  ;($('tidyUpEnd') as HTMLInputElement).disabled = false
  const dialog = $('tidyUpDialog') as HTMLDialogElement
  if (!dialog.open) dialog.showModal()
  ;($('tidyUpCancel') as HTMLButtonElement).focus()
}

function renderTidyUpPlan(): void {
  const context = tidyUpContext
  if (!context) return
  const deleteTombstone = ($('tidyUpTombstone') as HTMLInputElement).checked
  const end = context.canEnd && ($('tidyUpEnd') as HTMLInputElement).checked
  $('tidyUpTombstoneRow').hidden = !context.account
  $('tidyUpEndRow').hidden = !context.canEnd
  const list = $('tidyUpSteps')
  const results = new Map([...list.querySelectorAll<HTMLElement>('li')].map(li => [li.dataset.step, li.querySelector('.tidyResult')]))
  list.replaceChildren(...tidyUpSteps({ creator: !!context.inviterSk, account: !!context.account, deleteTombstone, end, files: true }).map(step => {
    const li = document.createElement('li')
    li.dataset.step = step.id
    li.textContent = step.label
    const kept = results.get(step.id)
    if (kept) li.append(kept)
    return li
  }))
  $('tidyUpLimits').replaceChildren(...TIDY_UP_LIMITS.map(text => { const li = document.createElement('li'); li.textContent = text; return li }))
}

function describeTidyStep(report: TidyStepReport): string {
  if (report.skipped) return report.skipped
  if (report.files) return describeFileStep(report.files)
  const parts: string[] = []
  if (['invitations', 'retirement', 'device', 'account'].includes(report.id)) parts.push(report.found === 0 ? 'Nothing found to delete.' : `Found ${report.found}.`)
  for (const answer of report.answers) parts.push(`${answer.relay}: ${answer.status}${answer.detail ? ` (${answer.detail})` : ''}.`)
  if (report.unread.length) parts.push(`Did not answer the query: ${report.unread.join(', ')}.`)
  if (report.id === 'check') parts.push(report.found === 0 ? 'The relays that answered hold nothing more of yours for this room.' : `${report.found} still found.`)
  return parts.join(' ') || 'Done.'
}

function describeFileStep(files: FileDeletionReport): string {
  if (files.found === 0) return 'No files from this device found to delete.'
  const parts = [`Deleted ${files.deleted} of ${files.found}.`]
  if (files.refused) parts.push(`${files.refused} not on a file server this app uploads to, so not asked.`)
  for (const line of files.details) parts.push(`${line}`)
  if (files.pending) parts.push(`This device asks again each time it starts, for ${Math.round(BLOB_DELETE_RETRY_SECONDS / 86_400)} days.`)
  return parts.join(' ')
}

function showTidyStep(report: TidyStepReport): void {
  const li = $('tidyUpSteps').querySelector<HTMLElement>(`li[data-step="${report.id}"]`)
  if (!li) return
  li.querySelector('.tidyResult')?.remove()
  const result = document.createElement('span')
  result.className = 'tidyResult'
  result.dataset.status = report.skipped ? 'skipped' : report.answers.some(a => a.status !== 'accepted') || (report.files && report.files.deleted < report.files.found) ? 'partial' : 'done'
  result.textContent = describeTidyStep(report)
  li.append(result)
}

function showTidyReport(report: TidyUpReport): void {
  const results = $('tidyUpResults')
  results.replaceChildren()
  const heading = document.createElement('h3')
  heading.textContent = report.refused ? 'Nothing was deleted' : report.localRetained ? 'Tidy-up paused' : report.remaining.length ? 'What a fresh query still finds' : 'Tidied up'
  const lead = document.createElement('p')
  lead.textContent = report.refused ?? report.localRetained ?? (report.remaining.length ? 'These relays still return records of yours for this room:' : 'Every relay that answered returned nothing more of yours for this room.')
  results.append(heading, lead)
  if (report.remaining.length) {
    const list = document.createElement('ul')
    list.id = 'tidyUpRemaining'
    for (const left of report.remaining) {
      const li = document.createElement('li')
      li.textContent = left.count < 0 ? `${left.what}: ${left.relay}` : `${left.what}: ${left.count} on ${left.relay}`
      list.append(li)
    }
    results.append(list)
  }
}

/** The tidy-up's file step for a room: delete every file this device
 *  recorded uploading there, and those its own announcements name, from a
 *  server this app uploads to. See app/src/blob-deletion.ts. */
function deleteRoomFiles(context: TidyUpContext): (deviceEvents: readonly NostrEvent[]) => Promise<FileDeletionReport> {
  return async deviceEvents => {
    const recorded = roomUploads(deviceStore, context.roomId)
    const origins = [blossomServer()].filter(Boolean)
    return deleteUploads({
      blobs: [...recorded, ...uploadsFromEvents(deviceEvents, getPublicKey(context.deviceSk))],
      origins,
      signedUploads: deviceEvents,
      sk: context.deviceSk,
      now: nowSeconds,
      store: deviceStore,
    })
  }
}

function clearRoomLocally(context: TidyUpContext, sweep = false): void {
  // The archive's older epochs and the room's channels, named while the
  // epoch records forgetLocally removes are still here.
  if (sweep) sweepRoomArchive(context.roomId, context.roomKey)
  forgetLocally(context.roomId)
  bookmarks?.dropLocalRecord(context.roomId)
  if (bookmarks) forgetRoom(bookmarks.rooms, context.roomId)
  forgetRoom(deviceStore, context.roomId)
  if (context.invitation) forgetInvitationOwner(context.invitation)
  const names = [context.roomId, ...(context.invitation ? [deriveInvitationId(context.invitation)] : [])]
  for (const storage of [localStorage, sessionStorage]) {
    try {
      for (const key of Object.keys(storage)) if (names.some(name => key.includes(name))) storage.removeItem(key)
    } catch { /* Storage unavailable: nothing more is held there. */ }
  }
  if (!sweep) return
  relayConnections.forgetRoom(context.roomId)
  // A self-destructed room goes from the shared records too: the map of
  // every room's relays, pins, projects. What cannot be cut out is said.
  for (const storage of [localStorage, sessionStorage]) {
    try {
      const left = scrubStore(browserDeviceStore(storage), names)
      if (left.length) console.warn(`self-destruct: ${left.length} stored record(s) still name the room`, left)
    } catch { /* Storage unavailable: nothing more is held there. */ }
  }
  void closeRoomNotifications(context.roomId)
}

/** Forget every archive stream this device can name for the room: its
 *  main chat and rekeys, the main chat of every epoch kept, and the known
 *  channels in each of those epochs. A named channel this device never
 *  learned the name of stays as ciphertext nothing here can open. */
function sweepRoomArchive(roomId: string, roomKey: Uint8Array | undefined): void {
  const archive = roomArchive
  if (!archive) return
  const roots: { id: string; key: Uint8Array }[] = []
  if (roomKey) roots.push({ id: roomId, key: roomKey })
  const kept = loadKeptRoomEpoch(deviceStore, roomId)
  if (kept) for (const e of [kept.epoch, ...kept.past]) if (e.epoch > 0) { const keys = deriveEpoch(e); roots.push({ id: keys.id, key: keys.key }) }
  const names = new Set([AGENT_CHANNEL, TRANSCRIPT_CHANNEL, MINUTES_CHANNEL, CONTROL_CHANNEL, ...(session && currentRoomId() === roomId ? channels : [])])
  const streams = roots.flatMap(root => [...names].flatMap(name => {
    try { return [{ kind: KINDS.CHAT, d: deriveChannel(root.id, root.key, name).id }] } catch { return [] }
  }))
  void Promise.all(streams.map(stream => archive.forget(stream))).catch(error => console.warn('room archive could not forget a channel', error))
}

async function runRoomTidyUp(): Promise<void> {
  const context = tidyUpContext
  if (!context || tidyUpRunning) return
  if (await browserRoomRoutes.selected(context.roomId)) { setStatus('Withdraw this room’s Bothy permissions before public cleanup.'); return }
  tidyUpRunning = true
  const deleteTombstone = ($('tidyUpTombstone') as HTMLInputElement).checked
  const end = context.canEnd && ($('tidyUpEnd') as HTMLInputElement).checked
  ;($('tidyUpEnd') as HTMLInputElement).disabled = true
  ;($('tidyUpRun') as HTMLButtonElement).hidden = true
  ;($('tidyUpCancel') as HTMLButtonElement).hidden = true
  ;($('tidyUpTombstone') as HTMLInputElement).disabled = true
  const reader = new NostrHistoryRelayReader()
  const writer = new NostrPublicDeletionRelayWriter()
  const account = context.account
  let tabsLeft: boolean | undefined
  ++roomOperation
  try {
    const report = await runTidyUp({
      now: nowSeconds,
      roomRelays: context.roomRelays,
      accountRelays: [...new Set([...RELAYS, ...context.roomRelays])],
      read: reader.read,
      publish: (to, event) => writer.publish(to, event),
      ...(context.invitation && context.inviterSk ? { inviter: { sk: context.inviterSk, invitationId: deriveInvitationId(context.invitation) } } : {}),
      device: { sk: context.deviceSk },
      files: deleteRoomFiles(context),
      ...(end ? { endRoom: endRoomForEveryone } : {}),
      ...(account ? { account: {
        pubkey: account.pubkey,
        sign: template => account.signer.signEvent(template),
        ...(context.roomKey ? { readPositionD: readPositionId(context.roomKey) } : {}),
        forgetBookmark: async () => {
          stopWatching(context.roomId)
          return bookmarks ? bookmarks.removeAndConfirm(context.roomId) : undefined
        },
        deleteTombstone,
      } } : {}),
      otherTabsAnswer: async () => { tabsLeft = roomTabs ? await roomTabs.leaveOthers(context.roomId) : true; return tabsLeft },
      leaveOtherTabs: async () => tabsLeft !== false && (roomTabs ? await roomTabs.leaveOthers(context.roomId) : true),
      stopReadPositions: () => stopReadPositions(context.roomId),
      leaveHere: async () => {
        closeAllDrafts()
        await closeRoomSession()
      },
      clearLocal: () => clearRoomLocally(context),
      progress: showTidyStep,
    })
    showTidyReport(report)
    if (report.refused || report.localRetained) {
      ;($('tidyUpCancel') as HTMLButtonElement).hidden = false
      ;($('tidyUpCancel') as HTMLButtonElement).textContent = 'Close'
      return
    }
    tidyUpContext = undefined
    ;($('tidyUpDone') as HTMLButtonElement).hidden = false
    ;($('tidyUpDone') as HTMLButtonElement).focus()
  } catch (err) {
    const problem = document.createElement('p')
    problem.textContent = `The tidy-up stopped: ${describeError(err)}. Steps marked above ran; the rest did not.`
    $('tidyUpResults').append(problem)
    ;($('tidyUpDone') as HTMLButtonElement).hidden = false
  } finally {
    --roomOperation
    tidyUpRunning = false
  }
}

$('tidyUpTombstone').addEventListener('change', renderTidyUpPlan)
$('tidyUpEnd').addEventListener('change', renderTidyUpPlan)
$('tidyUpCancel').addEventListener('click', () => { if (!tidyUpRunning) ($('tidyUpDialog') as HTMLDialogElement).close() })
$('tidyUpDialog').addEventListener('cancel', event => { if (tidyUpRunning) event.preventDefault() })
$('tidyUpDialog').addEventListener('close', () => { ($('tidyUpCancel') as HTMLButtonElement).textContent = 'Cancel' })
$('tidyUpRun').addEventListener('click', () => { void runRoomTidyUp() })
$('tidyUpDone').addEventListener('click', () => {
  ;($('tidyUpDialog') as HTMLDialogElement).close()
  if (session) return
  history.replaceState(null, '', joinLinkBase())
  approvedReload()
})

// ---------------------------------------------------------------------------
// The countdown: green, amber, red, then the final minute, for a room that
// self-destructs; the same pill in neutral grey ("Ends in…") for one that
// ends and keeps a read-only copy, so the colours mean destruction only.
// Every pill carries words and a fuse icon, never colour alone. The arithmetic
// is app/src/self-destruct.ts.
// ---------------------------------------------------------------------------

/** A fuse: a curling cord ending in a spark, in the text's own colour. */
function fuseIcon(): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('viewBox', '0 0 16 16')
  svg.setAttribute('width', '12')
  svg.setAttribute('height', '12')
  svg.setAttribute('aria-hidden', 'true')
  svg.classList.add('fuseIcon')
  const cord = document.createElementNS('http://www.w3.org/2000/svg', 'path')
  cord.setAttribute('d', 'M2 14c3 0 3-4 6-4s3-4 5-5')
  cord.setAttribute('fill', 'none')
  cord.setAttribute('stroke', 'currentColor')
  cord.setAttribute('stroke-width', '1.6')
  cord.setAttribute('stroke-linecap', 'round')
  const spark = document.createElementNS('http://www.w3.org/2000/svg', 'path')
  spark.setAttribute('d', 'M13 1.5l.7 1.8 1.8.7-1.8.7-.7 1.8-.7-1.8-1.8-.7 1.8-.7z')
  spark.setAttribute('fill', 'currentColor')
  svg.append(cord, spark)
  return svg
}

/** A countdown pill for a room ending at `endsAt`. Ticked by `tickFuses`
 *  through its data attributes, wherever it sits. */
function fusePill(endsAt: number, startsAt: number | undefined, destruct: boolean, el: HTMLElement = document.createElement('span')): HTMLElement {
  el.classList.add('fusePill')
  el.dataset.fuseEnds = String(endsAt)
  if (startsAt !== undefined) el.dataset.fuseStarts = String(startsAt)
  else delete el.dataset.fuseStarts
  el.dataset.fuseDestruct = String(destruct)
  fillFuse(el, nowSeconds())
  return el
}

function fillFuse(el: HTMLElement, now: number): CountdownStage {
  const endsAt = Number(el.dataset.fuseEnds)
  const startsAt = el.dataset.fuseStarts ? Number(el.dataset.fuseStarts) : undefined
  const destruct = el.dataset.fuseDestruct === 'true'
  const c = countdown({ endsAt, ...(startsAt !== undefined ? { startsAt } : {}), destruct, now })
  const was = el.dataset.stage
  el.dataset.stage = destruct ? c.stage : 'neutral'
  // The room on screen says its stage changes aloud, once each: amber, red,
  // the final minute. Never the ticks, and never the stage it opened in.
  if (destruct && el.id === 'roomEndsLine' && was && was !== c.stage && el.dataset.fuseFor === String(endsAt)) {
    const said = stageAnnouncement(c.stage, endsAt - now)
    if (said) $('fuseAnnounce').textContent = said
    if (c.stage === 'final') outbox.render()
  }
  el.dataset.fuseFor = String(endsAt)
  el.title = `${destruct ? 'Self-destructs' : 'Ends'} ${formatConferenceEnd(endsAt)}`
  let text = el.querySelector<HTMLElement>('.fuseText')
  let spoken = el.querySelector<HTMLElement>('.fuseSpoken')
  if (!text || !spoken) {
    text = document.createElement('span')
    text.className = 'fuseText'
    text.setAttribute('aria-hidden', 'true')
    spoken = document.createElement('span')
    spoken.className = 'fuseSpoken sr-only'
    el.replaceChildren(fuseIcon(), text, spoken)
  }
  if (text.textContent !== c.text) text.textContent = c.text
  // The spoken name changes only by the minute, so a reader that is
  // looking at it is not interrupted every second.
  const said = c.stage === 'red' || c.stage === 'final' ? `${destruct ? 'Self-destructs' : 'Ends'} in under ${Math.max(1, Math.ceil((endsAt - now) / 60))} ${Math.ceil((endsAt - now) / 60) <= 1 ? 'minute' : 'minutes'}` : c.spoken
  if (spoken.textContent !== said) spoken.textContent = said
  return c.stage
}

/** The countdown's words for a screen reader, as a row's description says it. */
function fuseSpoken(room: Pick<KnownRoom, 'endsAt' | 'startsAt' | 'destruct'>): string | undefined {
  if (room.endsAt === undefined) return undefined
  return countdown({ endsAt: room.endsAt, ...(room.startsAt !== undefined ? { startsAt: room.startsAt } : {}), destruct: !!room.destruct, now: nowSeconds() }).spoken
}

let fuseTicks = 0
const HEADS_UP_PREFIX = 'kithmoot.destruct-heads-up.'

/** Once a second: every pill on the page, the final minute's banner, stage
 *  announcements for the room on screen, and (every ten seconds) the
 *  heads-up at the start of red for any self-destructing room. */
function tickFuses(): void {
  const now = nowSeconds()
  if (muteEnd !== undefined && now >= muteEnd) refreshMutes()
  for (const el of document.querySelectorAll<HTMLElement>('.fusePill[data-fuse-ends]')) fillFuse(el, now)
  const roomId = session ? currentRoomId() : undefined
  const banner = $('fuseBanner')
  const hero = $('roomFuse')
  hero.hidden = !(roomId && roomEndsAt !== undefined && roomDestruct)
  if (roomId && roomEndsAt !== undefined && roomDestruct) {
    const startsAt = roomStartsAt ?? knownRoom(roomStore(), roomId)?.startsAt
    const c = countdown({ endsAt: roomEndsAt, ...(startsAt !== undefined ? { startsAt } : {}), destruct: true, now })
    hero.dataset.stage = c.stage
    const remaining = fuseRemaining(roomEndsAt, startsAt, now)
    hero.style.setProperty('--fuse-remaining', String(remaining))
    $('roomFuseClock').textContent = countdownClock(roomEndsAt - now)
    $('roomFuseBurn').style.width = `${remaining * 100}%`
    $('roomFuseHint').textContent = c.stage === 'gone' ? 'Removing the room…' : c.stage === 'final' ? 'Final seconds · save anything you need now' : 'Save anything you want to keep'
    $('roomFuseSpoken').textContent = $('roomEndsLine').querySelector('.fuseSpoken')?.textContent ?? c.spoken
    banner.hidden = c.stage !== 'final'
    if (c.stage === 'final') banner.textContent = finalBannerText(roomEndsAt - now)
  } else {
    banner.hidden = true
  }
  if (++fuseTicks % 10 === 1) sendHeadsUps(now)
}
setInterval(tickFuses, 1000)

/** One heads-up per self-destructing room, at the start of red, through
 *  the person's notification settings. None at the final minute, and none
 *  for a room first seen already past red. */
function sendHeadsUps(now: number): void {
  const seen = new Set<string>()
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) {
    for (const room of knownRooms(store)) {
      if (seen.has(room.roomId) || !room.destruct || room.endsAt === undefined || room.endedAt !== undefined) continue
      seen.add(room.roomId)
      const life = room.startsAt !== undefined && room.startsAt < room.endsAt ? room.endsAt - room.startsAt : undefined
      if (countdownStage(room.endsAt - now, life) !== 'red') continue
      const key = HEADS_UP_PREFIX + room.roomId
      try { if (localStorage.getItem(key)) continue; localStorage.setItem(key, String(now)) } catch { continue }
      // The room on screen, being looked at, has its pill and its announcement.
      if (session && currentRoomId() === room.roomId && !document.hidden) continue
      const settings = notifySettings(deviceStore)
      if (!settings.enabled || !roomNotificationsEnabled(deviceStore, nostrSession?.pubkey, room.roomId, notificationProjectsForRoom(room.roomId))) continue
      const label = knownRoomLabel(room)
      void deliverIncomingCallAlert({ title: label, body: headsUpText(label, room.endsAt - now), tag: `kithmoot:${room.roomId}:destruct` }, room.roomId).catch(() => {})
    }
  }
}

/** A pending message in a self-destructing room that cannot leave before
 *  the end: shown as "Will not be sent". */
function pendingDoomed(item: PendingSend): boolean {
  if (item.acknowledged || item.state === 'sending') return false
  const room = item.roomId === currentRoomId() && session
    ? { endsAt: roomEndsAt, destruct: roomDestruct }
    : knownRoom(roomStore(), item.roomId) ?? knownRoom(deviceStore, item.roomId)
  if (!room?.destruct || room.endsAt === undefined) return false
  const left = room.endsAt - nowSeconds()
  if (left <= FINAL_SECONDS) return true
  return item.state === 'holding' && (item.holdUntil ?? 0) / 1000 >= room.endsAt
}

// ---------------------------------------------------------------------------
// Self-destruct. A room whose group invitation or closing rekey says
// `destruct` is tidied away on every member's device when it ends, without
// asking: the same steps as "Leave and tidy up" above, run from what this
// device stored, so a device offline at the end does it the next time it
// starts. See docs/persistent-groups.md and app/src/self-destruct.ts.
// ---------------------------------------------------------------------------

const SELF_DESTRUCTED_MESSAGE = 'This room self-destructed.'
/** Rooms this tab is tidying away now: never started twice, and the
 *  bookmark tombstone this tab sends is not taken for another device's. */
const destructing = new Set<string>()
/** A room's secret, held for a moment by whoever learned of the end while
 *  the room was open, in case nothing stored holds it any more. */
const destructSecrets = new Map<string, Uint8Array>()

function roomIsDestruct(roomId: string | undefined): boolean {
  if (!roomId) return false
  return !!(knownRoom(deviceStore, roomId)?.destruct || (bookmarks && knownRoom(bookmarks.rooms, roomId)?.destruct))
}

/** Keep a self-destructing room's device key past the usual 30 days. */
function retainDeviceKey(roomId: string): boolean {
  return roomIsDestruct(roomId)
}

function markRoomDestruct(roomId: string): void {
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) markDestruct(store, roomId)
}

/** Every self-destructing room whose end has come, in either list. */
function dueDestructRooms(): KnownRoom[] {
  const now = nowSeconds()
  const byId = new Map<string, KnownRoom>()
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) {
    for (const room of destructDue(store, now)) if (!byId.has(room.roomId)) byId.set(room.roomId, room)
  }
  return [...byId.values()]
}

let destructRun: Promise<void> | undefined
/** Tidy away every self-destructing room whose end has come. One run at a
 *  time; each room is tried once a run, so a relay that fails is retried at
 *  the next one (the list's timer, the next launch), not in a loop. */
function runDueDestructs(): Promise<void> {
  if (destructRun) return destructRun
  destructRun = (async () => {
    const tried = new Set<string>()
    for (;;) {
      const due = dueDestructRooms().filter(room => !tried.has(room.roomId) && !destructing.has(room.roomId))
      if (!due.length) break
      for (const room of due) {
        tried.add(room.roomId)
        try { await selfDestruct(room) } catch (error) { console.warn('self-destruct did not finish', error) }
      }
    }
  })().finally(() => { destructRun = undefined })
  return destructRun
}

/** One tab at a time per room: the others leave when told. Without the
 *  Web Locks API (old browsers) every tab may try, which only repeats the
 *  same deletion requests. */
async function withRoomLock(roomId: string, run: () => Promise<void>): Promise<boolean> {
  const locks = (navigator as Navigator & { locks?: LockManager }).locks
  if (!locks) { await run(); return true }
  let ran = false
  await locks.request(`kithmoot.self-destruct.${roomId}`, { ifAvailable: true }, async lock => {
    if (!lock) return
    ran = true
    await run()
  })
  return ran
}

/** What the tidy-up needs, from storage: the link's relays and keys, this
 *  device's key for the room, and the account when this tab has its signer. */
function destructContext(room: KnownRoom): TidyUpContext {
  const roomId = room.roomId
  let link: RoomLink | undefined
  try { link = parseRoomLink(room.link) } catch { link = undefined }
  const here = session && currentRoomId() === roomId
  const secret = destructSecrets.get(roomId) ?? (here ? roomSecret : undefined) ?? (link ? secretForKnownRoom(link) : undefined)
  const owner = link?.invitation ? loadInvitationOwner(link.invitation) : undefined
  const roomRelays = here ? [...relays]
    : relayConnections.configuration(`room:${roomId}`, link?.relays ?? []).filter(relay => relay.write).map(relay => relay.url)
  // A device that never wrote in the room holds no key for it: a fresh one
  // finds nothing to delete, which is the truth.
  const deviceSk = loadDeviceKeyFor(deviceStore, roomId) ?? loadDeviceKeyFor(browserDeviceStore(sessionStorage), roomId) ?? generateSecretKey()
  return {
    roomId,
    ...(secret ? { roomKey: deriveRoom(secret).roomKey } : {}),
    roomRelays,
    ...(owner && link?.invitation ? { invitation: link.invitation, inviterSk: owner.inviterSk } : {}),
    deviceSk,
    account: tidyUpAccount(roomId),
    canEnd: false,
  }
}

/** Close whatever notifications this device is showing for the room. */
async function closeRoomNotifications(roomId: string): Promise<void> {
  window.kithmootDesktop?.clearRoomNotices?.(roomId)
  try {
    const registration = await navigator.serviceWorker?.getRegistration()
    for (const shown of await registration?.getNotifications() ?? []) if (shown.tag.startsWith(`kithmoot:${roomId}:`)) shown.close()
  } catch { /* Nothing shown, or nothing to close it with. */ }
}

/**
 * Tidy one self-destructing room away on this device, in the design's
 * order: leave in every tab, delete this device's events, tombstone the
 * account's bookmark and read position, wipe locally, and leave a tombstone
 * row that names no room. `endRoom` closes it for everyone first (Self-
 * destruct now). Deleting the link-key records goes first when this device
 * made the room, while their keys still exist.
 */
async function selfDestruct(room: KnownRoom, endRoom?: () => Promise<void>): Promise<void> {
  const roomId = room.roomId
  if (destructing.has(roomId)) return
  destructing.add(roomId)
  discardRoomRecording(roomId)
  if (dockedCall?.session.roomId === roomId) {
    destructSecrets.set(roomId, dockedCall.ui.roomSecret)
    await endDockedCall('user', SELF_DESTRUCTED_MESSAGE)
  }
  const here = !!session && currentRoomId() === roomId
  try {
    const ran = await withRoomLock(roomId, async () => {
      // Another tab may have finished it while this one waited.
      if (!knownRoom(deviceStore, roomId) && !(bookmarks && knownRoom(bookmarks.rooms, roomId))) return
      const context = destructContext(room)
      const reader = new NostrHistoryRelayReader()
      const writer = new NostrPublicDeletionRelayWriter()
      const account = context.account
      // Only the room on screen: a room tidied away in the background must
      // not stop the one in front of the person hearing that it closed.
      if (here) tidyUpRunning = true
      ++roomOperation
      try {
        const report = await runTidyUp({
          now: nowSeconds,
          roomRelays: context.roomRelays,
          accountRelays: [...new Set([...RELAYS, ...context.roomRelays])],
          read: reader.read,
          publish: (to, event) => writer.publish(to, event),
          ...(context.invitation && context.inviterSk ? { inviter: { sk: context.inviterSk, invitationId: deriveInvitationId(context.invitation) } } : {}),
          device: { sk: context.deviceSk },
          files: deleteRoomFiles(context),
          ...(endRoom ? { endRoom } : {}),
          ...(account ? { account: {
            pubkey: account.pubkey,
            sign: template => account.signer.signEvent(template),
            ...(context.roomKey ? { readPositionD: readPositionId(context.roomKey) } : {}),
            forgetBookmark: async () => {
              stopWatching(roomId)
              return bookmarks ? bookmarks.removeAndConfirm(roomId) : undefined
            },
            deleteTombstone: false,
          } } : {}),
          // The room is over whether or not every tab answers: a tab that
          // did not is ending by its own clock and leaves by itself.
          otherTabsAnswer: async () => { if (roomTabs) await roomTabs.leaveOthers(roomId); return true },
          leaveOtherTabs: async () => (roomTabs ? await roomTabs.leaveOthers(roomId) : true),
          stopReadPositions: () => stopReadPositions(roomId),
          leaveHere: async () => {
            if (!here || !session) return
            closeAllDrafts()
            await closeRoomSession()
          },
          // The row that says a room went is written with the wipe, not
          // after the relay check that follows it: a tab closed or reloaded
          // during that check would otherwise lose it, and the room would
          // vanish from the list without a word.
          clearLocal: () => {
            clearRoomLocally(context, true)
            addTombstone(deviceStore, nowSeconds(), bytesToHex(crypto.getRandomValues(new Uint8Array(16))))
          },
        })
        if (report.refused || report.localRetained) throw new Error(report.refused ?? report.localRetained)
        console.info(`room self-destructed: ${report.steps.map(step => `${step.id}${step.skipped ? ' (skipped)' : ''}`).join(', ')}; ${report.remaining.length} relay record groups still found`)
      } finally {
        --roomOperation
        if (here) tidyUpRunning = false
      }
    })
    // Another tab holds the room's lock and is tidying it; this one only leaves.
    if (!ran && here) await closeRoomSession()
  } finally {
    destructing.delete(roomId)
    destructSecrets.delete(roomId)
    renderRooms()
  }
  if (here) {
    try { sessionStorage.setItem(NOTICE_STORAGE_KEY, SELF_DESTRUCTED_MESSAGE) } catch { /* The room is still gone. */ }
    history.replaceState(null, '', joinLinkBase())
    approvedReload()
  }
}

/** Whether the closing rekey a refusal stood in for said the room self-
 *  destructs. The authority's refusal carries no flag (fold-kit 0.9.0); the
 *  rekey does, and is stored on the room's relays. Read with this device's
 *  current epoch key, so it is found only when the device was one epoch
 *  behind at most, and only while relays keep it (a conference room's rekey
 *  lapses at the room's end under NIP-40). Not found: the room just ends. */
async function closingRekeyDestructs(roomId: string, authority: string, previous: EpochKeys, roomRelays: readonly string[]): Promise<boolean> {
  const reader = new NostrHistoryRelayReader()
  const filter = { kinds: [KINDS.ROOM_REKEY], authors: [authority], '#d': [roomId], limit: 50 }
  const results = await Promise.all(roomRelays.map(relay => Promise.race([
    reader.read(relay, filter).then(result => result.events).catch(() => [] as NostrEvent[]),
    new Promise<NostrEvent[]>(resolve => setTimeout(() => resolve([]), 5_000)),
  ])))
  return results.flat().some(event => readRekeyEvidence(event, { roomId, authority, previous })?.destruct === true)
}

/** A saved room found ended at its door (its link retired): before it is
 *  marked ended, which drops its admission, see whether its closing rekey
 *  said it self-destructs, read with what this device kept of the room. */
async function learnDestructAtDoor(room: KnownRoom): Promise<void> {
  const roomId = room.roomId
  let link: RoomLink
  try { link = parseRoomLink(room.link) } catch { return }
  const secret = secretForKnownRoom(link)
  if (!roomIsDestruct(roomId) && secret && link.invitation) {
    const kept = loadKeptRoomEpoch(deviceStore, roomId)
    const previous: EpochKeys = kept && kept.epoch.epoch > 0 ? deriveEpoch(kept.epoch) : { epoch: 0, id: roomId, key: deriveRoom(secret).roomKey }
    const relays = relayConnections.configuration(`room:${roomId}`, link.relays).filter(relay => relay.read).map(relay => relay.url)
    if (await closingRekeyDestructs(roomId, link.invitation.inviter, previous, relays).catch(() => false)) {
      destructSecrets.set(roomId, secret)
      markRoomDestruct(roomId)
    }
  }
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) markEnded(store, roomId, nowSeconds())
  if (roomIsDestruct(roomId)) await runDueDestructs()
}

/** A docked call's room was closed under it: written down, and tidied
 *  away if it self-destructs. */
function dockedRoomClosed(roomId: string, notice: { destruct?: true }): void {
  const owner = dockedCall
  if (!owner || owner.session.roomId !== roomId) return
  if (notice.destruct || roomIsDestruct(roomId)) {
    destructSecrets.set(roomId, owner.ui.roomSecret)
    discardRoomRecording(roomId)
    markRoomDestruct(roomId)
  }
  void endDockedCall('user', `${owner.label} was closed.`)
  for (const store of bookmarks ? [deviceStore, bookmarks.rooms] : [deviceStore]) markEnded(store, roomId, nowSeconds())
  if (roomIsDestruct(roomId)) void runDueDestructs()
}

/** "Self-destruct now": the authority closes the room with `destruct`, then
 *  tidies away its own copy. */
async function selfDestructNow(): Promise<void> {
  const roomId = currentRoomId()
  if (!roomId || !canEndRoom()) throw new Error('Only the browser that started this room can make it self-destruct.')
  roomDestruct = true
  markRoomDestruct(roomId)
  const room = knownRoom(roomStore(), roomId) ?? knownRoom(deviceStore, roomId)
  if (!room) throw new Error('This room is not saved on this device, so it cannot be tidied away here.')
  destructSecrets.set(roomId, roomSecret)
  await selfDestruct(room, () => endRoomForEveryone(true))
}

/** Taken out by a tidy-up elsewhere: back to the rooms list, not the room's
 *  own link, whose keys are about to go. The read position goes quiet before
 *  this tab says it left, or its delayed record would land on a relay after
 *  the other tab had deleted what it found. */
async function leaveForTidyUp(): Promise<void> {
  const roomId = currentRoomId()
  history.replaceState(null, '', joinLinkBase())
  if (roomId) await stopReadPositions(roomId)
  leaveWithNotice(roomIsDestruct(roomId) ? SELF_DESTRUCTED_MESSAGE : 'You tidied this room up in another tab, so this tab left it.')
}

// A tab frozen while another tidied the room up could not answer. When it
// wakes, the room's device key is gone from storage: leave rather than go on
// publishing under a key nothing here holds any more.
window.addEventListener('storage', event => {
  const callRoom = dockedCall?.session.roomId
  if (callRoom && event.key === DEVICE_PREFIX + callRoom && event.newValue === null) {
    discardRoomRecording(callRoom)
    void endDockedCall('user', SELF_DESTRUCTED_MESSAGE)
    return
  }
  const roomId = session ? currentRoomId() : undefined
  if (!roomId || event.key !== DEVICE_PREFIX + roomId || event.newValue !== null) return
  void leaveForTidyUp()
})

/** Leaving, asked once (design-calm-shell 11). The box folds the old "Leave and
 *  tidy up" in: ticked, the tidy-up flow runs in place of a plain leave and
 *  shows its own steps and report; unticked it is just leaving. Unsent work is
 *  still asked about first, as it always was. */
$('leave').addEventListener('click', async () => {
  if (hasUnsentWork() && !await confirmDiscardAndLeave()) return
  const me = meParticipant || currentParticipant()
  const chat = Boolean(me && dmPeer(roomPolicy, me))
  const tidy = document.createElement('label')
  tidy.className = 'leaveTidy'
  const box = document.createElement('input')
  box.type = 'checkbox'
  box.id = 'leaveTidyBox'
  tidy.append(box, document.createTextNode('Also ask relays and the file server to delete what I left'))
  if (!await confirmRoomAction({
    title: chat ? 'Leave this private chat?' : `Leave ${currentRoomLabel()}?`,
    message: 'You stop getting its messages. You can come back with the link.',
    confirmLabel: 'Leave',
    danger: true,
    content: tidy,
  })) return
  if (box.checked) { await openTidyUp(); return }
  void leaveRoom()
})

// A closed tab, a navigation away, or a phone putting the browser to sleep
// is a departure too, and a silent one costs everybody else the whole
// presence timeout. Best effort: the farewell is one small publish over
// sockets that are already open, and the page is gone whatever happens.
window.addEventListener('beforeunload', event => {
  // A recording running, or finished and not yet shared or saved, is lost
  // with the page.
  if (activeRecording || pendingRecording) { event.preventDefault(); event.returnValue = ''; return }
  if (navigationApproved || (!boardsPanel?.hasPendingEdits && !hasUnsentWork())) return
  event.preventDefault()
  event.returnValue = ''
})
window.addEventListener('pagehide', () => {
  closeAllDrafts()
  resetIncomingCall()
  session?.leave()
  dockedCall?.session.leave()
  stopInvitationHost()
  for (const roomId of [...roomWatches.keys()]) stopWatching(roomId)
  void callWakeLock.release()
})

setToggle('toggleAgentsHear', agentsMayHear)
document.documentElement.toggleAttribute('data-agents-hear', agentsMayHear)
$('toggleAgentsHear').addEventListener('click', () => setAgentsMayHear(!agentsMayHear))

// The agents' conversation had its own box to type in, under the chat's
// own box, on the same screen. Two writing boxes on one page is a question
// nobody should have to answer. There is one now, and the tab above it says
// which conversation it is writing to - see `activeChat`.

/**
 * The box grows with what is written in it.
 *
 * It was one line that scrolled sideways, so a message longer than the box
 * could not be read back before it was sent - and somebody who cannot
 * re-read what they wrote sends it anyway and finds the typo afterwards.
 * Six lines is enough for a paragraph; past that it scrolls, because a box
 * that grows without limit eats the conversation above it.
 */
const COMPOSER_MAX_LINES = 6

function growComposer(box: HTMLTextAreaElement): void {
  // A hidden box measures as nothing, and writing that measurement back
  // would leave it nothing once it is shown again.
  if (!box.isConnected || box.offsetParent === null) return
  box.style.height = 'auto'
  const style = getComputedStyle(box)
  const line = Number.parseFloat(style.lineHeight) || 20
  const padding = (Number.parseFloat(style.paddingTop) || 0) + (Number.parseFloat(style.paddingBottom) || 0)
  const borders = (Number.parseFloat(style.borderTopWidth) || 0) + (Number.parseFloat(style.borderBottomWidth) || 0)
  const most = line * COMPOSER_MAX_LINES + padding + borders
  // A long conversation name in the placeholder is not a multi-line draft.
  box.style.height = `${box.value ? Math.min(box.scrollHeight + borders, most) : line + padding + borders}px`
  // Past one line the pill around it is a rounded box rather than a capsule.
  box.parentElement?.classList.toggle('grown', box.scrollHeight > line + padding + borders + 2)
}

// ---------------------------------------------------------------------------
// Typing somebody's name
//
// An `@` opens the room. It filters as you keep typing, a tap or Enter puts
// the name in, Escape closes it. What goes into the box is the display name
// EXACTLY as the roster spells it - not slugified, not stripped of spaces,
// not lowercased - because the agent side matches on that string and a
// transformed one silently never matches. "The moot" is a real name in a
// real room and `@The moot` has to work.
//
// The list opens UPWARDS, above the box. Below the box on a phone is where
// the keyboard is, and a picker behind a keyboard does not exist.
// ---------------------------------------------------------------------------

interface MentionChoice {
  name: string
  /** Which participant this names, for the picker to record when it is
   *  chosen - see `chooseMention`. Absent for `@all`/`@everyone` and for a
   *  model completion. */
  participant?: string
  agent: boolean
  room?: boolean
  model?: ComposerModel
  /** The short npub, shown only when another candidate shares this name. */
  npub?: string
}

/** Where the `@` being completed sits in the box, or -1 for closed. */
let mentionAt = -1
let mentionChoices: MentionChoice[] = []
let mentionCursor = 0
let dismissedMention: { session: typeof session; channel: typeof currentChannel; value: string; start: number; end: number } | undefined

/** How much text after an `@` is still plausibly a name being typed. Names
 *  can carry spaces, so this cannot stop at the first one; it stops when
 *  what has been typed is longer than any name could reasonably be. */
const MENTION_QUERY_LIMIT = 48

function closeMentionPicker(): void {
  if (mentionAt === -1) return
  mentionAt = -1
  mentionChoices = []
  mentionCursor = 0
  const box = $('mentions')
  box.hidden = true
  box.innerHTML = ''
  $('chatInput').setAttribute('aria-expanded', 'false')
  $('chatInput').removeAttribute('aria-activedescendant')
}

function availableComposerModels(): ComposerModel[] {
  return composerModels(catalogues.values(), session?.participants() ?? [])
}

function modelClerkNames(): string[] {
  // Remember the addressed clerk after it leaves so a draft's selector is
  // still validated, rather than becoming ordinary text when the roster shrinks.
  const names = new Set(rosterNames())
  for (const catalogue of catalogues.values()) {
    for (const entry of catalogue.agents) {
      if (entry.models && catalogue.running.some(r => r.id === entry.id && r.participant === catalogue.host)) names.add(entry.name)
    }
  }
  return [...names]
}

/** Everybody in the room bar yourself, people and agents alike, ordered so
 *  that what you have typed so far leads the list, and named as they are
 *  actually shown on screen - not by the roster's announced joining name,
 *  which can differ once a profile arrives. Two people shown under the
 *  same name both appear, each with its own short npub so they can be
 *  told apart before picking. See `mention-candidates.ts`. */
function mentionCandidates(query: string): MentionChoice[] {
  const roster = (session?.participants() ?? [])
    .filter((view) => view.participant !== meParticipant)
    .map((view) => ({ participant: view.participant, name: shownAs(view.participant, view.name).name ?? '', agent: view.agent === true }))
  return buildMentionCandidates(query, roster, (participant) => shortNpub(participant))
}

/**
 * Decide whether an `@` is being completed right now, and draw the list.
 *
 * Run on every keystroke and every move of the caret. The `@` counts only
 * at the start of a word, so an email address in the middle of a sentence
 * does not open a picker.
 */
function renderMentionPicker(): void {
  const box = $('chatInput')
  if (!(box instanceof HTMLTextAreaElement) || !session) {
    dismissedMention = undefined
    closeMentionPicker()
    return
  }
  const caret = box.selectionStart ?? 0
  // Escape dismisses this completion until the draft or caret changes.
  // Queued selection events and catalogue updates must not reopen it.
  if (dismissedMention?.session === session && dismissedMention.channel === currentChannel &&
    dismissedMention.value === box.value && dismissedMention.start === caret && dismissedMention.end === box.selectionEnd) {
    closeMentionPicker()
    return
  }
  dismissedMention = undefined
  if (box.selectionEnd !== caret) { closeMentionPicker(); return }
  const before = box.value.slice(0, caret)
  const models = modelCompletions(before, availableComposerModels(), modelClerkNames())
  const at = models === undefined ? before.lastIndexOf('@') : 0
  const priorChar = at > 0 ? before[at - 1] ?? '' : ''
  const startsWord = at === 0 || /[^\p{L}\p{N}_]/u.test(priorChar)
  const query = at === -1 ? '' : before.slice(at + 1)
  if (models === undefined && (at === -1 || !startsWord || query.includes('\n') || query.length > MENTION_QUERY_LIMIT)) {
    closeMentionPicker()
    return
  }
  const choices: MentionChoice[] = models === undefined ? mentionCandidates(query) :
    models.map(model => ({ name: `^${model.id}`, agent: true, model }))
  if (choices.length === 0) {
    closeMentionPicker()
    return
  }
  const reopened = mentionAt !== at
  mentionAt = at
  mentionChoices = choices
  mentionCursor = reopened ? 0 : Math.min(mentionCursor, choices.length - 1)

  const list = $('mentions')
  list.setAttribute('aria-label', models === undefined ? 'People and agents in this room' : 'Models available for this task')
  list.innerHTML = ''
  choices.forEach((choice, i) => {
    const option = document.createElement('button')
    option.type = 'button'
    option.id = `composer-choice-${i}`
    option.setAttribute('role', 'option')
    option.setAttribute('aria-selected', String(i === mentionCursor))
    const name = document.createElement('span')
    name.className = 'name'
    name.textContent = choice.name
    option.append(name)
    if (choice.room) {
      const detail = document.createElement('span')
      detail.className = 'model-label'
      detail.textContent = 'Everyone in this room, including agents'
      option.append(detail)
    }
    if (choice.model) {
      option.className = 'model-choice'
      const detail = document.createElement('span')
      detail.className = 'model-label'
      detail.textContent = `${choice.model.label} · ${choice.model.agent}`
      option.append(detail)
    }
    // Two people shown under the same name: the npub is the only thing
    // telling this entry apart from its name-mate before it is picked.
    if (choice.npub) {
      const detail = document.createElement('span')
      detail.className = 'model-label'
      detail.textContent = choice.npub
      option.append(detail)
    }
    // The same tag in the same colour as on the roster and on the bubbles,
    // so "this one is a program" is one idea told one way everywhere.
    if (choice.agent && !choice.model) {
      const badge = document.createElement('span')
      badge.className = 'badge agent'
      badge.textContent = 'Agent'
      option.append(badge)
    }
    // Pointer down rather than click: a tap takes focus off the box, and a
    // box that has lost focus has no caret to insert at.
    option.addEventListener('pointerdown', (event) => {
      event.preventDefault()
      chooseMention(i)
    })
    list.append(option)
  })
  list.hidden = false
  box.setAttribute('aria-expanded', 'true')
  box.setAttribute('aria-activedescendant', `composer-choice-${mentionCursor}`)
  list.querySelector('[aria-selected="true"]')?.scrollIntoView({ block: 'nearest' })
}

/** Put the chosen name in, spelled exactly as the roster spells it, with a
 *  space after it so the next word is not stuck to the name. */
function chooseMention(index: number): void {
  const box = $('chatInput')
  const choice = mentionChoices[index]
  if (!(box instanceof HTMLTextAreaElement) || !choice || mentionAt === -1) return
  const caret = box.selectionStart ?? 0
  const suffix = box.value.slice(caret)
  const separator = /^\s/.test(suffix) ? '' : ' '
  const inserted = (choice.model ? `@${choice.model.agent} ^${choice.model.id}` : `@${choice.name}`) + separator
  box.value = box.value.slice(0, mentionAt) + inserted + suffix
  const after = mentionAt + inserted.length
  closeMentionPicker()
  box.focus()
  box.setSelectionRange(after, after)
  dismissedMention = { session, channel: currentChannel, value: box.value, start: after, end: after }
  growComposer(box)
  const draft = captureDraft()
  // Remember which participant this name resolved to, so a name shared by
  // more than one person still addresses the one actually picked - see
  // `resolveDraftMentions` in mention-candidates.ts.
  if (choice.participant) {
    if (!draft.pickedMentions) draft.pickedMentions = new Map()
    draft.pickedMentions.set(choice.name.trim().toLowerCase(), choice.participant)
  }
}

function moveMentionCursor(by: number): void {
  if (mentionChoices.length === 0) return
  mentionCursor = (mentionCursor + by + mentionChoices.length) % mentionChoices.length
  const options = $('mentions').querySelectorAll('[role="option"]')
  options.forEach((option, i) => option.setAttribute('aria-selected', String(i === mentionCursor)))
  $('chatInput').setAttribute('aria-activedescendant', `composer-choice-${mentionCursor}`)
  options[mentionCursor]?.scrollIntoView({ block: 'nearest' })
}

/**
 * Say what will come of a typed `!minutes`, either way.
 *
 * The Minutes tab printed that instruction unconditionally, and in a room
 * with no scribe in it typing the words posted a plain message and produced
 * nothing: no minutes, no refusal, no error. Silence after following a
 * written instruction reads as "I did it wrong", which is the worst answer
 * a first-time reader can be given. The tab no longer prints the
 * instruction when nothing can answer it, and this answers anybody who
 * types it anyway - or who was told the words by somebody else.
 */
function acknowledgeMinutesRequest(): void {
  addSystemLine(
    minuteTakerHere()
      ? 'You asked for the minutes. They appear on the Minutes tab once the agent has written them.'
      : 'Nothing in this room writes minutes at the moment, so nobody is going to answer that. ' +
          'Minutes are written by an agent somebody brings in, and the Agents tab says who is here.',
  )
}

function openChatArt(mode: 'emoji' | 'stickers' | 'gifs'): void {
  const input = $('chatInput') as HTMLTextAreaElement
  if (input.readOnly) return
  chatArtPicker.close()
  const generation = roomGeneration, channel = currentChannel
  // Touch browsers can reset an inactive textarea's selection after a picker
  // button receives focus. Keep our insertion range until the person moves it.
  let start = input.selectionStart, end = input.selectionEnd, direction = input.selectionDirection
  const selectionEvents = new AbortController()
  const rememberSelection = () => {
    if (document.activeElement !== input || roomGeneration !== generation || currentChannel !== channel) return
    start = input.selectionStart; end = input.selectionEnd; direction = input.selectionDirection
  }
  for (const event of ['input', 'click', 'keyup', 'select']) input.addEventListener(event, rememberSelection, { signal: selectionEvents.signal })
  chatArtPicker.openComposer($('emojiToggle'), input, mode, emoji => {
    if (roomGeneration !== generation || currentChannel !== channel || input.readOnly) return
    if (input.value.length - (end - start) + emoji.length > MAX_CHAT_TEXT_LENGTH) {
      setStatus('There is no room for that emoji. Shorten your message first.')
      return
    }
    input.setRangeText(emoji, start, end, 'end')
    start += emoji.length; end = start; direction = 'none'
    input.dispatchEvent(new Event('input', { bubbles: true }))
  }, async (item, signal) => {
    signal.throwIfAborted()
    if (roomGeneration !== generation || currentChannel !== channel || input.readOnly) throw new Error('The conversation changed. Open the picker again.')
    const draft = captureDraft()
    if (draft.artwork.length >= MAX_CHAT_ARTWORK) throw new Error(`A message carries at most ${MAX_CHAT_ARTWORK} stickers or GIFs.`)
    draft.artwork.push(catalogueArtwork(item))
    draftChanged(draft)
  }, () => {
    selectionEvents.abort()
    if (roomGeneration === generation && currentChannel === channel && input.isConnected) input.setSelectionRange(start, end, direction)
  })
}
$('emojiToggle').addEventListener('click', () => openChatArt('emoji'))

// ---------------------------------------------------------------------------
// What the box is doing besides saying something new
//
// Answering a message puts the reply in its thread; editing replaces one of
// ours. Either is shown above the box with a way out, and cleared when the
// message goes. Reply and edit targets stay with their draft in this tab;
// they never carry over to a different room or conversation.
// ---------------------------------------------------------------------------

function setComposing(next: { replyTo?: ChatMessage; editing?: ChatMessage }, shown?: ChatMessage): void {
  const current = drafts.get(currentChannel)
  current.replyTo = next.replyTo
  current.editing = next.editing
  const box = $('chatInput') as HTMLTextAreaElement
  if (next.editing && shown) {
    // The message as it reads now, to correct, with its files staged so
    // an edit that says nothing about them keeps them. An edit is the
    // whole new message; see docs/messages.md.
    const draft = captureDraft()
    box.value = artworkMessageText(shown.text, shown.artwork)
    draft.text = box.value
    draft.attachments = [...(shown.attachments ?? [])]
    draft.artwork = [...(shown.artwork ?? [])]
    draftChanged(draft)
    growComposer(box)
  }
  renderComposerContext()
  box.focus()
}

function renderComposerContext(): void {
  const composing = drafts.get(currentChannel)
  const bar = $('composerContext')
  bar.innerHTML = ''
  const target = composing.editing ?? composing.replyTo
  if (!target) {
    bar.hidden = true
    return
  }
  const label = document.createElement('span')
  label.className = 'contextLabel'
  label.textContent = composing.editing ? 'Editing your message' : `Replying to ${senderLabel(target)}`
  const excerpt = document.createElement('span')
  excerpt.className = 'contextExcerpt'
  excerpt.textContent = resolveConversation(activeChat()?.messages() ?? []).byKey.get(refKey({ messageId: target.id, participant: target.participant }))?.shown.text ?? target.text
  const cancel = document.createElement('button')
  cancel.type = 'button'
  cancel.className = 'quiet'
  cancel.textContent = 'Cancel'
  cancel.setAttribute('aria-label', composing.editing ? 'Stop editing' : 'Stop replying')
  cancel.addEventListener('click', () => {
    if (composing.editing) {
      const box = $('chatInput') as HTMLTextAreaElement
      const draft = captureDraft()
      box.value = ''
      draft.text = ''
      draft.attachments = []
      draft.artwork = []
      draftChanged(draft)
      growComposer(box)
    }
    setComposing({})
  })
  bar.append(label, excerpt, cancel)
  bar.hidden = false
}

/**
 * Who the typed text addresses, declared on the wire: everybody on the
 * roster it names as a whole word, with or without the @, which is the
 * rule readers have always applied. Explicit @all and @everyone calls
 * include the entire room. The broadcast comes first so it survives the cap.
 */
function mentionsInDraft(text: string): string[] {
  const roster = (session?.participants() ?? [])
    .filter((view) => view.participant !== meParticipant)
    .map((view) => ({ participant: view.participant, name: shownAs(view.participant, view.name).name, agent: view.agent }))
  const picked = drafts.get(currentChannel).pickedMentions ?? new Map<string, string>()
  return resolveDraftMentions(text, roster, picked, MAX_MENTIONS)
}

async function retractMessage(original: ChatMessage): Promise<void> {
  const chat = activeChat() ?? session?.chat
  const channel = currentChannel
  if (!chat) return
  if (!await confirmRoomAction({ title: 'Retract this message?', message: 'It will be marked retracted. People who already received it may still have a copy.', confirmLabel: 'Retract message', danger: true })) return
  try {
    const text = retractionText()
    await queueSend(chat.prepare(text, { retracts: original.id }), channel ?? 'Chat')
  } catch (err) {
    setStatus(describeError(err))
  }
}

const retainingDrafts = new WeakMap<ConversationDraft, Set<string>>()
$('chatForm').addEventListener('submit', async (event) => {
  event.preventDefault()
  const draft = captureDraft()
  if (draft.job || draft.pendingFiles?.length || !channelAvailable(currentChannel) || (currentChannel !== undefined && WRITTEN_BY_AGENTS.includes(currentChannel))) return
  const input = $('chatInput') as HTMLTextAreaElement
  if (input.value.length > MAX_CHAT_TEXT_LENGTH) { void sendLongText(draft, input.value); return }
  let typed = input.value.trim()
  try {
    typed = prepareModelMessage(typed, availableComposerModels(), modelClerkNames())
  } catch (err) {
    setStatus(describeError(err))
    return
  }
  const attachments = draft.attachments
  const artwork = draft.artwork
  if ((!typed && attachments.length === 0 && artwork.length === 0) || !session) return
  // A file with nothing said about it still gets a caption, because the
  // caption is all a client that has never heard of attachments will show.
  const text =
    typed ||
    (attachments.length === 0 && artwork.length ? artworkFallbackText(artwork) : attachments.length === 1
      ? `Shared a file${attachments[0]?.name ? `: ${attachments[0].name}` : ''}`
      : `Shared ${attachments.length} files`)
  const log = activeChat() ?? session.chat
  const sendOpts: SendOptions = attachments.length ? { attachments } : {}
  if (artwork.length) sendOpts.artwork = artwork
  const mentions = mentionsInDraft(typed)
  if (mentions.length) sendOpts.mentions = mentions
  if (draft.editing) sendOpts.replaces = draft.editing.id
  else if (draft.replyTo) sendOpts.replyTo = draft.replyTo
  const submissionSnapshot = draftSubmissionSnapshot(input.value, draft)
  let submissions = retainingDrafts.get(draft)
  if (submissions?.has(submissionSnapshot)) return
  if (!submissions) { submissions = new Set(); retainingDrafts.set(draft, submissions) }
  submissions.add(submissionSnapshot)
  let prepared: PreparedSend
  try {
    prepared = log.prepare(text, sendOpts)
  } catch (err) {
    submissions.delete(submissionSnapshot)
    if (!submissions.size) retainingDrafts.delete(draft)
    setStatus(describeError(err))
    return
  }
  // Into whichever conversation is on screen, which is the main chat until
  // somebody picks another.
  // Kept across a reload when it is an ordinary main-chat message in a room
  // that is not quiet: a quiet room keeps its own queue.
  // Edit takes back only what it can put back as it was: a plain new
  // message, not a reply, an edit or one carrying files.
  // Queue and show it before clearing the draft.
  const sendingSession = session, sendingChannel = currentChannel
  const draftSnapshot = draftSubmissionSnapshot(input.value, draft)
  try {
    await queueSend(prepared, currentChannel ?? 'Chat', {
      files: attachments.map(a => a.name ?? 'Encrypted file'),
      durable: currentChannel === undefined && !quietTransport,
      editable: !attachments.length && !sendOpts.replaces && !sendOpts.replyTo,
      holdSeconds: sendDelaySeconds(),
    })
  } catch (err) {
    setStatus(describeError(err))
    return
  } finally {
    submissions.delete(submissionSnapshot)
    if (!submissions.size) retainingDrafts.delete(draft)
  }
  if (session !== sendingSession || currentChannel !== sendingChannel || drafts.get(sendingChannel) !== draft ||
      draftSubmissionSnapshot(input.value, draft) !== draftSnapshot) return
  input.value = ''
  showPasteSize()
  draft.text = ''
  draft.pickedMentions = undefined
  draft.selectionStart = draft.selectionEnd = 0
  growComposer(input)
  closeMentionPicker()
  draft.attachments = []
  draft.artwork = []
  draftChanged(draft)
  setComposing({})
  chatScroll.latest()
  if (currentChannel === undefined && asksForMinutes(typed)) acknowledgeMinutesRequest()
})

// The box grows as it is typed into, and Enter sends. Shift and Enter start
// a new line, which is the pair of habits every chat box has and the reason
// a multi-line box costs nothing to use.
$('chatInput').addEventListener('input', () => {
  dismissedMention = undefined
  const draft = captureDraft()
  growComposer($('chatInput') as HTMLTextAreaElement)
  renderMentionPicker()
  renderDraftBadges()
  renderWorkspace()
  ;($('discardDraft') as HTMLButtonElement).hidden = !draftHasWork(draft)
  $('draftHelp').hidden = drafts.pending().length === 0
})
// The caret can move without a keystroke - a tap, a drag, an arrow key -
// and whether an `@` is being completed depends on where it is.
for (const kind of ['click', 'keyup', 'select'] as const) {
  $('chatInput').addEventListener(kind, event => {
    if (event instanceof KeyboardEvent && event.key === 'Escape') return
    renderMentionPicker()
  })
}
$('chatInput').addEventListener('blur', () => closeMentionPicker())

$('chatInput').addEventListener('keydown', (event) => {
  if (!(event instanceof KeyboardEvent)) return
  // Mid-composition in an IME, these keys belong to the IME.
  if (event.isComposing) return

  // While the picker is open it has the keys it needs, and Enter picks a
  // name rather than sending a half-typed one.
  if (mentionAt !== -1) {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      moveMentionCursor(1)
      return
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      moveMentionCursor(-1)
      return
    }
    if (event.key === 'Enter' || event.key === 'Tab') {
      event.preventDefault()
      chooseMention(mentionCursor)
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      const box = $('chatInput') as HTMLTextAreaElement
      dismissedMention = { session, channel: currentChannel, value: box.value, start: box.selectionStart, end: box.selectionEnd }
      closeMentionPicker()
      return
    }
  }

  if (event.key !== 'Enter' || event.shiftKey || event.altKey || event.ctrlKey || event.metaKey) return
  event.preventDefault()
  ;($('chatForm') as HTMLFormElement).requestSubmit()
})

$('roomRename').addEventListener('submit', (event) => {
  event.preventDefault()
  const input = $('roomRenameInput') as HTMLInputElement
  const name = sanitiseDisplayName(input.value)
  if (name === undefined) {
    setStatus('A room name cannot be empty.')
    return
  }
  if (name === roomName) return
  const button = $('roomRenameSave') as HTMLButtonElement
  button.disabled = true
  renameRoomForEveryone(name)
    .then(() => { input.blur(); setStatus(`Renamed the room to “${name}” for everyone.`) })
    .catch((err) => setStatus(describeError(err)))
    .finally(() => { button.disabled = false; renderRoomRename() })
})

$('roomLogoEdit').addEventListener('click', () => {
  const s = session, follower = s ? roomLogoFollowers.get(s) : undefined
  if (!s || !follower || s.channel(CONTROL_CHANNEL).readOnly) return
  const epoch = s.epoch, me = s.participant
  openLogoEditor({ name: currentRoomLabel(), image: follower.current()?.image,
    removeLabel: 'Remove room logo',
    save: async image => {
      if (session !== s || s.epoch !== epoch || s.participant !== me || roomLogoFollowers.get(s) !== follower || conferenceEnded(s.endsAt, nowSeconds())) {
        throw new Error('This room changed while you were editing. Close the editor and try again.')
      }
      const record = await follower.replace(image)
      if (session === s) adoptSharedRoomLogo(s, record)
    } })
})

$('channelNew').addEventListener('submit', (event) => {
  event.preventDefault()
  const input = $('channelName')
  if (!(input instanceof HTMLInputElement)) return
  const name = input.value.trim().toLowerCase()
  // Checked here as well as in the protocol, so a typo is answered on the
  // spot rather than by a request that quietly does nothing.
  if (!CHANNEL_NAME.test(name)) {
    setStatus('A channel name is lower case letters, digits and hyphens, starting with a letter or digit.')
    return
  }
  input.value = ''
  void requestChannel(name, true)
})

// Two clicks rather than a `confirm()`. A browser modal blocks the page and
// reads as an error, and this is not one: closing a channel takes it off the
// room's list and deletes nothing, because everybody admitted still holds
// the key that opens what was said there. So the button says so and asks
// again, in the page.
$('channelClose').addEventListener('click', () => {
  const name = currentChannel
  if (name === undefined) return
  const button = $('channelClose')
  if (button.dataset.arm !== name) {
    button.dataset.arm = name
    button.textContent = `Really close ${name}? Nothing is deleted`
    return
  }
  delete button.dataset.arm
  void requestChannel(name, false)
})

// ---------------------------------------------------------------------------
// Attaching a Wildbloom share to a message
// ---------------------------------------------------------------------------

function renderStaged(): void {
  const draft = drafts.get(currentChannel)
  const box = $('attachStaged')
  box.innerHTML = ''
  draft.attachments.forEach((a, i) => {
    const chip = document.createElement('span')
    chip.className = 'attachChip'
    chip.textContent = `${a.name ?? 'Encrypted file'}${a.size !== undefined ? ` \u00b7 ${formatBytes(a.size)}` : ''} `
    const remove = document.createElement('button')
    remove.type = 'button'
    remove.textContent = 'remove'
    remove.addEventListener('click', () => {
      draft.attachments.splice(i, 1)
      draftChanged(draft)
    })
    chip.append(remove)
    box.append(chip)
  })
  draft.artwork.forEach((artwork, index) => {
    const chip = document.createElement('span'); chip.className = 'attachChip artworkChip'
    chip.append(artworkCards([artwork]), document.createTextNode(`${artwork.kind === 'gif' ? 'GIF' : 'Sticker'}: ${artwork.label} `))
    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = 'remove'; remove.setAttribute('aria-label', `Remove ${artwork.label} ${artwork.kind}`)
    remove.onclick = () => { draft.artwork.splice(index, 1); draftChanged(draft) }
    chip.append(remove); box.append(chip)
  })
  // One name, whatever the state. The button used to be "Add a file" in the
  // markup and "Attach" the moment anything re-rendered it, so a control a
  // person had already found went and a different one appeared in its
  // place. Only the count changes, and it has a span of its own so that
  // neither the label nor the accessible name is touched.
  $('attachCount').textContent = draft.attachments.length ? ` (${draft.attachments.length})` : ''
}

/**
 * The kind-1063 event behind what was pasted: the signed JSON itself, or an
 * id (hex, note1 or nevent1) looked up on the room's relays. Wildbloom shows
 * its uploader the id, so that is the common case; the JSON is for when the
 * event was published somewhere these relays never saw.
 */
async function resolveFileEvent(text: string, signal?: AbortSignal): Promise<NostrEvent> {
  signal?.throwIfAborted()
  const value = text.trim()
  if (value.startsWith('{')) {
    let event: NostrEvent
    try {
      event = JSON.parse(value) as NostrEvent
    } catch {
      throw new Error('That is not event JSON.')
    }
    if (!verifyEventUncached(event)) throw new Error('That event JSON does not verify.')
    return event
  }
  let id = value.toLowerCase()
  if (/^(note1|nevent1)/.test(id)) {
    try {
      const decoded = nip19Decode(value)
      id = decoded.type === 'note' ? decoded.data : decoded.type === 'nevent' ? decoded.data.id : ''
    } catch {
      id = ''
    }
  }
  if (!/^[0-9a-f]{64}$/.test(id)) throw new Error('Paste the file event id (64 hex characters) or the event JSON.')
  const transport = configuredPool(relays)
  try {
    return await new Promise<NostrEvent>((resolve, reject) => {
      let off = (): void => {}
      const stop = (): void => {
        clearTimeout(timer)
        off()
        signal?.removeEventListener('abort', cancel)
      }
      const cancel = (): void => { stop(); reject(new Error('Stopped adding the file.')) }
      const timer = setTimeout(() => {
        stop()
        reject(new Error('The room\'s relays do not have that event. Paste the event JSON instead.'))
      }, 8_000)
      signal?.addEventListener('abort', cancel, { once: true })
      off = transport.subscribe([{ ids: [id] }], (event) => {
        if (event.id !== id || !verifyEventUncached(event)) return
        stop()
        resolve(event)
      })
    })
  } finally {
    transport.close()
  }
}

/** What the chat carries for a file event, once the key is known. The
 *  event tells where the envelope is and what its bytes hash to; the source
 *  name and type are inside the envelope and stay there until it is opened. */
function shareFromEvent(event: NostrEvent, keyHex: string): ChatAttachment {
  if (event.kind !== 1063) throw new Error('That is not a file event (kind 1063).')
  const tag = (name: string): string | undefined => event.tags.find((t) => t[0] === name)?.[1]
  const url = tag('url')
  const sha256 = tag('x')
  const size = Number(tag('size'))
  if (!url || !/^https:\/\//i.test(url)) throw new Error('The file event has no https URL.')
  if (!sha256 || !/^[0-9a-fA-F]{64}$/.test(sha256)) throw new Error('The file event has no hash.')
  const share: ChatAttachment = { event: event.id, url, sha256: sha256.toLowerCase(), key: keyHex }
  if (Number.isSafeInteger(size) && size > 0) share.size = size
  return share
}

// ---------------------------------------------------------------------------
// Dropping a file straight into the chat
// ---------------------------------------------------------------------------

/** No implicit host fallback, including for Context uploads. */
function blossomServer(): string {
  return sharedFileServer(localStorage)
}

/** A file server someone who built this copy of the app chose to suggest
 *  (`VITE_KITHMOOT_FILE_SERVER`, set at build time). ForgeSworn's own build
 *  sets nothing, so the field is empty unless this device remembers a choice.
 *  A suggestion is never consent. */
const deployerFileServer = typeof import.meta.env.VITE_KITHMOOT_FILE_SERVER === 'string'
  ? import.meta.env.VITE_KITHMOOT_FILE_SERVER as string
  : undefined

/** Set when start-up removed a consent that only the old pre-filled
 *  suggestion had given. Shown until a server is chosen, and does not name
 *  the old host, so it steers nobody back to it. */
const FILE_SERVER_RETIRED = 'KithMoot no longer suggests a file server. Choose where your files go to send files again.'
let fileServerRetired = false

function renderFileStorage(): void {
  const server = blossomServer()
  if (server) fileServerRetired = false
  $('fileStorageStatus').textContent = server
    ? `Uploads go to ${server}. Files are encrypted on this device first.`
    : fileServerRetired ? FILE_SERVER_RETIRED : 'File uploads are off. Choose where files go to turn them on.'
  $('fileStorageSummary').textContent = server ? 'Change where files go' : 'Choose where files go'
  $('stopFileUploads').hidden = !server
}

function requireFileStorage(server: string): void {
  if (!server || requireSharedFileServer(localStorage) !== server) throw new Error(FILE_STORAGE_REQUIRED)
}

/** Something to look at while a file is sealed and sent. Stage by stage
 *  rather than byte by byte: fetch gives no upload progress, and a stage
 *  line with the file's name and size says what is being waited for. */
function dropProgress(draft: ConversationDraft, stage: string, file: File): void {
  draft.status = `${stage} ${file.name} (${formatBytes(file.size)})…`
  draftChanged(draft)
}

/**
 * One dropped file, from bytes on this device to a staged attachment:
 * sealed here under a fresh key, put on the Blossom server as an opaque
 * blob, announced with a kind-1063 event on the room's relays, and then
 * staged exactly as a pasted Wildbloom share is. The device key signs the
 * upload and any announcement, so a hardware signer is never asked and a
 * relay learns only that this device shared some encrypted bytes.
 *
 * A quiet room never gets that announcement: the chat message a moment
 * later already carries the url, hash, key, name, type and size inside its
 * ciphertext (or gift wrap), and a kind-1063 event bare on the relay would
 * say, in the open, that a device in this room shared a file and when -
 * exactly what a quiet room promises never to show. See `src/quiet.ts`.
 *
 * Whether this room is quiet, and which transport actually carries the
 * announcement, are both fixed at the top of this function, before any
 * `await` - not re-read afterwards. This upload spans several awaited
 * steps, during which the room can close, rekey or be left (another
 * device's action, not just this one's), which flips `quietTransport` to
 * something else entirely; reading it again after that would ask "is the
 * CURRENT room quiet" instead of "was the room this upload was for quiet".
 * The room-generation check below catches the same staleness from the
 * other side: if the room changed at all while this ran, nothing is
 * announced or staged, whether or not it was quiet. And the announcement,
 * when one is sent, still goes out through the room's own transport as it
 * stood at the start - a `QuietRoomTransport`, if that room was quiet - so
 * even if this file is ever wrong, that transport's own refusal of a bare
 * kind-1063 (`QUIET_BLOCKED_KINDS` in `src/quiet.ts`) is what actually
 * stops it, not this file's bookkeeping.
 *
 * The key goes into the staged attachment and nowhere else.
 */
async function shareDroppedFile(file: File, draft: ConversationDraft, signal: AbortSignal, server: string): Promise<void> {
  signal.throwIfAborted()
  const startGeneration = roomGeneration
  const pool = sessionTransport
  if (!session || !pool) throw new Error('Join the room first.')
  // Fixed now, alongside the transport: see the function comment above.
  const quiet = quietTransport !== undefined
  const transport: RelayTransport = quietTransport ?? pool
  // A conference room's end, fixed with the rest: the announcement, and the
  // upload's authorisation, lapse with the room.
  const endsAt = session.endsAt
  if (file.size > MAX_UPLOAD_SOURCE_BYTES) {
    throw new Error(`${file.name} is ${formatBytes(file.size)}; a room sends up to ${formatBytes(MAX_UPLOAD_SOURCE_BYTES)}.`)
  }
  if (file.size === 0) throw new Error(`${file.name} is empty.`)
  requireFileStorage(server)
  const origin = normaliseBlossomServer(server)
  const deviceSk = deviceKey()
  // Fixed with the key: the room whose tidy-up deletes this upload.
  const uploadRoomId = currentRoomId()!

  dropProgress(draft, 'Encrypting', file)
  // Let the line above paint before the main thread is busy sealing.
  await new Promise((resolve) => setTimeout(resolve, 0))
  signal.throwIfAborted()
  const sealed = await encryptEnvelopeBlob(file, { name: file.name, type: file.type })

  let descriptor: Awaited<ReturnType<typeof uploadEnvelopeBlob>>
  try {
    signal.throwIfAborted()
    // Consent may have been removed or the destination edited while sealing.
    requireFileStorage(server)
    dropProgress(draft, `Uploading to ${new URL(origin).hostname}:`, file)
    descriptor = await uploadEnvelopeBlob(origin, sealed.envelope, sealed.sha256, {
      sign: (t) => finalizeEvent(t, deviceSk), signal,
      ...(endsAt !== undefined ? { expiresAt: endsAt } : {}),
      fetch: (input, init) => { requireFileStorage(server); return fetch(input, init) },
    })
  } finally {
    await sealed.dispose?.()
  }
  // Written down at once, before anything below can give up on it: a blob
  // left on the server by a room that changed mid-upload is still this
  // device's to delete when the room is tidied away.
  recordUpload(deviceStore, uploadRoomId, descriptor)

  signal.throwIfAborted()
  // The room this upload was for is gone, replaced or rekeyed: another
  // device's action, a keeper closing the room, a dropped connection, not
  // necessarily anything this tab did. Whatever it was, this file is not
  // announced or staged into a draft that is no longer this room's - the
  // draft object itself may belong to a room nobody is looking at any
  // more. The blob is already on the Blossom server if it is still wanted.
  if (roomGeneration !== startGeneration) {
    throw new Error('This room changed while the file was uploading, so nothing was shared. The file is stored on the server; drop it again in the current room if you still want to send it.')
  }
  // In a quiet room, no announcement leaves this device: see the function
  // comment above. `quiet` and `transport` were fixed at the top of this
  // function, before the room could change out from under this decision.
  let eventId: string | undefined
  if (!quiet) {
    dropProgress(draft, 'Announcing', file)
    const announcement = buildFileEvent(descriptor)
    const event = finalizeEvent({ ...announcement, tags: withExpiration(announcement.tags, endsAt) }, deviceSk)
    await transport.publish(event)
    eventId = event.id
  }
  signal.throwIfAborted()
  const attachment: ChatAttachment = {
    ...(eventId !== undefined ? { event: eventId } : {}),
    url: descriptor.url,
    sha256: descriptor.sha256,
    key: sealed.key,
    name: sealed.name,
    type: sealed.type,
    size: sealed.envelope.size,
  }
  draft.attachments.push(attachment)
  if (pendingRecording?.file === file && pendingRecording.roomId === uploadRoomId) {
    pendingRecording.addedTo = draft
    pendingRecording.attachment = attachment
  }
  draft.status = ''
  draftChanged(draft)
}

/** A conversation has one file operation at a time, covering its whole
 * batch. Switching conversations does not change that operation's owner. */
async function fileWork(draft: ConversationDraft, work: (signal: AbortSignal) => Promise<void>): Promise<void> {
  if (draft.job || !channelAvailable(draft.channel) || (draft.channel !== undefined && WRITTEN_BY_AGENTS.includes(draft.channel))) return
  const job = new AbortController()
  draft.job = job
  draft.panelOpen = true
  draftChanged(draft)
  // A relay publish has no abort API. Release the editor immediately while
  // the operation's signal checks keep any late result out of this draft.
  let onAbort!: () => void
  const cancelled = new Promise<never>((_, reject) => {
    onAbort = () => reject(job.signal.reason)
    job.signal.addEventListener('abort', onAbort, { once: true })
  })
  try {
    await Promise.race([work(job.signal), cancelled])
    if (draft.job !== job) return
    draft.status = ''
    draft.panelOpen = false
  } catch (error) {
    if (draft.job !== job) return
    draft.status = job.signal.aborted
      ? 'Stopped adding files. Completed files stay in this draft. The store may already hold encrypted bytes; nothing was sent to the conversation.'
      : describeError(error)
  } finally {
    job.signal.removeEventListener('abort', onAbort)
    if (draft.job === job) {
      draft.job = undefined
      draftChanged(draft)
    }
  }
}

/** Keep the exact paste in the encrypted document. An upload never sends a
 * different draft if its owner switches conversations or edits while waiting. */
async function sendLongText(draft: ConversationDraft, fullText: string): Promise<void> {
  const generation = roomGeneration
  let uploaded = false
  await fileWork(draft, async signal => {
    if (draft.attachments.length >= MAX_CHAT_ATTACHMENTS) throw new Error(`A message carries at most ${MAX_CHAT_ATTACHMENTS} files.`)
    const file = new File([fullText], `message-${new Date().toISOString().replace(/[:.]/g, '-')}.txt`, { type: 'text/plain;charset=utf-8' })
    await shareDroppedFile(file, draft, signal, blossomServer())
    uploaded = true
  })
  if (!uploaded || generation !== roomGeneration) return
  if (draft.text !== fullText) {
    draft.status = 'Full text attached. Your newer edits are kept; review the draft before sending.'
    draft.panelOpen = true
    draftChanged(draft)
    return
  }
  draft.text = `Shared full text (${fullText.length.toLocaleString()} characters). Open the encrypted document to read or copy everything.\n\n${fullText.slice(0, 600).replace(/[\uD800-\uDBFF]$/, '')}…`
  draft.selectionStart = draft.selectionEnd = draft.text.length
  if (draft !== drafts.get(currentChannel)) { draftChanged(draft); return }
  restoreDraft()
  ;($('chatForm') as HTMLFormElement).requestSubmit()
}

/** Files from a drop or the file input, one after another, stopping at the
 *  first that fails so the reason is the last thing on the line. */
async function shareDroppedFiles(files: FileList | File[] | null): Promise<void> {
  if (roomUsesBothy) throw new Error('File sharing is unavailable on this text-only Bothy route.')
  const draft = captureDraft()
  if (!channelAvailable(currentChannel) || (currentChannel !== undefined && WRITTEN_BY_AGENTS.includes(currentChannel))) return
  const list = Array.from(files ?? [])
  if (!list.length) return
  const server = blossomServer()
  if (!server) {
    draft.panelOpen = true
    const pending = draft.pendingFiles ?? []
    if (draft.attachments.length + pending.length + list.length > MAX_CHAT_ATTACHMENTS) {
      draft.status = `A message carries at most ${MAX_CHAT_ATTACHMENTS} files. Remove a selected file before adding more.`
    } else if (list.some(file => file.size === 0 || file.size > MAX_UPLOAD_SOURCE_BYTES)) {
      draft.status = `Choose non-empty files up to ${formatBytes(MAX_UPLOAD_SOURCE_BYTES)} each.`
    } else {
      draft.pendingFiles = [...pending, ...list]
      draft.status = 'File uploads are off. Your files are held on this device. Choose and allow a storage destination below, then press Upload selected files.'
    }
    ;($('fileStorageOptions') as HTMLDetailsElement).open = true
    draftChanged(draft)
    return
  }
  await fileWork(draft, async signal => {
    for (const file of list) {
      signal.throwIfAborted()
      if (draft.attachments.length >= MAX_CHAT_ATTACHMENTS) {
        throw new Error(`A message carries at most ${MAX_CHAT_ATTACHMENTS} files.`)
      }
      await shareDroppedFile(file, draft, signal, server)
      draft.pendingFiles = draft.pendingFiles?.filter(pending => pending !== file)
    }
  })
}

/** Public servers run by other people, built from the one list in
 *  `file-storage.ts`. A button only fills the field, through the same input
 *  event typing raises, so choosing one revokes consent and unticks the box
 *  exactly as typing does. It never grants consent. */
function renderPublicFileServers(): void {
  const input = $('attachServer') as HTMLInputElement
  $('publicFileServerList').replaceChildren(...PUBLIC_FILE_SERVERS.map(server => {
    const button = document.createElement('button')
    button.type = 'button'
    button.dataset.origin = server.origin
    const host = document.createElement('span')
    host.className = 'publicFileServerHost'
    host.textContent = new URL(server.origin).host
    const detail = document.createElement('span')
    detail.className = 'publicFileServerDetail'
    detail.textContent = `run by ${server.operator}, files up to ${Math.round(server.maxBytes / (1024 * 1024))} MB`
    button.append(host, detail)
    button.addEventListener('click', () => {
      input.value = server.origin
      input.dispatchEvent(new Event('input', { bubbles: true }))
    })
    return button
  }))
  $('publicFileServers').hidden = PUBLIC_FILE_SERVERS.length === 0
}

/** Say which public server, if any, is in the field. */
function markPublicFileServer(): void {
  const value = ($('attachServer') as HTMLInputElement).value.trim().replace(/\/$/, '')
  for (const button of $('publicFileServerList').querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(button.dataset.origin === value))
  }
}

// Before anything reads the stored choice: a consent made only by the old
// pre-filled suggestion is removed here, and the person is told once.
fileServerRetired = retireSuggestedForgeSwornConsent(localStorage)
;($('attachServer') as HTMLInputElement).value = suggestedFileServer(localStorage, deployerFileServer)
;($('allowSharedFiles') as HTMLInputElement).checked = !!blossomServer()
renderPublicFileServers()
markPublicFileServer()
renderFileStorage()
$('attachServer').addEventListener('input', () => {
  // Editing never retains approval for the old destination, even if the new
  // text is invalid. Typing a URL is not consent to public ciphertext storage.
  stopFileUploads(localStorage)
  ;($('allowSharedFiles') as HTMLInputElement).checked = false
  markPublicFileServer()
  renderFileStorage()
})
$('saveFileStorage').addEventListener('click', () => {
  const input = $('attachServer') as HTMLInputElement
  const draft = captureDraft()
  try {
    input.value = allowSharedFileServer(localStorage, input.value, ($('allowSharedFiles') as HTMLInputElement).checked)
    draft.status = ''
    // The choice is made; the status line says where files go from here.
    ;($('fileStorageOptions') as HTMLDetailsElement).open = false
  } catch (err) {
    draft.status = describeError(err)
  }
  renderFileStorage()
  draftChanged(draft)
})
$('stopFileUploads').addEventListener('click', () => {
  stopFileUploads(localStorage)
  ;($('allowSharedFiles') as HTMLInputElement).checked = false
  renderFileStorage()
})
$('allowSharedFiles').addEventListener('change', () => {
  if (($('allowSharedFiles') as HTMLInputElement).checked) return
  stopFileUploads(localStorage)
  renderFileStorage()
})
window.addEventListener('storage', event => {
  if (event.key !== FILE_STORAGE_KEY && event.key !== null) return
  ;($('allowSharedFiles') as HTMLInputElement).checked = false
  renderFileStorage()
})
$('attachFile').addEventListener('change', () => {
  const input = $('attachFile') as HTMLInputElement
  const files = Array.from(input.files ?? [])
  input.value = ''
  void shareDroppedFiles(files)
})

// Drag a file onto the chat form and it goes the same way. The class is
// only a visual cue that the drop will be taken.
const chatForm = $('chatForm')
// Clipboard files use the same consent, encryption, limits and draft ownership
// as the picker. Plain text keeps the browser's normal paste behaviour.
document.addEventListener('paste', event => {
  if (!session || $('roomArea').hidden || document.querySelector('dialog[open]')) return
  const target = event.target instanceof Element ? event.target : null
  if (target?.closest('input, textarea, [contenteditable="true"]') && target.id !== 'chatInput') return
  const data = event.clipboardData
  const files = Array.from(data?.files ?? [])
  // Some browser clipboard implementations expose items without filling
  // FileList. Do not take both lists: that would stage every file twice.
  if (!files.length) for (const item of Array.from(data?.items ?? [])) {
    if (item.kind !== 'file') continue
    const file = item.getAsFile()
    if (file) files.push(file)
  }
  if (!files.length) return
  event.preventDefault()
  void shareDroppedFiles(files)
})

for (const type of ['dragenter', 'dragover'] as const) {
  chatForm.addEventListener(type, (event) => {
    if (!event.dataTransfer?.types.includes('Files')) return
    event.preventDefault()
    chatForm.classList.add('dropping')
  })
}
chatForm.addEventListener('dragleave', (event) => {
  if (event.relatedTarget instanceof Node && chatForm.contains(event.relatedTarget)) return
  chatForm.classList.remove('dropping')
})
chatForm.addEventListener('drop', (event) => {
  chatForm.classList.remove('dropping')
  if (!event.dataTransfer?.files.length) return
  event.preventDefault()
  void shareDroppedFiles(event.dataTransfer.files)
})

$('uploadPendingFiles').addEventListener('click', () => { void shareDroppedFiles(drafts.get(currentChannel).pendingFiles ?? []) })
$('clearPendingFiles').addEventListener('click', () => {
  const draft = drafts.get(currentChannel)
  draft.pendingFiles = []
  draft.status = ''
  draftChanged(draft)
})

$('attachToggle').addEventListener('click', () => {
  const draft = captureDraft()
  draft.panelOpen = !draft.panelOpen
  draftChanged(draft)
  // The picker is the first thing in the panel and takes focus. Not
  // opened programmatically: a native chooser opened from script blocks
  // the page in some browsers, and cannot be dismissed by the app.
  if (draft.panelOpen) $('attachFile').focus()
})
$('attachCancel').addEventListener('click', () => {
  const draft = captureDraft()
  draft.panelOpen = false
  draftChanged(draft)
  $('attachToggle').focus()
})
$('attachAdd').addEventListener('click', async () => {
  const draft = captureDraft()
  const key = draft.key
  const sourceEvent = draft.event
  await fileWork(draft, async signal => {
    if (draft.attachments.length >= MAX_CHAT_ATTACHMENTS) throw new Error(`A message carries at most ${MAX_CHAT_ATTACHMENTS} files.`)
    draft.status = 'Checking…'
    draftChanged(draft)
    const keyHex = parseRecoveryKey(key)
    const event = await resolveFileEvent(sourceEvent, signal)
    signal.throwIfAborted()
    draft.attachments.push(shareFromEvent(event, keyHex))
    draft.key = draft.event = ''
    if (draft === drafts.get(currentChannel)) {
      ;($('attachKey') as HTMLInputElement).value = ''
      ;($('attachEvent') as HTMLInputElement).value = ''
    }
  })
})

for (const id of ['attachEvent', 'attachKey']) {
  $(id).addEventListener('input', () => {
    captureDraft()
    renderDraftBadges()
  })
}
$('cancelFileWork').addEventListener('click', () => drafts.get(currentChannel).job?.abort())
$('discardDraft').addEventListener('click', async () => {
  const draft = captureDraft()
  if (!draftHasWork(draft) || !await confirmRoomAction({ title: 'Discard this draft?', message: 'Your unsent text and files will be removed from this conversation. Files still being added will stop. Uploaded encrypted files are not deleted from their store.', confirmLabel: 'Discard draft', danger: true })) return
  drafts.discard(draft)
  restoreDraft()
  if (!channelAvailable(currentChannel)) selectChannel(undefined)
  else renderChannels()
})

// Never let maxlength silently discard the tail of a paste.
;($('chatInput') as HTMLTextAreaElement).removeAttribute('maxlength')
function showPasteSize(): void {
  const input = $('chatInput') as HTMLTextAreaElement
  const note = $('pasteSizeNote')
  const over = input.value.length > MAX_CHAT_TEXT_LENGTH
  note.hidden = !over
  note.textContent = over ? `${input.value.length.toLocaleString()} characters pasted. Send will share a short preview and the complete encrypted text document.` : ''
  input.removeAttribute('aria-invalid')
}
$('chatInput').addEventListener('input', showPasteSize)

// The effect controls start where a remembered choice from this browser's
// last call says they start (`call-prefs.ts`), or otherwise where the
// constants say: BLUR_ON_BY_DEFAULT is a product decision and it is meant
// to stay one line to change.
const savedEffectMode = loadEffectMode(deviceStore) ?? (BLUR_ON_BY_DEFAULT ? 'blur' : 'off')
const savedBlurStrength = loadBlurStrength(deviceStore) ?? DEFAULT_BLUR_STRENGTH
let savedFacePrivacyMode = loadFacePrivacyMode(deviceStore)
let savedVoicePreset = loadVoicePreset(deviceStore) ?? DEFAULT_VOICE_PRESET
const savedBackgroundId = loadBackgroundId(deviceStore)
if (savedBackgroundId && BACKGROUNDS.some((b) => b.id === savedBackgroundId)) backgroundId = savedBackgroundId
;($('blurStrength') as HTMLInputElement).value = String(Math.round(savedBlurStrength * 100))
markSegmented('effectModes', 'mode', savedEffectMode)
markSegmented('voicePresets', 'preset', savedVoicePreset)
$('effectMode').textContent = savedEffectMode
$('voiceMode').textContent = savedVoicePreset
renderFacePrivacyState()

// What kind of visit this is, said before the relays are asked.
//
// The page used to paint the setup furniture first - a name box, "Start a
// room", a place to paste a link - because that is what index.html said,
// and only replace it with the invitation screen once the admission had
// come back over a relay. On a cold arrival that is seconds of being shown
// a console for making a room you have never heard of, followed by the page
// changing under you.
//
// Once the app loads, select its door before waiting for admission. The
// dashboard stays hidden for an invitation, including one that cannot open.
if (location.hash.length > 1) {
  $('identity').hidden = false
  $('arrivalTitle').textContent = 'Opening your invite link'
  const lead = $('arrivalLead')
  lead.textContent = 'Opening the link somebody sent you.'
  lead.hidden = false
}

/** The door was replaced by "Opening …" before it was known that the room
 *  may open by itself; undone if it turns out it may not. */
let provisionalOpening = false

const pendingRoomSwitch = (() => {
  try {
    const raw = sessionStorage.getItem(ROOM_SWITCH_KEY)
    sessionStorage.removeItem(ROOM_SWITCH_KEY)
    return raw
  } catch { return null }
})()
armStopOpening()
// Defer until identityReady has been initialised below. Admission can then
// wait for a returning account without delaying the first door paint.
const roomArrival = Promise.resolve().then(roomFromLocation)
// A meeting code End room, New link or Forget could not delete last time.
drainMeetingCodeRetirements()
roomArrival
  .finally(disarmStopOpening)
  .then((found) => {
    if (!found) {
      // No link: the front page, with the rooms this device has been in.
      showRoomsList()
      // kithmoot.app/c/<code> arrives here as ?c=<code>: the same path as
      // typing it into Join with code, so it reaches the door and no further.
      // Password words that came in the link's fragment (see `linkWords`,
      // already out of the address bar) open a sealed code without a prompt.
      const code = new URL(location.href).searchParams.get('c')
      if (code !== null) {
        ;($('joinCode') as HTMLDialogElement).showModal()
        ;($('meetingCodeInput') as HTMLInputElement).value = code
        void joinWithCode(code)
      }
    } else {
      showRoomUi()
      renderIdentity()
      // A room this device has joined opens itself below: say so now, so the
      // name form never flashes while a signer is being restored.
      const joined = !guestAdmissionPreview && (identityRestoring || !needsAccountReconnect()) ? joinedRoomHere(true) : undefined
      if (joined) { provisionalOpening = true; showOpening(joined) }
    }
    // Why the last page left, if the room told it to. A tab taken out by a
    // tidy-up elsewhere comes back to the front page, not the room.
    try {
      const notice = sessionStorage.getItem(NOTICE_STORAGE_KEY)
      if (notice) {
        sessionStorage.removeItem(NOTICE_STORAGE_KEY)
        setStatus(notice)
        if (notice === SELF_DESTRUCTED_MESSAGE) showDestructEffect()
      }
    } catch {
      // No storage, no notice.
    }
  })
  .catch(showArrivalFailure)

function showArrivalFailure(err: unknown): void {
  if (err instanceof AdmissionPreviewCancelled) {
    $('arrivalTitle').textContent = err.requested ? 'Your request was cancelled' : 'Invitation closed'
    $('arrivalLead').textContent = err.requested
      ? 'You have not entered the room. Your details are kept here; request again when you are ready.'
      : 'No request was sent. Your details are kept here if you choose to try again.'
    $('arrivalLead').hidden = false
    $('joinRoomForm').hidden = true; $('identityMore').hidden = true
    $('arrivalActions').hidden = false; $('retryArrival').hidden = false
    $('arrivalRelays').hidden = true
    setStatus('')
    return
  }
  const declined = err instanceof InvitationDeclinedError
  const reason = describeError(err)
  let valid = false
  try { parseRoomLink(location.href); valid = true } catch { /* Incomplete or malformed invitation. */ }
  // Not a room link at all, but a contact card handed over as a link: the
  // door offers to keep it. Read only on the person's say-so, so a link
  // merely opened adds nobody.
  const card = valid ? undefined : cardAtTheDoor()
  if (card) {
    $('arrivalTitle').textContent = 'This is a contact card'
    $('arrivalLead').textContent = `From ${card.name ?? 'somebody'}: their key, ${card.relays.length} public relay${card.relays.length === 1 ? '' : 's'} and ${card.boxes.length === 0 ? 'no box' : card.boxes.length === 1 ? 'one box' : `${card.boxes.length} boxes`}. Add it to the contacts on this device?`
    $('arrivalLead').hidden = false
    $('joinRoomForm').hidden = true
    $('identityMore').hidden = true
    $('arrivalActions').hidden = false
    $('retryArrival').hidden = true
    $('arrivalRelays').hidden = true
    $('addCardArrival').hidden = false
    setStatus('')
    return
  }
  $('addCardArrival').hidden = true
  const conference = reason.startsWith(CONFERENCE_ENDED_PREFIX)
  const ended = reason === ROOM_ENDED_MESSAGE || reason === SELF_DESTRUCTED_MESSAGE || conference
  const retired = ended || reason.includes('retired')
  const persistent = valid && parseRoomLink(location.href).invitation?.persistent
  if (ended) markLinkEnded(location.href)
  $('arrivalTitle').textContent = declined ? 'Your request was declined' : ended ? 'This room has ended' : retired ? 'This invite link is no longer valid' : valid ? persistent ? 'The invite link could not be loaded' : 'The room has not answered' : 'This invite link is incomplete'
  $('arrivalLead').textContent = declined
    ? 'Someone in the room declined this request. Ask them before trying again. Your details are still on this device.'
    : conference
    ? `${reason} Nobody can join it any more.`
    : ended
    ? 'It was ended by the person who started it, so nobody can join it any more.'
    : retired
    ? 'Ask somebody in the room for its current invite link.'
    : valid
      ? persistent
        ? 'Its invitation was not on the link\u2019s relays or on yours. If you know a relay the room uses, add it and try again. Otherwise ask someone in the room for a fresh invite link.'
        : 'Nobody let you in. Somebody in the room has to be online and accept you: ask them, or try again when they are around. A room can also be kept open for anyone with the link (Room details, Keep this room open).'
      : 'Copy the whole invite link, including everything after #, then open it again.'
  $('arrivalLead').hidden = false
  $('joinRoomForm').hidden = true
  $('identityMore').hidden = true
  $('arrivalActions').hidden = false
  $('retryArrival').hidden = !valid || retired
  $('arrivalRelays').hidden = !valid || retired || !persistent
  setStatus('')
}


// Rewrite what is in storage with what a reader would actually see, so a
// name that arrived there by some other route does not sit in raw form.
storeName(typedName)
renderIdentity()

// A signer paired on an earlier visit reconnects itself. Deliberately not
// awaited before the page is usable: a bunker over a relay can take seconds.
// Joining waits for it so the room uses the same identity the account UI
// shows. renderIdentity() runs again when it lands.
/**
 * `restoreSession`, with a moment's grace for an extension.
 *
 * An extension's content script lands after this module runs, so a sign-in
 * stored as "extension" was restored while `window.nostr` did not exist
 * yet, which signet-login reads as the extension having been uninstalled:
 * it hands back an identity that can prove who you are and sign nothing,
 * and the door said "Reconnect Nostr account" to a person whose extension
 * was right there. Wait for it, briefly, and restore again.
 */
async function restoreSessionWithExtensionGrace(): Promise<SignetSession | null> {
  reachStoredSignerOnSignetRelay()
  const session = await restoreSession()
  if (session?.signer.capabilities.canSignEvents) return session
  let storedMethod: string | null = null
  try { storedMethod = localStorage.getItem('signet:login.method') } catch { /* no storage, nothing stored */ }
  if (storedMethod !== 'nip07') return session
  for (let waited = 0; waited < 3000 && !extensionSignerPresent(); waited += 100) {
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  if (!extensionSignerPresent()) return session
  return restoreSession()
}

const identityReady = restoreSessionWithExtensionGrace()
  .then(async (session) => {
    if (identityGeneration !== 0) return
    if (!session?.signer.capabilities.canSignEvents) {
      if (!location.hash && new URL(location.href).searchParams.get('signin') === 'nostr') {
        history.replaceState(null, '', joinLinkBase())
        // This is an explicit sign-in, not a failed background restore.
        // Keep its error visible instead of swallowing it below.
        return signInWithNostr().catch(error => setStatus(describeError(error)))
      }
      return
    }
    await adoptRestoredSession(session)
  })
  .catch(() => {
    // No stored session, or a signer that is not answering today. Either
    // way this page still works: type a name and join. A bunker that did
    // not answer is tried again by retryStoredBunker.
  })
  .finally(() => {
    identityRestoring = false
    renderIdentity()
    if (rememberAfterRestore) rememberCurrentRoom()
    scheduleBunkerRetry()
    // A self-destructing room that ended while this device was away is
    // tidied away now, with the account's signer if it came back.
    void runDueDestructs()
  })

// A room this device has joined goes straight in, as the identity that joined
// it; so does an explicit room switch or safe update in this tab. An
// invitation never auto-joins (it gets the door), and a failed or different
// Nostr restore never joins as a guest: the account has to be reconnected, or
// a name chosen, first.
Promise.all([roomArrival, identityReady]).then(async ([found]) => {
  const undo = (): void => {
    if (!provisionalOpening) return
    provisionalOpening = false
    if (session || joining) return
    setStatus('')
    $('joinRoomForm').hidden = false
    renderArrival()
    renderIdentity()
  }
  const join = $('join') as HTMLButtonElement
  if (!found || session || joining || join.disabled || guestAdmissionPreview) { undo(); return }
  const raw = pendingRoomSwitch
  if (raw) {
    const intent = JSON.parse(raw) as { hash?: string; account?: string | null; at?: number }
    const age = Date.now() - (intent.at ?? 0)
    if (intent.hash !== location.hash || age < 0 || age > 120_000) { undo(); return }
    if (intent.account !== (nostrSession?.pubkey ?? null)) {
      undo()
      setStatus('Check your sign-in before entering: the previous account is not available.')
      return
    }
    provisionalOpening = false
    return startSession()
  }
  const room = needsAccountReconnect() ? undefined : joinedRoomHere()
  if (!room) { undo(); return }
  provisionalOpening = false
  showOpening(room)
  await startSession()
  if (!session) {
    $('joinRoomForm').hidden = false
    renderArrival()
    renderIdentity()
  }
}).catch(() => { /* Admission/sign-in failures leave the normal door available. */ })

// The pubkey we would join as, so the identity line is right before the
// first room is ever opened.
const known = currentParticipant()
if (known) profiles.want([known])

// Restore only explicit discovery preferences after all screen state exists.
boxDiscovery = new BoxDiscovery({
  allowed: contact => !contactIsBlocked(contact),
  store: deviceStore,
  transport: unavailable => new BoxRelayReader(relayConnections.configuration('default'), unavailable),
  changed: () => { renderContacts(); renderLaneNote(); renderHistoryRecovery() },
})
boxDiscovery.reconcile()
document.addEventListener('visibilitychange', () => { if (!document.hidden) boxDiscovery?.tick() })
